import { useCallback, useEffect, useRef, useState } from 'react';
import { useShallow } from 'zustand/react/shallow';
import {
  useFocusable,
  setFocus,
  FocusContext,
} from '@noriginmedia/norigin-spatial-navigation';
import { pressWithFocus } from '../nav/pressWithFocus.js';
import { categoryLabel, type CatalogSort } from '@mfp/core';
import { VirtualGrid } from '../components/VirtualGrid.js';
import { PosterCard } from '../components/PosterCard.js';
import { GenreChips } from '../components/GenreChips.js';
import { SortDropdown } from '../components/SortDropdown.js';
import { OnScreenKeyboard } from '../components/OnScreenKeyboard.js';
import { FocusButton } from '../components/FocusButton.js';
import { EmptyState, ErrorScreen, LoadingState } from '../components/states.js';
import { SearchIcon } from '../components/icons.js';
import { focusRing } from '../nav/focusRing.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useProvider } from '../runtime/useProvider.js';
import { useNavigation, voltandoComFoco } from '../nav/navigationStack.js';
import { useBrowse, type BrowseItem, type BrowseSection } from '../state/browse.js';
import { useCatalog } from '../state/catalog.js';
import { useSync } from '../state/sync.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';

/**
 * Sem closure: nada aqui depende do componente, então a função é estável para
 * sempre — nem precisa de `useCallback` (PERF-09 / spec 002). É o que permite
 * ao `GridCell` memoizado do `VirtualGrid` pular o re-render das células.
 */
const renderPoster = (it: BrowseItem, i: number, focused: boolean) => (
  <PosterCard
    focused={focused}
    prioridade={i}
    data={{
      title: it.name,
      poster: it.poster,
      meta: it.rating ? `★ ${it.rating.toFixed(1)}` : undefined,
    }}
  />
);

export function Catalog({ listId, section }: { listId: string; section: BrowseSection }) {
  const rt = useRuntime();
  const push = useNavigation((s) => s.push);
  const counts = useCatalog((s) => s.counts);
  const countsLoaded = useCatalog((s) => s.loaded);
  const loadHome = useCatalog((s) => s.loadHome);
  const runSync = useSync((s) => s.run);
  const stalled = useSync((s) => s.sections[section].status === 'stalled');
  const getProvider = useProvider();
  // LG-022: sync parou por cota antes de chegar nesta seção — tenta de novo em
  // vez de deixar o usuário preso no spinner eterno de `boot.firstSync`. Ver
  // nota equivalente em `Home.tsx`: limpa o cache reconstruível (LS-RF-15)
  // antes de tentar de novo, senão bate na mesma cota estourada na hora.
  const onRetrySync = useCallback(() => {
    void (async () => {
      const { provider } = await getProvider();
      await rt.db.wipeReconstructibleCache(listId);
      await runSync(rt, listId, provider);
      await loadHome(rt, listId);
    })();
  }, [getProvider, runSync, loadHome, rt, listId]);
  // Fatia composta com `useShallow` (PERF-11): sem isto, `useBrowse()` inteiro
  // re-renderiza a cada mudança de QUALQUER campo do store — inclusive
  // `carregandoMais` (o spinner da rolagem infinita), que esta tela nem usa
  // diretamente, mas que troca de valor a cada leva carregada.
  const {
    categories,
    categoryId,
    sort,
    query,
    items,
    total,
    carregando,
    erro,
    load,
    setCategory,
    setSort,
    setQuery,
    carregarMais,
    retry,
  } = useBrowse(
    useShallow((s) => ({
      categories: s.categories,
      categoryId: s.categoryId,
      sort: s.sort,
      query: s.query,
      items: s.items,
      total: s.total,
      carregando: s.carregando,
      erro: s.erro,
      load: s.load,
      setCategory: s.setCategory,
      setSort: s.setSort,
      setQuery: s.setQuery,
      carregarMais: s.carregarMais,
      retry: s.retry,
    })),
  );
  const [kbOpen, setKbOpen] = useState(false);
  /** Texto sendo digitado no teclado; vira busca só ao confirmar. */
  const [rascunho, setRascunho] = useState('');
  // Prende o foco no modal do teclado enquanto aberto (mesma ideia do
  // SortDropdown): teclado + botão "Fechar" na MESMA escala, para o D-pad
  // não escapar para a grade por trás nem para os gêneros. `isFocusBoundary`
  // é reativo — liga/desliga sozinho com `kbOpen`, sem remontar nada.
  const { ref: kbModalRef, focusKey: kbModalFk } = useFocusable({
    focusKey: 'catalog-kb-modal',
    trackChildren: true,
    saveLastFocusedChild: true,
    isFocusBoundary: kbOpen,
    focusBoundaryDirections: ['up', 'down', 'left', 'right'],
  });

  // RP-6 (spec 002): fecha o par de `browse:change` quando a grade repinta. O
  // primeiro render é a carga inicial (medida por outro caminho), não uma troca.
  const jaRenderou = useRef(false);
  useEffect(() => {
    if (jaRenderou.current) rt.perf.marcar('browse:painted', { itens: items.length });
    else jaRenderou.current = true;
  }, [items, rt]);

  // Foco na primeira tecla ao abrir, e de volta pro campo de busca ao
  // fechar (GTV-RF-03/GTV-RF-06): pedir o foco no MESMO onPress/onSubmit que
  // muda `kbOpen` não funciona nos dois sentidos —
  //   abrir: o teclado ainda nem existe no DOM nesse instante;
  //   fechar: `isFocusBoundary` do modal ainda está ATIVO nesse instante
  //     (o `kbOpen` que o liga só vira false depois do React processar o
  //     `setState`), então o `setFocus('catalog-search')` mirava um alvo
  //     FORA do boundary enquanto ele ainda prendia o foco — bloqueado, o
  //     campo de busca nunca recuperava o foco de verdade.
  // Só aqui, depois que `kbOpen` comitou de um jeito ou de outro, o alvo
  // certo existe e/ou o boundary já soltou.
  const kbEsteveAbertoRef = useRef(false);
  useEffect(() => {
    if (kbOpen) {
      kbEsteveAbertoRef.current = true;
      setFocus('catalog-kb');
    } else if (kbEsteveAbertoRef.current) {
      kbEsteveAbertoRef.current = false;
      setFocus('catalog-search');
    }
  }, [kbOpen]);

  useEffect(() => {
    // Voltando de um detalhe: mantém o que já estava carregado (gênero,
    // ordenação, busca) e não mexe no foco — quem o devolve, no item exato de
    // onde se saiu, é o `useRestoreFocus` do App.
    const voltando = voltandoComFoco();
    void load(rt, listId, section, voltando).then(() => {
      if (!voltando) setFocus('catalog-grid');
    });
  }, [rt, listId, section, load]);

  // Antes do `return` condicional abaixo: hooks não podem ser pulados em
  // algumas renderizações e chamados em outras (regra dos hooks).
  const openDetail = useCallback(
    (id: string) =>
      push({
        name: section === 'vod' ? 'movieDetail' : 'seriesDetail',
        params: { id },
      }),
    [push, section],
  );
  const onItemPress = useCallback((it: BrowseItem) => openDetail(it.id), [openDetail]);
  // PERF-01a: pede a próxima leva quando a grade se aproxima do fim
  const onNearEnd = useCallback(
    () => void carregarMais(rt, listId),
    [carregarMais, rt, listId],
  );
  // LS-030: retenta a busca que falhou — mesma leva (gênero/ordenação/busca
  // atuais), não um reset completo, senão o retry "perde" o que o usuário
  // tinha escolhido antes da falha.
  const onRetryBusca = useCallback(() => void retry(rt, listId), [retry, rt, listId]);

  const sectionCount = section === 'vod' ? counts.vod : counts.series;
  if (sectionCount === 0) {
    const titulo = section === 'vod' ? t('nav.movies') : t('nav.series');
    // Ver nota em `state/catalog.ts`: "ainda lendo o cache" != "vazio de fato".
    if (!countsLoaded) return <LoadingState label={titulo} />;
    if (stalled) {
      return (
        <EmptyState
          title={titulo}
          body={t('boot.syncStalled')}
          action={
            <FocusButton
              primary
              autoFocus
              focusKey="catalog-retry-sync"
              onPress={onRetrySync}
            >
              {t('common.retry')}
            </FocusButton>
          }
        />
      );
    }
    return <EmptyState loading title={titulo} body={t('boot.firstSync')} />;
  }

  // Erro na busca (troca de gênero/ordenação/busca) sem NENHUM item pra
  // mostrar — tela cheia com retry. Com itens (stale), a grade continua na
  // tela e o aviso já saiu como toast em `browse.ts` — não duplica aqui.
  if (erro && items.length === 0 && !carregando) {
    return <ErrorScreen onRetry={onRetryBusca} autoFocusRetry />;
  }

  const semResultado = carregando ? (
    <LoadingState />
  ) : (
    <EmptyState body={t('catalog.noResults', { q: query })} />
  );

  const sortOptions: { id: CatalogSort; label: string }[] = [
    { id: 'recent', label: t('catalog.sortRecent') },
    { id: 'name', label: t('catalog.sortName') },
    { id: 'rating', label: t('catalog.sortRating') },
  ];

  return (
    <div
      className={gapColClass}
      style={{
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        // sem piso de altura: um `minHeight` maior que o <main> (medido: 30rem =
        // 390px num main de 348px) empurra o fim da grade para baixo da dobra —
        // e a grade, que dimensiona o cartão pela altura que mede, acreditaria
        // ter 291px visíveis quando só há 231px de tela.
        minHeight: 0,
        ...gapVar('1rem'),
      }}
    >
      <div
        className={gapRowClass}
        style={{ display: 'flex', alignItems: 'center', ...gapVar('1rem') }}
      >
        <span style={{ color: 'var(--text-secondary)' }}>
          {items.length < total
            ? t('catalog.titleCountPartial', { shown: items.length, n: total })
            : t('catalog.titleCount', { n: total })}
        </span>
        <SortDropdown
          focusKey="catalog-sort"
          selectedId={sort}
          options={sortOptions}
          onChange={(id) => void setSort(rt, listId, id as CatalogSort)}
          onArrowPress={(direction) => {
            if (direction === 'down') {
              void setFocus('catalog-genres');
              return false;
            }
            return true;
          }}
        />
        <SearchField
          value={query}
          onOpen={() => {
            setRascunho(query); // abre para editar o termo em vigor
            setKbOpen(true);
            // Foco vai no useEffect([kbOpen]) — o teclado ainda não existe
            // no DOM aqui, um setFocus síncrono não acharia o alvo.
          }}
        />
      </div>

      <GenreChips
        focusKey="catalog-genres"
        selectedId={categoryId ?? ''}
        onSelect={(id) => void setCategory(rt, listId, id)}
        onArrowPress={(direction) => {
          if (direction === 'up') {
            void setFocus('catalog-sort-trigger');
            return false;
          }
          return true;
        }}
        chips={
          // sem o prefixo da seção ("Filmes | Terror" → "Terror"): ele repete em
          // todo chip e alarga a faixa (5153px de conteúdo para 766px visíveis)
          categories.map((c) => ({ id: c.id, label: categoryLabel(c.name, section) }))
        }
      />

      {items.length === 0 ? (
        semResultado
      ) : (
        <div
          style={{
            flex: 1,
            // `min-height: auto` (padrão do item flex) faria esta div crescer
            // para caber a grade inteira — medido: 78.000px para 600 filmes.
            // Aí `maxOffset` vira 0, a grade nunca rola sozinha, todas as
            // células ficam montadas e quem rola é a página: sem virtualização.
            minHeight: 0,
          }}
        >
          <VirtualGrid
            focusKey="catalog-grid"
            // a posição guardada vale para *este* recorte: trocar de gênero,
            // ordenação ou busca é outra lista, e ela começa do topo
            restoreKey={`catalog:${section}:${categoryId ?? 'todos'}:${sort}:${query}`}
            items={items}
            minItemWidth={220}
            renderItem={renderPoster}
            onItemPress={onItemPress}
            onNearEnd={onNearEnd}
          />
        </div>
      )}

      {kbOpen && (
        <FocusContext.Provider value={kbModalFk}>
          <div
            ref={kbModalRef}
            style={{
              position: 'fixed',
              top: 0,
              right: 0,
              bottom: 0,
              left: 0,
              background: 'var(--bg-scrim)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            <div
              className={gapColClass}
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                ...gapVar('1rem'),
              }}
            >
              <strong style={{ fontSize: 'var(--fs-section)' }}>{rascunho || ' '}</strong>
              {/* O que se digita é rascunho; a consulta só sai ao confirmar. Uma
                  busca por tecla varria as 54 mil linhas do índice a cada letra. */}
              <OnScreenKeyboard
                focusKey="catalog-kb"
                onInput={(ch) => setRascunho((q) => q + ch)}
                onDelete={() => setRascunho((q) => q.slice(0, -1))}
                onClear={() => setRascunho('')}
                onSubmit={() => {
                  setKbOpen(false);
                  void setQuery(rt, listId, rascunho);
                  // Foco volta pro campo de busca via o useEffect([kbOpen])
                  // acima — chamar setFocus aqui miraria um alvo fora do
                  // boundary do modal, ainda ativo neste exato instante.
                }}
              />
              <FocusButton focusKey="catalog-kb-done" onPress={() => setKbOpen(false)}>
                {t('common.close')}
              </FocusButton>
            </div>
          </div>
        </FocusContext.Provider>
      )}
    </div>
  );
}

function SearchField({ value, onOpen }: { value: string; onOpen: () => void }) {
  // `onArrowPress` (Down): sem isto, o norigin escalava a navegação até o
  // container-pai ('catalog-sort'/'catalog-search' são caixas estreitas) e
  // comparava com os IRMÃOS DO PAI (mesma escala do `GenreChips`/`app-header`,
  // que são containers largos) — o `app-header`, por cobrir a largura toda,
  // "ganhava" a prioridade mesmo estando bem mais longe, e Down nunca chegava
  // aos gêneros logo abaixo. Ver a mesma nota em `SortDropdown`.
  const { ref, focused } = useFocusable({
    focusKey: 'catalog-search',
    onEnterPress: onOpen,
    onArrowPress: (direction) => {
      if (direction === 'down') {
        void setFocus('catalog-genres');
        return false;
      }
      return true;
    },
  });
  return (
    <button
      ref={ref}
      type="button"
      onClick={pressWithFocus('catalog-search', onOpen)}
      style={{
        appearance: 'none',
        cursor: 'pointer',
        border: '2px solid var(--border-subtle)',
        borderRadius: 999,
        padding: '0.5rem 1.2rem',
        background: 'var(--bg-raised)',
        color: value ? 'var(--text-primary)' : 'var(--text-disabled)',
        font: 'inherit',
        ...focusRing(focused),
      }}
    >
      {value || (
        <>
          <SearchIcon /> {t('catalog.search')}
        </>
      )}
    </button>
  );
}
