import { create } from 'zustand';
import { DEFAULT_CACHE_CONFIG, type BufferPreset, type VideoFit } from '@mfp/core';
import type { Runtime } from '../runtime/runtime.js';
import {
  setAccentColor,
  setHighContrast,
  setReducedMotion,
  DEFAULT_ACCENT,
} from '../theme/appearance.js';

// Preferências do app (não por lista): reprodução + aparência. Persistidas em
// `meta` sob um listId reservado. Perfis (M8c) vão escopar isto por perfil.

const APP = '__app';
const KEY = 'settings';

export interface AppSettings {
  autoplayNext: boolean;
  buffer: BufferPreset;
  highContrast: boolean;
  reducedMotion: boolean;
  accent: string;
  streamFormat: 'm3u8' | 'ts';
  /** Formato de exibição do vídeo no player (D-21), global. */
  videoFit: VideoFit;
  /**
   * Teto de resolução vertical do vídeo (PERF-26 / spec 002). `'auto'` deriva do
   * display; `0` = sem limite. Sem teto, o engine escolhe a variante mais alta
   * do HLS — 1080p/4K decodificado para exibir em 720p custa CPU, calor e
   * rebuffer sem ganho visível.
   */
  maxVideoHeight: 'auto' | 720 | 1080 | 0;
  /** Mostrar o programa no ar em cada linha da lista de canais (D-23). */
  epgInList: boolean;
  /**
   * Idioma de áudio e de legenda escolhidos por último, aplicados ao próximo
   * título. Guardamos o **idioma**, não o id da faixa: o id é do engine e muda
   * de um título para outro. `''` = sem preferência; em `subtitleLang`, `'off'`
   * = legenda desligada de propósito.
   */
  audioLang: string;
  subtitleLang: string;
  /**
   * Teto de itens por categoria que `CatalogSync` grava em TV antiga (spec 003
   * LG-022) — exposto aqui de propósito, NÃO como recurso pro usuário final
   * mexer, mas pra dar pra ajustar/estressar esse cenário em campo sem
   * depender de gerar um novo build a cada tentativa. O valor não vem de
   * nenhuma cota oficial documentada pela LG (ver `cache/config.ts`); é só um
   * chute pragmático que pode precisar de ajuste conforme aparelhos reais.
   * Só tem efeito em aparelhos sem `navigator.storage.estimate`
   * (`isLowStorageDevice()`, `cache/quota.ts`) — em qualquer outro, é ignorado.
   */
  catalogItemCapOldDevices: number;
}

const DEFAULTS: AppSettings = {
  autoplayNext: true,
  buffer: 'medio',
  highContrast: false,
  reducedMotion: false,
  accent: DEFAULT_ACCENT,
  streamFormat: 'm3u8',
  videoFit: 'original',
  maxVideoHeight: 'auto',
  epgInList: true,
  audioLang: '',
  subtitleLang: '',
  catalogItemCapOldDevices: DEFAULT_CACHE_CONFIG.sync.maxItemsPerCategoryLowStorage,
};

interface SettingsState extends AppSettings {
  loaded: boolean;
  /** Preenchido quando a última `update()` falhou ao persistir (ex. cota de armazenamento estourada). */
  saveError: boolean;
  load: (rt: Runtime) => Promise<void>;
  update: (rt: Runtime, patch: Partial<AppSettings>) => Promise<void>;
}

function apply(s: AppSettings) {
  setAccentColor(s.accent === DEFAULT_ACCENT ? null : s.accent);
  setHighContrast(s.highContrast);
  setReducedMotion(s.reducedMotion);
}

export const useSettings = create<SettingsState>((set, get) => ({
  ...DEFAULTS,
  loaded: false,
  saveError: false,

  load: async (rt) => {
    const row = await rt.db.meta.get([APP, KEY]);
    const merged = { ...DEFAULTS, ...((row?.value as Partial<AppSettings>) ?? {}) };
    apply(merged);
    set({ ...merged, loaded: true });
  },

  update: async (rt, patch) => {
    const anterior = pick(get());
    const next = { ...anterior, ...patch };
    apply(next);
    set({ ...next, saveError: false });
    try {
      await rt.db.meta.put({ listId: APP, key: KEY, value: next, updatedAt: Date.now() });
    } catch (err) {
      // Ex.: QuotaExceededError em TV antiga com armazenamento esgotado — sem
      // isto, a gravação falha em silêncio e a tela some com a mudança que o
      // usuário acabou de fazer, sem nenhum aviso do porquê.
      rt.logger.error('falha ao salvar configurações', { err });
      apply(anterior);
      set({ ...anterior, saveError: true });
    }
  },
}));

function pick(s: SettingsState): AppSettings {
  return {
    autoplayNext: s.autoplayNext,
    buffer: s.buffer,
    highContrast: s.highContrast,
    reducedMotion: s.reducedMotion,
    accent: s.accent,
    streamFormat: s.streamFormat,
    videoFit: s.videoFit,
    maxVideoHeight: s.maxVideoHeight,
    epgInList: s.epgInList,
    audioLang: s.audioLang,
    subtitleLang: s.subtitleLang,
    catalogItemCapOldDevices: s.catalogItemCapOldDevices,
  };
}
