import { useEffect, type ReactNode } from 'react';
import {
  useFocusable,
  setFocus,
} from '@noriginmedia/norigin-spatial-navigation';
import { pressWithFocus } from '../nav/pressWithFocus.js';

export interface FocusButtonProps {
  children: ReactNode;
  onPress: () => void;
  /** Ação primária: anel vermelho + glow quando focada (design-inventory §Foco). */
  primary?: boolean;
  focusKey?: string;
  disabled?: boolean;
  /** Rótulo acessível — obrigatório quando `children` é só ícone, sem texto. */
  title?: string;
  /** Se true, solicita foco quando o botão está montado (GTV-RF-03). */
  autoFocus?: boolean;
  /**
   * Sobrescreve a navegação D-pad numa direção específica — necessário quando
   * este botão fica ao lado de um container largo (ex.: uma fileira de chips)
   * e a resolução geométrica padrão do norigin favorece o container maior por
   * cobrir mais largura, mesmo que este botão esteja bem mais perto. Devolver
   * `false` consome a tecla (a navegação padrão não roda); `true`/ausente
   * mantém o comportamento normal.
   */
  onArrowPress?: (direction: string) => boolean;
}

/**
 * Botão navegável por D-pad. Regras de foco 10-foot: anel branco 3px + leve escala;
 * a ação primária troca o anel por vermelho com glow.
 */
export function FocusButton({
  children,
  onPress,
  primary = false,
  focusKey,
  disabled = false,
  title,
  autoFocus = false,
  onArrowPress,
}: FocusButtonProps) {
  // `focusKey` é opcional aqui; o norigin gera uma quando não vem. Usamos a
  // que ele devolve para o toque poder mover o foco em qualquer caso.
  const { ref, focused, focusKey: fk } = useFocusable({
    focusKey,
    focusable: !disabled,
    onEnterPress: onPress,
    ...(onArrowPress ? { onArrowPress: (direction: string) => onArrowPress(direction) } : {}),
  });

  // GTV-RF-03: foco solicitado pelo componente focável após existir,
  // não como efeito colateral de callback assíncrono
  useEffect(() => {
    if (autoFocus && fk) {
      void setFocus(fk);
    }
  }, [autoFocus, fk]);

  const ring = primary ? 'var(--focus-ring-armed)' : 'var(--focus-ring)';

  return (
    <button
      ref={ref}
      type="button"
      title={title}
      aria-label={title}
      disabled={disabled}
      onClick={pressWithFocus(fk, onPress)}
      style={{
        appearance: 'none',
        border: 'none',
        cursor: disabled ? 'default' : 'pointer',
        padding: '0.6em 1.4em',
        borderRadius: 6,
        font: 'inherit',
        fontWeight: 600,
        letterSpacing: '0.02em',
        color: primary ? 'var(--text-on-accent)' : 'var(--text-primary)',
        background: primary ? 'var(--accent)' : 'var(--bg-raised)',
        opacity: disabled ? 0.4 : 1,
        outline: focused ? `3px solid ${ring}` : '3px solid transparent',
        boxShadow: focused && primary ? '0 0 16px var(--accent)' : 'none',
        transform: focused ? 'scale(1.04)' : 'scale(1)',
        transition: 'transform 160ms, outline-color 160ms',
      }}
    >
      {children}
    </button>
  );
}
