import { useEffect, useState } from 'react';
import type { Channel, EpgEntry } from '@mfp/core';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useProvider } from '../runtime/useProvider.js';

/** Enquanto o programa não vira, o cache do `get_short_epg` serve. */
const TTL_MS = 30 * 60_000;
/** Espera o foco assentar antes de pedir — percorrer a lista não vira rajada. */
const ESPERA_MS = 450;

export interface NowNext {
  /** Canal a que este resultado pertence — o dado só vale para ele. */
  channelId: string;
  agora?: EpgEntry;
  proximo?: EpgEntry;
}

/**
 * "Agora / a seguir" do canal focado (tela 02) e do player.
 *
 * Ordem das fontes (D-22):
 * 1. **EPG local** vindo do `xmltv.php` (`EpgRepo`) — cobre a maioria dos canais
 *    e não custa rede;
 * 2. **`get_short_epg`** como reserva, só quando o local não tem nada e o canal
 *    traz `epg_channel_id`. Neste painel de teste ele volta `[]`, mas outros
 *    painéis servem por aqui.
 *
 * Sem nenhuma das duas, a linha de guia simplesmente não aparece.
 */
export function useNowNext(listId: string, canal: Channel | undefined): NowNext | null {
  const rt = useRuntime();
  const getProvider = useProvider();
  const [dados, setDados] = useState<NowNext | null>(null);

  const id = canal?.id;
  const epgId = canal?.epgChannelId;

  useEffect(() => {
    if (!id) return;
    let vivo = true;
    const timer = window.setTimeout(() => {
      void (async () => {
        // 1) EPG local (XMLTV)
        const local = await rt.epg(listId).nowNext(id);
        if (!vivo) return;
        if (local.now || local.next) {
          setDados({
            channelId: id,
            ...(local.now ? { agora: local.now } : {}),
            ...(local.next ? { proximo: local.next } : {}),
          });
          return;
        }

        // 2) fallback get_short_epg — só faz sentido com epg_channel_id
        if (!epgId) {
          setDados({ channelId: id });
          return;
        }
        try {
          const cache = await rt.db.epgNowNext.get([listId, id]);
          let entradas = cache?.entries;
          if (!cache || Date.now() - cache.cachedAt > TTL_MS) {
            const { provider } = await getProvider();
            entradas = await provider.getShortEpg(id, 4);
            await rt.db.epgNowNext.put({
              listId,
              channelId: id,
              entries: entradas,
              cachedAt: Date.now(),
            });
          }
          if (!vivo) return;
          const agora = Date.now();
          const emCurso = entradas?.find((e) => e.start <= agora && e.stop > agora);
          const aSeguir = entradas?.find((e) => e.start > agora);
          setDados({
            channelId: id,
            ...(emCurso ? { agora: emCurso } : {}),
            ...(aSeguir ? { proximo: aSeguir } : {}),
          });
        } catch {
          // guia é enfeite: falhar aqui não pode atrapalhar a lista de canais
          if (vivo) setDados({ channelId: id });
        }
      })();
    }, ESPERA_MS);

    return () => {
      vivo = false;
      window.clearTimeout(timer);
    };
  }, [rt, listId, id, epgId, getProvider]);

  // O resultado só vale para o canal focado agora; entre a troca de foco e a
  // resposta, quem pergunta não recebe o dado do canal anterior.
  return dados?.channelId === id ? dados : null;
}

/**
 * "Agora / a seguir" de um canal fixo (o player ao vivo), só do EPG local.
 * Re-consulta no virar de cada minuto para o programa "virar" quando termina.
 */
export function useEpgNow(
  listId: string,
  channelId: string | undefined,
): { now?: EpgEntry; next?: EpgEntry } | null {
  const rt = useRuntime();
  const [dados, setDados] = useState<{
    channelId: string;
    now?: EpgEntry;
    next?: EpgEntry;
  } | null>(null);

  useEffect(() => {
    // sem canal, o guard do retorno já devolve null — nada a fazer aqui
    if (!channelId || !listId) return;
    let vivo = true;
    const buscar = () =>
      void rt
        .epg(listId)
        .nowNext(channelId)
        .then((r) => {
          if (!vivo) return;
          setDados({
            channelId,
            ...(r.now ? { now: r.now } : {}),
            ...(r.next ? { next: r.next } : {}),
          });
        });
    buscar();
    const timer = window.setInterval(buscar, 60_000);
    return () => {
      vivo = false;
      window.clearInterval(timer);
    };
  }, [rt, listId, channelId]);

  return dados?.channelId === channelId ? dados : null;
}

const MAPA_VAZIO = new Map<string, EpgEntry>();

/**
 * Programa no ar de **todos** os canais da lista, numa consulta só (D-23).
 * Recarrega no virar do minuto. `enabled` desligado devolve o mapa vazio sem
 * tocar no banco.
 */
export function useEpgNowForList(
  listId: string,
  enabled: boolean,
): Map<string, EpgEntry> {
  const rt = useRuntime();
  const [mapa, setMapa] = useState<Map<string, EpgEntry>>(MAPA_VAZIO);

  useEffect(() => {
    if (!enabled || !listId) return;
    let vivo = true;
    const buscar = () =>
      void rt
        .epg(listId)
        .nowForList()
        .then((m) => {
          if (vivo) setMapa(m);
        });
    buscar();
    const timer = window.setInterval(buscar, 60_000);
    return () => {
      vivo = false;
      window.clearInterval(timer);
    };
  }, [rt, listId, enabled]);

  return enabled ? mapa : MAPA_VAZIO;
}

/** `20:15` — horário de um programa, no fuso do aparelho. */
export function hora(epochMs: number): string {
  const d = new Date(epochMs);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${pad(d.getHours())}:${pad(d.getMinutes())}`;
}
