import { create } from 'zustand';
import { getCurrentFocusKey } from '@noriginmedia/norigin-spatial-navigation';

// Pilha de navegação própria (plan.md §Navegação D-pad): não depender do history
// do browser — nas cascas de TV ele não existe de forma confiável. `Back` do
// controle desempilha; na raiz, o app pede confirmação de saída.

export type RouteName =
  | 'home'
  | 'live'
  | 'movies'
  | 'series'
  | 'favorites'
  | 'settings'
  | 'search'
  | 'manageLists'
  | 'movieDetail'
  | 'seriesDetail'
  | 'player';

/**
 * Seções do cabeçalho (as demais são telas empilhadas sobre a seção atual).
 * `search` também tem um item no cabeçalho, mas não conta como "seção" para o
 * boot→última-seção (RF-56) — abrir o app direto na Busca vazia não faz sentido.
 */
export const HEADER_SECTIONS = [
  'home',
  'live',
  'movies',
  'series',
  'favorites',
  'settings',
] as const satisfies readonly RouteName[];

/** Toda rota que o cabeçalho realça — inclui a Busca. */
const REALCE_CABECALHO = new Set<RouteName>([...HEADER_SECTIONS, 'search']);

/**
 * Seção do cabeçalho em que o usuário está, mesmo dentro de um detalhe ou do
 * player. `current.name` sozinho vira `movieDetail`/`player` e o realce some —
 * o usuário perde a noção de onde está. A pilha guarda o caminho: a seção é a
 * entrada mais funda cujo nome é de cabeçalho (o fundo da pilha é sempre uma).
 */
export function secaoDoCabecalho(stack: readonly RouteEntry[]): RouteName {
  for (let i = stack.length - 1; i >= 0; i--) {
    const nome = stack[i]!.name;
    if (REALCE_CABECALHO.has(nome)) return nome;
  }
  return stack[0]?.name ?? 'home';
}

export interface RouteEntry {
  name: RouteName;
  params?: Record<string, string>;
  /** focusKey a restaurar ao voltar para esta entrada. */
  restoreFocus?: string;
}

interface NavState {
  stack: RouteEntry[];
  current: RouteEntry;
  /**
   * Como se chegou na rota atual. Uma tela que recarrega dados na montagem usa
   * isto para não jogar fora o que o usuário escolheu ao **voltar** para ela
   * (gênero, ordenação, busca) — entrar pelo cabeçalho continua recomeçando.
   */
  ultimaAcao: 'push' | 'pop' | 'reset';
  push: (entry: RouteEntry) => void;
  replace: (entry: RouteEntry) => void;
  /** Desempilha. Retorna false se já estava na raiz (nada a fazer). */
  pop: () => boolean;
  /** Volta à raiz mantendo só a primeira entrada. */
  resetTo: (entry: RouteEntry) => void;
}

const ROOT: RouteEntry = { name: 'home' };

export const useNavigation = create<NavState>((set, get) => ({
  stack: [ROOT],
  current: ROOT,
  ultimaAcao: 'reset',
  push: (entry) =>
    set((s) => {
      // Antes de empilhar, anota onde o foco estava: a tela que fica embaixo vai
      // ser desmontada e, ao voltar, é para este item que o foco (e com ele a
      // posição da lista) precisa retornar. Ver `useRestoreFocus`.
      const stack = [...s.stack];
      const topo = stack[stack.length - 1];
      const focoAtual = getCurrentFocusKey();
      if (topo && focoAtual)
        stack[stack.length - 1] = { ...topo, restoreFocus: focoAtual };
      stack.push(entry);
      return { stack, current: entry, ultimaAcao: 'push' };
    }),
  replace: (entry) =>
    set((s) => {
      const stack = [...s.stack.slice(0, -1), entry];
      return { stack, current: entry, ultimaAcao: 'reset' };
    }),
  pop: () => {
    const { stack } = get();
    if (stack.length <= 1) return false;
    const next = stack.slice(0, -1);
    const current = next[next.length - 1] ?? ROOT;
    set({ stack: next, current, ultimaAcao: 'pop' });
    return true;
  },
  resetTo: (entry) => set({ stack: [entry], current: entry, ultimaAcao: 'reset' }),
}));

/**
 * Estamos **voltando** para esta tela, com um foco anotado para restaurar?
 *
 * Telas que recarregam dados na montagem consultam isto para não desfazer o que
 * o usuário tinha escolhido (gênero, categoria, ordenação) nem roubar o foco de
 * volta para o topo — quem devolve o foco nesse caso é o `useRestoreFocus`.
 * Entrar na seção pelo cabeçalho (`resetTo`) continua recomeçando do zero.
 */
export function voltandoComFoco(): boolean {
  const { ultimaAcao, current } = useNavigation.getState();
  return ultimaAcao === 'pop' && current.restoreFocus !== undefined;
}
