import { lazy, Suspense, useEffect, useRef, useState } from 'react';
import { setFocus } from '@noriginmedia/norigin-spatial-navigation';
import type { PlatformAdapter } from '@mfp/platform';
import { MetaRepo, type StoredList } from '@mfp/core';
import {
  initNavigation,
  useLogicalKeys,
  useNavigation,
  type RouteName,
} from './nav/index.js';
import { HEADER_SECTIONS } from './nav/navigationStack.js';
import { useFocusGuard, useRestoreFocus } from './nav/focusGuard.js';
import { handleBack } from './nav/backStack.js';
import {
  AppHeader,
  EmptyState,
  LoadingState,
  ToastViewport,
} from './components/index.js';
import { Onboarding } from './screens/Onboarding.js';
import { Boot } from './screens/Boot.js';
import { AccountExpired } from './screens/AccountExpired.js';
import { CredentialRequired } from './screens/CredentialRequired.js';
import { Home } from './screens/Home.js';
import { LiveChannels } from './screens/LiveChannels.js';
import { Catalog } from './screens/Catalog.js';
import { Favorites } from './screens/Favorites.js';
import { MovieDetail } from './screens/MovieDetail.js';
import { SeriesDetail } from './screens/SeriesDetail.js';
import type { PlayerParams } from './screens/Player.js';

// PERF-22 (spec 002, §2.4): fora do chunk inicial — Home/LiveChannels/Catalog
// são as telas do primeiro pouso (RF-56) e ficam estáticas; estas quatro só
// entram sob navegação explícita do usuário, então o parse/execute delas não
// precisa atrasar `boot:firstPaint`. Exports nomeados: `.then` reembala em
// `{ default }`, que é o que `lazy()` exige.
const AutoConfig = lazy(() =>
  import('./screens/AutoConfig.js').then((m) => ({ default: m.AutoConfig })),
);
const Search = lazy(() =>
  import('./screens/Search.js').then((m) => ({ default: m.Search })),
);
const Settings = lazy(() =>
  import('./screens/Settings.js').then((m) => ({ default: m.Settings })),
);
const ManageLists = lazy(() =>
  import('./screens/ManageLists.js').then((m) => ({ default: m.ManageLists })),
);
const Player = lazy(() =>
  import('./screens/Player.js').then((m) => ({ default: m.Player })),
);
import { RuntimeProvider, useRuntime } from './runtime/RuntimeContext.js';
import type { Runtime } from './runtime/runtime.js';
import { useProvider } from './runtime/useProvider.js';
import { useLists } from './state/lists.js';
import { useCatalog } from './state/catalog.js';
import { useSettings } from './state/settings.js';
import { useSync } from './state/sync.js';
import { useEpg } from './state/epg.js';
import { useSession } from './state/session.js';
import { useParental } from './state/parental.js';
import { t } from './i18n/index.js';

export interface AppProps {
  /** Implementação da plataforma, injetada na raiz de cada apps/<plataforma>. */
  adapter: PlatformAdapter;
  /**
   * Chamado uma vez com o runtime recém-criado. A casca usa para publicar
   * `globalThis.__auraPerf` ao roteiro de medição (spec 002), nunca em release.
   */
  onRuntime?: (rt: Runtime) => void;
}

export function App({ adapter, onRuntime }: AppProps) {
  return (
    <RuntimeProvider adapter={adapter} onRuntime={onRuntime}>
      <AppInner adapter={adapter} />
    </RuntimeProvider>
  );
}

function AppInner({ adapter }: Readonly<AppProps>) {
  const rt = useRuntime();
  const pop = useNavigation((s) => s.pop);
  const { loaded, lists, activeListId, load } = useLists();
  const backArmedAt = useRef(0);
  const [exitHint, setExitHint] = useState(false);

  useEffect(() => {
    initNavigation(); // idempotente; o main.tsx já chamou antes do 1º render
    void load(rt);
  }, [rt, load]);

  useLogicalKeys(adapter, {
    Back: () => {
      // um overlay aberto (modal de PIN, por exemplo) tem a primeira palavra
      if (handleBack()) return;
      if (pop()) return;
      const now = Date.now();
      if (now - backArmedAt.current < 2500) {
        adapter.exitApp();
        return;
      }
      backArmedAt.current = now;
      setExitHint(true);
      window.setTimeout(() => setExitHint(false), 2500);
    },
  });

  const activeList = lists.find((l) => l.id === activeListId);

  let body: React.ReactNode;
  if (!loaded) {
    body = <LoadingState label={t('boot.starting')} />;
  } else if (!activeList) {
    body = (
      <main className="scroll-page safe-area">
        <Onboarding onDone={() => setFocus('header-home')} />
      </main>
    );
  } else {
    // A chave inclui servidor e usuário: editar as credenciais da lista ativa
    // (Gerenciar listas) apaga o cache e precisa refazer boot + sync — sem isto
    // o `ActiveList` não remontava e ficava com o catálogo vazio até o timer.
    body = (
      <ActiveList
        key={`${activeList.id}:${activeList.serverUrl}:${activeList.username}`}
        list={activeList}
        adapter={adapter}
      />
    );
  }

  return (
    <>
      {body}
      <ToastViewport />
      {exitHint && (
        <div
          role="status"
          style={{
            position: 'fixed',
            top: 0,
            right: 0,
            bottom: 0,
            left: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            pointerEvents: 'none',
            zIndex: 1000,
          }}
        >
          <div
            style={{
              background: 'var(--bg-panel)',
              border: '1px solid var(--border-strong)',
              borderRadius: 'var(--radius-lg)',
              boxShadow: '0 1rem 3rem rgba(0, 0, 0, 0.5)',
              padding: '1.6rem 3rem',
              maxWidth: '80vw',
              textAlign: 'center',
              color: 'var(--text-primary)',
              fontSize: 'var(--fs-title)',
              fontWeight: 600,
            }}
          >
            {t('exitDialog.message')}
          </div>
        </div>
      )}
    </>
  );
}

type Phase = 'boot' | 'ready' | 'expired' | 'credencial-necessaria' | 'servidor-fora';

/** Chave em `meta` da seção do cabeçalho visitada por último, por lista. */
const ULTIMA_SECAO = 'ui.lastSection';

/** A rota é uma das seções do cabeçalho (as demais são telas empilhadas)? */
const ehSecao = (nome: string): nome is RouteName =>
  (HEADER_SECTIONS as readonly string[]).includes(nome);

/** Alvo de foco preferido de cada rota, para o guarda de foco (§7). */
const ROUTE_FOCUS: Record<RouteName, readonly string[]> = {
  home: ['home-hero', 'home-continue'],
  live: ['live-cats'],
  movies: ['catalog-grid'],
  series: ['catalog-grid'],
  favorites: ['fav-grid', 'fav-tabs'], // a grade daqui não é a `catalog-grid`
  settings: [],
  search: ['search-kb'], // o teclado desta tela; `catalog-kb` é o do catálogo
  manageLists: ['lists-add', 'onboarding-field-serverUrl'],
  movieDetail: ['detail-watch'],
  seriesDetail: ['series-play'],
  player: ['player-playpause'],
};

/** Ciclo de vida de uma lista ativa: boot → (expirada | pronta). Remonta ao trocar. */
function ActiveList({
  list,
  adapter,
}: Readonly<{ list: StoredList; adapter: PlatformAdapter }>) {
  const rt = useRuntime();
  const currentRoute = useNavigation((s) => s.current);
  const current = currentRoute.name;
  const removeList = useLists((s) => s.removeList);
  const loadSettings = useSettings((s) => s.load);
  const getProvider = useProvider();
  const runSync = useSync((s) => s.run);
  const loadParental = useParental((s) => s.load);
  const [phase, setPhase] = useState<Phase>('boot');
  /** Muda a cada autoconfiguração bem-sucedida, para o `Boot` refazer tudo. */
  const [tentativa, setTentativa] = useState(0);
  const [visible, setVisible] = useState(true);

  // Voltar de um detalhe/player devolve o foco ao item de onde se saiu — as
  // listas, que guardam a própria posição por conteúdo, reabrem ali em vez de
  // no topo. Se o item não existir mais, o guarda abaixo assume.
  useRestoreFocus(currentRoute.restoreFocus, [currentRoute, phase]);

  // rede de segurança: nenhuma rota pode ficar sem foco (ver focusGuard.ts).
  // O primeiro alvo de cada rota é o mesmo que a tela tenta focar sozinha — o
  // guarda só entra quando aquele `setFocus` perdeu a corrida com o commit.
  useFocusGuard([...ROUTE_FOCUS[current], 'header-home'], [current, phase]);

  // Boot → última seção usada (RF-56). Só uma vez, ao ficar pronto: depois disso
  // quem manda é a navegação. Gravar acontece abaixo, a cada seção visitada.
  const secaoRestaurada = useRef(false);
  useEffect(() => {
    if (phase !== 'ready' || secaoRestaurada.current) return;
    secaoRestaurada.current = true;
    void new MetaRepo(rt.db, list.id).get<RouteName>(ULTIMA_SECAO).then((secao) => {
      if (secao && secao !== 'home' && ehSecao(secao)) {
        useNavigation.getState().resetTo({ name: secao });
      }
    });
  }, [phase, rt, list.id]);

  useEffect(() => {
    if (phase !== 'ready') return;
    if (!ehSecao(current)) return;
    void new MetaRepo(rt.db, list.id).set(ULTIMA_SECAO, current);
  }, [phase, current, rt, list.id]);

  // RP-1 (spec 002): "Home interativa" = catálogo em mãos. Mora aqui, não na
  // tela Home, porque o RF-56 acima costuma redirecionar para fora da Home
  // antes de `loadHome` terminar — medido no aparelho: a Home montava, disparava
  // a carga, e o RF-56 trocava para "TV ao vivo" antes da contagem chegar a
  // >0; como o efeito da Home só reage enquanto ela está montada, a marca nunca
  // saía para quem não pousa na Home. Aqui em cima ela sobrevive ao redirect.
  const totalCatalogo = useCatalog((s) => s.counts.vod + s.counts.series + s.counts.live);
  useEffect(() => {
    if (phase === 'ready' && totalCatalogo > 0)
      rt.perf.marcarUnica('boot:homeInteractive');
  }, [phase, totalCatalogo, rt]);

  useEffect(() => adapter.onVisibilityChange(setVisible), [adapter]);
  useEffect(() => {
    void loadSettings(rt);
    // A política de conteúdo precisa valer desde o primeiro render: se só
    // carregasse ao abrir Configurações, o catálogo já teria sido lido sem o
    // filtro e o conteúdo bloqueado apareceria até alguém visitar a tela.
    void loadParental(rt);
  }, [rt, loadSettings, loadParental]);

  // Índice de palavras da busca (RF-42). Quem já tinha catálogo antes desta
  // versão tem dezenas de milhares de linhas sem `words`, e sem elas a busca cai
  // na varredura da tabela inteira (5,5s medidos com 54.535 linhas). Preenche em
  // blocos, depois do boot, cedendo a thread entre eles; até terminar, a busca
  // continua funcionando pelo caminho antigo.
  useEffect(() => {
    if (phase !== 'ready') return;
    void rt
      .search(list.id)
      .garantirIndiceDePalavras()
      .then((n) => {
        if (n > 0) rt.logger.info('índice de palavras preenchido', { linhas: n });
      })
      .catch((err: unknown) => {
        rt.logger.warn('falha ao preencher o índice de palavras', { err: String(err) });
      });
  }, [phase, rt, list.id]);

  // `norm` em movies/series (PERF-01b / spec 002 — esquema v4). Mesma ideia
  // do índice de palavras acima: quem já tinha catálogo antes desta versão
  // não tem `norm`, e sem ele "Todos" ordenado por nome cai no caminho antigo
  // (materializa + ordena em memória) até o próximo sync completo reescrever
  // cada linha. Preenche em blocos, depois do boot, cedendo a thread entre
  // eles — até terminar, a ordenação por nome continua funcionando, só não
  // pelo caminho rápido.
  useEffect(() => {
    if (phase !== 'ready') return;
    void rt
      .catalog(list.id)
      .garantirNorm()
      .then((n) => {
        if (n > 0) rt.logger.info('índice de nome preenchido', { linhas: n });
      })
      .catch((err: unknown) => {
        rt.logger.warn('falha ao preencher o índice de nome', { err: String(err) });
      });
  }, [phase, rt, list.id]);

  // auto-refresh de catálogo a cada 12h (RF-65) — o timer vive no adapter/ui
  useEffect(() => {
    if (phase !== 'ready') return;
    const id = window.setInterval(
      () => {
        void (async () => {
          const { provider, listId } = await getProvider();
          await runSync(rt, listId, provider);
          const tz = useSession.getState().account?.serverTimezone;
          await useEpg.getState().run(rt, listId, provider, tz);
        })();
      },
      12 * 3600 * 1000,
    );
    return () => window.clearInterval(id);
  }, [phase, rt, getProvider, runSync]);

  if (phase === 'expired') {
    return (
      <main className="safe-area">
        <AccountExpired onSwitch={() => void removeList(rt, list.id)} />
      </main>
    );
  }

  if (phase === 'credencial-necessaria') {
    return (
      <main className="safe-area">
        <CredentialRequired
          list={list}
          onOk={() => {
            setTentativa((n) => n + 1);
            setPhase('boot');
          }}
          onEsquecerLista={() => void removeList(rt, list.id)}
        />
      </main>
    );
  }

  if (phase === 'servidor-fora') {
    return (
      <main className="safe-area">
        <Suspense fallback={<LoadingState />}>
          <AutoConfig
            list={list}
            onSucesso={() => {
              // servidor já trocado: refaz o boot inteiro (auth + sync) com o novo
              setTentativa((n) => n + 1);
              setPhase('boot');
            }}
            // desistiu: segue com o cache, que é o comportamento de sempre
            onDesistir={() => {
              setPhase('ready');
              setFocus('header-home');
            }}
          />
        </Suspense>
      </main>
    );
  }

  if (phase === 'boot') {
    return (
      <main className="safe-area">
        <Boot
          key={tentativa}
          list={list}
          onReady={() => {
            setPhase('ready');
            setFocus('header-home');
          }}
          onExpired={() => setPhase('expired')}
          onCredencialNecessaria={() => setPhase('credencial-necessaria')}
          onServidorInacessivel={() => setPhase('servidor-fora')}
        />
      </main>
    );
  }

  if (current === 'player' && currentRoute.params) {
    return (
      <Suspense fallback={<LoadingState />}>
        <Player
          adapter={adapter}
          params={currentRoute.params as unknown as PlayerParams}
        />
      </Suspense>
    );
  }

  return (
    <div className="app-shell">
      <AppHeader />
      <main className="scroll-fill safe-area">
        {!visible ? (
          <EmptyState title={t('app.name')} body="" />
        ) : (
          <Suspense fallback={<LoadingState />}>
            {renderScreen(current, currentRoute.params, list.id)}
          </Suspense>
        )}
      </main>
    </div>
  );
}

function renderScreen(
  name: string,
  params: Record<string, string> | undefined,
  listId: string,
) {
  switch (name) {
    case 'home':
      return <Home listId={listId} />;
    case 'live':
      return <LiveChannels listId={listId} />;
    case 'movies':
      return <Catalog listId={listId} section="vod" />;
    case 'series':
      return <Catalog listId={listId} section="series" />;
    case 'favorites':
      return <Favorites listId={listId} />;
    case 'search':
      return <Search listId={listId} />;
    case 'settings':
      return <Settings listId={listId} />;
    case 'manageLists':
      return <ManageLists />;
    case 'movieDetail':
      return <MovieDetail id={params?.id ?? ''} listId={listId} />;
    case 'seriesDetail':
      return <SeriesDetail id={params?.id ?? ''} listId={listId} />;
    default:
      return <EmptyState title={t('nav.settings')} body={t('states.emptyBody')} />;
  }
}
