/**
 * Policy de cache para detalhe com TTL e stale-while-revalidate (GTV-RF-24/25).
 * Spec 004 M5: cache válido não dispara atualização bloqueante; cache expirado
 * mostra imediatamente e revalida no background.
 */

export interface DetailCachePolicy {
  /** TTL em ms. Proposto: 24h. */
  ttlMs: number;
  /** Tempo após expiration antes de forçar revalidação (ms). */
  staleWhileRevalidateMs: number;
}

export const DEFAULT_DETAIL_CACHE_POLICY: DetailCachePolicy = {
  ttlMs: 24 * 60 * 60 * 1000, // 24h
  staleWhileRevalidateMs: 7 * 24 * 60 * 60 * 1000, // 7 dias
};

export interface CachedDetail<T> {
  data: T;
  cachedAt: number; // timestamp do cache
}

/**
 * Estado de um detalhe: local (seed do catálogo), cache, ou rede.
 */
export type DetailState<T> =
  | { kind: 'seed'; data: T } // Dados locais (CatalogRepo)
  | { kind: 'cached'; data: T; isStale: boolean } // Cache: fresco ou stale
  | { kind: 'loading'; data: T | null } // Carregando (com ou sem fallback)
  | { kind: 'error'; data: T | null; error: Error }; // Erro com fallback opcional

/**
 * Resolve o estado de um detalhe baseado em timestamps e policy.
 */
export function resolveDetailState<T>(
  seed: T | null,
  cached: CachedDetail<T> | null,
  policy: DetailCachePolicy,
  now: number = Date.now(),
): DetailState<T> {
  // Prioridade: seed (local) > cache > nothing
  if (seed) return { kind: 'seed', data: seed };
  if (!cached) return { kind: 'loading', data: null };

  const age = now - cached.cachedAt;
  const isStale = age > policy.ttlMs; // Stale após TTL

  return {
    kind: 'cached',
    data: cached.data,
    isStale,
  };
}

/**
 * Decide se devemos buscar rede para um detalhe.
 * - Cache fresco (< TTL): não busca
 * - Cache expirado mas stale-while-revalidate válido: mostra + revalida
 * - Completamente expirado: busca obrigatório
 */
export function shouldFetchDetail<T>(
  state: DetailState<T>,
  policy: DetailCachePolicy,
): { fetch: boolean; blockUI: boolean } {
  switch (state.kind) {
    case 'seed':
      // Dados locais (seed) nunca requerem busca de rede
      return { fetch: false, blockUI: false };
    case 'cached':
      // Cache fresco não busca; cache stale busca background
      return { fetch: state.isStale, blockUI: false };
    case 'loading':
      // Já está buscando
      return { fetch: false, blockUI: !state.data };
    case 'error':
      // Erro com fallback: não busca mais
      return { fetch: false, blockUI: !state.data };
  }
}
