import { categoryLabel, type CatalogSection } from '@mfp/core';
import { BalanceLoader } from './BalanceLoader.js';
import { SYNC_SECTIONS, type SectionProgress } from '../state/sync.js';
import { t, type TextKey } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';
import { cssLen } from '../theme/cssMath.js';

/**
 * Tela de progresso do sync inicial (D-24): o balanço Aura 67 + uma barra por
 * seção do catálogo (canais, filmes, séries), enchendo conforme cada uma baixa.
 * Antes era um contador único que resetava a cada seção e parecia travar.
 */

const ROTULO: Record<CatalogSection, TextKey> = {
  live: 'nav.live',
  vod: 'nav.movies',
  series: 'nav.series',
};

export function SyncProgress({
  sections,
  firstRun,
}: Readonly<{
  sections: Record<CatalogSection, SectionProgress>;
  firstRun: boolean;
}>) {
  return (
    <div className="sync-progress safe-area">
      <BalanceLoader />

      <div>
        <h2 style={{ margin: 0 }}>{t('boot.preparing')}</h2>
        {firstRun && (
          <p style={{ color: 'var(--text-secondary)', margin: '0.4em 0 0' }}>
            {t('boot.firstSyncHint')}
          </p>
        )}
      </div>

      <div
        className={gapColClass}
        style={{
          display: 'flex',
          flexDirection: 'column',
          width: cssLen('min(38rem, 80vw)'),
          ...gapVar('1.1rem'),
        }}
      >
        {SYNC_SECTIONS.map((s) => (
          <SectionBar key={s} secao={s} rotulo={t(ROTULO[s])} p={sections[s]} />
        ))}
      </div>
    </div>
  );
}

/** Texto à direita da barra: "✓" / "aguardando" / "Ação · 12/28". */
function statusTexto(p: SectionProgress, secao: CatalogSection): string {
  if (p.status === 'done') return '✓';
  // LG-022: parou por cota antes de começar esta seção — o retry mora nas
  // telas de catálogo (EmptyState + botão), aqui só evita "aguardando" eterno.
  if (p.status === 'stalled') return '—';
  if (p.status === 'pending') return t('boot.waiting');
  const contagem = p.total > 0 ? `${p.done}/${p.total}` : t('common.loading');
  // tira o prefixo "Canais | " / "Filmes | " como nas outras telas
  const cat = p.categoria ? categoryLabel(p.categoria, secao) : '';
  return cat ? `${cat} · ${contagem}` : contagem;
}

const OPACIDADE: Record<SectionProgress['status'], number> = {
  pending: 0.4,
  active: 1,
  done: 0.65,
  stalled: 0.4,
};

function fracao(p: SectionProgress): number {
  if (p.status === 'done') return 1;
  return p.total > 0 ? p.done / p.total : 0;
}

function SectionBar({
  secao,
  rotulo,
  p,
}: Readonly<{ secao: CatalogSection; rotulo: string; p: SectionProgress }>) {
  const frac = fracao(p);

  return (
    <div
      style={{
        textAlign: 'left',
        opacity: OPACIDADE[p.status],
        transition: 'opacity 300ms',
      }}
    >
      <div
        className={gapRowClass}
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'baseline',
          marginBottom: '0.35rem',
          ...gapVar('1rem'),
        }}
      >
        <span
          style={{
            fontFamily: 'var(--font-display)',
            textTransform: 'uppercase',
            letterSpacing: '0.03em',
          }}
        >
          {rotulo}
        </span>
        <span
          style={{
            fontSize: 'var(--fs-meta)',
            color: 'var(--text-secondary)',
            whiteSpace: 'nowrap',
            minWidth: 0,
            overflow: 'hidden',
            textOverflow: 'ellipsis',
          }}
        >
          {statusTexto(p, secao)}
        </span>
      </div>

      <div
        style={{
          height: '0.5rem',
          borderRadius: '999px',
          background: 'var(--bg-raised)',
          overflow: 'hidden',
        }}
      >
        <div
          style={{
            width: `${Math.round(frac * 100)}%`,
            height: '100%',
            background: 'var(--accent)',
            borderRadius: '999px',
            transition: 'width 400ms ease-out',
          }}
        />
      </div>
    </div>
  );
}
