import { FocusContext, useFocusable } from '@noriginmedia/norigin-spatial-navigation';
import { pressWithFocus } from '../nav/pressWithFocus.js';
import { gapRowClass, gapVar } from '../theme/gap.js';

export interface Chip {
  id: string;
  label: string;
}

export interface GenreChipsProps {
  chips: Chip[];
  selectedId: string;
  onSelect: (id: string) => void;
  focusKey: string;
  /**
   * Sobrescreve a navegação D-pad dos chips numa direção (ex.: 'up' para
   * alcançar um container estreito acima — dropdown/campo de busca — que a
   * resolução geométrica padrão do norigin pula em favor de um container mais
   * largo, como o cabeçalho do app. Ver a nota em `Catalog.tsx`).
   */
  onArrowPress?: (direction: string) => boolean;
}

/** Filtro por gênero/categoria (telas 04/06). Rola na horizontal com o foco. */
export function GenreChips({
  chips,
  selectedId,
  onSelect,
  focusKey,
  onArrowPress,
}: GenreChipsProps) {
  const { ref, focusKey: fk } = useFocusable({ focusKey, trackChildren: true });
  return (
    <FocusContext.Provider value={fk}>
      <div
        ref={ref}
        data-scroll-x
        className={gapRowClass}
        style={{
          display: 'flex',
          padding: '0.3rem 0.2rem',
          ...gapVar('0.6rem'),
        }}
      >
        {chips.map((chip) => (
          <ChipButton
            key={chip.id}
            chip={chip}
            selected={chip.id === selectedId}
            onSelect={() => onSelect(chip.id)}
            focusKey={`${focusKey}-${chip.id}`}
            onArrowPress={onArrowPress}
          />
        ))}
      </div>
    </FocusContext.Provider>
  );
}

function ChipButton({
  chip,
  selected,
  onSelect,
  focusKey,
  onArrowPress,
}: {
  chip: Chip;
  selected: boolean;
  onSelect: () => void;
  focusKey: string;
  onArrowPress?: (direction: string) => boolean;
}) {
  const { ref, focused } = useFocusable({
    focusKey,
    onEnterPress: onSelect,
    ...(onArrowPress ? { onArrowPress: (direction: string) => onArrowPress(direction) } : {}),
  });
  return (
    <button
      ref={ref}
      type="button"
      onClick={pressWithFocus(focusKey, onSelect)}
      style={{
        appearance: 'none',
        border: '1px solid var(--border-subtle)',
        cursor: 'pointer',
        whiteSpace: 'nowrap',
        flexShrink: 0,
        font: 'inherit',
        fontSize: 'var(--fs-meta)',
        fontWeight: 600,
        textTransform: 'uppercase',
        letterSpacing: '0.03em',
        padding: '0.4em 1em',
        borderRadius: 999,
        color: selected
          ? 'var(--text-on-accent)'
          : focused
            ? 'var(--text-primary)'
            : 'var(--text-secondary)',
        background: selected ? 'var(--accent)' : 'var(--bg-raised)',
        outline: focused
          ? 'var(--focus-ring-width) solid var(--focus-ring)'
          : 'var(--focus-ring-width) solid transparent',
        transform: focused ? 'scale(1.05)' : 'scale(1)',
        transition: 'transform 160ms',
      }}
    >
      {chip.label}
    </button>
  );
}
