import { useEffect } from 'react';
import {
  doesFocusableExist,
  getCurrentFocusKey,
  setFocus,
} from '@noriginmedia/norigin-spatial-navigation';

/**
 * PERF-13 (spec 002): observa o DOM em vez de espiar de 150 em 150ms sem
 * parar. O alvo quase sempre resolve no 1º quadro pós-commit (o `requestAnimationFrame`
 * abaixo) ou assim que o elemento entra no DOM (o `MutationObserver`) — o
 * registro do `useFocusable` do norigin é outro efeito que roda logo depois
 * do node aparecer, por isso o `queueMicrotask` antes de checar. O polling de
 * 150ms continua existindo, mas só como rede de segurança de ÚLTIMO recurso
 * (mesmo teto de tentativas de antes), pro caso raro de um registro sem
 * mutação de DOM correspondente.
 */
function observarAteResolver(
  tentar: () => boolean,
  tetoPollingMs: number,
  /** Chamado sempre que a observação para — por sucesso ou por desistência. */
  aoParar?: () => void,
): () => void {
  let terminado = false;
  const raf = requestAnimationFrame(() => {
    if (!terminado && tentar()) parar();
  });

  const observer = new MutationObserver(() => {
    if (terminado) return;
    queueMicrotask(() => {
      if (!terminado && tentar()) parar();
    });
  });
  observer.observe(document.body, { childList: true, subtree: true });

  let tries = 0;
  const intervalMs = 150;
  const maxTries = Math.ceil(tetoPollingMs / intervalMs);
  const id = window.setInterval(() => {
    if (terminado) return;
    if (tentar()) {
      parar();
      return;
    }
    if (++tries >= maxTries) parar();
  }, intervalMs);

  function parar() {
    if (terminado) return;
    terminado = true;
    cancelAnimationFrame(raf);
    observer.disconnect();
    window.clearInterval(id);
    aoParar?.();
  }

  return parar;
}

/**
 * Rede de segurança da navegação por D-pad (constitution §7).
 *
 * Quando uma tela é desmontada (sair do player, fechar um overlay, uma lista que
 * recarrega e troca os itens), o norigin pode ficar sem elemento focado — e aí
 * *nenhuma* tecla move nada: o app parece travado. Medido no device: ao voltar
 * do player para a Início, o foco morria e só reiniciando o app voltava.
 *
 * Cada tela continua responsável pelo seu foco inicial; este hook só age se,
 * depois que o DOM assentou, não existir foco válido.
 *
 * @param fallbackKeys chaves candidatas, da mais específica para a mais genérica.
 * @param deps quando reavaliar (rota, dados carregados…).
 */
export function useFocusGuard(fallbackKeys: readonly string[], deps: unknown[] = []) {
  useEffect(() => {
    const tentar = (): boolean => {
      const current = getCurrentFocusKey();
      if (current && doesFocusableExist(current)) return true;
      const target = fallbackKeys.find((k) => doesFocusableExist(k));
      if (target) {
        void setFocus(target);
        return true;
      }
      return false;
    };
    return observarAteResolver(tentar, 3_000); // ~3s e desiste, igual antes
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
}

/**
 * Devolve o foco para onde ele estava nesta tela, ao voltar de uma rota
 * empilhada (`restoreFocus`, anotado pelo `push`).
 *
 * Voltar de um detalhe **remonta** a tela de baixo, e o foco recomeçaria no
 * primeiro item — a lista saltava para o topo mesmo tendo os dados de antes.
 * Insiste até o alvo existir, porque a célula só volta ao DOM depois que a tela
 * recarrega os dados (a busca por título, medida no aparelho, leva ~7s para
 * repovoar as trilhas). Para na primeira vez que consegue — e desiste na hora
 * se o usuário mexer antes disso: daí em diante o comando é dele.
 */
export function useRestoreFocus(focusKey: string | undefined, deps: unknown[] = []) {
  useEffect(() => {
    if (!focusKey) return;
    const tentar = (): boolean => {
      if (!doesFocusableExist(focusKey)) return false;
      void setFocus(focusKey);
      return true;
    };

    const removerListeners = () => {
      window.removeEventListener('keydown', pararTudo, true);
      window.removeEventListener('pointerdown', pararTudo, true);
    };
    // `aoParar`: a observação também termina sozinha (sucesso ou desistência
    // do teto) — sem isto os listeners de "usuário mexeu" ficariam presos
    // até a tela desmontar, mesmo depois de já ter resolvido.
    const pararObservacao = observarAteResolver(tentar, 9_000, removerListeners); // ~9s e desiste, igual antes
    function pararTudo() {
      pararObservacao();
      removerListeners();
    }
    // o usuário mexer antes de resolver cancela — daí em diante o comando é dele
    window.addEventListener('keydown', pararTudo, true);
    window.addEventListener('pointerdown', pararTudo, true);
    return pararTudo;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
}
