// Ajustes de aparência aplicados no elemento raiz (decisions D-4). Persistência
// real (por perfil) entra com o store de configurações; aqui só o efeito no DOM.

const DEFAULT_ACCENT = '#e53935';

/** Troca só o token `--accent` (e derivados) — cor de destaque configurável. */
export function setAccentColor(hex: string | null) {
  const root = document.documentElement;
  if (!hex) {
    root.style.removeProperty('--accent');
    root.style.removeProperty('--accent-hover');
    root.style.removeProperty('--accent-press');
    root.style.removeProperty('--focus-ring-armed');
    root.style.removeProperty('--live');
    root.style.removeProperty('--danger');
    return;
  }
  root.style.setProperty('--accent', hex);
  root.style.setProperty('--accent-hover', lighten(hex, 0.15));
  root.style.setProperty('--accent-press', lighten(hex, -0.15));
  root.style.setProperty('--focus-ring-armed', hex);
  root.style.setProperty('--live', hex);
  root.style.setProperty('--danger', hex);
}

export function setHighContrast(on: boolean) {
  document.documentElement.dataset['contrast'] = on ? 'high' : '';
}

export function setReducedMotion(on: boolean) {
  document.documentElement.dataset['motion'] = on ? 'reduced' : '';
}

export { DEFAULT_ACCENT };

function lighten(hex: string, amount: number): string {
  const m = /^#?([\da-f]{2})([\da-f]{2})([\da-f]{2})$/i.exec(hex.trim());
  if (!m) return hex;
  const clamp = (n: number) => Math.max(0, Math.min(255, Math.round(n)));
  const ch = (i: 1 | 2 | 3) => {
    const v = parseInt(m[i] as string, 16);
    return clamp(amount >= 0 ? v + (255 - v) * amount : v * (1 + amount));
  };
  const hx = (n: number) => n.toString(16).padStart(2, '0');
  return `#${hx(ch(1))}${hx(ch(2))}${hx(ch(3))}`;
}
