import { useEffect } from 'react';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useProvider } from '../runtime/useProvider.js';
import { useLive } from './live.js';
import { useEpg } from './epg.js';
import { useSession } from './session.js';

/**
 * Enfileira a leitura completa do EPG (GTV-RF-31 / M6) depois que a primeira
 * lista de canais foi pintada, não durante o boot nem bloqueando navegação.
 *
 * A menos que o panel tenha mudado muito desde M6, o XMLTV fica pronto antes
 * da lista ser útil — aqui a gente só garante que as teclas funcionam antes
 * do EPG começar a pesar.
 *
 * O agendamento é cancelado ao sair; uma ingestão já iniciada é compartilhada
 * com o boot/timer e termina em segundo plano.
 */
export function useEpgBackground(listId: string): void {
  const rt = useRuntime();
  const hasChannels = useLive((s) => s.channels.length > 0);
  const getProvider = useProvider();
  const runEpg = useEpg((s) => s.run);
  const serverTz = useSession((s) => s.account?.serverTimezone);

  useEffect(() => {
    // Só dispara se houver canais — é o marker de "primeira lista pintada"
    if (!hasChannels) return;

    // AbortController para cancelar se o usuário navegar para fora de Live
    const ctrl = new AbortController();
    let rodando = true;

    (async () => {
      try {
        // Aguarda um pouco para o realce de canais estabilizar
        await new Promise<void>((r) => {
          const timer = setTimeout(r, 300);
          ctrl.signal.addEventListener('abort', () => {
            clearTimeout(timer);
            r();
          });
        });

        if (!rodando) return;

        const { provider } = await getProvider();
        if (!rodando) return;
        // A promessa cobre download + ingestão; run compartilha a operação
        // se o boot ou o timer já a iniciou para esta lista.
        await runEpg(rt, listId, provider, serverTz);
      } catch {
        // Ignorar erro (network, cancelled, etc.) — EPG é "enfeite" (epg.ts)
      }
    })();

    return () => {
      rodando = false;
      ctrl.abort();
    };
  }, [hasChannels, listId, rt, getProvider, runEpg, serverTz]);
}
