import { memo } from 'react';
import { AgeBadge, ProgressBar, QualityBadge } from './badges.js';
import { focusRing } from '../nav/focusRing.js';
import { Poster } from '../media/Poster.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';

export interface PosterCardData {
  title: string;
  poster?: string;
  meta?: string;
  ageRating?: string;
  quality?: '4K' | 'HDR' | 'DUAL' | 'LEG';
  progress?: number; // 0..1
}

/**
 * Cartão de pôster ~2:3 (design-inventory §Grid). Usado em trilhas e grades.
 * Memoizado (PERF-09 / spec 002): é a folha mais repetida da UI (20-40
 * instâncias por tela) — em cima do `GridCell`/`RowCell` já memoizados, é
 * defesa a mais caso algum chamador reconstrua `data` sem necessidade.
 */
export const PosterCard = memo(function PosterCard({
  data,
  focused,
  prioridade = 0,
}: {
  data: PosterCardData;
  focused: boolean;
  /** Ver `Poster` (PERF-16) — menor é mais urgente na fila de carregamento. */
  prioridade?: number;
}) {
  return (
    <div
      style={{
        position: 'relative',
        width: '100%',
        height: '100%',
        borderRadius: 'var(--radius-sm)',
        overflow: 'hidden',
        background: 'var(--bg-panel)',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'flex-end',
        ...focusRing(focused),
      }}
    >
      {/* Iniciais por baixo do pôster (dentro do `Poster`): o cartão já nasce
          com identidade e a imagem entra por cima quando a fila (PERF-16)
          libera a vaga. Também é o que sobra quando o painel não tem pôster
          ou a URL falha — antes ficava um retângulo vazio. */}
      <Poster url={data.poster} titulo={data.title} prioridade={prioridade} />

      <div
        className={gapColClass}
        style={{
          position: 'relative', // acima das camadas absolutas do Poster
          padding: '0.5rem',
          background: 'linear-gradient(transparent, rgba(0,0,0,0.85))',
          display: 'flex',
          flexDirection: 'column',
          ...gapVar('0.25rem'),
        }}
      >
        <div className={gapRowClass} style={{ display: 'flex', ...gapVar('0.3rem') }}>
          {data.ageRating && <AgeBadge rating={data.ageRating} />}
          {data.quality && <QualityBadge label={data.quality} />}
        </div>
        <strong style={{ fontSize: 'var(--fs-meta)', lineHeight: 1.2 }}>
          {data.title}
        </strong>
        {data.meta && (
          <span style={{ fontSize: '0.8em', color: 'var(--text-secondary)' }}>
            {data.meta}
          </span>
        )}
        {data.progress != null && <ProgressBar value={data.progress} />}
      </div>
    </div>
  );
});
