import { create } from 'zustand';
import { passwordKey, type Runtime } from '../runtime/runtime.js';
import { encodePin, isValidPin, tempoConstante, verifyPin } from '../util/pin.js';

// Controle parental (RF-31..34 / decisions D-8). Independente de perfis: o M8c
// (perfis, `maxRating`, "Quem está assistindo?") segue pós-MVP — aqui é só o
// bloqueio de categorias adultas com desbloqueio por PIN.

const CHAVE_PIN = 'parental.pin';
const CHAVE_LIGADO = 'parental.enabled';

/** 3 tentativas erradas → 60s de espera (RF-32). */
const MAX_TENTATIVAS = 3;
const ESPERA_MS = 60_000;

interface ParentalState {
  carregado: boolean;
  /** O bloqueio está ativo (o usuário configurou um PIN e ligou). */
  ligado: boolean;
  /**
   * Destravado nesta sessão do app. Some ao fechar — é o que o produto pediu:
   * prático para navegar, mas reabrir o app tranca de novo.
   */
  destravado: boolean;
  tentativasRestantes: number;
  /** epoch ms até quando novas tentativas são recusadas; 0 = liberado. */
  bloqueadoAte: number;

  load: (rt: Runtime) => Promise<void>;
  /** Define o PIN e liga o bloqueio. */
  ativar: (rt: Runtime, pin: string) => Promise<boolean>;
  /** Desliga o bloqueio — exige o PIN atual, senão qualquer um contornaria. */
  desativar: (rt: Runtime, pin: string) => Promise<boolean>;
  /** Libera o conteúdo adulto pelo resto da sessão. */
  destravar: (rt: Runtime, pin: string) => Promise<boolean>;
  /** Volta a esconder sem desligar o recurso. */
  travar: (rt: Runtime) => void;
  trocarPin: (rt: Runtime, atual: string, novo: string) => Promise<boolean>;
  /**
   * "Esqueci o PIN": confere a senha da lista Xtream ativa como prova de
   * identidade — é o único segredo que já existe, único por instalação, e
   * nunca aparece em texto claro em nenhuma tela do app (diferente de uma
   * fórmula fixa, que seria igual para todo mundo que instala o app). Só
   * confere; não muda nada — a UI avança para o novo PIN apenas se `true`,
   * em vez de deixar o usuário digitar tudo para só então descobrir o erro.
   */
  verificarSenhaDaLista: (rt: Runtime, listId: string, senha: string) => Promise<boolean>;
  /** Grava o novo PIN após `verificarSenhaDaLista` já ter confirmado a senha. */
  resetarComSenhaDaLista: (
    rt: Runtime,
    listId: string,
    senhaDigitada: string,
    novoPin: string,
  ) => Promise<boolean>;
}

/**
 * A política vive no Runtime porque é lá que os repositórios são criados. Um
 * único ponto de verdade evita o pior erro possível aqui: uma tela lendo o
 * catálogo sem o filtro.
 */
function aplicar(rt: Runtime, ligado: boolean, destravado: boolean) {
  rt.contentPolicy.hideAdult = ligado && !destravado;
}

export const useParental = create<ParentalState>((set, get) => ({
  carregado: false,
  ligado: false,
  destravado: false,
  tentativasRestantes: MAX_TENTATIVAS,
  bloqueadoAte: 0,

  load: async (rt) => {
    const [pin, ligadoStr] = await Promise.all([
      rt.adapter.secureStorage.get(CHAVE_PIN),
      rt.adapter.secureStorage.get(CHAVE_LIGADO),
    ]);
    // sem PIN guardado o recurso não pode estar ligado, aconteça o que acontecer
    const ligado = !!pin && ligadoStr === '1';
    aplicar(rt, ligado, false);
    set({ carregado: true, ligado, destravado: false });
  },

  ativar: async (rt, pin) => {
    if (!isValidPin(pin)) return false;
    await rt.adapter.secureStorage.set(CHAVE_PIN, await encodePin(pin));
    await rt.adapter.secureStorage.set(CHAVE_LIGADO, '1');
    aplicar(rt, true, false);
    set({ ligado: true, destravado: false, tentativasRestantes: MAX_TENTATIVAS });
    return true;
  },

  desativar: async (rt, pin) => {
    if (!(await conferir(rt, pin, set, get))) return false;
    await rt.adapter.secureStorage.set(CHAVE_LIGADO, '0');
    aplicar(rt, false, false);
    set({ ligado: false, destravado: false });
    return true;
  },

  destravar: async (rt, pin) => {
    if (!(await conferir(rt, pin, set, get))) return false;
    aplicar(rt, get().ligado, true);
    set({ destravado: true });
    return true;
  },

  travar: (rt) => {
    aplicar(rt, get().ligado, false);
    set({ destravado: false });
  },

  trocarPin: async (rt, atual, novo) => {
    if (!isValidPin(novo)) return false;
    if (!(await conferir(rt, atual, set, get))) return false;
    await rt.adapter.secureStorage.set(CHAVE_PIN, await encodePin(novo));
    return true;
  },

  verificarSenhaDaLista: (rt, listId, senha) => conferirSenhaDaLista(rt, listId, senha, set, get),

  resetarComSenhaDaLista: async (rt, listId, senhaDigitada, novoPin) => {
    if (!isValidPin(novoPin)) return false;
    if (!(await conferirSenhaDaLista(rt, listId, senhaDigitada, set, get))) return false;

    await rt.adapter.secureStorage.set(CHAVE_PIN, await encodePin(novoPin));
    await rt.adapter.secureStorage.set(CHAVE_LIGADO, '1');
    aplicar(rt, true, false);
    set({ ligado: true, destravado: false });
    return true;
  },
}));

/**
 * Confere a senha da lista contra o valor real guardado no secure storage,
 * aplicando o mesmo limite de tentativas do PIN (RF-32). Usada tanto para só
 * validar (`verificarSenhaDaLista`) quanto como primeiro passo do reset
 * (`resetarComSenhaDaLista`) — nunca duplica a comparação.
 */
async function conferirSenhaDaLista(
  rt: Runtime,
  listId: string,
  senha: string,
  set: (p: Partial<ParentalState>) => void,
  get: () => ParentalState,
): Promise<boolean> {
  if (Date.now() < get().bloqueadoAte) return false;

  const senhaReal = await rt.adapter.secureStorage.get(passwordKey(listId));
  // sem senha guardada (lista removida/senha nunca salva) não dá pra provar
  // identidade nenhuma — recusa em vez de comparar contra vazio
  if (!senhaReal) return false;

  const bateu = tempoConstante(senha, senhaReal);
  aplicarLimiteTentativas(bateu, set, get);
  return bateu;
}

/** Confere o PIN aplicando o limite de tentativas (RF-32). */
async function conferir(
  rt: Runtime,
  pin: string,
  set: (p: Partial<ParentalState>) => void,
  get: () => ParentalState,
): Promise<boolean> {
  if (Date.now() < get().bloqueadoAte) return false;

  const guardado = await rt.adapter.secureStorage.get(CHAVE_PIN);
  if (!guardado) return false;

  const bateu = await verifyPin(pin, guardado);
  aplicarLimiteTentativas(bateu, set, get);
  return bateu;
}

/**
 * Mesmo limite de 3 tentativas → 60s (RF-32), compartilhado entre conferir o
 * PIN e conferir a senha da lista no reset — quem está tentando adivinhar não
 * ganha mais chances só por trocar de fluxo.
 */
function aplicarLimiteTentativas(
  bateu: boolean,
  set: (p: Partial<ParentalState>) => void,
  get: () => ParentalState,
): void {
  if (bateu) {
    set({ tentativasRestantes: MAX_TENTATIVAS, bloqueadoAte: 0 });
    return;
  }
  const restantes = get().tentativasRestantes - 1;
  if (restantes <= 0) {
    set({ tentativasRestantes: MAX_TENTATIVAS, bloqueadoAte: Date.now() + ESPERA_MS });
  } else {
    set({ tentativasRestantes: restantes });
  }
}
