/**
 * Fila global de imagens (PERF-16 / spec 002): concorrência, prioridade,
 * cancelamento e um LRU do que já carregou. Sem isto, uma rolagem rápida numa
 * grade de milhares de pôsteres enfileira dezenas de requisições ao mesmo
 * tempo, atrasando exatamente as que estão à vista.
 *
 * **Desenho difere do esboço do plan.md**: em vez de a fila fazer o fetch por
 * conta própria (um `Image()` interno, chamando `aoCarregar`/`aoFalhar`) e o
 * consumidor confiar no cache HTTP para o `<img>` real reaproveitar essa
 * busca, aqui a fila só decide **quando** o próprio `<img>` do consumidor pode
 * começar a carregar (`aoLiberar`) — um fetch só, nunca dois. Painéis Xtream
 * não têm `Cache-Control` garantido (a caracterização fica para `PERF-17`),
 * então depender do cache do navegador para a 2ª leitura seria uma aposta.
 *
 * Puro — sem DOM, sem React. Só a *decisão* de quando carregar mora aqui; o
 * `<img>` em si é do componente (`Poster.tsx`/`useImageSlot.ts`).
 */

/** Acima disso, uma rolagem rápida satura a rede com pôsteres já fora de vista. */
const CONCORRENCIA = 6;
/** Chaves (URLs) lembradas como "já carregou" — não é o dado, só a URL. */
const TAMANHO_LRU = 300;

interface Pedido {
  url: string;
  prioridade: number;
  aoLiberar: () => void;
}

/** Aguardando uma vaga de concorrência. */
const pendentes: Pedido[] = [];
/** URLs com a vaga concedida (o `<img>` do consumidor está carregando). */
const ativos = new Set<string>();

/**
 * Contadores cumulativos desde o último `_zerarEstatisticas()` — só para o
 * roteiro de medição (RP-8/RP-16) ler quantas vagas terminaram vs. foram
 * canceladas numa rolagem rápida. Não afeta a decisão da fila; puramente
 * observacional.
 */
let totalSolicitado = 0;
let totalConcluido = 0;
let totalCancelado = 0;

export interface EstatisticasDaFila {
  solicitado: number;
  concluido: number;
  cancelado: number;
  pendentes: number;
  ativos: number;
}

export function _estatisticas(): EstatisticasDaFila {
  return {
    solicitado: totalSolicitado,
    concluido: totalConcluido,
    cancelado: totalCancelado,
    pendentes: pendentes.length,
    ativos: ativos.size,
  };
}

export function _zerarEstatisticas(): void {
  totalSolicitado = 0;
  totalConcluido = 0;
  totalCancelado = 0;
}

/**
 * URLs que já terminaram de carregar nesta sessão. Sem tamanho ilimitado —
 * ver `TAMANHO_LRU`. A ordem de inserção do `Set` é a ordem de acesso: reinserir
 * uma chave (`delete` + `add`) a marca como a mais recente.
 */
const resolvidas = new Set<string>();

function marcarResolvida(url: string): void {
  resolvidas.delete(url);
  resolvidas.add(url);
  if (resolvidas.size > TAMANHO_LRU) {
    const maisAntiga = resolvidas.values().next().value;
    if (maisAntiga !== undefined) resolvidas.delete(maisAntiga);
  }
}

/** Já vimos esta URL carregar com sucesso nesta sessão? Dica para pular a fila. */
export function jaResolvida(url: string): boolean {
  return resolvidas.has(url);
}

/** Concede vagas aos pedidos de maior prioridade (menor número) até a fila zerar. */
function liberarProximos(): void {
  while (ativos.size < CONCORRENCIA && pendentes.length > 0) {
    let melhor = 0;
    for (let i = 1; i < pendentes.length; i++) {
      if (pendentes[i]!.prioridade < pendentes[melhor]!.prioridade) melhor = i;
    }
    const [pedido] = pendentes.splice(melhor, 1);
    if (!pedido) break;
    ativos.add(pedido.url);
    pedido.aoLiberar();
  }
}

export interface Solicitacao {
  /** Chame no `onLoad`/`onError` do `<img>` — libera a vaga para o próximo. */
  concluir(sucesso: boolean): void;
  /**
   * Desiste do pedido. Se ainda não tinha ganho a vaga, só sai da fila (sem
   * custo). Se já tinha ganho (o `<img>` estava carregando), libera a vaga
   * para o próximo — o cancelamento real do fetch é o consumidor tirar o
   * `src` do `<img>`, isto aqui só para de contar a vaga como ocupada.
   */
  cancelar(): void;
}

export interface PedidoImagem {
  url: string;
  /** Menor = mais urgente. Distância ao índice focado, por exemplo. */
  prioridade: number;
  /** Chamado quando a vaga é concedida — o consumidor deve setar o `src` agora. */
  aoLiberar: () => void;
}

/** Pede uma vaga na fila. Devolve como concluir ou cancelar o pedido. */
export function solicitar(p: PedidoImagem): Solicitacao {
  const pedido: Pedido = { url: p.url, prioridade: p.prioridade, aoLiberar: p.aoLiberar };
  let resolvido = false;

  pendentes.push(pedido);
  totalSolicitado++;
  liberarProximos();

  return {
    concluir(sucesso) {
      if (resolvido) return;
      resolvido = true;
      totalConcluido++;
      if (sucesso) marcarResolvida(pedido.url);
      ativos.delete(pedido.url);
      liberarProximos();
    },
    cancelar() {
      if (resolvido) return;
      resolvido = true;
      totalCancelado++;
      const idx = pendentes.indexOf(pedido);
      if (idx >= 0) {
        pendentes.splice(idx, 1);
        return; // nunca chegou a ocupar vaga — nada mais a liberar
      }
      ativos.delete(pedido.url);
      liberarProximos();
    },
  };
}

/** Só para os testes: zera a fila entre casos, sem depender de um `describe` global. */
export function _resetParaTeste(): void {
  pendentes.length = 0;
  ativos.clear();
  resolvidas.clear();
  _zerarEstatisticas();
}
