import { create } from 'zustand';
import type { CatalogSection, IptvProvider } from '@mfp/core';
import type { Runtime } from '../runtime/runtime.js';
import { createSingleFlight } from '../runtime/singleFlight.js';
import { useSession } from './session.js';
import { useSettings } from './settings.js';

// Espelha os eventos do CatalogSync do core para a UI (RF-64). O timer de
// auto-refresh de 12h (RF-65) fica no adapter/app, não aqui.

export type SyncPhase = 'idle' | 'running' | 'done' | 'error';

/** Estado de cada seção no boot — uma barra de progresso por seção (D-24). */
export type SectionStatus = 'pending' | 'active' | 'done' | 'stalled';
export interface SectionProgress {
  status: SectionStatus;
  done: number;
  total: number;
  /** categoria sendo baixada agora — dá sinal de vida ao usuário. */
  categoria?: string;
}

export const SYNC_SECTIONS: readonly CatalogSection[] = ['live', 'vod', 'series'];

const inicial = (): Record<CatalogSection, SectionProgress> => ({
  live: { status: 'pending', done: 0, total: 0 },
  vod: { status: 'pending', done: 0, total: 0 },
  series: { status: 'pending', done: 0, total: 0 },
});

interface SyncState {
  phase: SyncPhase;
  /** progresso das três seções, para as barras do boot. */
  sections: Record<CatalogSection, SectionProgress>;
  /** nunca houve sync completo antes desta rodada — mostra copy de "primeira vez". */
  firstRun: boolean;
  run: (
    rt: Runtime,
    listId: string,
    provider: IptvProvider,
    opts?: { force?: boolean },
  ) => Promise<void>;
}

const runOnce = createSingleFlight<void>();

export const useSync = create<SyncState>((set) => ({
  phase: 'idle',
  sections: inicial(),
  firstRun: false,

  // Boot, timer e atualização manual compartilham a rodada já em andamento.
  // Duas gerações simultâneas duplicariam downloads e disputariam a poda do cache.
  run: (rt, listId, provider, opts) =>
    runOnce(rt, listId, async () => {
      const sync = rt.makeSync(listId, provider);
      const firstRun = await sync.isEmpty();
      set({ phase: 'running', firstRun, sections: inicial() });
      // PERF-20: teto de conexões simultâneas da CONTA (não só o configurado no
      // app) — respeitar `max_connections` evita que o próprio painel rejeite
      // ou derrube conexão por excesso.
      const maxConnections = useSession.getState().account?.maxConnections;
      // Ajustável em Configurações (spec 003 LG-022): chute pragmático sem cota
      // oficial da LG pra mirar, exposto pra dar pra estressar em campo sem
      // depender de um novo build a cada tentativa. Sem efeito fora de TV antiga.
      const maxItemsPerCategoryLowStorage =
        useSettings.getState().catalogItemCapOldDevices;

      const patch = (s: CatalogSection, p: Partial<SectionProgress>) =>
        set((st) => ({ sections: { ...st.sections, [s]: { ...st.sections[s], ...p } } }));

      const offs = [
        sync.events.on('section:start', (e) => {
          rt.perf.marcar('sync:section:start', { section: e.section }); // RP (spec 002)
          patch(e.section, { status: 'active', done: 0, total: e.totalCategories });
        }),
        sync.events.on('section:progress', (e) =>
          patch(e.section, { done: e.done, total: e.total, categoria: e.categoryName }),
        ),
        sync.events.on('section:done', (e) => {
          rt.invalidateCatalog(listId);
          rt.perf.marcar('sync:section:done', { section: e.section, itens: e.itemCount });
          // barra cheia mesmo quando o painel ignora category_id (total pode ser 0)
          patch(e.section, { status: 'done', done: 1, total: 1, categoria: undefined });
        }),
        sync.events.on('section:skip', (e) =>
          patch(e.section, { status: 'done', done: 1, total: 1 }),
        ),
      ];

      try {
        const res = await sync.run({
          ...opts,
          maxConnections,
          maxItemsPerCategoryLowStorage,
        });
        // LG-022: `cancelled` (cota do IndexedDB estourou no meio da rodada) para o
        // `for` do CatalogSync — tanto ANTES de uma seção sequer começar (fica em
        // 'pending' para sempre) quanto NO MEIO dela: `CatalogSync.syncSection()`
        // devolve `true` (conta como "rodou") quando `persistComLimite` estoura a
        // cota a meio de uma categoria — ela nunca emite `section:done` (a seção
        // fica presa em 'active' para sempre, mesmo já tendo gravado parte dos
        // itens). Nos dois casos a UI (Catalog/LiveChannels/Home) não tinha como
        // distinguir "ainda vou terminar" de "nunca mais vou terminar" — mostrava
        // o spinner de "baixando catálogo" pra sempre.
        if (res.cancelled) {
          set((st) => ({
            sections: Object.fromEntries(
              SYNC_SECTIONS.map((s) => [
                s,
                st.sections[s].status !== 'done'
                  ? { ...st.sections[s], status: 'stalled' as const }
                  : st.sections[s],
              ]),
            ) as Record<CatalogSection, SectionProgress>,
          }));
        }
        set({ phase: res.cancelled || (res.failed.length && !res.ran.length) ? 'error' : 'done' });
      } catch {
        set({ phase: 'error' });
      } finally {
        offs.forEach((off) => off());
      }
    }),
}));
