import { memo, useCallback, useEffect, useMemo, useState } from 'react';
import { setFocus } from '@noriginmedia/norigin-spatial-navigation';
import { categoryLabel, type Channel, type EpgEntry } from '@mfp/core';
import { focusRing } from '../nav/focusRing.js';
import { EmptyState, LoadingState } from '../components/states.js';
import { FocusButton } from '../components/FocusButton.js';
import { VirtualGrid } from '../components/VirtualGrid.js';
import { useImageSlot } from '../media/useImageSlot.js';
import { useLogicalKeys } from '../nav/keys.js';
import { lembrarPosicao } from '../nav/listMemory.js';
import { useRemPx } from '../theme/useRemPx.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useLive } from '../state/live.js';
import { useFavorites } from '../state/favorites.js';
import { useNowNext, useEpgNowForList, hora } from '../state/nowNext.js';
import { useNowPlaying } from '../state/nowPlaying.js';
import { useSettings } from '../state/settings.js';
import { useNavigation, voltandoComFoco } from '../nav/navigationStack.js';
import { useCatalog } from '../state/catalog.js';
import { useSync } from '../state/sync.js';
import { useProvider } from '../runtime/useProvider.js';
import { useEpgBackground } from '../state/useEpgBackground.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';

export function LiveChannels({ listId }: { listId: string }) {
  // Enfileira EPG após o primeiro paint de canais (GTV-RF-31 / M6)
  useEpgBackground(listId);
  const rt = useRuntime();
  const {
    categories,
    categoryId,
    channels,
    carregandoCanais,
    loadCategories,
    selectCategory,
    getLastChannel,
  } = useLive();
  // Seletores estreitos (PERF-11) em vez do store inteiro: `isFav`/`toggle`/`load`
  // são ações estáveis (a mesma referência para sempre), e `favKeys` entra só
  // para invalidar a memoização das linhas quando os favoritos mudam (abaixo).
  const isFav = useFavorites((s) => s.isFav);
  const favKeys = useFavorites((s) => s.keys);
  const alternarFavoritoAcao = useFavorites((s) => s.toggle);
  const carregarFavoritos = useFavorites((s) => s.load);
  const counts = useCatalog((s) => s.counts);
  const countsLoaded = useCatalog((s) => s.loaded);
  const loadHome = useCatalog((s) => s.loadHome);
  const runSync = useSync((s) => s.run);
  const stalled = useSync((s) => s.sections.live.status === 'stalled');
  // Primeira sincronização com a seção ao vivo ainda chegando: as categorias
  // entram no cache uma a uma, e mostrá-las já faria a coluna crescer e os
  // canais pularem de lugar. Espera a seção fechar, como Filmes/Séries.
  // Sincronizações seguintes (auto-refresh) não bloqueiam: já há catálogo.
  const sincronizandoAoVivo = useSync(
    (s) =>
      s.firstRun &&
      (s.sections.live.status === 'active' ||
        (s.phase === 'running' && s.sections.live.status === 'pending')),
  );
  const getProvider = useProvider();
  const push = useNavigation((s) => s.push);
  const setQueue = useNowPlaying((s) => s.setQueue);
  // LG-022: sync parou por cota antes de chegar nesta seção — tenta de novo em
  // vez de deixar o usuário preso no spinner eterno de `boot.firstSync`.
  const onRetrySync = useCallback(() => {
    void (async () => {
      const { provider } = await getProvider();
      await runSync(rt, listId, provider);
      await loadHome(rt, listId);
    })();
  }, [getProvider, runSync, loadHome, rt, listId]);

  // Canal sobre o qual a ação de favoritar age. Segue o foco na lista; quando a
  // lista troca (outra categoria), volta para o primeiro — favoritar um canal
  // que não está mais à vista seria uma ação às cegas.
  const [canalFocado, setCanalFocado] = useState<Channel | undefined>(channels[0]);
  const [listaAnterior, setListaAnterior] = useState(channels);
  if (listaAnterior !== channels) {
    setListaAnterior(channels);
    setCanalFocado(channels[0]);
  }

  // "agora / a seguir" do canal focado — o miolo da tela 02 sem roubar uma
  // coluna: no telefone deitado não sobra largura para um painel próprio.
  const noAr = useNowNext(listId, canalFocado);

  // D-23: programa no ar em cada linha da lista (ajuste em Configurações). A
  // barra do canal focado (acima) continua com o mais rico: agora + a seguir.
  const mostrarEpgNaLista = useSettings((s) => s.epgInList);
  const epgPorCanal = useEpgNowForList(listId, mostrarEpgNaLista);

  // `favKeys` só entra na dependência para invalidar `ehFavorito` quando os
  // favoritos mudam — `isFav` em si é estável e sempre lê o estado atual, mas
  // sem isto o `renderItem` memoizado da coluna (abaixo) não saberia que
  // precisa re-renderizar a linha (PERF-09).
  const ehFavorito = useCallback(
    (c: Channel) => isFav('live', c.id),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [isFav, favKeys],
  );
  const favorito = canalFocado ? ehFavorito(canalFocado) : false;
  const favoritarFocado = () => {
    if (canalFocado) void alternarFavoritoAcao(rt, listId, 'live', canalFocado.id);
  };
  // Tecla amarela do controle: o caminho natural em TV (webOS/Tizen entregam as
  // coloridas por `event.key`). Quem não tem tecla colorida usa o botão.
  useLogicalKeys(rt.adapter, { Yellow: favoritarFocado });

  useEffect(() => {
    void carregarFavoritos(rt, listId);
  }, [rt, listId, carregarFavoritos]);

  useEffect(() => {
    if (sincronizandoAoVivo) return;
    void (async () => {
      // O estado é global (zustand fora do componente): trocar de lista aqui
      // reaproveitaria o `carregandoCanais` da lista anterior — se ela já
      // tinha terminado de carregar, o flash de "nada por aqui" voltaria
      // enquanto esta nova lista ainda decide qual categoria abrir.
      useLive.setState({ carregandoCanais: true });
      await loadCategories(rt, listId);
      // Voltando do player: a categoria e os canais dela continuam no estado.
      // Reselecionar a primeira aqui jogaria o usuário de volta para o começo
      // da lista de canais; o foco, no canal de onde ele saiu, volta pelo
      // `useRestoreFocus` do App.
      if (voltandoComFoco() && useLive.getState().channels.length > 0) return;

      // Retomar o último canal assistido (RF-34): abre na categoria dele, com
      // ele já focado. A posição é semeada em `listMemory` **antes** de os
      // canais entrarem no estado — é de lá que a grade tira a janela inicial,
      // e um `setFocus` numa célula fora da janela não teria em quem pegar.
      const ultimo = await getLastChannel(rt, listId);
      const canal = ultimo ? await rt.catalog(listId).channel(ultimo) : undefined;
      if (canal) {
        let idx = -1;
        await selectCategory(rt, listId, canal.categoryId ?? null, (channels) => {
          idx = channels.findIndex((c) => c.id === canal.id);
          if (idx >= 0) lembrarPosicao(`live-ch:${canal.categoryId ?? 'todos'}`, idx);
        });
        if (idx >= 0) {
          setFocus(`live-channels-${idx}`);
          return;
        }
      }

      // A seleção segue o foco (ver `CategoryColumn`), e o foco começa no
      // primeiro item — que agora é uma categoria real, porque "Todos" ficou no
      // fim da lista. Selecionar a mesma coisa aqui evita carregar os canais
      // duas vezes na abertura (todos, e logo em seguida os da categoria).
      const primeira = useLive.getState().categories[0];
      await selectCategory(rt, listId, primeira?.id ?? null);
      setFocus('live-cats');
    })();
  }, [rt, listId, sincronizandoAoVivo, loadCategories, selectCategory, getLastChannel]);

  // PERF-15 (spec 002): `openChannel` rodava a cada troca de canal — inclusive
  // durante o zapping (`ChannelUp`/`ChannelDown` no player, que reabre esta
  // função via `push`/estado, não remonta `LiveChannels`, mas a versão antiga
  // remapeava os 2.400 canais A CADA canal aberto). `channels` só muda quando a
  // CATEGORIA muda — `useMemo` faz o remapeamento uma vez por categoria, não
  // uma vez por canal.
  const filaDaCategoria = useMemo(
    () =>
      channels.map((c) => ({
        id: c.id,
        title: c.name,
        ext: c.containerExt,
        // número e logo alimentam a barra de info e a lista dentro do player
        ...(c.num !== undefined ? { num: c.num } : {}),
        ...(c.logo ? { logo: c.logo } : {}),
      })),
    [channels],
  );

  const openChannel = useCallback(
    (index: number) => {
      setQueue('live', filaDaCategoria, index);
      const c = channels[index];
      if (!c) return;
      push({
        name: 'player',
        params: {
          kind: 'live',
          streamId: c.id,
          ext: c.containerExt ?? 'm3u8',
          title: c.name,
        },
      });
    },
    [channels, filaDaCategoria, setQueue, push],
  );

  const onSelect = useCallback(
    (id: string | null) => void selectCategory(rt, listId, id),
    [rt, listId, selectCategory],
  );

  if (sincronizandoAoVivo) {
    return <EmptyState loading title={t('nav.live')} body={t('boot.firstSync')} />;
  }

  if (counts.live === 0) {
    // Ver nota em `state/catalog.ts`: "ainda lendo o cache" != "vazio de fato".
    if (!countsLoaded) return <LoadingState label={t('nav.live')} />;
    if (stalled) {
      return (
        <EmptyState
          title={t('nav.live')}
          body={t('boot.syncStalled')}
          action={
            <FocusButton primary focusKey="live-retry-sync" onPress={onRetrySync}>
              {t('common.retry')}
            </FocusButton>
          }
        />
      );
    }
    return <EmptyState loading title={t('nav.live')} body={t('boot.firstSync')} />;
  }

  // Categoria sem canais: só afirma isso depois que `selectCategory` respondeu
  // (`carregandoCanais`) — antes disso é só a busca ainda em curso.
  const semCanais = carregandoCanais ? <LoadingState /> : <EmptyState />;

  return (
    <div
      className={gapRowClass}
      style={{
        display: 'flex',
        height: '100%',
        minHeight: 0, // ver a nota em `Catalog.tsx`
        ...gapVar('1.5rem'),
      }}
    >
      <CategoryColumn categories={categories} activeId={categoryId} onSelect={onSelect} />
      <div
        className={gapColClass}
        style={{
          flex: 1,
          minWidth: 0,
          height: '100%',
          display: 'flex',
          flexDirection: 'column',
          ...gapVar('0.6rem'),
        }}
      >
        <div
          className={gapRowClass}
          style={{ display: 'flex', alignItems: 'center', ...gapVar('0.8rem') }}
        >
          {canalFocado?.logo && (
            <img
              src={canalFocado.logo}
              alt=""
              loading="lazy"
              decoding="async"
              style={{ width: '2.4rem', height: '2.4rem', objectFit: 'contain' }}
            />
          )}
          <div style={{ flex: 1, minWidth: 0, lineHeight: 1.25 }}>
            <div
              style={{
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
              }}
            >
              {canalFocado?.name ?? ''}
            </div>
            {(noAr?.agora || noAr?.proximo) && (
              <div
                style={{
                  fontSize: 'var(--fs-meta)',
                  color: 'var(--text-secondary)',
                  lineHeight: 1.3,
                }}
              >
                {/* duas linhas: numa só, um título longo empurrava o "a seguir"
                    para fora da tela e o usuário nunca via o próximo programa */}
                {noAr.agora && (
                  <div
                    style={{
                      whiteSpace: 'nowrap',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                    }}
                  >
                    {hora(noAr.agora.start)}–{hora(noAr.agora.stop)} {noAr.agora.title}
                  </div>
                )}
                {noAr.proximo && (
                  <div
                    style={{
                      whiteSpace: 'nowrap',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      opacity: 0.75,
                    }}
                  >
                    {t('live.next')} {hora(noAr.proximo.start)} {noAr.proximo.title}
                  </div>
                )}
              </div>
            )}
          </div>
          <FocusButton
            focusKey="live-fav"
            disabled={!canalFocado}
            onPress={favoritarFocado}
          >
            {favorito ? t('live.inFavorites') : t('live.favorite')}
          </FocusButton>
        </div>
        {/*
          `key` por categoria: remonta a coluna ao trocar de categoria. Sem isso o
          norigin restaura o último filho focado por chave (`live-channels-126`),
          que não existe na lista nova — medido no device, trocar de "Todos" (2357)
          para uma de 79 canais abria no canal 71 em vez do primeiro.
        */}
        {channels.length === 0 ? (
          semCanais
        ) : (
          <ChannelColumn
            key={categoryId ?? 'todos'}
            channels={channels}
            categoriaId={categoryId}
            ehFavorito={ehFavorito}
            onFocus={setCanalFocado}
            onOpen={openChannel}
            epgPorCanal={epgPorCanal}
            mostrarEpg={mostrarEpgNaLista}
          />
        )}
      </div>
    </div>
  );
}

/** Item sintético de "Todas as categorias" (`id: null`), no fim da lista. */
type CatItem = { id: string | null; name: string };

function CategoryColumn({
  categories,
  activeId,
  onSelect,
}: Readonly<{
  categories: { id: string; name: string }[];
  activeId: string | null;
  onSelect: (id: string | null) => void;
}>) {
  const rem = useRemPx();
  // "Todos" por último: as categorias reais ficam com as primeiras posições,
  // que são as que o usuário alcança sem rolar.
  const itens: CatItem[] = [
    // sem o prefixo "CANAIS | " — ver `categoryLabel`
    ...categories.map((c) => ({ id: c.id, name: categoryLabel(c.name, 'live') })),
    { id: null, name: t('live.allCategories') },
  ];

  // seleciona ao focar: percorrer a coluna já troca a lista de canais. Uma
  // função só para os dois eventos, estável enquanto `onSelect` não mudar
  // (PERF-09) — sem isto o `VirtualGrid` recriava `handleFocus` a cada render.
  const onItemFocusOuPress = useCallback((c: CatItem) => onSelect(c.id), [onSelect]);
  const renderItem = useCallback(
    (c: CatItem, _i: number, focused: boolean) => (
      <div
        style={{
          height: '100%',
          display: 'flex',
          alignItems: 'center',
          padding: '0 0.9rem',
          borderRadius: 'var(--radius-sm)',
          color: activeId === c.id ? 'var(--accent)' : 'var(--text-secondary)',
          background: focused ? 'var(--bg-raised)' : 'transparent',
          fontFamily: 'var(--font-display)',
          textTransform: 'uppercase',
          // nomes de categoria são longos: uma linha, sem empurrar o layout
          whiteSpace: 'nowrap',
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          ...focusRing(focused),
        }}
      >
        {c.name}
      </div>
    ),
    [activeId],
  );

  return (
    <div style={{ width: '16rem', flexShrink: 0, height: '100%' }}>
      <VirtualGrid<CatItem>
        focusKey="live-cats"
        restoreKey="live-cats"
        items={itens}
        columns={1}
        itemHeight={Math.round(rem * 2.8)}
        rowGap={Math.round(rem * 0.3)}
        colGap={0}
        onItemFocus={onItemFocusOuPress}
        onItemPress={onItemFocusOuPress}
        renderItem={renderItem}
      />
    </div>
  );
}

function ChannelColumn({
  channels,
  categoriaId,
  ehFavorito,
  onFocus,
  onOpen,
  epgPorCanal,
  mostrarEpg,
}: Readonly<{
  channels: Channel[];
  categoriaId: string | null;
  ehFavorito: (c: Channel) => boolean;
  onFocus: (c: Channel) => void;
  onOpen: (index: number) => void;
  epgPorCanal: Map<string, EpgEntry>;
  mostrarEpg: boolean;
}>) {
  const rem = useRemPx();
  // Estáveis enquanto os favoritos e o EPG não mudarem (PERF-09): sem isto, o
  // `GridCell` memoizado nunca acertava — recebia um `renderItem` novo a cada
  // render de `LiveChannels` (que acontece a cada segundo pelo relógio do
  // cabeçalho, entre outras coisas).
  const renderItem = useCallback(
    (c: Channel, i: number, focused: boolean) => (
      <ChannelRow
        channel={c}
        focused={focused}
        favorito={ehFavorito(c)}
        agora={mostrarEpg ? epgPorCanal.get(c.id) : undefined}
        prioridade={i}
      />
    ),
    [ehFavorito, epgPorCanal, mostrarEpg],
  );
  const onItemPress = useCallback((_c: Channel, i: number) => onOpen(i), [onOpen]);

  return (
    <div style={{ flex: 1, minHeight: 0 }}>
      <VirtualGrid<Channel>
        focusKey="live-channels"
        restoreKey={`live-ch:${categoriaId ?? 'todos'}`}
        items={channels}
        columns={1}
        // 2 linhas (canal + programa) quando o EPG está na lista — D-23
        itemHeight={Math.round(rem * (mostrarEpg ? 5.6 : 4.3))}
        rowGap={Math.round(rem * 0.45)}
        colGap={0}
        onItemFocus={onFocus}
        onItemPress={onItemPress}
        renderItem={renderItem}
      />
    </div>
  );
}

/** Memoizada (PERF-09): folha mais repetida desta tela (até ~15 visíveis de
 * uma lista de milhares). */
const ChannelRow = memo(function ChannelRow({
  channel,
  focused,
  favorito,
  agora,
  prioridade,
}: Readonly<{
  channel: Channel;
  focused: boolean;
  favorito: boolean;
  agora?: EpgEntry;
  /** PERF-16 — fila do logo. Menor é mais urgente (ver `Poster`). */
  prioridade: number;
}>) {
  // Fila de carregamento (PERF-16): até ~15 logos visíveis de uma lista com
  // milhares de canais — sem concorrência limitada, uma rolagem rápida
  // dispara todos de uma vez e atrasa exatamente os que estão à vista.
  const logo = useImageSlot(channel.logo, prioridade);
  const mostrarLogo = !!channel.logo && logo.liberada && !logo.falhou;

  // Progresso do programa no ar — mesmo padrão do `LiveProgress` do player e
  // do `HeaderClock` (tick isolado no próprio componente, no virar do
  // minuto): `Date.now()` não pode ser lido direto no corpo do render (quebra
  // a pureza), por isso o valor mora em estado, atualizado por um timer só
  // deste card. Como a lista é virtualizada, só os ~15 cards visíveis têm um
  // timer vivo por vez — o mesmo raciocínio que já vale para `PinModal`.
  const [agoraMs, setAgoraMs] = useState(() => Date.now());
  useEffect(() => {
    if (!agora) return;
    let timer: number;
    const agendar = () => {
      const d = Date.now();
      setAgoraMs(d);
      timer = window.setTimeout(agendar, 60_000 - (d % 60_000) + 50);
    };
    agendar();
    return () => window.clearTimeout(timer);
  }, [agora]);

  return (
    <div
      className={gapRowClass}
      style={{
        height: '100%',
        display: 'flex',
        alignItems: 'center',
        padding: '0 1rem',
        borderRadius: 'var(--radius-sm)',
        background: focused ? 'var(--bg-raised)' : 'var(--bg-panel)',
        ...gapVar('1rem'),
        ...focusRing(focused),
      }}
    >
      <span style={{ width: '3ch', textAlign: 'right', color: 'var(--text-disabled)' }}>
        {channel.num ?? ''}
      </span>
      {channel.logo && (
        // caixa sempre reservada (mesmo antes de a fila liberar o logo) para
        // o texto ao lado não deslocar quando a imagem aparece; em rem: fixo
        // em px o logo ficava minúsculo na TV, onde 1rem ~ 25px
        <div style={{ width: '2.9rem', height: '2.9rem', flexShrink: 0 }}>
          {mostrarLogo && (
            <img
              src={channel.logo}
              alt=""
              loading="lazy"
              decoding="async"
              onLoad={logo.aoCarregar}
              onError={logo.aoFalhar}
              style={{ width: '100%', height: '100%', objectFit: 'contain' }}
            />
          )}
        </div>
      )}
      <span
        style={{
          flex: 1,
          minWidth: 0,
          display: 'flex',
          flexDirection: 'column',
          lineHeight: 1.25,
        }}
      >
        <span
          style={{
            whiteSpace: 'nowrap',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
          }}
        >
          {channel.name}
        </span>
        {agora && (
          <>
            <span
              style={{
                fontSize: 'var(--fs-meta)',
                color: 'var(--text-secondary)',
                opacity: 0.8,
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
              }}
            >
              {hora(agora.start)} {agora.title}
            </span>
            {/* Progresso do programa no ar — mesma fórmula do `LiveProgress`
                do player, sem tick próprio: esta linha já re-renderiza a
                cada 60s (o `useEpgNowForList` do cabeçalho recarrega a lista
                inteira nesse intervalo), então basta calcular a fração aqui
                no corpo do render — não precisa de outro relógio. */}
            <div
              style={{
                marginTop: '0.2rem',
                height: '0.2rem',
                borderRadius: '0.1rem',
                background: 'var(--bg-raised)',
                overflow: 'hidden',
              }}
            >
              <div
                style={{
                  width: `${Math.round(Math.min(1, Math.max(0, (agoraMs - agora.start) / Math.max(1, agora.stop - agora.start))) * 100)}%`,
                  height: '100%',
                  background: 'var(--accent)',
                }}
              />
            </div>
          </>
        )}
      </span>
      {/* estado, não botão: a ação está no `live-fav` (ou na tecla amarela) */}
      {favorito && <span aria-hidden>★</span>}
    </div>
  );
});
