import {
  memo,
  type ReactNode,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import {
  FocusContext,
  setFocus,
  useFocusable,
} from '@noriginmedia/norigin-spatial-navigation';
import { useDragScroll } from './useDragScroll.js';
import { lembrarPosicao, posicaoLembrada } from '../nav/listMemory.js';

export interface VirtualGridProps<T> {
  items: T[];
  /**
   * Identidade do conteúdo desta lista (seção + filtros). Com ela a grade
   * reabre onde parou depois de a tela ser desmontada — abrir um detalhe
   * desmonta a tela de baixo. Chave nova = conteúdo novo = volta ao topo.
   */
  restoreKey?: string;
  /** Largura mínima de cada cartão — colunas e largura reais vêm do viewport medido. */
  minItemWidth?: number;
  /** Proporção altura/largura do cartão (default 3/2 = pôster 2:3 + rodapé). */
  aspectRatio?: number;
  /** Fixos (fallback quando `minItemWidth` não é dado). */
  columns?: number;
  itemWidth?: number;
  itemHeight?: number;
  rowGap?: number;
  colGap?: number;
  /** Fração da altura visível onde a linha focada é ancorada (0..1). */
  anchor?: number;
  overscanRows?: number;
  focusKey: string;
  renderItem: (item: T, index: number, focused: boolean) => ReactNode;
  onItemPress?: (item: T, index: number) => void;
  onItemFocus?: (item: T, index: number) => void;
  /**
   * A janela renderizada chegou perto do fim de `items` (PERF-01a / spec 002)
   * — o chamador busca a próxima leva. Chamado uma vez por tamanho de `items`
   * (não repete enquanto a leva pedida não chega).
   */
  onNearEnd?: () => void;
}

/**
 * Grade 2D virtualizada por linha, foco preservado (plan.md §Listas virtualizadas).
 * Só as linhas visíveis + overscan são montadas; a rolagem é `translate3d` sem
 * suavização (constitution §8), com a linha focada ancorada. Cartões dimensionados
 * a partir do viewport medido (design-inventory §Responsividade).
 *
 * PERF-09/PERF-10 (spec 002): as células são memoizadas (`GridCell`) com
 * handlers estáveis, e o arrasto escreve o `transform` direto no nó — o React só
 * reconcilia quando a **janela de linhas** muda, não a cada quadro do gesto.
 */
export function VirtualGrid<T>({
  items,
  restoreKey,
  minItemWidth = 220,
  aspectRatio = 1.5,
  columns: fixedCols,
  itemWidth: fixedW,
  itemHeight: fixedH,
  rowGap = 24,
  colGap = 16,
  anchor = 1 / 3,
  overscanRows = 2,
  focusKey,
  renderItem,
  onItemPress,
  onItemFocus,
  onNearEnd,
}: VirtualGridProps<T>) {
  const [focusedIndex, setFocusedIndex] = useState(
    () => posicaoLembrada(restoreKey) ?? 0,
  );
  const [viewport, setViewport] = useState({ w: 1200, h: 700 });

  // Trocar de gênero/ordenação troca o conteúdo sem remontar a grade: a lista
  // nova tem de começar na posição dela (normalmente o topo), não no índice da
  // antiga. Ajuste durante o render, não num efeito: assim a primeira pintura já
  // sai na posição certa, sem um quadro na posição da lista anterior.
  const [chaveAnterior, setChaveAnterior] = useState(restoreKey);
  if (chaveAnterior !== restoreKey) {
    setChaveAnterior(restoreKey);
    setFocusedIndex(posicaoLembrada(restoreKey) ?? 0);
  }

  const { ref, focusKey: fk } = useFocusable({
    focusKey,
    trackChildren: true,
    saveLastFocusedChild: true,
  });

  useEffect(() => {
    const node = ref.current as HTMLDivElement | null;
    if (!node) return;
    const measure = () =>
      setViewport({
        w: node.clientWidth || 1200,
        h: node.clientHeight || 700,
      });
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(measure);
    ro.observe(node);
    return () => ro.disconnect();
  }, [ref]);

  // colunas/tamanho: fixos se passados, senão derivados do viewport
  const colunasPorLargura = Math.max(
    2,
    Math.floor((viewport.w + colGap) / (minItemWidth + colGap)),
  );
  // ...e o cartão inteiro precisa caber na ALTURA visível, senão a grade mostra
  // só um pedaço dele (medido no aparelho deitado: 3 colunas de 244px davam
  // pôsteres de 366px numa área de 214px — 40% do cartão fora da tela). Mais
  // colunas ⇒ cartão mais estreito ⇒ mais baixo, na mesma proporção. De
  // `(w + gap)/cols - gap <= h/aspecto`, resolvido para `cols`.
  const colunasPorAltura =
    fixedH == null && viewport.h > 0
      ? Math.ceil((viewport.w + colGap) / (viewport.h / aspectRatio + colGap))
      : 0;
  // Teto: numa área muito baixa, encolher sem limite viraria cartão ilegível a
  // 3m de distância (constitution §10). Metade da largura mínima é o piso.
  const colunasMax = Math.floor((viewport.w + colGap) / (minItemWidth / 2 + colGap));
  const columns =
    fixedCols ?? Math.max(colunasPorLargura, Math.min(colunasPorAltura, colunasMax));
  const itemWidth = fixedW ?? Math.floor((viewport.w - colGap * (columns - 1)) / columns);
  const itemHeight = fixedH ?? Math.round(itemWidth * aspectRatio);

  const rowStride = itemHeight + rowGap;
  const colStride = itemWidth + colGap;
  const rowCount = Math.ceil(items.length / columns);
  const viewportHeight = viewport.h;

  // A lista pode encolher sob o índice guardado (trocar de categoria em TV AO
  // VIVO leva de 2357 canais para 12). Sem limitar, a janela é calculada para uma
  // linha que não existe mais e a lista abre rolada para o vazio.
  const safeIndex = Math.min(focusedIndex, Math.max(0, items.length - 1));
  const focusedRow = Math.floor(safeIndex / columns);
  const maxOffset = Math.max(0, rowCount * rowStride - viewportHeight);
  // A âncora põe a linha focada a 1/3 da altura visível — mas quando o cartão
  // ocupa mais de 2/3 dessa altura, esse mesmo 1/3 joga o rodapé do cartão fora
  // da tela. Então a âncora só vale enquanto a linha focada continua inteira em
  // vista: o piso garante o rodapé, o teto (`topoDaLinha`) garante o topo.
  const topoDaLinha = focusedRow * rowStride;
  const offsetDoFoco = Math.max(
    0,
    Math.min(
      maxOffset,
      topoDaLinha,
      Math.max(
        topoDaLinha - anchor * viewportHeight,
        topoDaLinha + itemHeight - viewportHeight,
      ),
    ),
  );

  // Último offset de fato aplicado ao DOM (arrasto/inércia ou o do foco) — é o
  // que o `useDragScroll` lê como ponto de partida de um novo gesto.
  const offsetExibido = useRef(offsetDoFoco);
  const conteudoRef = useRef<HTMLDivElement>(null);

  const calcularJanela = useCallback(
    (off: number) => ({
      first: Math.max(0, Math.floor(off / rowStride) - overscanRows),
      last: Math.min(
        rowCount,
        Math.ceil((off + viewportHeight) / rowStride) + overscanRows,
      ),
    }),
    [rowStride, overscanRows, rowCount, viewportHeight],
  );
  // Janela para o caso comum (D-pad, sem gesto): pura, recalculada a cada
  // render a partir do offset do foco — sem `useState`, então não há setState
  // para disparar em efeito nenhum.
  const janelaFoco = calcularJanela(offsetDoFoco);
  // Janela do arrasto: só importa enquanto o gesto dura, e só quem escreve
  // nela é a assinatura do `useDragScroll` — nunca o corpo de um efeito.
  const [janelaArrasto, setJanelaArrasto] = useState(janelaFoco);

  // Escreve o offset direto no nó (fora do React) e só dispara um re-render
  // quando a janela de linhas muda — o que acontece a cada ~`rowStride` px de
  // rolagem, não a cada pixel do gesto (PERF-10). Chamada só pela assinatura
  // do arrasto (evento nativo), nunca de dentro de um efeito.
  const aplicarOffsetDoArrasto = useCallback(
    (off: number) => {
      offsetExibido.current = off;
      const node = conteudoRef.current;
      if (node) node.style.transform = `translate3d(0, ${-off}px, 0)`;
      setJanelaArrasto((atual) => {
        const nova = calcularJanela(off);
        return nova.first === atual.first && nova.last === atual.last ? atual : nova;
      });
    },
    [calcularJanela],
  );

  const adotarPosicaoRef = useRef<(fim: number) => void>(() => {});
  const arrasto = useDragScroll(
    ref as { current: HTMLElement | null },
    'y',
    maxOffset,
    () => offsetExibido.current,
    (fim) => adotarPosicaoRef.current(fim),
  );

  // O dedo manda enquanto arrasta; fora disso a janela segue o item focado.
  // Ao terminar o gesto, o foco **adota** onde o dedo parou: sem isso a lista
  // salta de volta para o item focado (medido: impulso levava a -655px e a tela
  // pulava para -430px quando o norigin refocava uma célula ainda montada).
  //
  // `setFocusedIndex` é chamado direto, e não só via `setFocus`: o norigin não
  // re-dispara `onFocus` quando o alvo já é a célula focada — e é exatamente o
  // que acontece no fim da lista, onde toda arrastada resolve para o mesmo
  // último item. Sem isto a âncora ficaria congelada lá.
  useEffect(() => {
    adotarPosicaoRef.current = (fim: number) => {
      const linha = Math.round((fim + anchor * viewportHeight) / rowStride);
      const idx = Math.max(0, Math.min(linha * columns, items.length - 1));
      setFocusedIndex(idx);
      void setFocus(`${focusKey}-${idx}`);
    };
  });

  // Escreve o transform no nó, fora do `style` declarativo do JSX (que nunca
  // declara `transform` — por isso a reconciliação do React não briga com as
  // escritas diretas feitas pela assinatura do arrasto, abaixo). Só roda
  // quando não há gesto em curso: durante o arrasto, quem manda é a
  // assinatura. Efeito de leitura/gravação de DOM, sem `setState` — não dispara
  // o aviso de setState síncrono em efeito.
  useLayoutEffect(() => {
    if (arrasto.ativo()) return;
    offsetExibido.current = offsetDoFoco;
    const node = conteudoRef.current;
    if (node) node.style.transform = `translate3d(0, ${-offsetDoFoco}px, 0)`;
  });

  // Assina os quadros do arrasto; `null` = soltou — a partir daí quem manda de
  // novo é o efeito acima, no próximo render (`adotarPosicaoRef` já rodou).
  useLayoutEffect(
    () =>
      arrasto.assinar((off) => (off !== null ? aplicarOffsetDoArrasto(off) : undefined)),
    [arrasto, aplicarOffsetDoArrasto],
  );

  // Só a janela do arrasto precisa de estado; fora dele, a do foco (pura) manda.
  const janela = arrasto.ativo() ? janelaArrasto : janelaFoco;

  // Rolagem infinita (PERF-01a): pede a próxima leva quando a janela chega
  // perto do fim. Uma vez por tamanho de `items` — não repete enquanto a leva
  // pedida não chega e `items.length` não muda.
  const pedidoParaTamanho = useRef(-1);
  useEffect(() => {
    if (!onNearEnd || rowCount === 0) return;
    if (janela.last >= rowCount - 2 && pedidoParaTamanho.current !== items.length) {
      pedidoParaTamanho.current = items.length;
      onNearEnd();
    }
  }, [janela.last, rowCount, items.length, onNearEnd]);

  const handleFocus = useCallback(
    (index: number) => {
      // Enquanto o dedo (ou o impulso) manda, o norigin ainda refoca células ao
      // montar/desmontar; reancorar aí faria a lista pular sob o dedo.
      if (!arrasto.ativo()) arrasto.soltar();
      setFocusedIndex(index);
      if (restoreKey) lembrarPosicao(restoreKey, index);
      const item = items[index];
      if (item !== undefined) onItemFocus?.(item, index);
    },
    [items, onItemFocus, arrasto, restoreKey],
  );

  const handlePress = useCallback(
    (index: number) => {
      // um arrasto termina com um clique sintético no item sob o dedo: abrir o
      // canal nesse caso seria uma abertura acidental
      if (arrasto.arrastou()) return;
      // o toque também leva o foco para o item, senão o anel fica para trás
      setFocus(`${focusKey}-${index}`);
      const item = items[index];
      if (item !== undefined) onItemPress?.(item, index);
    },
    [arrasto, focusKey, items, onItemPress],
  );

  const visible = useMemo(() => {
    const out: { item: T; index: number }[] = [];
    for (let r = janela.first; r < janela.last; r++) {
      for (let c = 0; c < columns; c++) {
        const index = r * columns + c;
        const item = items[index];
        if (item !== undefined) out.push({ item, index });
      }
    }
    return out;
  }, [items, janela, columns]);

  return (
    <FocusContext.Provider value={fk}>
      <div
        ref={ref}
        // Quem rola aqui é o `translate3d` de dentro. Ao focar uma célula que
        // ainda está fora da janela, porém, o WebView **também** rola esta caixa
        // sozinho (`scrollIntoView` nativo, mesmo com `overflow: hidden`):
        // medido, 232px de `scrollTop` somados ao nosso deslocamento, jogando o
        // cartão recém-focado inteiro para cima da área visível a cada tecla
        // para baixo. Desfazer no `onScroll` mantém a caixa sempre no zero.
        onScroll={(e) => {
          e.currentTarget.scrollTop = 0;
          e.currentTarget.scrollLeft = 0;
        }}
        // sem isto o WebView tenta rolar a página no gesto vertical
        style={{
          overflow: 'hidden',
          width: '100%',
          height: '100%',
          touchAction: 'none',
        }}
      >
        <div
          ref={conteudoRef}
          // `transform` de propósito fora deste objeto: quem escreve é sempre
          // código imperativo (acima), nunca o JSX — declará-lo aqui faria a
          // reconciliação do React reescrever o valor a cada render e brigar
          // com as atualizações do arrasto (PERF-10). Salto direto, sem
          // `transition`: a constitution §8 veta animação custosa no hardware
          // mínimo (webOS 4 / Tizen 4 / Android TV 8) — animar o transform de
          // uma camada de ~146.000px a cada tecla é justamente esse custo.
          style={{
            position: 'relative',
            width: columns * colStride,
            height: rowCount * rowStride,
          }}
        >
          {visible.map(({ item, index }) => (
            <GridCell
              key={`${focusKey}-${index}`}
              focusKeyPrefix={focusKey}
              index={index}
              item={item}
              renderItem={renderItem}
              onFocusIndex={handleFocus}
              onPressIndex={handlePress}
              left={(index % columns) * colStride}
              top={Math.floor(index / columns) * rowStride}
              width={itemWidth}
              height={itemHeight}
            />
          ))}
        </div>
      </div>
    </FocusContext.Provider>
  );
}

interface GridCellProps<T> {
  focusKeyPrefix: string;
  index: number;
  item: T;
  renderItem: (item: T, index: number, focused: boolean) => ReactNode;
  onFocusIndex: (index: number) => void;
  onPressIndex: (index: number) => void;
  left: number;
  top: number;
  width: number;
  height: number;
}

/**
 * Célula memoizada (PERF-09): enquanto `item`/geometria/handlers não mudam, um
 * re-render do `VirtualGrid` (rolagem, troca de janela) não re-renderiza as
 * ~30 células visíveis. Os handlers recebem só o `index` — construídos uma vez
 * no `VirtualGrid` via `useCallback`, não uma closure nova por célula.
 */
function GridCellInner<T>({
  focusKeyPrefix,
  index,
  item,
  renderItem,
  onFocusIndex,
  onPressIndex,
  left,
  top,
  width,
  height,
}: GridCellProps<T>) {
  const focusKey = `${focusKeyPrefix}-${index}`;
  const onFocus = useCallback(() => onFocusIndex(index), [onFocusIndex, index]);
  const onEnterPress = useCallback(() => onPressIndex(index), [onPressIndex, index]);
  const { ref, focused } = useFocusable({ focusKey, onFocus, onEnterPress });
  return (
    <div
      ref={ref}
      onClick={onEnterPress}
      style={{ position: 'absolute', left, top, width, height, cursor: 'pointer' }}
    >
      {renderItem(item, index, focused)}
    </div>
  );
}
const GridCell = memo(GridCellInner) as typeof GridCellInner;
