import { redact } from '../util/redact.js';

/**
 * Logger estruturado com nível ajustável (RF-72). Toda mensagem e todo valor de campo
 * do tipo string passa por `redact()` — credenciais Xtream viajam no path das URLs de
 * stream e não podem vazar para lugar nenhum (constitution §9 / RF-69).
 */

export type LogLevel = 'debug' | 'info' | 'warn' | 'error' | 'silent';

const ORDER: Record<LogLevel, number> = {
  debug: 10,
  info: 20,
  warn: 30,
  error: 40,
  silent: 99,
};

export interface LogRecord {
  level: Exclude<LogLevel, 'silent'>;
  msg: string;
  fields?: Record<string, unknown>;
  time: number;
}

export type LogSink = (record: LogRecord) => void;

export interface Logger {
  level: LogLevel;
  debug(msg: string, fields?: Record<string, unknown>): void;
  info(msg: string, fields?: Record<string, unknown>): void;
  warn(msg: string, fields?: Record<string, unknown>): void;
  error(msg: string, fields?: Record<string, unknown>): void;
  child(fields: Record<string, unknown>): Logger;
}

export interface LoggerOptions {
  level?: LogLevel;
  sinks?: LogSink[];
  /** Contexto herdado por `child()`. */
  base?: Record<string, unknown>;
}

export const consoleSink: LogSink = (r) => {
  const fn = r.level === 'debug' ? 'log' : r.level;
  // eslint-disable-next-line no-console
  (console[fn] ?? console.log)(`[${r.level}] ${r.msg}`, r.fields ?? '');
};

export function createLogger(opts: LoggerOptions = {}): Logger {
  const sinks = opts.sinks ?? [consoleSink];
  const base = opts.base ?? {};
  const state = { level: opts.level ?? 'info' };

  function emit(
    level: LogRecord['level'],
    msg: string,
    fields?: Record<string, unknown>,
  ) {
    if (ORDER[level] < ORDER[state.level]) return;
    const merged = { ...base, ...fields };
    const record: LogRecord = {
      level,
      msg: redact(msg),
      time: Date.now(),
      ...(Object.keys(merged).length ? { fields: redactFields(merged) } : {}),
    };
    for (const sink of sinks) {
      try {
        sink(record);
      } catch {
        /* um sink quebrado não pode derrubar o app */
      }
    }
  }

  const logger: Logger = {
    get level() {
      return state.level;
    },
    set level(l: LogLevel) {
      state.level = l;
    },
    debug: (m, f) => emit('debug', m, f),
    info: (m, f) => emit('info', m, f),
    warn: (m, f) => emit('warn', m, f),
    error: (m, f) => emit('error', m, f),
    child: (fields) =>
      createLogger({ ...opts, level: state.level, sinks, base: { ...base, ...fields } }),
  };
  return logger;
}

function redactFields(fields: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(fields)) {
    out[k] = typeof v === 'string' ? redact(v) : v;
  }
  return out;
}

/** Logger silencioso — default quando nenhum é injetado. */
export const nullLogger: Logger = createLogger({ level: 'silent', sinks: [] });
