import type { CSSProperties } from 'react';

/**
 * Espaçamento entre irmãos via margin, no lugar de `gap` (ver classes
 * `.mfp-gap-row`/`.mfp-gap-col`/`.mfp-gap-wrap` em `base.css`): o Chromium do
 * Simulador/TV webOS 6.0 (~Chrome 79) não aplica `gap` em `display:flex` —
 * falha silenciosa, sem erro no console, só o respiro visual desaparece
 * (`gap` em flexbox só chegou no Chrome 84, 2020). `display:grid` não tem
 * esse problema (grid-gap existe desde o Chrome 66) — não usar isto lá.
 *
 * Uso: `className={gapRowClass} style={{ display: 'flex', ...gapVar('0.8rem') }}`.
 * Com `flexWrap: 'wrap'`, precisa de DOIS elementos (não um): o externo com
 * `gapWrapClass` (sem margin próprio, só contém a margem negativa do de
 * dentro) e, dentro dele, o `<div>` de verdade com `display:flex`,
 * `flexWrap:'wrap'` e `gapWrapInnerClass` — ver a nota em `base.css` sobre
 * por que a margem negativa não pode ficar no elemento que o pai (`gapRowClass`/
 * `gapColClass`) enxerga como filho direto, achado numa TV LG real.
 */
export const gapRowClass = 'mfp-gap-row';
export const gapColClass = 'mfp-gap-col';
export const gapWrapClass = 'mfp-gap-wrap';
export const gapWrapInnerClass = 'mfp-gap-wrap-inner';

export function gapVar(value: string): CSSProperties {
  return { '--mfp-gap': value } as CSSProperties;
}
