import type { ReactNode } from 'react';
import { useFocusable, FocusContext } from '@noriginmedia/norigin-spatial-navigation';
import { pressWithFocus } from '../nav/pressWithFocus.js';
import { t } from '../i18n/index.js';
import {
  useNavigation,
  secaoDoCabecalho,
  type RouteName,
} from '../nav/navigationStack.js';
import { HeaderClock } from './HeaderClock.js';
import { SearchIcon, SettingsIcon } from './icons.js';
import logoUrl from '../assets/logo-aura-67.png';
import { gapRowClass, gapVar } from '../theme/gap.js';
import { cssLen } from '../theme/cssMath.js';

interface Section {
  name: RouteName;
  labelKey: Parameters<typeof t>[0];
  /** entrada compacta (só ícone) — não some em telas estreitas. */
  icon?: ReactNode;
}

const SECTIONS: Section[] = [
  { name: 'home', labelKey: 'nav.home' },
  { name: 'live', labelKey: 'nav.live' },
  { name: 'movies', labelKey: 'nav.movies' },
  { name: 'series', labelKey: 'nav.series' },
  { name: 'favorites', labelKey: 'nav.favorites' },
  { name: 'search', labelKey: 'search.title', icon: <SearchIcon /> },
  // engrenagem, como na maioria dos apps — o rótulo fica no `title` (a11y).
  // SVG (não o glifo `⚙`): achado em campo (TV LG real) — a fonte do
  // firmware não tem esse glifo, ficava simplesmente em branco.
  { name: 'settings', labelKey: 'nav.settings', icon: <SettingsIcon /> },
];

function HeaderItem({
  section,
  active,
}: Readonly<{ section: Section; active: boolean }>) {
  const resetTo = useNavigation((s) => s.resetTo);
  const go = () => resetTo({ name: section.name });
  const { ref, focused } = useFocusable({
    focusKey: `header-${section.name}`,
    onEnterPress: go,
  });

  return (
    <button
      ref={ref}
      type="button"
      onClick={pressWithFocus(`header-${section.name}`, go)}
      title={t(section.labelKey)}
      style={{
        appearance: 'none',
        background: 'none',
        border: 'none',
        cursor: 'pointer',
        font: 'inherit',
        fontFamily: 'var(--font-display)',
        // ícones (busca, engrenagem) um degrau maiores que o texto do menu
        fontSize: section.icon ? 'var(--fs-body)' : 'var(--fs-meta)',
        lineHeight: 1,
        textTransform: 'uppercase',
        letterSpacing: '0.04em',
        whiteSpace: 'nowrap',
        flexShrink: 0,
        padding: section.icon ? '0.2em 0.3em' : '0.35em 0.15em',
        color: active || focused ? 'var(--accent)' : 'var(--text-secondary)',
        borderBottom: `0.18rem solid ${active ? 'var(--accent)' : 'transparent'}`,
        outline: focused
          ? 'var(--focus-ring-width) solid var(--focus-ring)'
          : 'var(--focus-ring-width) solid transparent',
        outlineOffset: '0.1rem',
        transition: 'color 160ms',
      }}
    >
      {section.icon ?? t(section.labelKey)}
    </button>
  );
}

/** Navegação primária persistente (design-inventory §0). */
export function AppHeader() {
  const { ref, focusKey } = useFocusable({ focusKey: 'app-header', trackChildren: true });
  // A seção realçada vem da pilha, não de `current.name`: dentro de um detalhe
  // ou do player, `current.name` é `movieDetail`/`player` e o realce sumia,
  // deixando o usuário sem saber de que seção veio.
  const secaoAtiva = useNavigation((s) => secaoDoCabecalho(s.stack));

  return (
    <FocusContext.Provider value={focusKey}>
      <header
        ref={ref}
        className={gapRowClass}
        style={{
          display: 'flex',
          alignItems: 'center',
          minHeight: 'var(--header-h)',
          padding: '0.4rem var(--safe-x)',
          background: 'var(--bg-panel)',
          borderBottom: '1px solid var(--border-subtle)',
          ...gapVar('1rem'),
        }}
      >
        <img
          src={logoUrl}
          alt={t('app.shortName')}
          style={{
            // Altura nunca ultrapassa o espaço livre do header em nenhum ponto
            // do clamp responsivo (--header-h), incluindo o cenário mais
            // apertado (telefone deitado); a largura segue a proporção
            // natural do arquivo (~3,95:1) — nunca esticar/distorcer o logo.
            height: cssLen('min(2.4rem, calc(var(--header-h) - 1.2rem))'),
            width: 'auto',
            flexShrink: 0,
          }}
        />
        <nav
          data-scroll-x
          className={gapRowClass}
          style={{
            display: 'flex',
            marginLeft: 'auto',
            minWidth: 0,
            alignItems: 'center',
            ...gapVar('0.9rem'),
          }}
        >
          {SECTIONS.map((s) => (
            <HeaderItem key={s.name} section={s} active={s.name === secaoAtiva} />
          ))}
        </nav>
        <HeaderClock />
      </header>
    </FocusContext.Provider>
  );
}
