/**
 * Normalização de horário de EPG para epoch UTC (RF-67).
 *
 * O bug nº1 de guia de programação é comparar strings de hora ou ignorar o offset.
 * Aqui tudo vira `number` (epoch ms UTC) no momento do parse; a conversão para o fuso
 * da TV acontece só na renderização.
 *
 * Formato XMLTV: `YYYYMMDDHHMMSS ±HHMM` (offset quase sempre presente; quando ausente,
 * o padrão XMLTV manda assumir a hora local do gerador — usamos o fuso do painel).
 */

const XMLTV_RE = /^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})?(?:\s*([+-]\d{4}|Z))?$/;

export interface ParseXmltvOptions {
  /** Offset em minutos a assumir quando a string não traz offset (fuso do painel). */
  fallbackOffsetMinutes?: number;
}

/** `20260908193000 -0300` → epoch ms UTC. Retorna `null` se não parsear. */
export function parseXmltvTimestamp(
  raw: string,
  opts: ParseXmltvOptions = {},
): number | null {
  const m = XMLTV_RE.exec(raw.trim());
  if (!m) return null;
  const [, y, mo, d, h, mi, s, tz] = m;

  const utcNoTz = Date.UTC(+y!, +mo! - 1, +d!, +h!, +mi!, s ? +s : 0);
  if (Number.isNaN(utcNoTz)) return null;

  const offsetMin = parseOffset(tz) ?? opts.fallbackOffsetMinutes ?? 0;
  // a hora escrita está no fuso `offsetMin`; para chegar a UTC, subtrai o offset
  return utcNoTz - offsetMin * 60_000;
}

/** `America/Sao_Paulo`-style: converte um epoch UTC para os campos locais de um fuso. */
export function offsetOf(tz: string | undefined, at: number): number {
  if (!tz) return 0;
  try {
    const dtf = new Intl.DateTimeFormat('en-US', {
      timeZone: tz,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
    const parts = Object.fromEntries(dtf.formatToParts(at).map((p) => [p.type, p.value]));
    const asUtc = Date.UTC(
      +parts.year!,
      +parts.month! - 1,
      +parts.day!,
      +parts.hour!,
      +parts.minute!,
      +parts.second!,
    );
    return Math.round((asUtc - at) / 60_000);
  } catch {
    return 0;
  }
}

function parseOffset(tz: string | undefined): number | null {
  if (!tz) return null;
  if (tz === 'Z' || tz === '+0000' || tz === '-0000') return 0;
  const sign = tz[0] === '-' ? -1 : 1;
  const hh = Number(tz.slice(1, 3));
  const mm = Number(tz.slice(3, 5));
  if (Number.isNaN(hh) || Number.isNaN(mm)) return null;
  return sign * (hh * 60 + mm);
}
