import { useCallback } from 'react';
import type { XtreamProvider } from '@mfp/core';
import { useRuntime } from './RuntimeContext.js';
import { useLists } from '../state/lists.js';

/**
 * Cache de providers em sessão (GTV-RF-25 / M7). Chave: listId:server:user:password.
 * Reutiliza a mesma instância enquanto credenciais não mudarem.
 * Invalida quando lista é removida, servidor/usuário/senha mudam.
 */
const providerCache = new Map<string, XtreamProvider>();

function chaveProvider(listId: string, serverUrl: string, username: string, password: string): string {
  return `${listId}:${serverUrl}:${username}:${password}`;
}

/**
 * Devolve uma função que monta o `IptvProvider` da lista ativa (com a senha do
 * secure storage). Usada por telas que precisam de dados sob demanda —
 * `get_vod_info`, `get_series_info`, `get_short_epg`.
 *
 * O provider é memoizado por sessão (GTV-RF-25): a mesma lista + servidor +
 * usuário + senha reutiliza a mesma instância.
 */
export function useProvider() {
  const rt = useRuntime();
  const activeListId = useLists((s) => s.activeListId);
  const lists = useLists((s) => s.lists);
  const getPassword = useLists((s) => s.getPassword);

  return useCallback(async (): Promise<{ provider: XtreamProvider; listId: string }> => {
    const list = lists.find((l) => l.id === activeListId);
    if (!list) throw new Error('sem lista ativa');
    const password = (await getPassword(rt, list.id)) ?? '';
    const chave = chaveProvider(list.id, list.serverUrl, list.username, password);

    let provider = providerCache.get(chave);
    if (!provider) {
      provider = rt.makeProvider(list, password);
      providerCache.set(chave, provider);
    }

    return { provider, listId: list.id };
  }, [rt, activeListId, lists, getPassword]);
}

/**
 * Limpar cache de provider (chamado quando lista é removida ou credenciais mudam).
 * Interno — não exportado.
 */
export function invalidateProviderCache(listId: string): void {
  for (const key of providerCache.keys()) {
    if (key.startsWith(`${listId}:`)) {
      providerCache.delete(key);
    }
  }
}
