import { normalizeText } from './normalize.js';

/**
 * Painéis Xtream costumam prefixar a categoria com a seção — "Filmes | Terror",
 * "SERIES | Netflix", "CANAIS | Abertos". Dentro da tela de Filmes esse prefixo
 * é ruído: repete em todos os chips e os alarga (medido: a faixa de chips ficava
 * com 5153px de conteúdo para 766px visíveis).
 *
 * Só remove quando o prefixo é mesmo a seção atual, comparado sem acento e sem
 * caixa — nomes como "Documentarios" ou "Stand Up Comedy" passam intactos, e
 * "Filmes | 4K" não vira "4K" numa tela de séries.
 */
export function categoryLabel(name: string, section: 'vod' | 'series' | 'live'): string {
  const corte = name.indexOf('|');
  if (corte < 0) return name.trim();

  const prefixo = normalizeText(name.slice(0, corte));
  const resto = name.slice(corte + 1).trim();
  if (!resto) return name.trim();

  return PREFIXOS[section].includes(prefixo) ? resto : name.trim();
}

/** Variantes que os painéis usam para cada seção (já normalizadas). */
const PREFIXOS: Record<'vod' | 'series' | 'live', readonly string[]> = {
  vod: ['filmes', 'filme', 'movies', 'vod'],
  series: ['series', 'serie', 'seriados'],
  live: ['canais', 'canal', 'tv', 'live'],
};
