import type { CacheConfig } from './config.js';
import type { CatalogSection } from './db.js';

/** `true` quando o cache está velho o bastante para um refresh. */
export function isStale(
  lastSyncAt: number | undefined,
  ttlMs: number,
  now = Date.now(),
): boolean {
  if (lastSyncAt === undefined) return true;
  return now - lastSyncAt >= ttlMs;
}

/** Seções cujo cache passou do TTL — usado pelo scheduler de auto-refresh (RF-65). */
export function staleSections(
  lastSyncBySection: Partial<Record<CatalogSection, number>>,
  config: CacheConfig,
  now = Date.now(),
): CatalogSection[] {
  const sections: CatalogSection[] = ['live', 'vod', 'series'];
  return sections.filter((s) => isStale(lastSyncBySection[s], config.ttlMs[s], now));
}
