import { init, setKeyMap } from '@noriginmedia/norigin-spatial-navigation';

let started = false;

/**
 * Inicializa a navegação espacial (norigin). Deve rodar **antes** do primeiro
 * render que usa foco — chamada no `main.tsx` de cada `apps/<plataforma>`, nunca
 * num efeito: efeitos de filho rodam antes do efeito do App, e um `setFocus`
 * chegaria antes do `init` (validado no emulador Android TV — o foco ficava morto).
 *
 * O D-pad de TV pode chegar como keyCode web (Chromium traduz: 37-40/13) OU como
 * keyCode nativo do Android (19-22/23) — registramos os dois. `Back`, mídia,
 * coloridas e canal ficam no `useLogicalKeys` via `PlatformAdapter.keyMap`.
 */
export function initNavigation() {
  if (started) return;
  started = true;

  init({ debug: false, visualDebug: false, shouldFocusDOMNode: true });

  setKeyMap({
    up: [38, 19],
    down: [40, 20],
    left: [37, 21],
    right: [39, 22],
    enter: [13, 23, 66],
  });
}
