import { useEffect, useState } from 'react';
import { FocusContext, useFocusable } from '@noriginmedia/norigin-spatial-navigation';
import { FocusButton } from './FocusButton.js';
import { useImageSlot } from '../media/useImageSlot.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';
import { cssLen } from '../theme/cssMath.js';

export interface HeroItem {
  id: string;
  title: string;
  poster?: string;
  meta?: string;
  plot?: string;
}

export interface HeroCarouselProps {
  items: HeroItem[];
  focusKey: string;
  onWatch: (item: HeroItem) => void;
  onInfo: (item: HeroItem) => void;
}

const INTERVAL = 8000; // auto-avanço a cada ~8s (design-inventory §Movimento)

/** Carrossel de destaque da Home (tela 01). Pausa ao receber foco. */
export function HeroCarousel({ items, focusKey, onWatch, onInfo }: HeroCarouselProps) {
  const [index, setIndex] = useState(0);
  const {
    ref,
    focusKey: fk,
    focused,
    hasFocusedChild,
  } = useFocusable({
    focusKey,
    trackChildren: true,
  });

  const paused = focused || hasFocusedChild;
  const count = items.length;

  useEffect(() => {
    if (paused || count <= 1) return;
    const id = setInterval(() => setIndex((i) => (i + 1) % count), INTERVAL);
    return () => clearInterval(id);
  }, [paused, count]);

  // item/safeIndex calculados antes do `return null` abaixo: hooks não podem
  // ser pulados em algumas renderizações e chamados em outras (regra dos
  // hooks) — `useImageSlot`, logo a seguir, precisa vir antes desse `return`.
  const safeIndex = count > 0 ? index % count : 0; // itens podem encolher entre renders
  const item = items[safeIndex];

  // Fila de carregamento (PERF-16): só um destaque por vez, prioridade máxima
  // (0) — é a primeira coisa que a Home mostra. `useImageSlot` cancela o
  // pedido anterior sozinho quando `item.poster` muda (auto-avanço do carrossel).
  const { liberada, falhou, aoCarregar, aoFalhar } = useImageSlot(item?.poster, 0);

  if (!item) return null;
  const mostrarImagem = !!item.poster && liberada && !falhou;

  return (
    <FocusContext.Provider value={fk}>
      <section
        ref={ref}
        style={{
          position: 'relative',
          minHeight: cssLen('clamp(12rem, 38vh, 20rem)'),
          borderRadius: 'var(--radius-md)',
          overflow: 'hidden',
          background: 'var(--bg-panel)',
        }}
      >
        {mostrarImagem && (
          <img
            src={item.poster}
            alt=""
            loading="lazy"
            decoding="async"
            onLoad={aoCarregar}
            onError={aoFalhar}
            style={{
              position: 'absolute',
              top: 0,
              right: 0,
              bottom: 0,
              left: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              objectPosition: 'right center',
            }}
          />
        )}
        <div
          aria-hidden
          style={{
            position: 'absolute',
            top: 0,
            right: 0,
            bottom: 0,
            left: 0,
            background: 'linear-gradient(90deg, var(--bg-base) 35%, transparent 75%)',
          }}
        />
        <div
          className={gapColClass}
          style={{
            position: 'relative', // acima das camadas absolutas acima
            padding: cssLen('clamp(1rem, 3vw, 2rem)'),
            display: 'flex',
            flexDirection: 'column',
            ...gapVar('0.5rem'),
          }}
        >
          <p
            style={{
              color: 'var(--accent)',
              fontFamily: 'var(--font-display)',
              fontSize: 'var(--fs-meta)',
              margin: 0,
            }}
          >
            {t('nav.home')}
          </p>
          <h2
            style={{
              fontSize: 'var(--fs-title)',
              margin: 0,
              maxWidth: cssLen('min(90%, 34rem)'),
              display: '-webkit-box',
              WebkitLineClamp: 2,
              WebkitBoxOrient: 'vertical',
              overflow: 'hidden',
            }}
          >
            {item.title}
          </h2>
          {item.meta && (
            <p style={{ color: 'var(--text-secondary)', margin: 0 }}>{item.meta}</p>
          )}
          {item.plot && (
            <p
              style={{
                maxWidth: cssLen('min(90%, 34rem)'),
                color: 'var(--text-secondary)',
                margin: 0,
                display: '-webkit-box',
                WebkitLineClamp: 2,
                WebkitBoxOrient: 'vertical',
                overflow: 'hidden',
              }}
            >
              {truncate(item.plot, 160)}
            </p>
          )}
          <div
            className={gapRowClass}
            style={{ display: 'flex', marginTop: '1rem', ...gapVar('1rem') }}
          >
            <FocusButton
              primary
              focusKey={`${focusKey}-watch`}
              onPress={() => onWatch(item)}
            >
              {t('common.watch')}
            </FocusButton>
            <FocusButton focusKey={`${focusKey}-info`} onPress={() => onInfo(item)}>
              {t('common.moreInfo')}
            </FocusButton>
          </div>
          <div
            className={gapRowClass}
            style={{ display: 'flex', marginTop: '1rem', ...gapVar('0.4rem') }}
          >
            {items.map((it, i) => (
              <span
                key={it.id}
                style={{
                  width: i === safeIndex ? '1.4rem' : '0.5rem',
                  height: '0.5rem',
                  borderRadius: 999,
                  background: i === safeIndex ? 'var(--accent)' : 'var(--bg-raised)',
                  transition: 'width var(--dur-base) var(--ease)',
                }}
              />
            ))}
          </div>
        </div>
      </section>
    </FocusContext.Provider>
  );
}

function truncate(s: string, n: number): string {
  return s.length > n ? `${s.slice(0, n - 1)}…` : s;
}
