import { create } from 'zustand';
import type { Account, StoredList } from '@mfp/core';
import type { Runtime } from '../runtime/runtime.js';
import { classifyError, type AppError } from '../errors.js';
import { useLists } from './lists.js';

// Sessão da lista ativa: resultado do `authenticate()` + estado da conta (RF-54).

export type SessionStatus = 'unknown' | 'ok' | 'expired' | 'error';

interface SessionState {
  account: Account | null;
  status: SessionStatus;
  error: AppError | null;
  authenticate: (rt: Runtime, list: StoredList, password: string) => Promise<void>;
  reset: () => void;
}

function isExpired(account: Account): boolean {
  return account.expiresAt != null && account.expiresAt < Date.now();
}

export const useSession = create<SessionState>((set) => ({
  account: null,
  status: 'unknown',
  error: null,

  authenticate: async (rt, list, password) => {
    try {
      const provider = rt.makeProvider(list, password);
      const account = await provider.authenticate();
      set({
        account,
        status: isExpired(account) ? 'expired' : 'ok',
        error: null,
      });
      // GTV-033/034: probe HTTPS aprendeu algo novo neste boot — persiste pra
      // não refazer essa checagem de rede em todo boot futuro desta lista.
      if (account.preferredHttpsBase && account.preferredHttpsBase !== list.preferredHttpsBase) {
        void useLists.getState().definirHttpsBase(rt, list.id, account.preferredHttpsBase);
      }
    } catch (err) {
      const e = classifyError(err);
      set({
        account: null,
        status: e.code === 'AUTH-003' ? 'expired' : 'error',
        error: e,
      });
    }
  },

  reset: () => set({ account: null, status: 'unknown', error: null }),
}));
