import { useCallback, useEffect, useState } from 'react';
import { type StreamKind } from '@mfp/core';
import { VirtualGrid } from '../components/VirtualGrid.js';
import { PosterCard } from '../components/PosterCard.js';
import { GenreChips } from '../components/GenreChips.js';
import { FocusButton } from '../components/FocusButton.js';
import { EmptyState } from '../components/states.js';
import { useToast } from '../components/Toast.js';
import { useLogicalKeys } from '../nav/keys.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useNavigation } from '../nav/navigationStack.js';
import { useFavorites } from '../state/favorites.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';

interface FavItem {
  kind: StreamKind;
  id: string;
  name: string;
  poster?: string;
}

/** Sem closure — estável para sempre (PERF-09), como em `Catalog.tsx`. */
const renderPoster = (it: FavItem, i: number, focused: boolean) => (
  <PosterCard
    focused={focused}
    prioridade={i}
    data={{ title: it.name, poster: it.poster }}
  />
);

type Tab = 'all' | 'movie' | 'series' | 'live';

export function Favorites({ listId }: { listId: string }) {
  const rt = useRuntime();
  const push = useNavigation((s) => s.push);
  // Seletores estreitos (PERF-11): aqui `keys` já é usado direto (sem precisar
  // do truque do `_favKeys` das telas de detalhe) — ver o comentário em
  // MovieDetail.tsx para o porquê do padrão.
  const keys = useFavorites((s) => s.keys);
  const load = useFavorites((s) => s.load);
  const toggle = useFavorites((s) => s.toggle);
  const mostrarAviso = useToast((s) => s.show);
  const [items, setItems] = useState<FavItem[]>([]);
  const [tab, setTab] = useState<Tab>('all');
  /**
   * Índice — e não o item — do cartão focado: ao remover, o índice continua
   * apontando para quem ocupou o lugar, que é o próximo da lista. Guardar o
   * item faria o alvo saltar para outro canto a cada remoção.
   */
  const [indiceFocado, setIndiceFocado] = useState(0);
  const [abaAnterior, setAbaAnterior] = useState(tab);
  if (abaAnterior !== tab) {
    setAbaAnterior(tab);
    setIndiceFocado(0);
  }

  useEffect(() => {
    void load(rt, listId);
  }, [rt, listId, load]);

  useEffect(() => {
    void (async () => {
      const repo = rt.catalog(listId);
      const resolved: FavItem[] = [];
      for (const key of keys) {
        const [kind, id] = key.split(':') as [StreamKind, string];
        let name: string | undefined;
        let poster: string | undefined;
        if (kind === 'movie') {
          const m = await repo.movie(id);
          name = m?.name;
          poster = m?.poster;
        } else if (kind === 'series') {
          const s = await repo.seriesById(id);
          name = s?.name;
          poster = s?.poster;
        } else {
          const c = await repo.channel(id);
          name = c?.name;
          poster = c?.logo;
        }
        if (name) resolved.push({ kind, id, name, poster });
      }
      setItems(resolved);
    })();
  }, [rt, listId, keys]);

  const shown = tab === 'all' ? items : items.filter((i) => i.kind === tab);
  const alvo = shown[Math.min(indiceFocado, shown.length - 1)];

  const remover = () => {
    if (!alvo) return;
    void toggle(rt, listId, alvo.kind, alvo.id);
    // o cartão some na hora; sem um aviso, some sem explicação
    mostrarAviso(t('favorites.removed', { title: alvo.name }));
  };
  // mesma tecla que favorita na TV ao vivo e no player
  useLogicalKeys(rt.adapter, { Yellow: remover });

  // Antes do `return` condicional abaixo: hooks não podem ser pulados em
  // algumas renderizações e chamados em outras (regra dos hooks).
  const open = useCallback(
    (it: FavItem) => {
      if (it.kind === 'movie') push({ name: 'movieDetail', params: { id: it.id } });
      else if (it.kind === 'series')
        push({ name: 'seriesDetail', params: { id: it.id } });
      else
        push({
          name: 'player',
          params: { kind: 'live', streamId: it.id, title: it.name },
        });
    },
    [push],
  );
  const onItemFocus = useCallback((_it: FavItem, i: number) => setIndiceFocado(i), []);

  if (keys.size === 0) {
    return <EmptyState title={t('nav.favorites')} body={t('favorites.empty')} />;
  }

  return (
    <div
      className={gapColClass}
      style={{
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        minHeight: 0, // ver a nota em `Catalog.tsx`
        ...gapVar('1rem'),
      }}
    >
      <GenreChips
        focusKey="fav-tabs"
        selectedId={tab}
        onSelect={(id) => setTab(id as Tab)}
        chips={[
          { id: 'all', label: t('favorites.tabAll') },
          { id: 'movie', label: t('favorites.tabMovies') },
          { id: 'series', label: t('favorites.tabSeries') },
          { id: 'live', label: t('favorites.tabChannels') },
        ]}
      />
      {/* Barra de ação sobre o cartão focado — mesma ideia da TV ao vivo: a
          remoção precisa de um alvo explícito, senão vira ação às cegas.
          O botão fica à ESQUERDA, e não à direita como na TV ao vivo, porque
          ali as linhas ocupam a largura toda: aqui, com poucos favoritos, não
          há cartão nenhum debaixo do canto direito e o D-pad não descia da
          barra para a grade. Sobre a primeira coluna sempre há. */}
      <div
        className={gapRowClass}
        style={{ display: 'flex', alignItems: 'center', ...gapVar('0.8rem') }}
      >
        <FocusButton focusKey="fav-remove" disabled={!alvo} onPress={remover}>
          {t('favorites.remove')}
        </FocusButton>
        <span
          style={{
            flex: 1,
            minWidth: 0,
            whiteSpace: 'nowrap',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            color: 'var(--text-secondary)',
          }}
        >
          {alvo?.name ?? ''}
        </span>
      </div>

      {/* `minHeight: 0` — ver a nota em `Catalog.tsx` */}
      <div style={{ flex: 1, minHeight: 0 }}>
        <VirtualGrid<FavItem>
          focusKey="fav-grid"
          restoreKey={`fav:${tab}`}
          items={shown}
          minItemWidth={220}
          renderItem={renderPoster}
          onItemFocus={onItemFocus}
          onItemPress={open}
        />
      </div>
    </div>
  );
}
