import { memo } from 'react';
import { useImageSlot } from './useImageSlot.js';

/** Até duas iniciais do título, para o cartão nunca aparecer como um vazio. */
function iniciais(titulo: string): string {
  return titulo
    .split(/\s+/)
    .filter((p) => /[\p{L}\p{N}]/u.test(p))
    .slice(0, 2)
    .map((p) => p[0]!.toUpperCase())
    .join('');
}

export interface PosterProps {
  url: string | undefined;
  titulo: string;
  /**
   * Menor = mais urgente. **Simplificação assumida**: aqui entra o `index` do
   * item na lista (ordem de leitura), não a distância ao item focado como o
   * plan.md original sugeria — calcular a distância exigiria propagar o
   * índice focado como prop reativa até esta folha, e ele muda a cada tecla
   * de D-pad; isso re-renderizaria as células memoizadas do `PERF-09` a cada
   * movimento de foco, brigando com aquele trabalho em vez de completá-lo. A
   * fila (`imageQueue`) já captura a prioridade só uma vez, no primeiro
   * pedido — então o ganho de uma distância exata seria pequeno frente a esse
   * custo.
   */
  prioridade: number;
}

/**
 * Pôster com fila de carregamento (PERF-16 / spec 002): concorrência limitada,
 * cancelamento real ao sair da tela, e as iniciais por baixo como placeholder
 * e como estado de falha — igual ao `PosterCard` de antes, só a camada de
 * imagem mudou de `background-image` (sem como cancelar) para `<img>`.
 *
 * Memoizado (PERF-09): é a folha mais repetida da UI.
 */
export const Poster = memo(function Poster({ url, titulo, prioridade }: PosterProps) {
  const { liberada, falhou, aoCarregar, aoFalhar } = useImageSlot(url, prioridade);
  const mostrarImagem = !!url && liberada && !falhou;

  return (
    <>
      <span
        aria-hidden
        style={{
          position: 'absolute',
          top: 0,
          right: 0,
          bottom: 0,
          left: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontFamily: 'var(--font-display)',
          fontSize: '2.4em',
          letterSpacing: '0.05em',
          color: 'var(--text-disabled)',
        }}
      >
        {iniciais(titulo)}
      </span>
      {mostrarImagem && (
        // `position:absolute` + `top/right/bottom/left:0` já garantem o
        // tamanho final sem depender da imagem carregar — não há corte de
        // layout a evitar aqui, então `width`/`height` HTML (dica de
        // decodificação) ficaram de fora desta primeira versão.
        // `inset` (shorthand) é ignorado no Chromium do simulador/TV webOS
        // 6.0 (< Chrome 87) — some silenciosamente e some o layout junto.
        <img
          src={url}
          alt=""
          loading="lazy"
          decoding="async"
          onLoad={aoCarregar}
          onError={aoFalhar}
          style={{
            position: 'absolute',
            top: 0,
            right: 0,
            bottom: 0,
            left: 0,
            width: '100%',
            height: '100%',
            objectFit: 'cover',
          }}
        />
      )}
    </>
  );
});
