import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App, initNavigation, type Runtime } from '@mfp/ui';
import { createWebAdapter } from '@mfp/platform/web';
import { createWebVideoPlayer } from './webVideoPlayer.js';
import { installDevCorsProxy } from './devCorsProxy.js';
import { FaultPanel, comInjecaoDeFalha } from './faultPanel.js';

// spec 002: expõe o `Perf` do runtime ao roteiro de medição e marca o 1º pixel.
function publicarPerf(rt: Runtime): void {
  (globalThis as { __auraPerf?: Runtime['perf'] }).__auraPerf = rt.perf;
  requestAnimationFrame(() => {
    requestAnimationFrame(() => rt.perf.marcarUnica('boot:firstPaint'));
  });
}

// dev desktop: painéis Xtream não mandam CORS → passa tudo pelo /__cors/ do Vite
if (import.meta.env.DEV) installDevCorsProxy();

initNavigation();

const root = document.getElementById('root');
if (!root) throw new Error('#root não encontrado');

// A injeção de falha só existe no host de desenvolvimento; em build de produção
// do `apps/dev` (usado para conferir o bundle) o painel some junto.
const criarPlayer = import.meta.env.DEV
  ? comInjecaoDeFalha(createWebVideoPlayer)
  : createWebVideoPlayer;

createRoot(root).render(
  <StrictMode>
    <App
      adapter={createWebAdapter({ createVideoPlayer: criarPlayer })}
      onRuntime={import.meta.env.DEV ? publicarPerf : undefined}
    />
    {import.meta.env.DEV && <FaultPanel />}
  </StrictMode>,
);
