/**
 * Parser incremental de XMLTV (`xmltv.php` / `epg.php`) — decisions D-22.
 *
 * A stack é travada (constitution §4): sem lib de XML. O XMLTV de painel é
 * gerado por máquina e regular — dá para varrer blocos `<programme>…</programme>`
 * sobre um buffer que cresce por chunk e encolhe conforme consumido, sem nunca
 * segurar o arquivo inteiro (medido: 9,7 MB cru / 27 mil programas neste painel).
 *
 * Só `<programme>` interessa: o atributo `channel` já traz o id que casa com o
 * `epg_channel_id` do canal (RF-15). Os `<channel>` do topo são ignorados.
 *
 * Robustez: entidade/CDATA decodificadas, atributos em qualquer ordem, tag
 * partida entre dois chunks, programa sem título ou com XML torto é pulado —
 * **nunca lança**.
 */

export interface RawProgramme {
  /** valor do atributo `channel` — o id a casar com `epg_channel_id`. */
  channel: string;
  /** `YYYYMMDDHHMMSS ±HHMM` (formato XMLTV). */
  start: string;
  stop: string;
  /** epoch em segundos, quando o painel manda (mais simples e sem ambiguidade). */
  startTimestamp?: string;
  stopTimestamp?: string;
  title: string;
  desc?: string;
}

export interface XmltvParseOptions {
  aborted?: () => boolean;
  /** Descarta canais alheios antes de extrair horários, título e descrição. */
  acceptChannel?: (channel: string) => boolean;
  includeDescription?: boolean;
}

const ENTITIES: Record<string, string> = {
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
  apos: "'",
};

/** `&amp;` → `&`, `&#233;` → `é`, `&#xE9;` → `é`. Deixa intacto o que não conhece. */
export function decodeXmlText(s: string): string {
  return s.replace(/&(#x[0-9a-fA-F]+|#\d+|[a-zA-Z]+);/g, (m, e: string) => {
    if (e[0] === '#') {
      const code =
        e[1] === 'x' || e[1] === 'X'
          ? parseInt(e.slice(2), 16)
          : parseInt(e.slice(1), 10);
      return Number.isFinite(code) && code >= 0 && code <= 0x10ffff
        ? String.fromCodePoint(code)
        : m;
    }
    return ENTITIES[e] ?? m;
  });
}

const ATTRS = {
  channel: /\bchannel\s*=\s*"([^"]*)"/,
  start: /\bstart\s*=\s*"([^"]*)"/,
  stop: /\bstop\s*=\s*"([^"]*)"/,
  start_timestamp: /\bstart_timestamp\s*=\s*"([^"]*)"/,
  stop_timestamp: /\bstop_timestamp\s*=\s*"([^"]*)"/,
};
const CHILDREN = {
  title: /<title\b[^>]*>([\s\S]*?)<\/title>/,
  desc: /<desc\b[^>]*>([\s\S]*?)<\/desc>/,
};

function attr(openTag: string, name: keyof typeof ATTRS): string | undefined {
  const m = ATTRS[name].exec(openTag);
  return m ? m[1] : undefined;
}

/** Primeiro `<tag …>…</tag>` do bloco, com CDATA opcional. */
function childText(block: string, tag: keyof typeof CHILDREN): string | undefined {
  const m = CHILDREN[tag].exec(block);
  if (!m) return undefined;
  const inner = m[1] ?? '';
  const cdata = /^\s*<!\[CDATA\[([\s\S]*?)\]\]>\s*$/.exec(inner);
  if (cdata) return cdata[1]!.trim();
  return decodeXmlText(inner).trim();
}

function build(
  openTag: string,
  body: string,
  opts: XmltvParseOptions,
): RawProgramme | null {
  const channel = attr(openTag, 'channel');
  if (!channel || (opts.acceptChannel && !opts.acceptChannel(channel))) return null;
  const start = attr(openTag, 'start');
  const title = childText(body, 'title');
  if (!channel || !start || !title) return null;
  const stop = attr(openTag, 'stop') ?? '';
  const desc = opts.includeDescription === false ? undefined : childText(body, 'desc');
  const startTimestamp = attr(openTag, 'start_timestamp');
  const stopTimestamp = attr(openTag, 'stop_timestamp');
  return {
    channel,
    start,
    stop,
    title,
    ...(startTimestamp ? { startTimestamp } : {}),
    ...(stopTimestamp ? { stopTimestamp } : {}),
    ...(desc ? { desc } : {}),
  };
}

const TAG = '<programme';

/**
 * Consome todo `<programme>` completo no buffer; devolve o resto não
 * consumido. `onProgramme` pode devolver uma `Promise` (PERF-02 / spec 002):
 * quem grava em lote durante o parse precisa poder `await` a escrita antes de
 * seguir pro próximo. O orçamento é compartilhado entre chunks: inclusive
 * programas descartados precisam devolver a thread ao controle remoto.
 */
async function drain(
  buf: string,
  onProgramme: (p: RawProgramme) => void | Promise<void>,
  last: boolean,
  opts: XmltvParseOptions,
  budget: { deadline: number; programmes: number },
): Promise<string> {
  for (;;) {
    if (opts.aborted?.()) return '';
    if (++budget.programmes % 64 === 0 && Date.now() >= budget.deadline) {
      await new Promise<void>((resolve) => setTimeout(resolve, 0));
      budget.deadline = Date.now() + 12;
      if (opts.aborted?.()) return '';
    }
    const open = buf.indexOf(TAG);
    if (open < 0) {
      // pode haver um `<programm…` cortado no fim do chunk
      return last ? '' : buf.slice(Math.max(0, buf.length - TAG.length));
    }
    const gt = buf.indexOf('>', open);
    if (gt < 0) return buf.slice(open); // tag de abertura ainda incompleta

    // `<programme … />` sem filhos — sem título, não serve
    if (buf[gt - 1] === '/') {
      buf = buf.slice(gt + 1);
      continue;
    }

    const close = buf.indexOf('</programme>', gt);
    if (close < 0) {
      if (last) return '';
      return buf.slice(open); // espera o fechamento chegar
    }

    const p = build(buf.slice(open, gt + 1), buf.slice(gt + 1, close), opts);
    if (p) {
      const pending = onProgramme(p);
      if (pending) await pending;
    }
    buf = buf.slice(close + '</programme>'.length);
  }
}

export async function parseXmltvStream(
  stream: ReadableStream<Uint8Array>,
  onProgramme: (p: RawProgramme) => void | Promise<void>,
  opts: XmltvParseOptions = {},
): Promise<void> {
  const reader = stream.getReader();
  const decoder = new TextDecoder('utf-8');
  let buf = '';
  let completed = false;
  const budget = { deadline: Date.now() + 12, programmes: 0 };
  try {
    for (;;) {
      if (opts.aborted?.()) return;
      const { value, done } = await reader.read();
      if (!done && value) buf += decoder.decode(value, { stream: true });
      if (done) buf += decoder.decode();
      buf = await drain(buf, onProgramme, done, opts, budget);
      if (opts.aborted?.()) return;
      if (done) {
        completed = true;
        break;
      }
    }
  } finally {
    // releaseLock sozinho deixa o download continuar acumulando bytes na fila.
    if (!completed) await reader.cancel().catch(() => undefined);
    try {
      reader.releaseLock();
    } catch {
      // Achado real (Emulator webOS 4, 2026-09-17/18 — spec 005 research.md
      // §16.1): neste motor, `reader.cancel()` acima já pode liberar o lock
      // como efeito colateral; chamar `releaseLock()` de novo lança
      // "This readable stream reader has been released and cannot be used to
      // monitor the stream's state". Uma exceção síncrona dentro de um
      // `finally` vira a rejeição da função inteira mesmo com o try já tendo
      // terminado bem — sem este catch, virava uma promise rejeitada nunca
      // tratada (`Uncaught (in promise)` no console, não afeta o app, mas
      // suja o log e mascara erros reais). Idempotente: se já está liberado,
      // não há nada a fazer.
    }
  }
}
