import { useEffect } from 'react';

/**
 * Pilha de quem quer tratar o BACK antes do app.
 *
 * Os handlers de tecla são listeners de captura no `window`, então quem registra
 * primeiro roda primeiro — e o do `App` monta antes de qualquer modal. Sem esta
 * pilha, apertar BACK com o modal de PIN aberto ia direto para o "apertar de
 * novo para sair", em vez de fechar o modal. Numa TV o BACK é o cancelar
 * natural, então isso precisa funcionar.
 *
 * O topo vence: o overlay mais recente é o primeiro a ter chance.
 */
const pilha: Array<() => void> = [];

/** Registra um handler enquanto o componente estiver montado. */
export function useBackHandler(handler: () => void, ativo = true) {
  useEffect(() => {
    if (!ativo) return;
    pilha.push(handler);
    return () => {
      const i = pilha.lastIndexOf(handler);
      if (i >= 0) pilha.splice(i, 1);
    };
  }, [handler, ativo]);
}

/**
 * Executa o handler do topo, se houver.
 * @returns `true` se alguém tratou — o `App` então não desempilha nem sai.
 */
export function handleBack(): boolean {
  const topo = pilha[pilha.length - 1];
  if (!topo) return false;
  topo();
  return true;
}
