import { create } from 'zustand';
import {
  CatalogGateway,
  type CatalogSection,
  type Movie,
  type PlaybackProgress,
  type Series,
} from '@mfp/core';
import type { Runtime } from '../runtime/runtime.js';

// Leituras do catálogo em cache para a Home (constitution §6: servir do cache, já).
// A UI só lê; a escrita é do CatalogSync.

export const DEFAULT_PROFILE = 'default'; // 1 perfil implícito até o M8c (D-7)

/** Linha de progresso já resolvida para exibição na trilha "Continuar assistindo". */
export interface ContinueItem extends PlaybackProgress {
  title: string;
  poster?: string;
}

interface CatalogState {
  counts: Record<CatalogSection, number>;
  /**
   * `counts` já veio do banco ao menos uma vez nesta sessão do processo?
   *
   * Sem isto, `counts` some a cada reabertura do app: a store do Zustand é um
   * singleton do processo JS, não sobrevive a um restart. Como `counts` nasce
   * `{0,0,0}` e só é preenchido depois do primeiro `loadHome()` resolver, as
   * telas que decidem "mostrar aviso de primeira sincronização" quando
   * `counts.X === 0` não tinham como distinguir "ainda não terminei de ler o
   * cache" de "o catálogo está mesmo vazio" — e mostravam "Baixando catálogo
   * pela primeira vez" toda vez que o usuário saía e voltava ao app, mesmo com
   * tudo já sincronizado em disco.
   */
  loaded: boolean;
  recentMovies: Movie[];
  recentSeries: Series[];
  continueWatching: ContinueItem[];
  loadHome: (rt: Runtime, listId: string) => Promise<void>;
}

export const useCatalog = create<CatalogState>((set) => ({
  counts: { live: 0, vod: 0, series: 0 },
  loaded: false,
  recentMovies: [],
  recentSeries: [],
  continueWatching: [],

  loadHome: async (rt, listId) => {
    rt.perf.marcar('home:load'); // RP-5 (spec 002)
    const repo = rt.catalog(listId);

    // `counts` busca separado do resto, de propósito (achado real, spec 005
    // LS-002, 2026-09-18): `repo.movies()`/`repo.series()` com `sort: 'recent'`
    // podem tentar gravar a marca de "índice completo" (`indiceCompleto()`,
    // escrita mesmo numa leitura) e falhar por `QuotaExceededError` numa lista
    // perto do limite — antes, isso derrubava o `Promise.all` inteiro e jogava
    // fora um `counts()` que já tinha funcionado, deixando `counts.live` preso
    // em 0 para sempre e a tela de TV ao vivo/Catálogo presa no spinner de
    // "baixando catálogo pela primeira vez" mesmo com o catálogo já no cache.
    try {
      set({ counts: await repo.counts() });
    } catch (err) {
      rt.logger.error('loadHome: counts() falhou', { listId, err: String(err) });
    }

    try {
      const [recentMovies, recentSeries, progressRows] = await Promise.all([
        repo.movies({ sort: 'recent', limit: 30 }),
        repo.series({ sort: 'recent', limit: 30 }),
        rt.db.progress
          .where('[profileId+listId]')
          .equals([DEFAULT_PROFILE, listId])
          .toArray(),
      ]);

      const candidates = progressRows
        .filter((p) => !p.completed && p.positionSecs > 15)
        .sort((a, b) => b.updatedAt - a.updatedAt)
        .slice(0, 20)
        .map(stripProgress);

      const continueWatching = await resolveContinue(repo, candidates);

      set({ loaded: true, recentMovies, recentSeries, continueWatching });
      rt.perf.marcar('home:loaded', {
        itens: recentMovies.length + recentSeries.length + continueWatching.length,
      });
    } catch (err) {
      // Achado real (spec 003 LG-022, 2026-09-14): numa TV com cota de
      // IndexedDB estourada (catálogo grande + armazenamento pequeno), uma
      // leitura do Dexie pode falhar mesmo sendo só leitura (o motor tenta
      // gravar metadado interno na abertura da conexão). Sem este catch a
      // Home ficava presa em "Carregando…" para sempre — aqui ela cai pra
      // "catálogo vazio" (equivalente a `counts` zerado) em vez de travar; o
      // usuário ainda consegue navegar pelo resto do app.
      rt.logger.error('loadHome falhou — Home segue com catálogo vazio', {
        listId,
        err: String(err),
      });
      set({ loaded: true });
    }
  },
}));

/**
 * Resolve nome e pôster de cada retomada.
 *
 * O catálogo é a fonte preferida (título e imagem seguem a lista se ela mudar),
 * mas nem tudo está lá: episódio de série não tem tabela própria (vive dentro de
 * `seriesInfo`) e um item pode ter saído da lista na última sincronização. Por
 * isso o progresso guarda uma cópia de `title`/`poster` — ver `PlaybackProgress`.
 * Sem nenhuma das duas fontes a linha é descartada: melhor não mostrar do que
 * mostrar um código de stream.
 */
async function resolveContinue(
  repo: CatalogGateway,
  rows: PlaybackProgress[],
): Promise<ContinueItem[]> {
  const out = await Promise.all(
    rows.map(async (p) => {
      // O progresso guarda nome e pôster do que estava tocando, então sumir do
      // catálogo não basta para esconder: sem esta pergunta, um item bloqueado
      // continuaria estampado aqui com título e imagem (RF-33).
      const secao = p.seriesId != null || p.kind === 'series' ? 'series' : 'vod';
      const alvo = p.seriesId ?? p.id;
      if (await repo.isBlocked(secao, alvo)) return null;

      // Episódio: procurar `p.id` em `movies` seria errado — ids de episódio e de
      // filme dividem o mesmo espaço de stream id no Xtream, então um id repetido
      // mostraria o pôster e o nome de OUTRO título. Com `seriesId` só a série é
      // consultada, e o nome do episódio vem da cópia gravada (a série sozinha
      // não sabe em que episódio o usuário parou).
      const ehEpisodio = p.seriesId != null;
      const fromCatalog = ehEpisodio
        ? await repo.seriesById(p.seriesId!)
        : p.kind === 'series'
          ? await repo.seriesById(p.id)
          : await repo.movie(p.id);

      const title = ehEpisodio
        ? (p.title ?? fromCatalog?.name)
        : (fromCatalog?.name ?? p.title);
      if (!title) return null;
      const poster = ehEpisodio
        ? (p.poster ?? fromCatalog?.poster)
        : (fromCatalog?.poster ?? p.poster);
      return { ...p, title, ...(poster ? { poster } : {}) };
    }),
  );
  return out.filter((x): x is ContinueItem => x !== null);
}

function stripProgress(
  row: PlaybackProgress & { listId?: string; profileId?: string },
): PlaybackProgress {
  const { listId: _l, profileId: _p, ...rest } = row;
  return rest;
}
