// Painéis Xtream retornam o mesmo campo ora como string, ora int, ora `false`.
// Parsers tolerantes (RF-8).

export function str(v: unknown): string | undefined {
  if (v === null || v === undefined || v === false || v === '') return undefined;
  return String(v);
}

export function num(v: unknown): number | undefined {
  if (v === null || v === undefined || v === false || v === '') return undefined;
  const n = typeof v === 'number' ? v : Number(String(v).trim());
  return Number.isFinite(n) ? n : undefined;
}

/**
 * Primeiro valor útil de um campo que o painel manda ora como array, ora como
 * string solta (`backdrop_path` é assim). `str()` num array faria um join com
 * vírgulas e produziria uma URL inválida.
 */
export function firstStr(v: unknown): string | undefined {
  if (Array.isArray(v)) {
    for (const item of v) {
      const s = str(item);
      if (s) return s;
    }
    return undefined;
  }
  return str(v);
}

export function bool(v: unknown): boolean {
  return v === true || v === 1 || v === '1' || v === 'true';
}

/** Unix seconds (string ou number) → epoch ms. */
export function epochSecsToMs(v: unknown): number | null {
  const n = num(v);
  return n === undefined ? null : n * 1000;
}
