import { useEffect } from 'react';
import { create } from 'zustand';
import { gapColClass, gapVar } from '../theme/gap.js';

export interface ToastItem {
  id: number;
  message: string;
  kind: 'info' | 'success' | 'error';
}

interface ToastState {
  toasts: ToastItem[];
  show: (message: string, kind?: ToastItem['kind'], durationMs?: number) => number;
  dismiss: (id: number) => void;
}

let seq = 0;

export const useToast = create<ToastState>((set) => ({
  toasts: [],
  show: (message, kind = 'info', durationMs = 3000) => {
    const id = ++seq;
    set((s) => ({ toasts: [...s.toasts, { id, message, kind }] }));
    if (durationMs > 0) {
      setTimeout(() => {
        set((s) => ({ toasts: s.toasts.filter((tst) => tst.id !== id) }));
      }, durationMs);
    }
    return id;
  },
  dismiss: (id) => set((s) => ({ toasts: s.toasts.filter((t) => t.id !== id) })),
}));

const COLOR: Record<ToastItem['kind'], string> = {
  info: 'var(--bg-raised)',
  success: 'var(--success)',
  error: 'var(--danger)',
};

/** Fila de toasts não-focáveis, canto inferior. Montar uma vez na raiz do app. */
export function ToastViewport() {
  const toasts = useToast((s) => s.toasts);
  return (
    <div
      className={gapColClass}
      style={{
        position: 'fixed',
        left: 0,
        right: 0,
        bottom: 'var(--safe-y)',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        pointerEvents: 'none',
        ...gapVar('0.6rem'),
      }}
    >
      {toasts.map((toast) => (
        <ToastRow key={toast.id} toast={toast} />
      ))}
    </div>
  );
}

function ToastRow({ toast }: { toast: ToastItem }) {
  const dismiss = useToast((s) => s.dismiss);
  useEffect(() => {
    const onKey = () => dismiss(toast.id);
    window.addEventListener('keydown', onKey, { once: true });
    return () => window.removeEventListener('keydown', onKey);
  }, [toast.id, dismiss]);

  return (
    <div
      role="status"
      style={{
        background: COLOR[toast.kind],
        color: 'var(--text-primary)',
        padding: '0.7rem 1.4rem',
        borderRadius: 'var(--radius-sm)',
        maxWidth: '60vw',
        textAlign: 'center',
        boxShadow: '0 0.4rem 1.2rem rgba(0,0,0,0.4)',
      }}
    >
      {toast.message}
    </div>
  );
}
