import { redactUrl } from '../util/redact.js';

export interface HttpOptions {
  timeoutMs?: number;
  retries?: number;
  userAgent?: string;
  signal?: AbortSignal;
}

/** Erro com status HTTP preservado — a taxonomia do PlaybackController depende disto (RF-60). */
export class HttpError extends Error {
  constructor(
    readonly status: number,
    readonly url: string,
  ) {
    super(`HTTP ${status} em ${redactUrl(url)}`);
    this.name = 'HttpError';
  }
}

/**
 * Respondeu, mas não em JSON — HTML de erro do nginx com status 200, corpo
 * vazio, página de captive portal. Distinto de `NetworkError` (não chegou) e de
 * `HttpError` (chegou com status ruim): aqui o servidor existe e fala outra
 * coisa, o que na autenticação significa "não é um painel Xtream".
 */
export class NotJsonError extends Error {
  constructor(
    readonly url: string,
    readonly amostra: string,
  ) {
    super(`Resposta não-JSON de ${redactUrl(url)}: ${amostra}`);
    this.name = 'NotJsonError';
  }
}

/** Falha de transporte: timeout, DNS, socket, offline. Sempre elegível a retry. */
export class NetworkError extends Error {
  constructor(
    readonly url: string,
    readonly cause?: unknown,
  ) {
    super(`Falha de rede em ${redactUrl(url)}`);
    this.name = 'NetworkError';
  }
}

/**
 * Retry só onde faz sentido (decisions D-12): erro de transporte, 429 e 5xx.
 * 4xx nunca reentra — credencial errada ou stream removido não melhoram com repetição,
 * e insistir num painel com max_connections estourado piora o problema.
 */
export function isRetriable(err: unknown): boolean {
  if (err instanceof NetworkError) return true;
  if (err instanceof HttpError) return err.status === 429 || err.status >= 500;
  return false;
}

export interface HttpResponse<T> {
  data: T;
  /** URL após seguir redirects — é ela que vai para o player (RF-11). */
  finalUrl: string;
}

/**
 * Wrapper de fetch: timeout, retry seletivo, User-Agent opcional.
 * Nota: em WebView/browser o header User-Agent costuma ser read-only — o override real
 * de UA para streams acontece na camada nativa (ver plan.md).
 */
/**
 * PERF-19 (spec 002): full jitter (fórmula AWS), mesmo desenho do backoff do
 * player (`playback/config.ts`, D-12) — em vez de todo cliente que falhou ao
 * mesmo tempo (ex.: catálogo inteiro reconectando após uma queda de rede)
 * reintentar no mesmo instante, cada um sorteia um atraso entre 0 e o teto
 * exponencial da tentativa. `rand` injetável para teste determinístico.
 */
export function atrasoComJitterMs(
  attempt: number,
  rand: () => number = Math.random,
  baseMs = 300,
  capMs = 5_000,
): number {
  const teto = Math.min(capMs, baseMs * 2 ** attempt);
  return rand() * teto;
}

export class HttpClient {
  constructor(private readonly defaults: HttpOptions = {}) {}

  async json<T>(url: string, opts: HttpOptions = {}): Promise<T> {
    return (await this.jsonWithUrl<T>(url, opts)).data;
  }

  async jsonWithUrl<T>(url: string, opts: HttpOptions = {}): Promise<HttpResponse<T>> {
    const res = await this.request(url, opts);
    // A amostra precisa ser consumida e cancelada DURANTE o parse. Um clone
    // deixado sem leitor acumula o corpo inteiro na outra ponta do tee, mesmo
    // no caminho feliz — dezenas de MB extras para catálogos Xtream grandes.
    const amostra = responseSample(res.clone());
    // Achado real (Emulator webOS 4, 2026-09-17/18 — confirmado via sourcemap
    // que a rejeição vinha DAQUI, não do parser de EPG como o achado §16.1
    // supôs por coincidência de horário no console): no caminho feliz
    // (`res.json()` funciona), `amostra` nunca é aguardada — só entra em
    // `await amostra` dentro do `catch` abaixo. Se `responseSample` rejeitar
    // (ex.: `reader.cancel()` lançando "already released" no `finally` dela,
    // neste motor), a promise fica sem handler nenhum e vira
    // `Uncaught (in promise)` no console. Anexar este `.catch()` já marca a
    // promise como tratada para o motor, mesmo sem mudar o que `await amostra`
    // abaixo recebe (a mesma promise original, ainda rejeitável ali).
    amostra.catch(() => {});
    try {
      return { data: (await res.json()) as T, finalUrl: res.url || url };
    } catch {
      // painel devolvendo HTML de erro no lugar de JSON é comum
      throw new NotJsonError(url, await amostra.catch(() => ''));
    }
  }

  async stream(url: string, opts: HttpOptions = {}): Promise<ReadableStream<Uint8Array>> {
    const res = await this.request(url, opts);
    if (!res.body) throw new Error(`Sem corpo em ${redactUrl(url)}`);
    return res.body;
  }

  /** Resolve a URL final após redirects sem baixar o corpo (usado antes de tocar). */
  async resolveFinalUrl(url: string, opts: HttpOptions = {}): Promise<string> {
    const res = await this.request(url, { ...opts, method: 'HEAD' } as HttpOptions);
    return res.url || url;
  }

  private async attemptRequest(
    url: string,
    ctrl: AbortController,
    opts: { method?: string; headers: Record<string, string> },
  ): Promise<Response> {
    const res = await fetch(url, {
      method: opts.method ?? 'GET',
      headers: opts.headers,
      redirect: 'follow',
      signal: ctrl.signal,
    });
    if (!res.ok) throw new HttpError(res.status, url);
    return res;
  }

  private async request(
    url: string,
    opts: HttpOptions & { method?: string },
  ): Promise<Response> {
    const timeoutMs = opts.timeoutMs ?? this.defaults.timeoutMs ?? 15_000;
    const retries = opts.retries ?? this.defaults.retries ?? 2;
    const ua = opts.userAgent ?? this.defaults.userAgent;
    const externalSignal = opts.signal ?? this.defaults.signal;
    const headers: Record<string, string> = {};
    if (ua) headers['User-Agent'] = ua;

    if (externalSignal?.aborted) {
      throw new Error('Cancelado externamente');
    }

    let lastErr: unknown;
    for (let attempt = 0; attempt <= retries; attempt++) {
      const ctrl = new AbortController();
      const t = setTimeout(() => ctrl.abort(), timeoutMs);
      const onAbort = () => ctrl.abort();
      externalSignal?.addEventListener('abort', onAbort);

      try {
        return await this.attemptRequest(url, ctrl, { method: opts.method, headers });
      } catch (err) {
        if (externalSignal?.aborted) throw new Error('Cancelado externamente');
        lastErr = err instanceof HttpError ? err : new NetworkError(url, err);
        if (!isRetriable(lastErr) || attempt === retries) break;
        await delay(atrasoComJitterMs(attempt));
      } finally {
        clearTimeout(t);
        externalSignal?.removeEventListener('abort', onAbort);
      }
    }
    throw lastErr instanceof Error ? lastErr : new Error(String(lastErr));
  }
}

/** Retém só o prefixo do diagnóstico, sem decodificar/guardar o corpo inteiro. */
async function responseSample(response: Response): Promise<string> {
  const reader = response.body?.getReader();
  if (!reader) return '';
  const decoder = new TextDecoder();
  let sample = '';
  try {
    while (sample.length < 120) {
      const { done, value } = await reader.read();
      if (done) {
        sample += decoder.decode();
        break;
      }
      // UTF-8 usa até quatro bytes por caractere. Limita também a string
      // temporária caso o transporte entregue o corpo em um único chunk.
      sample += decoder.decode(value.subarray(0, (120 - sample.length) * 4), {
        stream: true,
      });
    }
    return sample.slice(0, 120);
  } catch {
    return sample.slice(0, 120);
  } finally {
    // Cancelar um ramo do tee espera o outro terminar: não aguardar aqui.
    // `cancel()` pode lançar SINCRONAMENTE em vez de rejeitar (achado real,
    // Emulator webOS 4 — o lado do tee já tinha liberado o reader sozinho
    // quando o outro ramo, `res.json()`, terminou de ler primeiro). Chamar
    // dentro de `Promise.resolve().then(...)` garante que tanto um lançamento
    // síncrono quanto uma rejeição caiam no mesmo `.catch()` — direto,
    // `void reader.cancel().catch(...)`, o lançamento síncrono escaparia do
    // `.catch()` (que só encadeia depois que `cancel()` já teria lançado) e
    // rejeitaria esta função inteira de dentro do `finally`, mesmo com o
    // `try` já tendo terminado bem.
    void Promise.resolve()
      .then(() => reader.cancel())
      .catch(() => {});
  }
}

const delay = (ms: number) => new Promise((r) => setTimeout(r, ms));
