import type { CatalogSection } from './db.js';

export interface CacheConfig {
  /** Idade máxima antes de disparar refresh de fundo. */
  ttlMs: Record<CatalogSection | 'epg' | 'info', number>;
  /** Intervalo do auto-refresh de catálogo (RF-65). */
  autoRefreshMs: number;
  sync: {
    /** Requisições de categoria simultâneas (D-14: não estourar `max_connections`). */
    concurrency: number;
    /**
     * Se a 1ª resposta de categoria trouxer mais itens que isto E de várias categorias,
     * o painel está ignorando `category_id` — abortamos o loop e usamos o que veio.
     */
    ignoredFilterItemThreshold: number;
    /**
     * Decisão explícita (spec 003 LG-022, 2026-09-14): teto de itens gravados
     * por categoria quando `isLowStorageDevice()` (cache/quota.ts) é `true` —
     * TVs sem `navigator.storage.estimate` (webOS 4.x/5.x reais, achado numa
     * TV LG física e no Emulator oficial webOS TV 4.0) estouram a cota do
     * IndexedDB tentando cachear o catálogo inteiro (categoria isolada com
     * ~11 mil itens, no painel de teste). Só corta a GRAVAÇÃO — a categoria em
     * si continua aparecendo, só com um recorte dos itens mais recentes.
     * Motores com a API de armazenamento (Android, webOS 6+, Tizen novo)
     * nunca usam este teto, mesmo com pouco espaço livre de verdade.
     *
     * ⚠️ O número `300` é um chute pragmático, NÃO um valor validado — a LG
     * não documenta uma cota oficial de IndexedDB (só de `localStorage`,
     * 16 MB desde webOS 3.5, e do DB8, 10 MB compartilhado — nenhum dos dois
     * é o que este app usa), e um único teste numa VM não é amostra
     * suficiente pra calibrar um número com confiança. Este teto NÃO garante
     * evitar o estouro de cota (uma TV com muitas categorias pode estourar
     * mesmo com cada uma abaixo dele) — quem garante isso é a parada limpa em
     * `QuotaExceededError` (`persistComLimite`, `sync/catalogSync.ts`), que
     * não depende de nenhum número. Este teto é só uma redução de escopo
     * best-effort para não deixar uma única categoria gigante dominar a
     * tentativa de sync antes de estourar.
     */
    maxItemsPerCategoryLowStorage: number;
  };
  lru: {
    /** Máximo de linhas em `movieInfo`/`seriesInfo` antes de podar as mais antigas. */
    infoMaxRows: number;
    /** Fração de uso da quota a partir da qual a poda LRU roda de forma agressiva. */
    quotaPressure: number;
  };
}

const H = 3_600_000;

export const DEFAULT_CACHE_CONFIG: CacheConfig = {
  ttlMs: { live: 6 * H, vod: 24 * H, series: 24 * H, epg: 6 * H, info: 7 * 24 * H },
  autoRefreshMs: 12 * H,
  sync: { concurrency: 2, ignoredFilterItemThreshold: 4000, maxItemsPerCategoryLowStorage: 300 },
  lru: { infoMaxRows: 800, quotaPressure: 0.9 },
};
