// Implementação do PlatformAdapter para navegador desktop — usada só pelo apps/dev
// durante o desenvolvimento (constitution §4: hls.js/mpegts.js nunca em TV).
// A impl de VideoPlayer (hls.js/mpegts.js) é injetada pelo apps/dev via
// `createWebAdapter({ createVideoPlayer })` — assim esses pacotes ficam fora de
// `packages/platform` e nunca entram num build de TV.

import type {
  LogicalKey,
  PlatformAdapter,
  SecureStorage,
  VideoPlayer,
} from '../index.js';

export interface WebAdapterOptions {
  /** Fábrica de VideoPlayer fornecida pelo apps/dev (hls.js / mpegts.js). */
  createVideoPlayer?: (mount: HTMLElement) => VideoPlayer;
}

const KEY_MAP: Readonly<Record<number, LogicalKey>> = {
  38: 'Up',
  40: 'Down',
  37: 'Left',
  39: 'Right',
  13: 'Enter',
  8: 'Back',
  27: 'Back',
  179: 'PlayPause',
  178: 'Stop',
  228: 'Rewind',
  227: 'FastForward',
  33: 'ChannelUp',
  34: 'ChannelDown',
};

const localSecureStorage: SecureStorage = {
  async get(key) {
    try {
      return localStorage.getItem(`aura67:${key}`);
    } catch {
      return null;
    }
  },
  async set(key, value) {
    localStorage.setItem(`aura67:${key}`, value);
  },
  async delete(key) {
    localStorage.removeItem(`aura67:${key}`);
  },
};

export function createWebAdapter(opts: WebAdapterOptions = {}): PlatformAdapter {
  return {
    name: 'web',
    secureStorage: localSecureStorage,
    keyMap: KEY_MAP,
    followsRedirects: true,
    createVideoPlayer(mount: HTMLElement): VideoPlayer {
      if (!opts.createVideoPlayer) {
        throw new Error(
          'createWebAdapter foi criado sem createVideoPlayer — passe a fábrica hls.js do apps/dev.',
        );
      }
      return opts.createVideoPlayer(mount);
    },
    onVisibilityChange(cb) {
      const handler = () => cb(document.visibilityState === 'visible');
      document.addEventListener('visibilitychange', handler);
      return () => document.removeEventListener('visibilitychange', handler);
    },
    exitApp() {
      // Sem equivalente no navegador; a casca real (Android/webOS/Tizen) fecha o app.
    },
  };
}
