import { ptBR, type Dict } from './pt-BR.js';

// pt-BR é o único idioma da v1 (constitution §10). A indireção existe só para
// centralizar o acesso e permitir interpolação simples `{chave}`.

const dict: Dict = ptBR;

type Leaves<T, P extends string = ''> = {
  [K in keyof T & string]: T[K] extends string ? `${P}${K}` : Leaves<T[K], `${P}${K}.`>;
}[keyof T & string];

export type TextKey = Leaves<Dict>;

export function t(key: TextKey, vars?: Record<string, string | number>): string {
  const raw = key.split('.').reduce<unknown>((acc, part) => {
    if (acc && typeof acc === 'object' && part in acc) {
      return (acc as Record<string, unknown>)[part];
    }
    return undefined;
  }, dict);

  let out = typeof raw === 'string' ? raw : key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      out = out.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
  }
  return out;
}

export { ptBR };
export type { Dict };
