import type { ReactNode } from 'react';
import { useState } from 'react';
import { FocusContext, useFocusable } from '@noriginmedia/norigin-spatial-navigation';
import { pressWithFocus } from '../nav/pressWithFocus.js';
import { focusRing } from '../nav/focusRing.js';
import { t } from '../i18n/index.js';
import { BackspaceIcon, SearchIcon } from './icons.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';
import { cssLen } from '../theme/cssMath.js';

export interface OnScreenKeyboardProps {
  onInput: (char: string) => void;
  onDelete: () => void;
  onClear: () => void;
  /**
   * Confirmação explícita. Quando existe, ganha uma tecla própria no fim da
   * última fila — onde o foco já está depois de digitar, a uma tecla de
   * distância. É o que dispara a busca: consultar a cada letra fazia o
   * aparelho enfileirar uma consulta por tecla.
   */
  onSubmit?: () => void;
  submitLabel?: ReactNode;
  focusKey: string;
}

// `.` / `-` / `_` / `@` também na camada de letras: aparecem em URL de servidor,
// usuário e e-mail o tempo todo — poupa a troca pra ?123.
const LETTERS = ['abcdefg', 'hijklmn', 'opqrstu', 'vwxyz', '.-_@/'];
const SYMBOLS = ['1234567', '890.-_@', ':/?#&=+', '\'"!,()'];

/** Teclado on-screen navegável por D-pad (telas 08 e onboarding). */
export function OnScreenKeyboard({
  onInput,
  onDelete,
  onClear,
  onSubmit,
  submitLabel,
  focusKey,
}: OnScreenKeyboardProps) {
  const [symbols, setSymbols] = useState(false);
  const [shift, setShift] = useState(false);
  const { ref, focusKey: fk } = useFocusable({
    focusKey,
    trackChildren: true,
    saveLastFocusedChild: true,
  });
  const rows = symbols ? SYMBOLS : LETTERS.map((r) => (shift ? r.toUpperCase() : r));

  const type = (ch: string) => {
    onInput(ch);
    if (shift) setShift(false); // caps só para a próxima letra
  };

  return (
    <FocusContext.Provider value={fk}>
      <div
        ref={ref}
        className={gapColClass}
        style={{
          display: 'inline-flex',
          flexDirection: 'column',
          ...gapVar(cssLen('min(8px, 1.6vh)')),
        }}
      >
        {rows.map((row, r) => (
          <div
            key={r}
            className={gapRowClass}
            style={{
              display: 'flex',
              justifyContent: 'center',
              ...gapVar(cssLen('min(8px, 1.6vh)')),
            }}
          >
            {row.split('').map((ch) => (
              <Key
                key={ch}
                label={ch}
                focusKey={`${focusKey}-${ch.toLowerCase()}`}
                onPress={() => type(ch)}
              />
            ))}
          </div>
        ))}
        <div
          className={gapRowClass}
          style={{ display: 'flex', justifyContent: 'center', ...gapVar(cssLen('min(8px, 1.6vh)')) }}
        >
          {!symbols && (
            <Key
              label="⇧"
              focusKey={`${focusKey}-shift`}
              onPress={() => setShift((v) => !v)}
              active={shift}
            />
          )}
          <Key
            label={symbols ? t('keyboard.letters') : t('keyboard.symbols')}
            focusKey={`${focusKey}-mode`}
            wide
            onPress={() => setSymbols((v) => !v)}
          />
          <Key
            label={t('keyboard.space')}
            focusKey={`${focusKey}-space`}
            wide
            onPress={() => onInput(' ')}
          />
          <Key label={<BackspaceIcon />} focusKey={`${focusKey}-del`} onPress={onDelete} />
          <Key
            label={t('keyboard.clear')}
            focusKey={`${focusKey}-clear`}
            wide
            onPress={onClear}
          />
          {onSubmit && (
            <Key
              label={
                submitLabel ?? (
                  <>
                    <SearchIcon /> {t('keyboard.search')}
                  </>
                )
              }
              focusKey={`${focusKey}-submit`}
              wide
              primary
              onPress={onSubmit}
            />
          )}
        </div>
      </div>
    </FocusContext.Provider>
  );
}

function Key({
  label,
  onPress,
  focusKey,
  wide = false,
  active = false,
  primary = false,
}: Readonly<{
  label: ReactNode;
  onPress: () => void;
  focusKey: string;
  wide?: boolean;
  active?: boolean;
  primary?: boolean;
}>) {
  const { ref, focused } = useFocusable({ focusKey, onEnterPress: onPress });
  const destacada = active || primary;
  return (
    <button
      ref={ref}
      type="button"
      onClick={pressWithFocus(focusKey, onPress)}
      style={{
        appearance: 'none',
        border: 'none',
        cursor: 'pointer',
        // Tamanho preso ao `rem` estourava a tela em viewport baixo: no
        // telefone deitado (387px de altura) as duas últimas linhas ficavam
        // fora. O `min()` com `vh` encolhe só onde falta espaço — na TV, onde
        // 1vh é grande, prevalece o valor em `rem`.
        minWidth: cssLen(wide ? 'min(5.5rem, 16vh)' : 'min(3rem, 8.5vh)'),
        height: cssLen('min(3rem, 8.5vh)'),
        borderRadius: 'var(--radius-sm)',
        font: 'inherit',
        fontWeight: 600,
        color: destacada ? 'var(--text-on-accent)' : 'var(--text-primary)',
        background: destacada ? 'var(--accent)' : 'var(--bg-raised)',
        ...focusRing(focused, primary),
      }}
    >
      {label}
    </button>
  );
}
