/**
 * URLs de stream Xtream carregam usuário e senha no path:
 *   http://host:8080/live/USUARIO/SENHA/123.m3u8
 * Nada pode sair para log, tela de erro ou "reportar problema" sem passar por aqui
 * (constitution §9 / RF-65).
 */

const CRED_PATH = /^(\/(?:live|movie|series|timeshift)\/)([^/]+)\/([^/]+)\//i;

/** Mascara credenciais em URLs de stream e em query strings de player_api.php. */
export function redactUrl(url: string): string {
  let u: URL;
  try {
    u = new URL(url);
  } catch {
    return redactLoose(url);
  }

  // credenciais no path do stream
  u.pathname = u.pathname.replace(CRED_PATH, '$1***/***/');

  // credenciais na query (player_api.php, xmltv.php)
  for (const key of ['username', 'password', 'user', 'pass', 'token']) {
    if (u.searchParams.has(key)) u.searchParams.set(key, '***');
  }

  // userinfo (http://user:pass@host)
  if (u.username || u.password) {
    u.username = u.username ? '***' : '';
    u.password = u.password ? '***' : '';
  }

  return u.toString();
}

/** Fallback para strings que não são URL válida (mensagens de erro de engine nativo). */
function redactLoose(text: string): string {
  return text
    .replace(/\/(live|movie|series|timeshift)\/[^/\s]+\/[^/\s]+\//gi, '/$1/***/***/')
    .replace(/([?&](?:username|password|user|pass|token)=)[^&\s]*/gi, '$1***');
}

/** Redige qualquer texto livre que possa conter uma URL de stream. */
export function redact(text: string): string {
  return redactLoose(text);
}
