import { CatalogRepo, type BrowseOptions, type CatalogPolicy, type Janela } from './catalogRepo.js';
import type { Category, Channel, Movie, Series } from '../models/index.js';
import type { AuraDb, CatalogSection } from './db.js';

/**
 * Ponto único de leitura do catálogo (spec 005 LS-015). Hoje delega 1:1 para
 * `CatalogRepo` — nenhum comportamento muda. O objetivo é isolar quem lê
 * catálogo (`runtime.ts`/UI) do `CatalogRepo` concreto, para que M2
 * (`CategoryLoader`/paginação real, sem materializar categoria inteira) possa
 * trocar a implementação por trás desta fachada sem tocar em nenhuma tela.
 *
 * Escrita (`put*`/`prune*`) fica de fora de propósito: só o `CatalogSync` usa
 * esses métodos, e M2 vai substituir esse lado por `CategoryLoader` — não há
 * ganho em espelhar aqui algo que muda de forma na próxima fase.
 */
export class CatalogGateway {
  private readonly repo: CatalogRepo;

  constructor(db: AuraDb, listId: string, policy: CatalogPolicy = {}) {
    this.repo = new CatalogRepo(db, listId, policy);
  }

  categories(section: CatalogSection): Promise<Category[]> {
    return this.repo.categories(section);
  }

  channels(categoryId?: string): Promise<Channel[]> {
    return this.repo.channels(categoryId);
  }

  channel(id: string): Promise<Channel | undefined> {
    return this.repo.channel(id);
  }

  movies(opts: BrowseOptions = {}): Promise<Movie[]> {
    return this.repo.movies(opts);
  }

  series(opts: BrowseOptions = {}): Promise<Series[]> {
    return this.repo.series(opts);
  }

  moviesPage(opts: BrowseOptions = {}): Promise<Janela<Movie>> {
    return this.repo.moviesPage(opts);
  }

  seriesPage(opts: BrowseOptions = {}): Promise<Janela<Series>> {
    return this.repo.seriesPage(opts);
  }

  countMovies(opts: Pick<BrowseOptions, 'categoryId'> = {}): Promise<number> {
    return this.repo.countMovies(opts);
  }

  countSeries(opts: Pick<BrowseOptions, 'categoryId'> = {}): Promise<number> {
    return this.repo.countSeries(opts);
  }

  movie(id: string): Promise<Movie | undefined> {
    return this.repo.movie(id);
  }

  seriesById(id: string): Promise<Series | undefined> {
    return this.repo.seriesById(id);
  }

  counts(): Promise<Record<CatalogSection, number>> {
    return this.repo.counts();
  }

  garantirNorm(tamanhoDoBloco?: number): Promise<number> {
    return this.repo.garantirNorm(tamanhoDoBloco);
  }

  isBlocked(section: CatalogSection, id: string): Promise<boolean> {
    return this.repo.isBlocked(section, id);
  }
}
