// Regra de "continuar assistindo" (playback-design.md §9 / RF): retoma se a posição
// está entre ~15s e 95% da duração; senão começa do zero. ≥95% = assistido.

const MIN_SECS = 15;
const MAX_PCT = 0.95;

/** Segundos de onde retomar (0 = do início). */
export function resumePoint(
  positionSecs: number,
  durationSecs: number,
  completed: boolean,
): number {
  if (completed) return 0;
  if (positionSecs < MIN_SECS) return 0;
  if (durationSecs > 0 && positionSecs / durationSecs >= MAX_PCT) return 0;
  return Math.floor(positionSecs);
}

export function isWatched(
  positionSecs: number,
  durationSecs: number,
  completed: boolean,
): boolean {
  if (completed) return true;
  return durationSecs > 0 && positionSecs / durationSecs >= MAX_PCT;
}
