import { useState } from 'react';
import { FocusContext, useFocusable } from '@noriginmedia/norigin-spatial-navigation';
import { FocusButton } from './FocusButton.js';

export interface SortOption {
  id: string;
  label: string;
}

export interface SortDropdownProps {
  options: SortOption[];
  selectedId: string;
  onChange: (id: string) => void;
  focusKey: string;
  /**
   * Sobrescreve a navegação D-pad do gatilho numa direção (ex.: 'down' para
   * pular direto a um container abaixo que, de outro modo, perderia a
   * disputa geométrica do norigin para um container mais largo — ver a nota
   * em `Catalog.tsx`/`SearchField`). Só se aplica ao gatilho, não à lista
   * aberta.
   */
  onArrowPress?: (direction: string) => boolean;
}

/**
 * Dropdown de ordenação (telas 04/06). Em TV abre uma lista sobreposta navegável
 * por D-pad; OK escolhe e fecha.
 */
export function SortDropdown({
  options,
  selectedId,
  onChange,
  focusKey,
  onArrowPress,
}: SortDropdownProps) {
  const [open, setOpen] = useState(false);
  const selected = options.find((o) => o.id === selectedId) ?? options[0];
  const { ref, focusKey: fk } = useFocusable({
    focusKey,
    trackChildren: true,
    saveLastFocusedChild: true,
    // Prende o foco no próprio dropdown enquanto a lista está aberta: sem
    // irmão válido numa direção, o norigin normalmente ESCALA para o
    // container-pai (é a mesma disputa geométrica da nota em `Catalog.tsx`)
    // e o D-pad escapava para os gêneros/busca com a lista ainda aberta por
    // cima, sem selecionar nada. `isFocusBoundary` é reativo — atualiza
    // sozinho quando `open` muda, sem precisar remontar o componente.
    isFocusBoundary: open,
    focusBoundaryDirections: ['up', 'down', 'left', 'right'],
  });

  return (
    <FocusContext.Provider value={fk}>
      <div ref={ref} style={{ position: 'relative', display: 'inline-block' }}>
        <FocusButton
          focusKey={`${focusKey}-trigger`}
          onPress={() => setOpen((v) => !v)}
          // Só desvia o Down quando a lista está FECHADA — aberta, o Down
          // precisa descer para as opções (irmã direta na mesma escala,
          // sem precisar de desvio nenhum). Sem este `!open`, a lista nunca
          // recebia foco: parecia travada aberta, sem dar para escolher
          // nada nem voltar aos gêneros.
          onArrowPress={(direction) => {
            if (!open && onArrowPress) return onArrowPress(direction);
            return true;
          }}
        >
          {selected?.label ?? ''} ▾
        </FocusButton>
        {open && (
          <ul
            style={{
              position: 'absolute',
              top: 'calc(100% + 0.4rem)',
              left: 0,
              margin: 0,
              padding: '0.4rem',
              listStyle: 'none',
              background: 'var(--bg-panel)',
              border: '1px solid var(--border-strong)',
              borderRadius: 'var(--radius-sm)',
              zIndex: 10,
              minWidth: '14rem',
            }}
          >
            {options.map((o) => (
              <li key={o.id} style={{ marginBottom: '0.3rem' }}>
                <FocusButton
                  focusKey={`${focusKey}-opt-${o.id}`}
                  primary={o.id === selectedId}
                  onPress={() => {
                    onChange(o.id);
                    setOpen(false);
                  }}
                >
                  {o.label}
                </FocusButton>
              </li>
            ))}
          </ul>
        )}
      </div>
    </FocusContext.Provider>
  );
}
