import { create } from 'zustand';
import type { IptvProvider } from '@mfp/core';
import type { Runtime } from '../runtime/runtime.js';
import { createSingleFlight } from '../runtime/singleFlight.js';

// Espelha o EpgSync do core (D-22). É "enfeite": nunca bloqueia o boot nem a
// navegação — o Boot dispara sem esperar, e a lista de canais lê o que já houver.

export type EpgPhase = 'idle' | 'running' | 'done' | 'error';

interface EpgState {
  phase: EpgPhase;
  programmes: number;
  run: (
    rt: Runtime,
    listId: string,
    provider: IptvProvider,
    serverTimezone?: string,
    opts?: { force?: boolean },
  ) => Promise<void>;
}

const runOnce = createSingleFlight<void>();

export const useEpg = create<EpgState>((set) => ({
  phase: 'idle',
  programmes: 0,

  run: (rt, listId, provider, serverTimezone, opts) =>
    runOnce(rt, listId, async () => {
      const sync = rt.makeEpgSync(listId, provider, serverTimezone);
      set({ phase: 'running' });
      const off = sync.events.on('epg:progress', (e) =>
        set({ programmes: e.programmes }),
      );
      try {
        const res = await sync.run(opts);
        set({ phase: res.ran ? 'done' : 'idle', programmes: res.programmeCount });
      } catch {
        set({ phase: 'error' });
      } finally {
        off();
      }
    }),
}));
