import { useCallback, useEffect, useRef, useState } from 'react';
import { jaResolvida, solicitar, type Solicitacao } from './imageQueue.js';

export interface EstadoImagem {
  /** A fila liberou a vaga — hora de o `<img>` ganhar o `src`. */
  liberada: boolean;
  /** O `<img>` já disparou `onLoad` (ou a URL já tinha carregado antes — LRU). */
  carregada: boolean;
  /** O `<img>` disparou `onError`. */
  falhou: boolean;
  /** Ligue ao `onLoad` do `<img>`. */
  aoCarregar: () => void;
  /** Ligue ao `onError` do `<img>`. */
  aoFalhar: () => void;
}

/**
 * Um slot de imagem na fila global (`imageQueue`), por card (PERF-16 / spec 002).
 * Pede ao montar (ou quando a URL muda), cancela ao desmontar/trocar — é o que
 * dá o cancelamento real que `background-image` nunca teve: sair da janela
 * virtualizada solta a vaga e, se já estava carregando, o `Poster` tira o
 * `src` do `<img>`, e o Chromium aborta a requisição em curso.
 *
 * **Simplificação assumida**: a prioridade só vale no momento do pedido — um
 * item que ainda espera vaga não é reprioritizado se o foco se aproximar dele
 * enquanto espera (só a concorrência/cancelamento importam de verdade aqui;
 * reprioritizar exigiria mutar um pedido já enfileirado, o que a fila não
 * expõe de propósito, para manter `imageQueue.ts` simples de auditar).
 */
export function useImageSlot(url: string | undefined, prioridade: number): EstadoImagem {
  const [liberada, setLiberada] = useState(() => !!url && jaResolvida(url));
  const [carregada, setCarregada] = useState(() => !!url && jaResolvida(url));
  const [falhou, setFalhou] = useState(false);
  const solicitacaoRef = useRef<Solicitacao | null>(null);

  // Reajusta o estado quando a URL muda — durante o render, não num efeito (o
  // padrão que o React recomenda para "resetar estado quando uma prop muda";
  // o `VirtualGrid` já usa a mesma ideia para `restoreKey`). Chamar `setState`
  // direto dentro de um `useEffect` para isto dispararia o aviso do
  // `react-hooks` v7 (`set-state-in-effect`) — e o motivo do aviso é real: só
  // o pedido à fila (efeito colateral de verdade, abaixo) precisa de efeito.
  const [urlAnterior, setUrlAnterior] = useState(url);
  if (url !== urlAnterior) {
    setUrlAnterior(url);
    const pronta = !!url && jaResolvida(url);
    setLiberada(pronta);
    setCarregada(pronta);
    setFalhou(false);
  }

  useEffect(() => {
    if (!url || jaResolvida(url)) return; // resolvido acima — nada a pedir
    // `prioridade` é o valor do render em que a URL mudou — não precisa ser
    // reativo depois (ver a nota de "simplificação assumida" acima)
    const solicitacao = solicitar({
      url,
      prioridade,
      aoLiberar: () => setLiberada(true),
    });
    solicitacaoRef.current = solicitacao;
    return () => {
      solicitacao.cancelar();
      solicitacaoRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [url]);

  const aoCarregar = useCallback(() => {
    solicitacaoRef.current?.concluir(true);
    setCarregada(true);
  }, []);
  const aoFalhar = useCallback(() => {
    solicitacaoRef.current?.concluir(false);
    setFalhou(true);
  }, []);

  return { liberada, carregada, falhou, aoCarregar, aoFalhar };
}
