import { useEffect, useState } from 'react';
import {
  FocusContext,
  useFocusable,
  setFocus,
} from '@noriginmedia/norigin-spatial-navigation';
import { focusRing } from '../nav/focusRing.js';
import { pressWithFocus } from '../nav/pressWithFocus.js';
import { FocusButton } from '../components/FocusButton.js';
import { OnScreenKeyboard } from '../components/OnScreenKeyboard.js';
import type { Account } from '@mfp/core';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useLists } from '../state/lists.js';
import { useBackHandler } from '../nav/backStack.js';
import { classifyError } from '../errors.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';

type FieldId = 'serverUrl' | 'username' | 'password';

function rotuloBotao(validando: boolean, editando: boolean): string {
  if (validando) return t('onboarding.validating');
  return editando ? t('onboarding.editSubmit') : t('onboarding.submit');
}

export interface OnboardingProps {
  /** Chamado ao concluir (adicionar) ou fechar (editar). */
  onDone: () => void;
  /**
   * Lista existente sendo **editada** (RF-49). Sem isto, é o cadastro de uma
   * lista nova. A senha nunca é pré-carregada — vive só no secure storage.
   */
  listId?: string;
  initial?: { serverUrl?: string; username?: string };
  /** Sai da edição sem gravar (BACK). Só faz sentido no modo editar. */
  onCancel?: () => void;
}

export function Onboarding({
  onDone,
  listId,
  initial,
  onCancel,
}: Readonly<OnboardingProps>) {
  const rt = useRuntime();
  const addList = useLists((s) => s.addList);
  const editList = useLists((s) => s.editList);
  const editando = listId !== undefined;

  // BACK volta para a lista de listas (Gerenciar), não desempilha até
  // Configurações. Só quando há um `onCancel` — no primeiro uso (Onboarding é a
  // tela raiz) não há para onde voltar.
  useBackHandler(() => onCancel?.(), !!onCancel);

  const [values, setValues] = useState<Record<FieldId, string>>({
    serverUrl: initial?.serverUrl ?? 'http://',
    username: initial?.username ?? '',
    password: '',
  });
  const [active, setActive] = useState<FieldId>('serverUrl');
  const [status, setStatus] = useState<'idle' | 'validating' | 'error' | 'ok'>('idle');
  const [errorMsg, setErrorMsg] = useState('');
  /** Conta validada — vira o card de confirmação antes de entrar (RF-53). */
  const [conta, setConta] = useState<Account | null>(null);

  const { ref, focusKey } = useFocusable({ focusKey: 'onboarding', trackChildren: true });

  useEffect(() => {
    setFocus('onboarding-field-serverUrl');
  }, []);

  const edit = (fn: (cur: string) => string) =>
    setValues((v) => ({ ...v, [active]: fn(v[active]) }));

  const submit = async () => {
    setStatus('validating');
    try {
      const entrada = {
        serverUrl: values.serverUrl,
        username: values.username.trim(),
        password: values.password,
      };
      const account = editando
        ? await editList(rt, listId, entrada)
        : await addList(rt, entrada);
      // Não entra direto: o usuário acabou de digitar servidor, usuário e senha
      // e merece ver que a conta é a esperada — status, validade e quantas
      // conexões simultâneas (RF-53). É também onde uma conta prestes a vencer
      // aparece antes de virar problema.
      setConta(account);
      setStatus('ok');
      setTimeout(() => setFocus('onboarding-entrar'), 0);
    } catch (err) {
      const e = classifyError(err);
      setErrorMsg(`${e.body} (${e.code})`);
      setStatus('error');
    }
  };

  // Conta validada: o formulário sai da frente e fica só a confirmação (RF-53).
  if (status === 'ok' && conta) {
    return <ContaValidada conta={conta} onEntrar={onDone} />;
  }

  return (
    <FocusContext.Provider value={focusKey}>
      <div
        ref={ref}
        className={gapColClass}
        style={{
          maxWidth: '48rem',
          margin: '0 auto',
          display: 'flex',
          flexDirection: 'column',
          ...gapVar('1rem'),
        }}
      >
        <h1>{editando ? t('onboarding.editTitle') : t('onboarding.title')}</h1>
        <p style={{ color: 'var(--text-secondary)' }}>
          {editando ? t('onboarding.editSubtitle') : t('onboarding.subtitle')}
        </p>

        <Field
          id="serverUrl"
          label={t('onboarding.server')}
          value={values.serverUrl}
          active={active === 'serverUrl'}
          onSelect={() => setActive('serverUrl')}
        />
        <Field
          id="username"
          label={t('onboarding.username')}
          value={values.username}
          active={active === 'username'}
          onSelect={() => setActive('username')}
        />
        <Field
          id="password"
          label={t('onboarding.password')}
          value={values.password}
          secret
          active={active === 'password'}
          onSelect={() => setActive('password')}
        />

        <OnScreenKeyboard
          focusKey="onboarding-kb"
          onInput={(ch) => edit((cur) => cur + ch)}
          onDelete={() => edit((cur) => cur.slice(0, -1))}
          onClear={() => edit(() => '')}
        />

        <div className={gapRowClass} style={{ display: 'flex', ...gapVar('1rem') }}>
          <FocusButton
            primary
            focusKey="onboarding-submit"
            disabled={status === 'validating'}
            onPress={() => void submit()}
          >
            {rotuloBotao(status === 'validating', editando)}
          </FocusButton>
          {onCancel && (
            <FocusButton focusKey="onboarding-cancel" onPress={onCancel}>
              {t('common.cancel')}
            </FocusButton>
          )}
        </div>

        {status === 'error' && (
          <p role="alert" style={{ color: 'var(--danger)' }}>
            {errorMsg}
          </p>
        )}
      </div>
    </FocusContext.Provider>
  );
}

function Field({
  id,
  label,
  value,
  active,
  secret = false,
  onSelect,
}: {
  id: FieldId;
  label: string;
  value: string;
  active: boolean;
  secret?: boolean;
  onSelect: () => void;
}) {
  const { ref, focused } = useFocusable({
    focusKey: `onboarding-field-${id}`,
    onFocus: onSelect,
    onEnterPress: () => setFocus('onboarding-kb'),
  });
  const shown = secret ? '•'.repeat(value.length) : value;
  return (
    <button
      ref={ref}
      type="button"
      onClick={pressWithFocus(`onboarding-field-${id}`, onSelect)}
      style={{
        appearance: 'none',
        textAlign: 'left',
        cursor: 'pointer',
        padding: '0.8rem 1rem',
        borderRadius: 'var(--radius-sm)',
        background: 'var(--bg-raised)',
        border: `2px solid ${active ? 'var(--accent)' : 'var(--border-subtle)'}`,
        color: 'var(--text-primary)',
        font: 'inherit',
        ...focusRing(focused),
      }}
    >
      <span
        style={{
          display: 'block',
          fontSize: 'var(--fs-meta)',
          color: 'var(--text-secondary)',
        }}
      >
        {label}
      </span>
      <span style={{ fontSize: 'var(--fs-body)' }}>{shown || ' '}</span>
    </button>
  );
}

/**
 * Confirmação depois que a lista autenticou (RF-53): status, validade e número
 * de conexões simultâneas. Serve para o usuário conferir que entrou na conta
 * certa antes de o app começar a baixar catálogo — e é onde uma conta perto de
 * vencer aparece antes de virar problema.
 */
function ContaValidada({
  conta,
  onEntrar,
}: Readonly<{ conta: Account; onEntrar: () => void }>) {
  const { ref, focusKey } = useFocusable({
    focusKey: 'onboarding-conta',
    trackChildren: true,
  });
  useEffect(() => {
    setFocus('onboarding-entrar');
  }, []);

  const data = conta.expiresAt
    ? new Date(conta.expiresAt).toLocaleDateString('pt-BR')
    : null;

  return (
    <FocusContext.Provider value={focusKey}>
      <div
        ref={ref}
        className={gapColClass}
        style={{
          maxWidth: '32rem',
          margin: '0 auto',
          display: 'flex',
          flexDirection: 'column',
          background: 'var(--bg-panel)',
          borderRadius: 'var(--radius-md)',
          padding: '2rem',
          ...gapVar('1rem'),
        }}
      >
        <h1 style={{ margin: 0 }}>{t('onboarding.accountStatus')}</h1>
        <Linha rotulo={t('onboarding.username')} valor={conta.username} />
        <Linha
          rotulo={t('onboarding.accountStatus')}
          valor={conta.status || t('onboarding.active')}
        />
        {data && <Linha rotulo="" valor={t('onboarding.expiresOn', { date: data })} />}
        <Linha
          rotulo=""
          valor={t('onboarding.connections', { n: conta.maxConnections })}
        />
        <FocusButton primary focusKey="onboarding-entrar" onPress={onEntrar}>
          {t('common.done')}
        </FocusButton>
      </div>
    </FocusContext.Provider>
  );
}

function Linha({ rotulo, valor }: Readonly<{ rotulo: string; valor: string }>) {
  return (
    <div className={gapRowClass} style={{ display: 'flex', ...gapVar('0.6rem') }}>
      {rotulo && <span style={{ color: 'var(--text-secondary)' }}>{rotulo}:</span>}
      <strong>{valor}</strong>
    </div>
  );
}
