import { Dexie, type Table } from 'dexie';
import type {
  Category,
  Channel,
  EpgEntry,
  Movie,
  MovieDetail,
  PlaybackProgress,
  Series,
  SeriesDetail,
  StreamKind,
} from '../models/index.js';

/**
 * Cache local (constitution §6). Tudo é escopado por `listId` — o app suporta várias
 * listas Xtream e cada uma tem seu próprio catálogo. Credenciais NÃO ficam aqui:
 * IndexedDB não é armazenamento seguro (constitution §9) — só metadados não-secretos.
 */

export type CatalogSection = 'live' | 'vod' | 'series';

/** Lista Xtream configurada — sem senha (essa vai para o secure storage da plataforma). */
export interface StoredList {
  id: string;
  name: string;
  serverUrl: string;
  username: string;
  userAgent?: string;
  streamFormat?: 'm3u8' | 'ts';
  livePathSegment?: string;
  /** Base HTTPS já validada para esta lista (ver `Account.preferredHttpsBase`). */
  preferredHttpsBase?: string;
  addedAt: number;
}

/** Linha de `meta`: bookkeeping de sync + kv livre, por lista. */
export interface MetaRow {
  listId: string;
  key: string;
  value: unknown;
  updatedAt: number;
}

type WithList<T> = T & { listId: string };
/** `syncGen` marca a rodada de sync que escreveu a linha; a poda apaga gerações antigas. */
type Catalogued<T> = WithList<T> & { syncGen: number };

export type StoredCategory = WithList<Category> & { kind: CatalogSection; order: number };
export type StoredChannel = Catalogued<Channel>;
/**
 * `norm` (PERF-01b / spec 002): título normalizado (mesma `normalizeText` da
 * busca), gravado pelo sync — habilita ordenar por nome pelo índice
 * `[listId+norm]` em vez de materializar+ordenar o acervo inteiro em memória.
 * Ausente em linhas gravadas antes da v4 do esquema (mesmo padrão de `words`
 * na busca) até o preenchimento em blocos rodar (`CatalogRepo.garantirNorm`).
 */
export type StoredMovie = Catalogued<Movie> & { norm?: string };
export type StoredSeries = Catalogued<Series> & { norm?: string };
export type StoredMovieInfo = WithList<MovieDetail> & { cachedAt: number };
export type StoredSeriesInfo = WithList<SeriesDetail> & { cachedAt: number };
export type StoredEpgNowNext = {
  listId: string;
  channelId: string;
  entries: EpgEntry[];
  cachedAt: number;
};
export interface StoredProgramme {
  listId: string;
  channelId: string;
  start: number;
  stop: number;
  title: string;
  description?: string;
  /**
   * Geração do sync que escreveu a linha (PERF-02/03, preparado no esquema v4
   * mas ainda sem gravador — a troca do `wipe()` prévio pelo padrão
   * "geração antiga inteira até a nova terminar" é trabalho futuro, não desta
   * migração). Sem valor até lá.
   */
  gen?: number;
}
export type StoredProgress = PlaybackProgress & { listId: string; profileId: string };
export interface StoredFavorite {
  profileId: string;
  listId: string;
  kind: StreamKind;
  id: string;
  addedAt: number;
}
/** Membership de item em categoria (GTV-RF-20/GTV-RF-22). Reconstruível no sync. */
export interface CategoryMember {
  listId: string;
  section: CatalogSection;
  categoryId: string;
  itemId: string;
  /**
   * Ordenação por recenticidade (quando o item foi adicionado à lista).
   * Mesmo valor pode ter múltiplas linhas — desempate por itemId.
   */
  recent: number;
  /**
   * Título normalizado (mesma `normalizeText` da busca). Usado para ordem por nome.
   * Vazio em linhas migradas — `CatalogRepo.garantirNorm` preenche.
   */
  norm: string;
  /**
   * Nota do item (painel provê). Usado para ordem por avaliação.
   * Negativo = não avaliado (desempate por itemId).
   */
  rating: number;
  /**
   * Geração do sync que escreveu a linha — permite prune de memberships órfãs
   * (de itens ou categorias removidas) sem varrer a tabela inteira em JS.
   */
  syncGen: number;
}
/** Índice de busca: uma linha por item, `norm` = título normalizado (RF-42). */
export interface SearchRow {
  listId: string;
  kind: CatalogSection;
  id: string;
  name: string;
  /**
   * Palavras de `norm`, indexadas uma a uma (multiEntry). É o que faz achar o
   * termo no meio do título sem varrer a tabela. Ausente nas linhas gravadas
   * antes da v2 do esquema — ver `SearchRepo.garantirIndiceDePalavras`.
   */
  words?: string[];
  norm: string;
  poster?: string;
  categoryId?: string;
  /** rodada de sync que escreveu a linha — a poda apaga órfãos ao final. */
  syncGen: number;
}

export class AuraDb extends Dexie {
  lists!: Table<StoredList, string>;
  meta!: Table<MetaRow, [string, string]>;
  categories!: Table<StoredCategory, [string, string, string]>;
  channels!: Table<StoredChannel, [string, string]>;
  movies!: Table<StoredMovie, [string, string]>;
  series!: Table<StoredSeries, [string, string]>;
  movieInfo!: Table<StoredMovieInfo, [string, string]>;
  seriesInfo!: Table<StoredSeriesInfo, [string, string]>;
  epgNowNext!: Table<StoredEpgNowNext, [string, string]>;
  epgProgrammes!: Table<StoredProgramme, [string, string, number]>;
  progress!: Table<StoredProgress, [string, string, string]>;
  favorites!: Table<StoredFavorite, [string, string, string, string]>;
  search!: Table<SearchRow, [string, string, string]>;
  categoryMembers!: Table<CategoryMember, [string, string, string, string]>;

  constructor(name = 'aura-cache') {
    super(name);
    this.version(1).stores({
      lists: 'id, addedAt',
      meta: '[listId+key], listId',
      categories: '[listId+kind+id], [listId+kind]',
      channels: '[listId+id], [listId+categoryId], [listId+num], [listId+syncGen]',
      movies: '[listId+id], [listId+categoryId], [listId+addedAt], [listId+syncGen]',
      series: '[listId+id], [listId+categoryId], [listId+lastModified], [listId+syncGen]',
      movieInfo: '[listId+id], cachedAt',
      seriesInfo: '[listId+id], cachedAt',
      epgNowNext: '[listId+channelId], cachedAt',
      epgProgrammes: '++pk, [listId+channelId+start], [listId+stop]',
      progress: '[profileId+listId+key], [profileId+listId], listId, updatedAt',
      favorites: '[profileId+listId+kind+id], [profileId+listId], listId, addedAt',
      search: '[listId+kind+id], [listId+norm], listId',
    });

    // v2 — índice multiEntry das palavras do título (RF-42). Sem ele, achar uma
    // palavra no meio do nome exigia varrer a tabela inteira: 5.473ms para
    // 54.535 linhas, medidos no aparelho de teste; pelo índice, 5-24ms.
    //
    // O IndexedDB não aceita índice composto **e** multiEntry ao mesmo tempo,
    // então `words` não carrega o `listId` — a consulta filtra a lista depois,
    // sobre as poucas linhas que casaram.
    this.version(2).stores({
      search: '[listId+kind+id], [listId+norm], listId, *words',
    });

    // v3 — `categoryIds` multiEntry: um item pode estar em mais de uma categoria
    // (`category_ids` do painel) e guardar só uma fazia a outra aparecer vazia na
    // tela — medido, "Filmes | Lancamentos" com 0 de 106 títulos
    // (panel-findings §category_ids). Como no índice de palavras, o multiEntry
    // não aceita composto: o índice não carrega o `listId` e a consulta filtra a
    // lista depois.
    this.version(3).stores({
      movies:
        '[listId+id], [listId+categoryId], [listId+addedAt], [listId+syncGen], *categoryIds',
      series:
        '[listId+id], [listId+categoryId], [listId+lastModified], [listId+syncGen], *categoryIds',
    });

    // v4 — uma migração única cobrindo três necessidades (spec 002 §2.1), pra
    // não bumpar o esquema três vezes em sequência:
    //
    // 1. PERF-01b: `[listId+norm]`/`[listId+rating]` em `movies`/`series` — o
    //    caminho rápido por índice do PERF-01a (`[listId+addedAt|lastModified]`)
    //    só cobria `sort: 'recent'`; "Todos" ordenado por nome/nota continuava
    //    materializando o acervo inteiro em memória a cada leva da rolagem
    //    infinita. `norm` é escrito por nós (mesma `normalizeText` da busca),
    //    então cobertura 100% é garantida assim que o preenchimento em blocos
    //    (`CatalogRepo.garantirNorm`) terminar — ao contrário de `addedAt`, que
    //    depende do painel mandar a data em todo item.
    // 2. PERF-04: `[listId+kind+syncGen]` em `search` — `pruneStale` varria
    //    ~55 mil linhas em JS (`.where('listId').filter(...)`), 3× por sync.
    // 3. PERF-03 (só a parte de esquema — a troca do `wipe()` por geração é
    //    trabalho futuro, §2.2): `epgProgrammes` promove o índice
    //    `[listId+channelId+start]` (já existia desde a v1) a CHAVE PRIMÁRIA,
    //    no lugar do `++pk` sintético — dedup natural (duas linhas para o
    //    mesmo canal+início são o mesmo programa) e prepara o `[listId+gen]`
    //    que o PERF-02 vai usar. `epgProgrammes` é cache 100% reconstruível
    //    (nenhum dado do usuário mora ali); o próximo sync de EPG repovoa
    //    (D-22 já roda em segundo plano no boot, RF-64).
    //
    // Dexie recusa mudar a chave primária de uma tabela existente numa única
    // `.stores()` ("Not yet support for changing primary key", mesmo com
    // `.clear()` no `upgrade()` — a checagem é estrutural, antes de rodar
    // qualquer código) — achado escrevendo o teste de migração. O jeito
    // documentado é apagar a tabela (`null`) e recriar na versão seguinte;
    // as duas versões saem juntas, no mesmo commit/release, então continua
    // sendo "uma migração" do ponto de vista de quem instala a atualização.
    this.version(4).stores({
      movies:
        '[listId+id], [listId+categoryId], [listId+addedAt], [listId+syncGen], *categoryIds, [listId+norm], [listId+rating]',
      series:
        '[listId+id], [listId+categoryId], [listId+lastModified], [listId+syncGen], *categoryIds, [listId+norm], [listId+rating]',
      search: '[listId+kind+id], [listId+norm], listId, *words, [listId+kind+syncGen]',
      epgProgrammes: null,
    });
    this.version(5).stores({
      epgProgrammes: '[listId+channelId+start], [listId+stop], [listId+gen]',
    });

    // v6 — `categoryMembers` para paginação eficiente (GTV-RF-20):
    // Permite listar itens de uma categoria sem materializar/ordenar em memória.
    // Índices compostos para recent/norm/rating com itemId para desempate.
    // Reconstruível no sync — nenhum dado do usuário.
    this.version(6).stores({
      categoryMembers:
        '[listId+section+categoryId+itemId], [listId+section+categoryId+recent+itemId], [listId+section+categoryId+norm+itemId], [listId+section+categoryId+rating+itemId], [listId+section+syncGen]',
    });

    // v7 — a fronteira da paginação inclui o id. Sem ele, cada página volta
    // ao início dos títulos/datas/notas empatados; empates grandes repetiam
    // resultados e podiam impedir a rolagem de alcançar o restante do catálogo.
    // Os prefixos destes índices também atendem às consultas antigas do Dexie.
    this.version(7).stores({
      movies:
        '[listId+id], [listId+categoryId], [listId+addedAt+id], [listId+syncGen], *categoryIds, [listId+norm+id], [listId+rating+id]',
      series:
        '[listId+id], [listId+categoryId], [listId+lastModified+id], [listId+syncGen], *categoryIds, [listId+norm+id], [listId+rating+id]',
      search:
        '[listId+kind+id], [listId+norm], [listId+kind+norm], listId, *words, [listId+kind+syncGen]',
    });
  }

  /** Apaga todo o cache de uma lista (remoção de lista). */
  async wipeList(listId: string): Promise<void> {
    const lo: [string, string] = [listId, ''];
    const hi: [string, string] = [listId, '￿'];
    const tables = [
      this.meta,
      this.categories,
      this.channels,
      this.movies,
      this.series,
      this.movieInfo,
      this.seriesInfo,
      this.epgNowNext,
      this.epgProgrammes,
      this.progress,
      this.favorites,
      this.search,
      this.categoryMembers,
    ];
    await this.transaction('rw', tables, async () => {
      await Promise.all([
        this.meta.where('listId').equals(listId).delete(),
        this.categories
          .where('[listId+kind+id]')
          .between([listId, '', ''], [listId, '￿', '￿'])
          .delete(),
        this.channels.where('[listId+id]').between(lo, hi).delete(),
        this.movies.where('[listId+id]').between(lo, hi).delete(),
        this.series.where('[listId+id]').between(lo, hi).delete(),
        this.movieInfo.where('[listId+id]').between(lo, hi).delete(),
        this.seriesInfo.where('[listId+id]').between(lo, hi).delete(),
        this.epgNowNext.where('[listId+channelId]').between(lo, hi).delete(),
        this.epgProgrammes
          .where('[listId+stop]')
          .between([listId, -Infinity], [listId, Infinity])
          .delete(),
        this.progress.where('listId').equals(listId).delete(),
        this.favorites.where('listId').equals(listId).delete(),
        this.search.where('listId').equals(listId).delete(),
        this.categoryMembers
          .where('[listId+section+categoryId+itemId]')
          .between([listId, '', '', ''], [listId, '￿', '￿', '￿'])
          .delete(),
      ]);
    });
  }

  /**
   * Apaga só as tabelas reconstruíveis do catálogo (LS-RF-15, spec 005) —
   * catálogo, busca, EPG, `categoryMembers` e `meta` (bookkeeping de sync,
   * força ressincronização completa). Preserva `lists`, `favorites` e
   * `progress`: ao contrário de `wipeList`, isto é seguro para o usuário
   * acionar quando o IndexedDB está perto/estourando a cota (LG-022) — quer
   * liberar espaço sem perder favoritos/continuar assistindo.
   */
  async wipeReconstructibleCache(listId: string): Promise<void> {
    const lo: [string, string] = [listId, ''];
    const hi: [string, string] = [listId, '￿'];
    const tables = [
      this.meta,
      this.categories,
      this.channels,
      this.movies,
      this.series,
      this.movieInfo,
      this.seriesInfo,
      this.epgNowNext,
      this.epgProgrammes,
      this.search,
      this.categoryMembers,
    ];
    await this.transaction('rw', tables, async () => {
      await Promise.all([
        this.meta.where('listId').equals(listId).delete(),
        this.categories
          .where('[listId+kind+id]')
          .between([listId, '', ''], [listId, '￿', '￿'])
          .delete(),
        this.channels.where('[listId+id]').between(lo, hi).delete(),
        this.movies.where('[listId+id]').between(lo, hi).delete(),
        this.series.where('[listId+id]').between(lo, hi).delete(),
        this.movieInfo.where('[listId+id]').between(lo, hi).delete(),
        this.seriesInfo.where('[listId+id]').between(lo, hi).delete(),
        this.epgNowNext.where('[listId+channelId]').between(lo, hi).delete(),
        this.epgProgrammes
          .where('[listId+stop]')
          .between([listId, -Infinity], [listId, Infinity])
          .delete(),
        this.search.where('listId').equals(listId).delete(),
        this.categoryMembers
          .where('[listId+section+categoryId+itemId]')
          .between([listId, '', '', ''], [listId, '￿', '￿', '￿'])
          .delete(),
      ]);
    });
  }
}
