import { createContext, useContext, useEffect, useMemo, type ReactNode } from 'react';
import type { PlatformAdapter } from '@mfp/platform';
import { createRuntime, type Runtime } from './runtime.js';

const RuntimeCtx = createContext<Runtime | null>(null);

export function RuntimeProvider({
  adapter,
  onRuntime,
  children,
}: {
  adapter: PlatformAdapter;
  /**
   * Chamado uma vez com o runtime recém-criado. A casca usa isto para publicar
   * `globalThis.__auraPerf` ao roteiro de medição (spec 002) — fora de release.
   */
  onRuntime?: (rt: Runtime) => void;
  children: ReactNode;
}) {
  const runtime = useMemo(() => createRuntime(adapter), [adapter]);
  useEffect(() => {
    onRuntime?.(runtime);
  }, [runtime, onRuntime]);
  return <RuntimeCtx.Provider value={runtime}>{children}</RuntimeCtx.Provider>;
}

export function useRuntime(): Runtime {
  const rt = useContext(RuntimeCtx);
  if (!rt) throw new Error('useRuntime fora de <RuntimeProvider>');
  return rt;
}
