import { useEffect, useState } from 'react';

export interface DetailBackdropProps {
  /** Arte widescreen (`backdrop_path`, ~w1280) — preferida. */
  backdrop?: string;
  /** Pôster retrato, usado quando não há arte widescreen. */
  poster?: string;
}

/**
 * Arte de fundo das telas de detalhe (design-inventory telas 05 e 07): a imagem
 * sangra até as bordas e o texto fica sobre um gradiente que garante contraste.
 *
 * Renderiza imediatamente sem a imagem (shell + gradientes) e carrega a imagem
 * assincronamente. Tela fica responsiva enquanto backdrop carrega.
 *
 * Fica atrás do conteúdo (`z-index: 0` + conteúdo em `position: relative`) e é
 * `aria-hidden`: é decoração, o título já está no `<h1>`. Sem imagem nenhuma o
 * componente não renderiza nada e a tela cai no fundo liso do tema.
 */
export function DetailBackdrop({ backdrop, poster }: Readonly<DetailBackdropProps>) {
  const src = backdrop ?? poster;
  const [imagemCarregada, setImagemCarregada] = useState(false);

  // Carrega a imagem assincronamente após o render
  useEffect(() => {
    if (!src) return;

    const img = new Image();
    img.onload = () => setImagemCarregada(true);
    img.onerror = () => setImagemCarregada(false);
    // Inicia o carregamento da imagem em background (não bloqueia UI)
    img.src = src;

    return () => {
      img.onload = null;
      img.onerror = null;
    };
  }, [src]);

  if (!src) return null;

  // O pôster é retrato: cobrir a tela inteira com ele estoura o enquadramento,
  // então ele ocupa só a faixa da direita, como a arte do desenho original.
  const larguraArte = backdrop ? '100%' : '55%';
  // a faixa estreita do pôster precisa de uma dissolvência mais larga
  const bordaSuave = backdrop
    ? 'linear-gradient(to right, transparent 0%, #000 18%)'
    : 'linear-gradient(to right, transparent 0%, #000 35%)';

  return (
    <div
      aria-hidden
      style={{
        position: 'absolute',
        // cancela o padding do <main> para a arte sangrar até as bordas
        top: 'calc(-1 * var(--safe-y))',
        left: 'calc(-1 * var(--safe-x))',
        right: 'calc(-1 * var(--safe-x))',
        height: '100vh',
        zIndex: 0,
        overflow: 'hidden',
        pointerEvents: 'none',
      }}
    >
      <div
        style={{
          position: 'absolute',
          top: 0,
          right: 0,
          bottom: 0,
          width: larguraArte,
          // Renderiza imediatamente sem imagem (shell vazio).
          // Quando imagemCarregada=true, a imagem aparece via background.
          background: imagemCarregada ? `url(${src}) center top / cover no-repeat` : 'transparent',
          // Dissolve a borda esquerda da arte. Sem isso o pôster (que ocupa só
          // uma faixa) deixa uma emenda vertical visível contra o fundo.
          // `-webkit-` para WebViews antigos das TVs.
          WebkitMaskImage: bordaSuave,
          maskImage: bordaSuave,
          // Transição suave quando a imagem aparece (GTV-A4 sem bloqueio)
          transition: imagemCarregada ? 'opacity 0.3s ease-in' : 'none',
          opacity: imagemCarregada ? 1 : 0.8,
        }}
      />
      {/*
        Véu horizontal: o texto vive à esquerda (telas 05/07), então o véu é
        opaco até onde a coluna de texto termina (`--detail-text-w`) e some
        rápido depois. Escurecer o centro uniformemente apagava artes escuras
        com o assunto centralizado — foi o que aconteceu com a primeira versão.
      */}
      <div
        style={{
          position: 'absolute',
          top: 0,
          right: 0,
          bottom: 0,
          left: 0,
          background:
            'linear-gradient(to right,' +
            ' var(--bg-base) 0%,' +
            ' rgba(0,0,0,0.88) 32%,' +
            ' rgba(0,0,0,0.5) 52%,' +
            ' rgba(0,0,0,0.12) 78%,' +
            ' rgba(0,0,0,0) 100%)',
        }}
      />
      {/* e vertical, para o conteúdo que rola por baixo não brigar com a arte */}
      <div
        style={{
          position: 'absolute',
          top: 0,
          right: 0,
          bottom: 0,
          left: 0,
          background:
            'linear-gradient(to bottom, rgba(0,0,0,0.25) 0%, transparent 25%, var(--bg-base) 92%)',
        }}
      />
    </div>
  );
}
