import { useEffect, useState } from 'react';
import {
  FocusContext,
  useFocusable,
  setFocus,
} from '@noriginmedia/norigin-spatial-navigation';
import { FocusButton } from '../components/FocusButton.js';
import { OnScreenKeyboard } from '../components/OnScreenKeyboard.js';
import type { StoredList } from '@mfp/core';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useLists } from '../state/lists.js';
import { useBackHandler } from '../nav/backStack.js';
import { classifyError } from '../errors.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';

/**
 * "Credencial necessária" (spec 003 LG-RF-24/LG-050): o secure storage não
 * tem a senha desta lista — servidor e usuário continuam salvos, só a senha
 * precisa ser redigitada. Distinta de `AccountExpired`: aqui a conta não
 * venceu, a plataforma só não guarda a senha entre execuções (webOS 4–23 sem
 * Keymanager3 — session-only, RF-24). A UI não menciona plataforma nenhuma:
 * reage só ao resultado do adapter/storage, então a mesma tela serve qualquer
 * caso futuro de keystore limpo por fora do app.
 */
export function CredentialRequired({
  list,
  onOk,
  onEsquecerLista,
}: Readonly<{
  list: StoredList;
  /** Reautenticou com sucesso — o `Boot` deve rodar de novo. */
  onOk: () => void;
  /** Usuário não lembra a senha — mesma saída de `AccountExpired`. */
  onEsquecerLista: () => void;
}>) {
  const rt = useRuntime();
  const reentrarComSenha = useLists((s) => s.reentrarComSenha);

  const [senha, setSenha] = useState('');
  const [status, setStatus] = useState<'idle' | 'validando' | 'erro'>('idle');
  const [erro, setErro] = useState('');

  const { ref, focusKey } = useFocusable({
    focusKey: 'credential-required',
    trackChildren: true,
  });

  useEffect(() => {
    setFocus('credential-kb');
  }, []);

  // Sem "voltar": não há rota anterior de verdade (é a única coisa entre o
  // boot e o app) — Back aqui equivale a desistir, mesma saída do CTA.
  useBackHandler(onEsquecerLista);

  const enviar = async () => {
    if (!senha) return;
    setStatus('validando');
    try {
      await reentrarComSenha(rt, list.id, senha);
      onOk();
    } catch (err) {
      const e = classifyError(err);
      setErro(`${e.body} (${e.code})`);
      setStatus('erro');
    }
  };

  return (
    <FocusContext.Provider value={focusKey}>
      <div
        ref={ref}
        className={gapColClass}
        style={{
          maxWidth: '40rem',
          margin: '0 auto',
          display: 'flex',
          flexDirection: 'column',
          ...gapVar('1rem'),
        }}
      >
        <h1>{t('credentialRequired.title')}</h1>
        <p style={{ color: 'var(--text-secondary)' }}>
          {t('credentialRequired.body', { server: list.serverUrl, user: list.username })}
        </p>

        <div
          style={{
            padding: '0.8rem 1rem',
            borderRadius: 'var(--radius-sm)',
            background: 'var(--bg-raised)',
            border: '2px solid var(--accent)',
          }}
        >
          <span
            style={{
              display: 'block',
              fontSize: 'var(--fs-meta)',
              color: 'var(--text-secondary)',
            }}
          >
            {t('onboarding.password')}
          </span>
          <span style={{ fontSize: 'var(--fs-body)' }}>
            {'•'.repeat(senha.length) || ' '}
          </span>
        </div>

        <OnScreenKeyboard
          focusKey="credential-kb"
          onInput={(ch) => setSenha((cur) => cur + ch)}
          onDelete={() => setSenha((cur) => cur.slice(0, -1))}
          onClear={() => setSenha('')}
        />

        <div className={gapRowClass} style={{ display: 'flex', ...gapVar('1rem') }}>
          <FocusButton
            primary
            focusKey="credential-submit"
            disabled={status === 'validando' || !senha}
            onPress={() => void enviar()}
          >
            {status === 'validando' ? t('onboarding.validating') : t('common.done')}
          </FocusButton>
          <FocusButton focusKey="credential-forget" onPress={onEsquecerLista}>
            {t('credentialRequired.forget')}
          </FocusButton>
        </div>

        {status === 'erro' && (
          <p role="alert" style={{ color: 'var(--danger)' }}>
            {erro}
          </p>
        )}
      </div>
    </FocusContext.Provider>
  );
}
