import { redact } from '../util/redact.js';

/**
 * Marcas de performance para o orçamento verificável do RF-68
 * (spec 002 — `specs/002-performance-hardening/`, RP-1..RP-12).
 *
 * `packages/core` não toca em `performance`/`window` (constitution §2): o relógio
 * entra **injetado**, no mesmo desenho do `Clock` do playback. A raiz de
 * composição (`packages/ui/src/runtime`) passa `() => performance.now()`; os
 * testes usam o `Date.now` do default ou um relógio manual.
 *
 * O objeto é barato de chamar no caminho crítico: `marcar` é um `push` num array
 * com teto. A leitura (`amostras`) só roda quando o roteiro de medição pergunta.
 */

export type NomeDeMarca =
  | 'boot:start'
  | 'boot:firstPaint'
  | 'boot:homeInteractive'
  | 'zap:keydown'
  | 'zap:firstFrame'
  | 'vod:open'
  | 'vod:firstFrame'
  | 'home:load'
  | 'home:loaded'
  | 'browse:change'
  | 'browse:painted'
  | 'sync:section:start'
  | 'sync:section:done'
  | 'nav:key'
  | 'nav:focusRecovered'
  | 'detail:open'
  | 'detail:shellPainted'
  | 'detail:cacheDone'
  | 'detail:apiDone'
  | 'detail:usable'
  | 'detail:back'
  | 'detail:returnFocused'
  | 'browse:queryStart'
  | 'browse:queryDone'
  | 'background:chunkStart'
  | 'background:chunkDone';

/** Anexo livre a uma marca (ex.: `{ section: 'live', canal: 42 }`). Sem URL. */
export type MarcaMeta = Record<string, string | number>;

export interface MarcaBruta {
  nome: NomeDeMarca;
  /** Instante em ms na base do relógio injetado (monotônico em produção). */
  t: number;
  meta?: MarcaMeta;
}

/** Um span resolvido: a distância entre a marca de início e a de fim. */
export interface Amostra {
  /** Nome do span, não da marca — ex.: `boot→homeInteractive`, `zap`. */
  nome: string;
  ms: number;
  meta?: MarcaMeta;
}

export interface Perf {
  /** Registra uma marca. Barato; seguro de chamar no caminho crítico. */
  marcar(nome: NomeDeMarca, meta?: MarcaMeta, em?: number): void;
  /**
   * Registra uma marca só se este nome nunca foi visto (desde o último
   * `limpar`). Para os marcos de boot, que telas remontadas repetiriam à toa.
   */
  marcarUnica(nome: NomeDeMarca, meta?: MarcaMeta, em?: number): void;
  /** Marcas cruas, na ordem de chegada (cópia — mexer aqui não afeta o buffer). */
  marcas(): readonly MarcaBruta[];
  /** Spans resolvidos: início→fim pareados em FIFO. Marca sem par é ignorada. */
  amostras(): readonly Amostra[];
  /** Zera marcas e o registro de nomes já vistos. */
  limpar(): void;
}

/** Teto do buffer em anel — medir não pode virar vazamento num app aberto horas. */
export const MAX_MARCAS = 500;

interface SpanDef {
  nome: string;
  de: NomeDeMarca;
  ate: NomeDeMarca;
}

/**
 * `boot:start` alimenta dois spans (RP-1 e RP-2): cada definição varre o buffer
 * por conta própria, então a mesma marca de início serve aos dois sem conflito.
 * Similarmente, `detail:open` alimenta shells, cache e back (GTV-A1/A4/A5).
 */
const SPANS: readonly SpanDef[] = [
  { nome: 'boot→firstPaint', de: 'boot:start', ate: 'boot:firstPaint' },
  { nome: 'boot→homeInteractive', de: 'boot:start', ate: 'boot:homeInteractive' },
  { nome: 'zap', de: 'zap:keydown', ate: 'zap:firstFrame' },
  { nome: 'vod', de: 'vod:open', ate: 'vod:firstFrame' },
  { nome: 'home:load', de: 'home:load', ate: 'home:loaded' },
  { nome: 'browse', de: 'browse:change', ate: 'browse:painted' },
  { nome: 'sync:section', de: 'sync:section:start', ate: 'sync:section:done' },
  { nome: 'detail:shell', de: 'detail:open', ate: 'detail:usable' },
  { nome: 'detail:cache', de: 'detail:open', ate: 'detail:cacheDone' },
  { nome: 'detail:back', de: 'detail:open', ate: 'detail:back' },
  { nome: 'category', de: 'browse:queryStart', ate: 'browse:queryDone' },
  { nome: 'background:chunk', de: 'background:chunkStart', ate: 'background:chunkDone' },
];

/**
 * Redige valores de meta por precaução: nenhuma marca deve carregar URL de
 * stream, mas se uma carregar, a credencial não vaza no relatório (RF-69).
 */
function metaSegura(meta?: MarcaMeta): MarcaMeta | undefined {
  if (!meta) return undefined;
  const out: MarcaMeta = {};
  for (const [k, v] of Object.entries(meta)) {
    out[k] = typeof v === 'string' ? redact(v) : v;
  }
  return out;
}

export function criarPerf(agora: () => number = Date.now): Perf {
  let marcas: MarcaBruta[] = [];
  /** Nomes já registrados alguma vez — para `marcarUnica`. */
  const vistas = new Set<NomeDeMarca>();

  const registrar = (nome: NomeDeMarca, meta?: MarcaMeta, em?: number): void => {
    // buffer em anel: a marca mais antiga sai quando o teto é atingido
    if (marcas.length >= MAX_MARCAS) marcas.shift();
    marcas.push({ nome, t: em ?? agora(), meta: metaSegura(meta) });
    vistas.add(nome);
  };

  return {
    marcar: registrar,
    marcarUnica(nome, meta, em) {
      if (vistas.has(nome)) return;
      registrar(nome, meta, em);
    },
    marcas: () => [...marcas],
    amostras() {
      const out: Amostra[] = [];
      for (const span of SPANS) {
        // só o início pendente MAIS RECENTE — não uma fila. Um `de` cujo `ate`
        // nunca chega (ex.: `detail:usable`/`cacheDone` só disparam `if (seed)`/
        // `if (cached)`, condicionalmente) não pode ficar pendurado esperando
        // casar com o `ate` de uma visita seguinte, sem relação nenhuma com
        // aquele início — foi o bug real por trás de `detail:shell`/`detail:cache`
        // acumulando dezenas/centenas de segundos (o `open` de uma visita antiga
        // pareava com o `usable`/`cacheDone` de uma visita bem posterior). Um
        // novo `de` descarta qualquer pendente anterior sem par: spans como este
        // são de um fluxo por vez, não sobrepostos.
        let pendente: MarcaBruta | undefined;
        for (const m of marcas) {
          if (m.nome === span.de) {
            pendente = m;
          } else if (m.nome === span.ate) {
            const inicio = pendente;
            pendente = undefined;
            if (!inicio) continue; // fim sem início — ignora
            const meta = { ...inicio.meta, ...m.meta };
            out.push({
              nome: span.nome,
              ms: m.t - inicio.t,
              ...(Object.keys(meta).length ? { meta } : {}),
            });
          }
        }
      }
      return out;
    },
    limpar() {
      marcas = [];
      vistas.clear();
    },
  };
}
