// Heurística de badge de qualidade sobre o `name` (decisions D-1): o painel não
// dá esses campos estruturados. Regex tolerante ao lixo comum ("FILME 2024 4K DUAL").

export type QualityTag = '4K' | 'HDR' | 'DUAL' | 'LEG';

const PATTERNS: [RegExp, QualityTag][] = [
  [/\b(4k|2160p?|uhd)\b/i, '4K'],
  [/\bhdr(10)?\b|dolby\s*vision|\bdv\b/i, 'HDR'],
  [/\bdual(\s*[aá]udio)?\b|\bdublado\b/i, 'DUAL'],
  [/\bleg(endado)?\b|\bsub\b/i, 'LEG'],
];

export function qualityFromName(name: string): QualityTag[] {
  const out: QualityTag[] = [];
  for (const [re, tag] of PATTERNS) {
    if (re.test(name) && !out.includes(tag)) out.push(tag);
  }
  return out;
}
