/**
 * Posição das listas entre montagens.
 *
 * Abrir um detalhe (ou o player) empilha uma rota, e o `renderScreen` troca a
 * árvore inteira: a tela de baixo é **desmontada**. Todo estado de posição que
 * vivesse num `useState` morre aí — foi o que fazia a grade reabrir no topo ao
 * voltar. Este mapa vive fora do React e sobrevive à desmontagem.
 *
 * A chave carrega o que define o conteúdo da lista (seção, gênero, ordenação,
 * busca): se o conteúdo muda, a chave muda e a lista recomeça do zero — que é o
 * certo, porque o índice guardado apontaria para outro item.
 */
const posicoes = new Map<string, number>();

/** Teto: a chave inclui texto digitado na busca, então não para de crescer sozinha. */
const TETO = 40;

export function lembrarPosicao(chave: string, indice: number): void {
  if (!posicoes.has(chave) && posicoes.size >= TETO) {
    const maisAntiga = posicoes.keys().next().value;
    if (maisAntiga !== undefined) posicoes.delete(maisAntiga);
  }
  posicoes.set(chave, indice);
}

export function posicaoLembrada(chave: string | undefined): number | undefined {
  return chave === undefined ? undefined : posicoes.get(chave);
}
