import type { Table } from 'dexie';
import { isAdultCategoryName } from '../util/adultContent.js';
import { normalizeText } from '../util/normalize.js';
import { paginateCategory } from './categoryPagination.js';
import type { Category, Channel, Movie, Series } from '../models/index.js';
import type {
  AuraDb,
  CategoryMember,
  CatalogSection,
  StoredCategory,
  StoredMovie,
  StoredSeries,
} from './db.js';

const LOW = '';
const HIGH = '￿';
/** Nenhuma categoria bloqueada — instância única, a política desligada é o normal. */
const VAZIO: ReadonlySet<string> = new Set<string>();

export type CatalogSort = 'recent' | 'name' | 'rating';

export interface BrowseOptions {
  categoryId?: string;
  sort?: CatalogSort;
  limit?: number;
  /** Opaco — devolvido por uma chamada anterior (`Janela.cursor`). Ausente = 1ª página. */
  cursor?: string;
}

/** Janela de resultados (PERF-01a / spec 002): substitui `Page<T>`. */
export interface Janela<T> {
  items: T[];
  /** Presente = há mais itens; repasse como `cursor` na próxima chamada. */
  cursor?: string;
  /**
   * Qual caminho de leitura respondeu — custo desprezível (um literal por
   * chamada), mantido de propósito: já pegou duas regressões reais nos testes
   * desta spec (cache de "populado" preso em `false`, depois checando seção
   * inteira em vez de por categoria). Não é para a UI decidir nada com isto.
   */
  _caminho?: 'rapida' | 'antiga' | 'indexada';
}

/** Política de conteúdo aplicada a **toda** leitura deste repositório. */
export interface CatalogPolicy {
  /**
   * Esconde as categorias adultas e tudo que pertence a elas (RF-33 / D-8).
   *
   * O filtro mora aqui, e não nas telas, de propósito: é um ponto único por onde
   * passam listas, detalhe, favoritos e retomada. Uma tela nova não tem como
   * esquecer de aplicar — e esquecer, aqui, significa expor conteúdo adulto.
   */
  hideAdult?: boolean;
}

/**
 * Leitura e escrita do catálogo em cache, sempre escopadas por `listId`.
 * A UI só lê; o `CatalogSync` usa os `put*`/`prune*`.
 */
/** Chave em `meta` que marca `categoryIds` gravado em todo o catálogo da lista. */
export const CHAVE_CATEGORIAS_MULTIPLAS = 'catalog.categoryIdsGen';
/** Suba se a forma de `categoryIds` mudar — força o próximo sync a remarcar. */
export const GERACAO_CATEGORIAS_MULTIPLAS = 1;
/**
 * Chave em `meta` que marca `norm` gravado em todo o catálogo da lista
 * (GTV-RF-10). Sem ela, `garantirNorm()` varria movies+series inteiros em
 * todo boot — mesmo sem nada para preencher — e essa varredura, competindo
 * pela fila do IndexedDB, foi a causa real da demora de "primeira abertura"
 * no detalhe de filme/série medida na Smart TV Pro G08.
 */
export const CHAVE_NORM_PRONTO = 'catalog.normGen';
/** Suba se a forma de `norm` mudar — força o próximo boot a reconferir. */
export const GERACAO_NORM = 1;

/**
 * Cursor da página rápida por índice (PERF-01a/PERF-01b): último item já
 * devolvido. `k` é `number` para `addedAt`/`lastModified`/`rating`, `string`
 * para `norm` (PERF-01b).
 */
interface CursorIndice {
  k: number | string;
  /** desempate — a chave primária ordena as linhas empatadas em `k` (spec IndexedDB). */
  id: string;
}
/** Cursor da página lenta (materializa + ordena em memória): posição no array. */
interface CursorOffset {
  s: number;
}

function codificarCursorIndice(c: CursorIndice): string {
  return JSON.stringify({ t: 'i', ...c });
}
function codificarCursorOffset(c: CursorOffset): string {
  return JSON.stringify({ t: 'o', ...c });
}
function decodificarCursor(
  raw: string | undefined,
): { tipo: 'i'; c: CursorIndice } | { tipo: 'o'; c: CursorOffset } | undefined {
  if (!raw) return undefined;
  try {
    const o = JSON.parse(raw) as Record<string, unknown>;
    if (
      o.t === 'i' &&
      (typeof o.k === 'number' || typeof o.k === 'string') &&
      typeof o.id === 'string'
    ) {
      return { tipo: 'i', c: { k: o.k, id: o.id } };
    }
    if (o.t === 'o' && typeof o.s === 'number') {
      return { tipo: 'o', c: { s: o.s } };
    }
  } catch {
    /* cursor inválido (de uma versão antiga, por exemplo) — trata como 1ª página */
  }
  return undefined;
}

/**
 * Ao filtrar categoria adulta por cima do índice, uma página pode encolher
 * abaixo do `limit` pedido — sobre-busca com laço (spec 002 §2.5). Teto de
 * idas ao índice por chamada: um catálogo majoritariamente bloqueado não pode
 * virar uma varredura disfarçada.
 */
const TETO_PAGINAS_SOBRE_BUSCA = 6;

/** Devolve a thread ao navegador entre blocos de `garantirNorm` (mesmo padrão de `SearchRepo`). */
const cederAThread = () => new Promise<void>((r) => setTimeout(r, 0));

/** Identificador do campo de ordenação rápida — não é o nome do índice em si. */
type CampoOrdenacao = 'recent' | 'norm' | 'rating';

function campoDoSort(sort: CatalogSort): CampoOrdenacao {
  if (sort === 'name') return 'norm';
  if (sort === 'rating') return 'rating';
  return 'recent';
}

/** Configuração de um campo de ordenação rápida para uma tabela `S` (PERF-01b). */
interface ConfigCampoOrdenacao<S> {
  campoIndice: string;
  chaveDe: (r: S) => number | string | undefined;
  tipo: 'numero' | 'texto';
  /** `desc` = mais recente/maior nota primeiro; `asc` = ordem alfabética (`norm`). */
  direcao: 'asc' | 'desc';
}

/**
 * Chave em `meta` da marca "índice completo" de um (seção, campo). O nome de
 * `'recent'` preserva o texto exato do PERF-01a (`catalog.recentIndexavel.*`)
 * — trocar a string invalidaria a marca de quem já mediu isso nesta sessão,
 * sem necessidade; `norm`/`rating` (PERF-01b) usam um formato novo.
 */
function chaveIndiceCompleto(section: CatalogSection, campo: CampoOrdenacao): string {
  return campo === 'recent'
    ? `catalog.recentIndexavel.${section}`
    : `catalog.indexavel.${section}.${campo}`;
}

const CAMPOS_ORDENACAO: readonly CampoOrdenacao[] = ['recent', 'norm', 'rating'];
const indexRevisions = new WeakMap<AuraDb, Map<string, number>>();

function indexRevision(db: AuraDb, listId: string): number {
  return indexRevisions.get(db)?.get(listId) ?? 0;
}

/**
 * Invalida a marca de "índice completo" (PERF-01a/PERF-01b) de uma seção, nos
 * três campos rastreados. Chamada pelo `CatalogSync` ao fim de um sync
 * completo, para a marca nunca ficar desatualizada se o painel passar a mandar
 * item sem `addedAt`/`lastModified`/`rating` depois de um dia ter mandado
 * todos com o campo (`norm` é nosso — sempre gravado — mas invalidar também
 * não custa nada e evita um caso extremo de bug futuro deixar a marca presa).
 */
export async function invalidarIndiceCompleto(
  db: AuraDb,
  listId: string,
  section: CatalogSection,
): Promise<void> {
  let revisions = indexRevisions.get(db);
  if (!revisions) {
    revisions = new Map();
    indexRevisions.set(db, revisions);
  }
  revisions.set(listId, indexRevision(db, listId) + 1);
  await Promise.all(
    CAMPOS_ORDENACAO.map((campo) =>
      db.meta.delete([listId, chaveIndiceCompleto(section, campo)]),
    ),
  );
}

export class CatalogRepo {
  /** ids das categorias adultas, por seção — resolvidos sob demanda e memoizados. */
  private bloqueadas: Partial<Record<CatalogSection, Promise<ReadonlySet<string>>>> = {};
  /**
   * Toda linha da seção tem `addedAt`/`lastModified` (PERF-01a)? Contar isso
   * custou **1,4s medidos no aparelho** para 42 mil linhas — nada de "barato só
   * por ser um índice" (achado real: `count()` do IndexedDB percorre a faixa,
   * não é O(1)). Por isso o resultado é memoizado aqui **e** em `meta`, para
   * sobreviver a uma nova instância de `CatalogRepo` (o runtime cria uma por
   * chamada — PERF-07 ainda não resolvido) sem recontar a cada leitura.
   */
  private indiceCompletoCache: Partial<Record<string, Promise<boolean>>> = {};
  private indexRevision = -1;
  /** memoizado por instância: a leitura é barata, mas roda a cada troca de gênero. */
  private multiplasProntas?: Promise<boolean>;
  /** memoizado por instância — ver `normPronto()`. */
  private normProntaCache?: Promise<boolean>;

  constructor(
    private readonly db: AuraDb,
    private readonly listId: string,
    private readonly policy: CatalogPolicy = {},
  ) {}

  /**
   * O catálogo desta lista já foi gravado com `categoryIds`?
   *
   * Só um sync completo pode responder que sim: o dado vem do painel
   * (`category_ids`) e não dá para deduzir do que está no cache — a linha antiga
   * guarda uma categoria só, e não se sabe quais outras faltam. Por isso não há
   * preenchimento em blocos aqui, ao contrário do índice de palavras (D-17).
   */
  private categoriasMultiplasProntas(): Promise<boolean> {
    this.multiplasProntas ??= this.db.meta
      .get([this.listId, CHAVE_CATEGORIAS_MULTIPLAS])
      .then((row) => row?.value === GERACAO_CATEGORIAS_MULTIPLAS);
    return this.multiplasProntas;
  }

  /** Ids de categoria escondidos nesta seção (vazio se a política não bloqueia). */
  private idsBloqueados(section: CatalogSection): Promise<ReadonlySet<string>> {
    if (!this.policy.hideAdult) return Promise.resolve(VAZIO);
    this.bloqueadas[section] ??= this.db.categories
      .where('[listId+kind]')
      .equals([this.listId, section])
      .toArray()
      .then(
        (rows) =>
          new Set(
            rows.filter((r) => isAdultCategoryName(r.name)).map((r) => String(r.id)),
          ),
      );
    return this.bloqueadas[section]!;
  }

  /**
   * O item pertence a uma categoria escondida? Usado onde a ausência no catálogo
   * não basta como resposta — a trilha "Continuar assistindo" guarda nome e
   * pôster no próprio progresso e mostraria o item mesmo sem achá-lo aqui.
   */
  async isBlocked(section: CatalogSection, id: string): Promise<boolean> {
    if (!this.policy.hideAdult) return false;
    const tabela =
      section === 'live'
        ? this.db.channels
        : section === 'vod'
          ? this.db.movies
          : this.db.series;
    const row = await tabela.get([this.listId, id]);
    if (!row?.categoryId) return false;
    return (await this.idsBloqueados(section)).has(String(row.categoryId));
  }

  // ---- leitura -------------------------------------------------------------

  async categories(section: CatalogSection): Promise<Category[]> {
    const rows = await this.db.categories
      .where('[listId+kind]')
      .equals([this.listId, section])
      .toArray();
    rows.sort((a, b) => a.order - b.order);
    const bloq = await this.idsBloqueados(section);
    return rows.filter((r) => !bloq.has(String(r.id))).map(stripStored);
  }

  async channels(categoryId?: string): Promise<Channel[]> {
    const bloq = await this.idsBloqueados('live');
    // pedir explicitamente uma categoria escondida não pode devolver nada
    if (categoryId && bloq.has(String(categoryId))) return [];
    const rows = categoryId
      ? await this.db.channels
          .where('[listId+categoryId]')
          .equals([this.listId, categoryId])
          .toArray()
      : // PERF-05: pelo índice `[listId+num]` — já chega ordenado, canais sem
        // `num` (fora do índice, valor ausente) entram depois, no fim.
        await this.canaisPorNumero();
    return rows.filter((r) => !bloq.has(String(r.categoryId))).map(stripStored);
  }

  /** `PERF-05`: canais com `num`, pelo índice (já ordenado); sem `num`, ao final. */
  private async canaisPorNumero() {
    const [comNumero, keys] = await Promise.all([
      this.db.channels
        .where('[listId+num]')
        .between([this.listId, -Infinity], [this.listId, Infinity])
        .toArray(),
      this.db.channels
        .where('[listId+id]')
        .between([this.listId, LOW], [this.listId, HIGH])
        .primaryKeys(),
    ]);
    if (comNumero.length === keys.length) return comNumero; // caminho comum
    const idsComNumero = new Set(comNumero.map((c) => c.id));
    const semNumero = (
      await this.db.channels.bulkGet(keys.filter(([, id]) => !idsComNumero.has(id)))
    )
      .filter((c): c is NonNullable<typeof c> => c !== undefined)
      .sort((a, b) => a.name.localeCompare(b.name));
    return [...comNumero, ...semNumero];
  }

  async channel(id: string): Promise<Channel | undefined> {
    const row = await this.db.channels.get([this.listId, id]);
    if (!row) return undefined;
    const bloq = await this.idsBloqueados('live');
    if (bloq.has(String(row.categoryId))) return undefined;
    return stripStored(row);
  }

  async movies(opts: BrowseOptions = {}): Promise<Movie[]> {
    return (await this.moviesPage(opts)).items;
  }

  async series(opts: BrowseOptions = {}): Promise<Series[]> {
    return (await this.seriesPage(opts)).items;
  }

  /** Quantos filmes existem para os filtros dados — pelo índice, sem materializar linha. */
  countMovies(opts: Pick<BrowseOptions, 'categoryId'> = {}): Promise<number> {
    return this.contarSecao(this.db.movies, 'vod', opts.categoryId);
  }

  /** Idem, para séries. */
  countSeries(opts: Pick<BrowseOptions, 'categoryId'> = {}): Promise<number> {
    return this.contarSecao(this.db.series, 'series', opts.categoryId);
  }

  private async contarSecao(
    table: { where: (i: string) => any },
    section: CatalogSection,
    categoryId: string | undefined,
  ): Promise<number> {
    const bloq = await this.idsBloqueados(section);
    if (categoryId) {
      if (bloq.has(String(categoryId))) return 0;
      // Achado real (2026-09-15): contar pelo caminho antigo (`daCategoria`)
      // materializa a categoria inteira só pra contar — rodando em paralelo
      // com `paginaCategoriaIndexada` (mesma categoria), os dois competem pelo
      // mesmo IndexedDB e ficam com custo quase idêntico (~550ms cada, medido
      // num tablet, categoria de 11 mil itens), mesmo a página já usando o
      // índice novo. Pelo índice de `categoryMembers`, contar é um `.count()`
      // sobre um range, sem tocar em nenhuma linha.
      if (
        (section === 'vod' || section === 'series') &&
        (await this.categoryMembersPopulada(section, categoryId))
      ) {
        return this.db.categoryMembers
          .where('[listId+section+categoryId+itemId]')
          .between(
            [this.listId, section, categoryId, LOW],
            [this.listId, section, categoryId, HIGH],
          )
          .count();
      }
      // categoryMembers ainda não populado (pré-migração) — cai pro caminho
      // antigo, sem regredir.
      return (await this.daCategoria(table, categoryId)).length;
    }
    const total = await table
      .where('[listId+id]')
      .between([this.listId, LOW], [this.listId, HIGH])
      .count();
    if (!bloq.size) return total;
    let bloqueados = 0;
    for (const catId of bloq) {
      bloqueados += await table
        .where('[listId+categoryId]')
        .equals([this.listId, catId])
        .count();
    }
    return Math.max(0, total - bloqueados);
  }

  /**
   * Filmes recentes/por nome/por nota (design-inventory §Grid). Sem `categoryId`,
   * os três critérios de ordenação vão pelo índice certo com paginação por
   * cursor (PERF-01a `recent`, PERF-01b `name`/`rating`): `[listId+addedAt]`,
   * `[listId+norm]`, `[listId+rating]` — é o caminho da Home e da aba "Todos"
   * do catálogo, e materializar o acervo inteiro (42 mil itens medidos) para
   * mostrar 30 era o gargalo nº 1 do RF-68. Busca **com** categoria continua
   * pelo caminho antigo (o índice multiEntry de categoria não pode ser
   * composto com a ordenação, §2.6) — já é barato nesse caso.
   */
  moviesPage(opts: BrowseOptions = {}): Promise<Janela<Movie>> {
    return this.paginar<StoredMovie, Movie>(
      this.db.movies,
      {
        recent: {
          campoIndice: '[listId+addedAt+id]',
          chaveDe: (r) => r.addedAt,
          tipo: 'numero',
          direcao: 'desc',
        },
        norm: {
          campoIndice: '[listId+norm+id]',
          chaveDe: (r) => r.norm,
          tipo: 'texto',
          direcao: 'asc',
        },
        rating: {
          campoIndice: '[listId+rating+id]',
          chaveDe: (r) => r.rating,
          tipo: 'numero',
          direcao: 'desc',
        },
      },
      opts,
      (a, b, sort) => {
        if (sort === 'name') return a.name.localeCompare(b.name);
        if (sort === 'rating') return (b.rating ?? 0) - (a.rating ?? 0);
        return (b.addedAt ?? 0) - (a.addedAt ?? 0);
      },
      'vod',
    );
  }

  seriesPage(opts: BrowseOptions = {}): Promise<Janela<Series>> {
    return this.paginar<StoredSeries, Series>(
      this.db.series,
      {
        recent: {
          campoIndice: '[listId+lastModified+id]',
          chaveDe: (r) => r.lastModified,
          tipo: 'numero',
          direcao: 'desc',
        },
        norm: {
          campoIndice: '[listId+norm+id]',
          chaveDe: (r) => r.norm,
          tipo: 'texto',
          direcao: 'asc',
        },
        rating: {
          campoIndice: '[listId+rating+id]',
          chaveDe: (r) => r.rating,
          tipo: 'numero',
          direcao: 'desc',
        },
      },
      opts,
      (a, b, sort) => {
        if (sort === 'name') return a.name.localeCompare(b.name);
        if (sort === 'rating') return (b.rating ?? 0) - (a.rating ?? 0);
        return (b.lastModified ?? 0) - (a.lastModified ?? 0);
      },
      'series',
    );
  }

  async movie(id: string): Promise<Movie | undefined> {
    const row = await this.db.movies.get([this.listId, id]);
    if (!row) return undefined;
    if ((await this.idsBloqueados('vod')).has(String(row.categoryId))) return undefined;
    return stripStored(row);
  }

  async seriesById(id: string): Promise<Series | undefined> {
    const row = await this.db.series.get([this.listId, id]);
    if (!row) return undefined;
    if ((await this.idsBloqueados('series')).has(String(row.categoryId)))
      return undefined;
    return stripStored(row);
  }

  async counts(): Promise<Record<CatalogSection, number>> {
    const [live, vod, series] = await Promise.all([
      this.db.channels
        .where('[listId+id]')
        .between([this.listId, LOW], [this.listId, HIGH])
        .count(),
      this.db.movies
        .where('[listId+id]')
        .between([this.listId, LOW], [this.listId, HIGH])
        .count(),
      this.db.series
        .where('[listId+id]')
        .between([this.listId, LOW], [this.listId, HIGH])
        .count(),
    ]);
    return { live, vod, series };
  }

  /**
   * Preenche `norm` nas linhas de `movies`/`series` gravadas antes da v4 do
   * esquema (PERF-01b) — mesmo padrão de `SearchRepo.garantirIndiceDePalavras`:
   * roda em segundo plano, em blocos, cedendo a thread entre eles. Sem isto,
   * quem já tinha catálogo não ganharia o caminho rápido de ordenação por
   * nome até o próximo sync completo reescrever cada linha.
   *
   * Diferente do índice de palavras, aqui não há uma "marca pronta" separada:
   * a própria `indiceCompleto()` (cache em `meta`) responde isso contando
   * linhas sem a chave — o preenchimento só precisa invalidar essa marca ao
   * terminar, para a próxima leitura recontar e achar 100%.
   *
   * @returns quantas linhas foram preenchidas, somando as duas tabelas.
   */
  /** `norm` já está gravado em toda linha de movies+series desta lista (GTV-RF-10)? */
  private normPronto(): Promise<boolean> {
    this.normProntaCache ??= this.db.meta
      .get([this.listId, CHAVE_NORM_PRONTO])
      .then((row) => row?.value === GERACAO_NORM);
    return this.normProntaCache;
  }

  private async marcarNormPronto(): Promise<void> {
    await this.db.meta.put({
      listId: this.listId,
      key: CHAVE_NORM_PRONTO,
      value: GERACAO_NORM,
      updatedAt: Date.now(),
    });
    this.normProntaCache = Promise.resolve(true);
  }

  async garantirNorm(tamanhoDoBloco = 800): Promise<number> {
    // GTV-RF-10: sem esta marca, toda ativação de lista ('ready') varria
    // movies+series inteiros de novo, para nada — em catálogos de dezenas de
    // milhares de linhas isso competia pela fila do IndexedDB com qualquer
    // leitura simples (abrir um detalhe, por exemplo) e causava segundos de
    // atraso bem no meio do boot, mesmo sem nenhuma linha para preencher.
    if (await this.normPronto()) return 0;

    // Sequencial, não `Promise.all` (spec 004 M6 §3.2): rodar as duas tabelas
    // ao mesmo tempo dobra a pressão sobre a mesma conexão IndexedDB na TV.
    const m = await this.preencherNorm(this.db.movies, 'vod', tamanhoDoBloco);
    const s = await this.preencherNorm(this.db.series, 'series', tamanhoDoBloco);
    await this.marcarNormPronto();
    return m + s;
  }

  private async preencherNorm<S extends { id: string; name: string; norm?: string }>(
    table: Table<S, [string, string]>,
    section: CatalogSection,
    tamanhoDoBloco: number,
  ): Promise<number> {
    let preenchidas = 0;
    let inicio: [string, string] = [this.listId, LOW];
    let incluiInicio = true;
    for (;;) {
      const bloco = await table
        .where('[listId+id]')
        .between(inicio, [this.listId, HIGH], incluiInicio, true)
        .limit(tamanhoDoBloco)
        .toArray();
      if (!bloco.length) break;

      const semNorm = bloco.filter((r) => r.norm === undefined);
      if (semNorm.length) {
        await table.bulkPut(semNorm.map((r) => ({ ...r, norm: normalizeText(r.name) })));
        preenchidas += semNorm.length;
      }

      const ultima = bloco[bloco.length - 1]!;
      inicio = [this.listId, ultima.id];
      incluiInicio = false;
      if (bloco.length < tamanhoDoBloco) break;
      await cederAThread();
    }
    if (preenchidas > 0) {
      // a marca de "índice completo" do campo `norm` pode ter ficado presa em
      // `false` de uma leitura anterior — invalida pra próxima recontar
      const chave = chaveIndiceCompleto(section, 'norm');
      await this.db.meta.delete([this.listId, chave]);
      delete this.indiceCompletoCache[`${section}:norm`];
    }
    return preenchidas;
  }

  // ---- escrita (usada pelo sync) -----------------------------------------

  async putCategories(section: CatalogSection, categories: Category[]): Promise<void> {
    const rows: StoredCategory[] = categories.map((c, order) => ({
      ...c,
      listId: this.listId,
      kind: section,
      order,
    }));
    // troca completa da lista de categorias da seção, atômica
    await this.db.transaction('rw', this.db.categories, async () => {
      await this.db.categories
        .where('[listId+kind]')
        .equals([this.listId, section])
        .delete();
      await this.db.categories.bulkPut(rows);
    });
  }

  async putChannels(channels: Channel[], syncGen: number): Promise<void> {
    await this.db.channels.bulkPut(
      channels.map((c) => ({ ...c, listId: this.listId, syncGen })),
    );
  }

  async putMovies(movies: Movie[], syncGen: number): Promise<void> {
    // PERF-01b: `norm` habilita o índice `[listId+norm]` — mesma
    // `normalizeText` da busca, gravado aqui pra nunca ficar fora de sincronia
    // com o `name` do item.
    await this.db.movies.bulkPut(
      movies.map((m) => ({
        ...m,
        listId: this.listId,
        syncGen,
        norm: normalizeText(m.name),
      })),
    );
    await this.putCategoryMembers('vod', movies, syncGen, (m) => m.addedAt ?? 0);
  }

  async putSeries(series: Series[], syncGen: number): Promise<void> {
    await this.db.series.bulkPut(
      series.map((s) => ({
        ...s,
        listId: this.listId,
        syncGen,
        norm: normalizeText(s.name),
      })),
    );
    await this.putCategoryMembers('series', series, syncGen, (s) => s.lastModified ?? 0);
  }

  /**
   * Espelha filmes/séries em `categoryMembers` (schema v6, GTV-RF-20/22/23) —
   * uma linha por (item, categoria) que o item pertence, com os campos de
   * ordenação já prontos. Permite paginar uma categoria pelo índice
   * (`categoryPagination.ts`) sem materializar+ordenar a categoria inteira em
   * memória (`paginaAntiga`) — achado real (2026-09-15): categoria de 11.019
   * itens levava ~950ms nesse caminho antigo, medido num tablet Android.
   */
  private async putCategoryMembers<
    S extends {
      id: string;
      name: string;
      categoryId?: string;
      categoryIds?: string[];
      rating?: number;
    },
  >(
    section: 'vod' | 'series',
    items: S[],
    syncGen: number,
    recenteDe: (item: S) => number,
  ): Promise<void> {
    const linhas: CategoryMember[] = [];
    for (const item of items) {
      const categorias = item.categoryIds?.length ? item.categoryIds : [item.categoryId];
      const norm = normalizeText(item.name);
      const recent = recenteDe(item);
      const rating = item.rating ?? -1;
      for (const categoryId of categorias) {
        if (!categoryId) continue;
        linhas.push({
          listId: this.listId,
          section,
          categoryId: String(categoryId),
          itemId: item.id,
          recent,
          norm,
          rating,
          syncGen,
        });
      }
    }
    if (linhas.length) await this.db.categoryMembers.bulkPut(linhas);
  }

  /** Apaga memberships de gerações anteriores — mesmo padrão de `pruneSection`. */
  async pruneCategoryMembers(
    section: CatalogSection,
    keepSyncGen: number,
  ): Promise<number> {
    if (section === 'live') return 0; // categoryMembers só cobre vod/series por ora
    const stale = await this.db.categoryMembers
      .where('[listId+section+syncGen]')
      .between(
        [this.listId, section, 0],
        [this.listId, section, keepSyncGen],
        true,
        false,
      )
      .primaryKeys();
    if (stale.length) await this.db.categoryMembers.bulkDelete(stale as never[]);
    return stale.length;
  }

  /** Apaga linhas de gerações anteriores — itens sumidos do painel (RF-63). */
  async pruneSection(section: CatalogSection, keepSyncGen: number): Promise<number> {
    const table = this.sectionTable(section);
    const stale = await table
      .where('[listId+syncGen]')
      .between([this.listId, 0], [this.listId, keepSyncGen], true, false)
      .primaryKeys();
    if (stale.length) await table.bulkDelete(stale as never[]);
    return stale.length;
  }

  private sectionTable(section: CatalogSection) {
    if (section === 'live') return this.db.channels;
    if (section === 'vod') return this.db.movies;
    return this.db.series;
  }

  /**
   * Itens de uma categoria.
   *
   * Depois que um sync completo gravou `categoryIds` (esquema v3), a consulta
   * vai pelo índice multiEntry: um item em "Lançamentos" **e** em "Drama"
   * aparece nos dois. Antes disso — cache escrito por uma versão anterior do
   * app — vale o índice antigo, com a categoria única que o painel mandou no
   * item; é o comportamento de sempre, sem regressão enquanto o próximo sync
   * não roda.
   */
  private async daCategoria<S extends { listId?: string; categoryIds?: string[] }>(
    table: { where: (i: string) => any },
    categoryId: string,
  ): Promise<S[]> {
    if (await this.categoriasMultiplasProntas()) {
      const linhas: S[] = await table.where('categoryIds').equals(categoryId).toArray();
      // o índice multiEntry não carrega o `listId` (não pode ser composto)
      return linhas.filter((r) => r.listId === this.listId);
    }
    return table.where('[listId+categoryId]').equals([this.listId, categoryId]).toArray();
  }

  /**
   * Roteador entre o caminho rápido (índice + cursor, PERF-01a/PERF-01b) e o
   * antigo (materializa + ordena em memória). O rápido só entra sem
   * `categoryId`, e quando **toda** linha da seção tem o campo do critério de
   * ordenação pedido indexado — um índice do IndexedDB simplesmente não lista
   * a linha cuja chave é `undefined`, então uma lista com alguma linha sem
   * `addedAt`/`lastModified`/`rating` teria esses itens apagados do resultado
   * no caminho rápido. Sem essa checagem, um painel que não manda o campo em
   * todo item regrediria. `norm` (PERF-01b) é escrito por nós em todo
   * `putMovies`/`putSeries`, então cobertura 100% é garantida assim que o
   * preenchimento em blocos das linhas antigas (`garantirNorm`) terminar.
   */
  private async paginar<
    S extends {
      id: string;
      name: string;
      categoryId?: string;
      listId?: string;
      categoryIds?: string[];
    },
    T,
  >(
    table: {
      where: (i: string) => any;
      bulkGet: (keys: [string, string][]) => Promise<(S | undefined)[]>;
    },
    indices: Record<CampoOrdenacao, ConfigCampoOrdenacao<S>>,
    opts: BrowseOptions,
    cmp: (a: S, b: S, sort: CatalogSort) => number,
    section: CatalogSection,
  ): Promise<Janela<T>> {
    const bloq = await this.idsBloqueados(section);
    if (opts.categoryId && bloq.has(String(opts.categoryId))) return { items: [] };

    const sort = opts.sort ?? 'recent';
    const campo: CampoOrdenacao = campoDoSort(sort);
    if (!opts.categoryId) {
      const rapida = await this.paginaRapida<S, T>(
        table,
        indices[campo],
        opts,
        bloq,
        section,
        campo,
      );
      // DIAGNÓSTICO TEMPORÁRIO (2026-09-15): confirma qual caminho respondeu —
      // reverter junto com o resto da instrumentação de `browse.ts`.
      if (rapida) return { ...rapida, _caminho: 'rapida' } as Janela<T>;
      // alguma linha sem o campo do critério pedido — cai pro caminho antigo, sem regredir
    } else if (section === 'vod' || section === 'series') {
      const indexada = await this.paginaCategoriaIndexada<S, T>(table, opts, section);
      if (indexada) return { ...indexada, _caminho: 'indexada' } as Janela<T>;
      // categoryMembers ainda não populado para esta seção (pré-migração) —
      // cai pro caminho antigo, sem regredir.
    }
    const antiga = await this.paginaAntiga<S, T>(table, opts, cmp, bloq);
    return { ...antiga, _caminho: 'antiga' } as Janela<T>;
  }

  /**
   * Memoiza, por (instância, categoria), SE `categoryMembers` já tem alguma
   * linha para ESSA categoria especificamente — só o resultado `true` é
   * guardado.
   *
   * Dois achados reais (2026-09-15), nessa ordem:
   * 1ª versão: cacheava `false` para sempre — um app já aberto antes do
   * primeiro sync com o código novo terminar ficava preso no caminho antigo
   * pelo resto da sessão, mesmo depois de os dados chegarem.
   * 2ª versão (este comentário): checava por SEÇÃO inteira, não por
   * categoria — a categoria "Legendados" (11 mil itens) foi resincronizada
   * com o código novo e marcou a seção `vod` inteira como "populada", mas a
   * categoria "Cinema" (11 itens, sync mais antigo, nunca retocado) tinha
   * ZERO linhas em `categoryMembers` — o caminho indexado passou a mostrar
   * ela vazia, uma regressão real (achada testando no tablet). Migração é
   * por categoria, não por seção inteira de uma vez — o sync completo de uma
   * lista grande pode nunca acontecer numa única rodada.
   */
  private categoryMembersPopuladaCache = new Map<string, true>();

  private async categoryMembersPopulada(
    section: 'vod' | 'series',
    categoryId: string,
  ): Promise<boolean> {
    const chave = `${section}:${categoryId}`;
    if (this.categoryMembersPopuladaCache.has(chave)) return true;
    const n = await this.db.categoryMembers
      .where('[listId+section+categoryId+itemId]')
      .between(
        [this.listId, section, categoryId, LOW],
        [this.listId, section, categoryId, HIGH],
      )
      .limit(1)
      .primaryKeys();
    if (n.length) this.categoryMembersPopuladaCache.set(chave, true);
    return n.length > 0;
  }

  /**
   * Pagina uma categoria pelo índice de `categoryMembers` (`categoryPagination.ts`)
   * em vez de materializar+ordenar a categoria inteira em memória — achado real
   * (2026-09-15): categoria de 11.019 itens levava ~950ms no caminho antigo,
   * medido num tablet Android de bom desempenho. `undefined` = categoryMembers
   * ainda não foi populado para ESSA categoria especificamente (migração é
   * por categoria, não por seção inteira — ver comentário de
   * `categoryMembersPopulada`) — o chamador cai pro caminho antigo sem regredir.
   */
  private async paginaCategoriaIndexada<S extends { id: string }, T>(
    table: { bulkGet: (keys: [string, string][]) => Promise<(S | undefined)[]> },
    opts: BrowseOptions,
    section: 'vod' | 'series',
  ): Promise<Janela<T> | undefined> {
    if (!opts.categoryId) return undefined;
    if (!(await this.categoryMembersPopulada(section, opts.categoryId))) return undefined;

    const pagina = await paginateCategory(
      this.db,
      this.listId,
      section,
      opts.categoryId,
      {
        limit: opts.limit ?? 60,
        sort: opts.sort,
        cursor: opts.cursor,
      },
    );
    const linhas = await table.bulkGet(pagina.items.map((id) => [this.listId, id]));
    const items = linhas
      .filter((r): r is S => r !== undefined)
      .map((r) => stripStored(r) as unknown as T);
    return { items, ...(pagina.cursor ? { cursor: pagina.cursor } : {}) };
  }

  /**
   * `true` se toda linha da seção tem o campo de ordenação indexado —
   * memoizado por instância e em `meta` (ver o comentário do campo
   * `indiceCompletoCache`). `tipo` escolhe os limites do `between`: `norm` é
   * string (chave `''`/`'￿'`), `addedAt`/`lastModified`/`rating` são number
   * (chave `-Infinity`/`Infinity`) — usar o par errado nunca dá erro, só conta
   * zero linhas, então importa acertar.
   */
  private indiceCompleto(
    table: { where: (i: string) => any },
    campoIndice: string,
    section: CatalogSection,
    campo: CampoOrdenacao,
    tipo: 'numero' | 'texto' = 'numero',
  ): Promise<boolean> {
    const revision = indexRevision(this.db, this.listId);
    if (revision !== this.indexRevision) {
      this.indiceCompletoCache = {};
      this.indexRevision = revision;
    }
    const chaveCache = `${section}:${campo}`;
    this.indiceCompletoCache[chaveCache] ??= (async () => {
      const chave = chaveIndiceCompleto(section, campo);
      const linha = await this.db.meta.get([this.listId, chave]);
      if (typeof linha?.value === 'boolean') return linha.value;

      // 1ª leitura desta lista+seção+campo: paga o custo uma vez e grava a resposta.
      const [lo, hi] = tipo === 'texto' ? [LOW, HIGH] : [-Infinity, Infinity];
      const comChave: number = await table
        .where(campoIndice)
        .between([this.listId, lo, LOW], [this.listId, hi, HIGH], true, true)
        .count();
      const totalGeral: number = await table
        .where('[listId+id]')
        .between([this.listId, LOW], [this.listId, HIGH])
        .count();
      const completo = comChave >= totalGeral;
      // Uma leitura iniciada antes do sync não pode ressuscitar a marca antiga.
      if (revision === indexRevision(this.db, this.listId)) {
        await this.db.meta.put({
          listId: this.listId,
          key: chave,
          value: completo,
          updatedAt: Date.now(),
        });
      }
      return completo;
    })();
    return this.indiceCompletoCache[chaveCache]!;
  }

  /**
   * Caminho rápido (PERF-01a/PERF-01b): pelo índice do campo pedido
   * (`[listId+addedAt|lastModified]` para `recent`, `[listId+norm]` para
   * `name`, `[listId+rating]` para `rating`), com o cursor pareando (valor,
   * id) para atravessar empates — a ordem por chave primária em valores
   * empatados é garantida pela própria especificação do IndexedDB, não uma
   * suposição nossa. `direcao: 'desc'` (recent/rating) percorre do topo pra
   * baixo com `.reverse()`; `direcao: 'asc'` (norm — ordem alfabética) percorre
   * de baixo pra cima sem inverter.
   *
   * `undefined` = não é seguro usar este caminho (existe linha sem a chave).
   */
  private async paginaRapida<S extends { id: string; categoryId?: string }, T>(
    table: { where: (i: string) => any },
    cfg: ConfigCampoOrdenacao<S>,
    opts: BrowseOptions,
    bloq: ReadonlySet<string>,
    section: CatalogSection,
    campo: CampoOrdenacao,
  ): Promise<Janela<T> | undefined> {
    const { campoIndice, chaveDe, tipo, direcao } = cfg;
    const elegivel = await this.indiceCompleto(table, campoIndice, section, campo, tipo);
    if (!elegivel) return undefined; // alguma linha sem a chave — não regride

    const limit = opts.limit ?? 60;
    const decodificado = decodificarCursor(opts.cursor);
    let baseCursor: CursorIndice | undefined =
      decodificado?.tipo === 'i' ? decodificado.c : undefined;

    const [baixo, alto] = tipo === 'texto' ? [LOW, HIGH] : [-Infinity, Infinity];

    const coletadas: S[] = [];
    let esgotouIndice = false;

    for (
      let pagina = 0;
      coletadas.length < limit && !esgotouIndice && pagina < TETO_PAGINAS_SOBRE_BUSCA;
      pagina++
    ) {
      const fronteira = baseCursor && [this.listId, baseCursor.k, baseCursor.id];
      const teto = limit + 1; // sentinela; o id no índice atravessa qualquer empate
      const query =
        direcao === 'desc'
          ? table
              .where(campoIndice)
              .between(
                [this.listId, baixo, LOW],
                fronteira ?? [this.listId, alto, HIGH],
                true,
                !fronteira,
              )
              .reverse()
          : table
              .where(campoIndice)
              .between(
                fronteira ?? [this.listId, baixo, LOW],
                [this.listId, alto, HIGH],
                !fronteira,
                true,
              );
      const brutas: S[] = await query.limit(teto).toArray();
      if (brutas.length === 0) {
        esgotouIndice = true;
        break;
      }

      // Avança linha a linha, não em bloco: se a página encher no meio deste
      // lote, o cursor tem de apontar exatamente para a linha em que paramos —
      // nunca para o fim do lote inteiro, senão a próxima chamada pula por
      // cima de linhas do MEIO do lote que nunca chegaram a ser examinadas
      // (bug real, achado pelos testes: um lote de 10 com só 3 liberadas e
      // `espaco=1` saltava as outras 2 liberadas ao fixar o cursor no fim).
      let parouNoMeio = false;
      for (const row of brutas) {
        baseCursor = { k: chaveDe(row)!, id: row.id };
        if (bloq.has(String(row.categoryId))) continue;
        coletadas.push(row);
        if (coletadas.length === limit) {
          parouNoMeio = row !== brutas[brutas.length - 1];
          break;
        }
      }
      if (!parouNoMeio && brutas.length < teto) esgotouIndice = true; // nada mais além da fronteira
    }

    const cursor =
      !esgotouIndice && baseCursor ? codificarCursorIndice(baseCursor) : undefined;
    return {
      items: coletadas.map((r) => stripStored(r) as unknown as T),
      ...(cursor ? { cursor } : {}),
    };
  }

  /**
   * Caminho antigo: materializa (a categoria inteira, ou — sem categoria — a
   * seção inteira) e ordena em memória. Usado quando o rápido não se aplica:
   * com categoria (o índice multiEntry de categoria não pode ser composto com
   * a ordenação, §2.6), sem categoria em `name`/`rating` (falta o esquema v4,
   * PERF-01b), e como rede de segurança quando alguma linha não tem a chave
   * de data. O cursor aqui é só a posição no array já ordenado.
   */
  private async paginaAntiga<
    S extends {
      name: string;
      categoryId?: string;
      listId?: string;
      categoryIds?: string[];
    },
    T,
  >(
    table: { where: (i: string) => any },
    opts: BrowseOptions,
    cmp: (a: S, b: S, sort: CatalogSort) => number,
    bloq: ReadonlySet<string>,
  ): Promise<Janela<T>> {
    const brutas: S[] = opts.categoryId
      ? await this.daCategoria<S>(table, opts.categoryId)
      : await table
          .where('[listId+id]')
          .between([this.listId, LOW], [this.listId, HIGH])
          .toArray();
    const rows = bloq.size
      ? brutas.filter((r) => !bloq.has(String(r.categoryId)))
      : brutas;
    rows.sort((a, b) => cmp(a, b, opts.sort ?? 'recent'));

    const decodificado = decodificarCursor(opts.cursor);
    const start = decodificado?.tipo === 'o' ? decodificado.c.s : 0;
    const limit = opts.limit;
    const end = limit ? start + limit : undefined;
    const pagina = rows.slice(start, end);
    const cursor =
      end != null && end < rows.length ? codificarCursorOffset({ s: end }) : undefined;
    return {
      items: pagina.map((r) => stripStored(r) as unknown as T),
      ...(cursor ? { cursor } : {}),
    };
  }
}

/** Remove os campos de cache (`listId`, `syncGen`, `kind`, `order`, `norm`) do objeto de domínio. */
function stripStored<T>(
  row: T & {
    listId?: string;
    syncGen?: number;
    kind?: string;
    order?: number;
    norm?: string;
  },
): T {
  const { listId: _l, syncGen: _g, kind: _k, order: _o, norm: _n, ...rest } = row;
  return rest as T;
}
