import { useEffect, useRef, useState } from 'react';
import {
  FocusContext,
  useFocusable,
} from '@noriginmedia/norigin-spatial-navigation';
import {
  DEFAULT_DETAIL_CACHE_POLICY,
  resolveDetailState,
  shouldFetchDetail,
  type MovieDetail as MovieDetailModel,
} from '@mfp/core';
import { FocusButton } from '../components/FocusButton.js';
import { AgeBadge, QualityBadge, RatingStars } from '../components/badges.js';
import { LoadingState, ErrorScreen } from '../components/states.js';
import { BalanceLoader } from '../components/BalanceLoader.js';
import { DetailBackdrop } from '../components/DetailBackdrop.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useProvider } from '../runtime/useProvider.js';
import { useNavigation } from '../nav/navigationStack.js';
import { useFavorites } from '../state/favorites.js';
import { DEFAULT_PROFILE } from '../state/catalog.js';
import { classifyError, type AppError } from '../errors.js';
import { qualityFromName } from '../util/quality.js';
import { resumePoint } from '../util/resume.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar, gapWrapClass, gapWrapInnerClass } from '../theme/gap.js';
import { cssLen } from '../theme/cssMath.js';

let nextGeneration = 0;
function newGeneration(): number {
  return ++nextGeneration;
}

export function MovieDetail({ id, listId }: { id: string; listId: string }) {
  const rt = useRuntime();
  const getProvider = useProvider();
  const push = useNavigation((s) => s.push);
  const isFav = useFavorites((s) => s.isFav);
  const toggle = useFavorites((s) => s.toggle);
  const loadFavs = useFavorites((s) => s.load);
  const _favKeys = useFavorites((s) => s.keys);
  const [detail, setDetail] = useState<MovieDetailModel | null>(null);
  const [error, setError] = useState<AppError | null>(null);
  const [resumeSecs, setResumeSecs] = useState(0);
  // Indicador de enriquecimento (só aparece com o shell já visível — GTV-RF-23):
  // some assim que cache OU rede completarem. Uma revalidação de cache stale
  // (SWR) não liga isto de novo — ela é silenciosa por definição (GTV-RF-25).
  const [enriching, setEnriching] = useState(true);
  const ctrlRef = useRef<AbortController | null>(null);
  const genRef = useRef(newGeneration());

  useEffect(() => {
    const ctrl = new AbortController();
    const gen = newGeneration();
    ctrlRef.current = ctrl;
    genRef.current = gen;

    let isActive = true;
    setEnriching(true);

    rt.perf.marcar('detail:open', { tipo: 'vod' });
    void loadFavs(rt, listId);
    void (async () => {
      try {
        // Shell imediato (GTV-RF-23): pinta nome/poster/rating já sincronizados
        // no catálogo, sem esperar `get_vod_info` nem o cache de detalhe — é o
        // que tira a tela de "Carregando…" na primeira visita a um item.
        const seed = await rt.catalog(listId).movie(id);
        if (!isActive || genRef.current !== gen) return;
        if (seed) {
          setDetail((d) => d ?? (seed as MovieDetailModel));
          rt.perf.marcar('detail:usable', { origem: 'seed' });
        }

        const prog = await rt.db.progress.get([DEFAULT_PROFILE, listId, `movie:${id}`]);
        if (!isActive || genRef.current !== gen) return;
        if (prog)
          setResumeSecs(resumePoint(prog.positionSecs, prog.durationSecs, prog.completed));

        const cached = await rt.db.movieInfo.get([listId, id]);
        if (!isActive || genRef.current !== gen) return;
        if (cached) {
          setDetail(cached);
          setEnriching(false);
          rt.perf.marcar('detail:cacheDone', { origem: 'cache' });
        }

        // TTL (GTV-RF-24): cache válido não dispara `get_vod_info` de novo —
        // sem isto, toda abertura de detalhe batia rede mesmo com dado fresco.
        const policy = DEFAULT_DETAIL_CACHE_POLICY;
        const state = resolveDetailState(
          null,
          cached ? { data: cached, cachedAt: cached.cachedAt } : null,
          policy,
        );
        const { fetch: deveBuscar } = shouldFetchDetail(state, policy);
        if (cached && !deveBuscar) return;

        const { provider } = await getProvider();
        const fresh = await provider.getVodInfo(id, { signal: ctrl.signal });
        if (!isActive || genRef.current !== gen) return;
        setDetail(fresh);
        setEnriching(false);
        rt.perf.marcar('detail:apiDone', { origem: 'network' });
        await rt.db.movieInfo.put({ ...fresh, listId, cachedAt: Date.now() });
      } catch (err) {
        if (!isActive || genRef.current !== gen) return;
        setEnriching(false);
        if (!detail) setError(classifyError(err));
      }
    })();

    return () => {
      isActive = false;
      ctrl.abort();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, listId]);

  if (error && !detail)
    return <ErrorScreen title={error.title} body={error.body} code={error.code} />;
  if (!detail) return <LoadingState />;

  const fav = isFav('movie', id);
  const quality = qualityFromName(detail.name);
  const meta = [
    detail.releaseDate?.slice(0, 4),
    detail.durationSecs ? `${Math.round(detail.durationSecs / 60)} min` : null,
  ].filter(Boolean);

  return (
    <DetailContainer>
      <DetailBackdrop backdrop={detail.backdrop} poster={detail.poster} />
      {enriching && (
        <div
          role="status"
          className={gapRowClass}
          style={{
            position: 'absolute',
            top: '1.5rem',
            right: '1.5rem',
            zIndex: 1,
            padding: '0.5rem 1rem',
            borderRadius: 'var(--radius-sm)',
            background: 'var(--bg-scrim)',
            color: 'var(--text-primary)',
            display: 'flex',
            alignItems: 'center',
            ...gapVar('0.7rem'),
          }}
        >
          {/* mesmo indicador do player durante abertura/buffering */}
          <BalanceLoader size="1.1em" />
          {t('detail.enriching')}
        </div>
      )}
      <div
        className={gapColClass}
        style={{
          position: 'relative', // acima da arte de fundo
          // deixa a faixa da direita para a arte de fundo (DetailBackdrop)
          maxWidth: cssLen('min(60rem, 62%)'),
          display: 'flex',
          flexDirection: 'column',
          ...gapVar('1rem'),
        }}
      >
        <h1>{detail.name}</h1>
        <div className={gapWrapClass}>
          <div
            className={gapWrapInnerClass}
            style={{
              display: 'flex',
              alignItems: 'center',
              flexWrap: 'wrap',
              ...gapVar('0.6rem'),
            }}
          >
            {meta.map((m) => (
              <span key={m} style={{ color: 'var(--text-secondary)' }}>
                {m}
              </span>
            ))}
            <AgeBadge rating="14+" />
            {quality.map((q) => (
              <QualityBadge key={q} label={q} />
            ))}
            {detail.rating != null && detail.rating > 0 && (
              <RatingStars value={detail.rating} />
            )}
          </div>
        </div>

        {detail.genre && <p style={{ color: 'var(--text-secondary)' }}>{detail.genre}</p>}
        {detail.plot && <p>{detail.plot}</p>}
        {detail.cast && (
          <p style={{ color: 'var(--text-secondary)' }}>
            <strong>{t('detail.cast')}:</strong> {detail.cast}
          </p>
        )}
        {detail.director && (
          <p style={{ color: 'var(--text-secondary)' }}>
            <strong>{t('detail.director')}:</strong> {detail.director}
          </p>
        )}

        <div className={gapRowClass} style={{ display: 'flex', ...gapVar('1rem') }}>
          <FocusButton
            primary
            autoFocus
            focusKey="detail-watch"
            onPress={() =>
              push({
                name: 'player',
                params: {
                  kind: 'vod',
                  streamId: id,
                  ext: detail.containerExt ?? 'mp4',
                  title: detail.name,
                  ...(detail.poster ? { poster: detail.poster } : {}),
                  ...(resumeSecs > 0 ? { startAtSecs: String(resumeSecs) } : {}),
                },
              })
            }
          >
            {resumeSecs > 0
              ? t('detail.resume', {
                  label: `${Math.floor(resumeSecs / 60)} min`,
                })
              : t('detail.watch')}
          </FocusButton>
          <FocusButton
            focusKey="detail-fav"
            onPress={() => void toggle(rt, listId, 'movie', id)}
          >
            {fav ? t('detail.inMyList') : t('detail.myList')}
          </FocusButton>
        </div>
      </div>
    </DetailContainer>
  );
}

export function DetailContainer({ children }: { children: React.ReactNode }) {
  const { ref, focusKey } = useFocusable({ focusKey: 'detail', trackChildren: true });
  return (
    <FocusContext.Provider value={focusKey}>
      {/* âncora do `DetailBackdrop`, que se posiciona em relação a este container */}
      <div ref={ref} style={{ position: 'relative' }}>
        {children}
      </div>
    </FocusContext.Provider>
  );
}
