/**
 * Paginação eficiente por categoria usando índices compostos (GTV-RF-20/22/23).
 * Alternativa a materializar+ordenar a categoria inteira em memória
 * (`CatalogRepo.paginaAntiga`) — achado real (2026-09-15): selecionar uma
 * categoria de 11.019 itens levava ~950ms nesse caminho antigo, medido
 * repetidamente num tablet Android de bom desempenho, porque `paginaAntiga`
 * busca a categoria inteira e ordena em JS antes de cortar pro tamanho da
 * página, não importa quantos itens a tela realmente mostra.
 *
 * Índices disponíveis (schema v6, `CategoryMember`):
 * - [listId+section+categoryId+recent+itemId] para ordenar por recenticidade
 * - [listId+section+categoryId+norm+itemId] para ordenar por nome
 * - [listId+section+categoryId+rating+itemId] para ordenar por avaliação
 *
 * Bloqueio de categoria adulta é checado pelo chamador ANTES de paginar aqui
 * (a categoria inteira é bloqueada ou não — diferente do caminho sem
 * categoria, uma linha de `categoryMembers` não precisa de filtro por linha).
 */

import type { AuraDb, CategoryMember } from './db.js';
import type { CatalogSort } from './catalogRepo.js';

export interface PaginationOptions {
  limit?: number;
  sort?: CatalogSort;
  cursor?: string;
}

export interface PaginationResult {
  items: string[]; // itemIds, na ordem pedida
  cursor?: string; // presente = há mais itens; repasse na próxima chamada
}

interface CursorCategoria {
  k: number | string;
  id: string;
}

function codificarCursor(c: CursorCategoria): string {
  return JSON.stringify({ t: 'category', ...c });
}

function decodificarCursor(cursor?: string): CursorCategoria | undefined {
  if (!cursor) return undefined;
  try {
    const obj: unknown = JSON.parse(cursor);
    if (
      obj &&
      typeof obj === 'object' &&
      (obj as { t?: unknown }).t === 'category' &&
      'k' in obj &&
      'id' in obj
    ) {
      const o = obj as { k: number | string; id: string };
      return { k: o.k, id: o.id };
    }
  } catch {
    /* cursor inválido (versão antiga, por exemplo) — trata como 1ª página */
  }
  return undefined;
}

interface ConfigIndice {
  campo: '[listId+section+categoryId+recent+itemId]' | '[listId+section+categoryId+norm+itemId]' | '[listId+section+categoryId+rating+itemId]';
  chaveDe: (r: CategoryMember) => number | string;
  /** `desc` usa `.reverse()` (mais recente/maior nota primeiro); `asc` não. */
  direcao: 'asc' | 'desc';
  extremoBaixo: number | string;
  extremoAlto: number | string;
}

const INDICES: Record<'recent' | 'name' | 'rating', ConfigIndice> = {
  recent: {
    campo: '[listId+section+categoryId+recent+itemId]',
    chaveDe: (r) => r.recent,
    direcao: 'desc',
    extremoBaixo: -Infinity,
    extremoAlto: Infinity,
  },
  name: {
    campo: '[listId+section+categoryId+norm+itemId]',
    chaveDe: (r) => r.norm,
    direcao: 'asc',
    extremoBaixo: '',
    extremoAlto: '￿',
  },
  rating: {
    campo: '[listId+section+categoryId+rating+itemId]',
    chaveDe: (r) => r.rating,
    direcao: 'desc',
    extremoBaixo: -Infinity,
    extremoAlto: Infinity,
  },
};

/**
 * Pagina itens de uma categoria usando índice eficiente — nunca materializa a
 * categoria inteira, só o `limit` pedido (+1 sentinela para saber se há mais).
 * Retorna apenas IDs — o chamador busca os dados completos (`bulkGet` na
 * tabela principal), como já faz para a visão sem categoria.
 */
export async function paginateCategory(
  db: AuraDb,
  listId: string,
  section: 'vod' | 'series',
  categoryId: string,
  opts: PaginationOptions = {},
): Promise<PaginationResult> {
  const limit = opts.limit ?? 200;
  const sortKey = opts.sort === 'name' || opts.sort === 'rating' ? opts.sort : 'recent';
  const cfg = INDICES[sortKey];
  const cursor = decodificarCursor(opts.cursor);

  // Sem cursor: começa no extremo alto (desc) ou baixo (asc) da faixa.
  // Com cursor: continua estritamente depois do último item já entregue —
  // por isso o bound do lado do cursor é EXCLUSIVO (`false`).
  const chave = db.categoryMembers.where(cfg.campo);
  const desc = cfg.direcao === 'desc';
  let query;
  if (cursor && desc) {
    query = chave
      .between(
        [listId, section, categoryId, cfg.extremoBaixo, ''],
        [listId, section, categoryId, cursor.k, cursor.id],
        true,
        false,
      )
      .reverse();
  } else if (cursor) {
    query = chave.between(
      [listId, section, categoryId, cursor.k, cursor.id],
      [listId, section, categoryId, cfg.extremoAlto, '￿'],
      false,
      true,
    );
  } else if (desc) {
    query = chave
      .between(
        [listId, section, categoryId, cfg.extremoBaixo, ''],
        [listId, section, categoryId, cfg.extremoAlto, '￿'],
      )
      .reverse();
  } else {
    query = chave.between(
      [listId, section, categoryId, cfg.extremoBaixo, ''],
      [listId, section, categoryId, cfg.extremoAlto, '￿'],
    );
  }

  const rows: CategoryMember[] = await query.limit(limit + 1).toArray();
  const hasMore = rows.length > limit;
  const pagina = rows.slice(0, limit);
  const ultima = pagina.at(-1);
  const proximoCursor =
    hasMore && ultima ? codificarCursor({ k: cfg.chaveDe(ultima), id: ultima.itemId }) : undefined;

  return {
    items: pagina.map((r) => r.itemId),
    ...(proximoCursor ? { cursor: proximoCursor } : {}),
  };
}
