export interface PoolOptions {
  /** Consultado antes de iniciar cada item; `true` interrompe o processamento. */
  shouldStop?: () => boolean;
}

/**
 * Processa `items` com no máximo `limit` execuções simultâneas, preservando a ordem
 * dos resultados. Usado no sync de catálogo para não abrir mais que N conexões ao
 * painel de uma vez (D-14).
 */
export async function mapPool<T, R>(
  items: readonly T[],
  limit: number,
  fn: (item: T, index: number) => Promise<R>,
  opts: PoolOptions = {},
): Promise<R[]> {
  const results = new Array<R>(items.length);
  let next = 0;
  const width = Math.max(1, Math.min(limit, items.length));

  async function worker(): Promise<void> {
    while (next < items.length) {
      if (opts.shouldStop?.()) return;
      const i = next++;
      results[i] = await fn(items[i]!, i);
    }
  }

  await Promise.all(Array.from({ length: width }, worker));
  return results;
}
