export interface BalanceLoaderProps {
  /** Altura total; a largura sai daí. Em `em` para acompanhar o contexto. */
  size?: string;
  /** Duração de um ciclo completo do balanço. */
  duration?: string;
}

/**
 * Indicador de carregamento do app: duas formas que sobem e descem em
 * contratempo, num balanço contínuo — a leitura de "pesando" que dá nome ao
 * Aura 67, sem desenhar nada literal.
 *
 * Abstrato de propósito: numa TV, a 3 metros, formas simples e um movimento
 * amplo leem melhor do que um ícone detalhado.
 *
 * Sem `<img>` nem SVG: são duas divs e um `@keyframes` de `transform`/`opacity`
 * (ver base.css), o que mantém o custo dentro do que a constitution §8 permite
 * no hardware mínimo.
 */
export function BalanceLoader({
  size = '4.2em',
  duration = '1400ms',
}: Readonly<BalanceLoaderProps>) {
  const comum: React.CSSProperties = {
    // achatado e com canto arredondado: lê como uma palma, não como um ponto —
    // dois círculos viravam um "loading dots" qualquer
    width: '40%',
    height: '22%',
    borderRadius: '999px',
    background: 'var(--accent)',
    animationDuration: duration,
    animationIterationCount: 'infinite',
    // `ease-in-out` dá o vai-e-vem pendular; linear pareceria mecânico
    animationTimingFunction: 'cubic-bezier(0.45, 0, 0.55, 1)',
    willChange: 'transform, opacity',
  };

  return (
    <div
      aria-hidden
      data-balance
      style={{
        // a caixa é mais larga que alta para as duas formas terem folga vertical
        width: `calc(${size} * 1.7)`,
        height: size,
        margin: '0 auto',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}
    >
      <div style={{ ...comum, animationName: 'aura-balance-a' }} />
      <div style={{ ...comum, animationName: 'aura-balance-b' }} />
    </div>
  );
}
