import type { AuraDb } from './db.js';

export interface QuotaEstimate {
  usage: number;
  quota: number;
  ratio: number;
}

/**
 * Uso de armazenamento (RF-66). `null` quando a API não existe (webOS/Tizen antigos) —
 * nesse caso a poda LRU roda só pela contagem de linhas, sem sinal de pressão.
 */
export async function storageEstimate(): Promise<QuotaEstimate | null> {
  const nav = (globalThis as { navigator?: Navigator }).navigator;
  if (!nav?.storage?.estimate) return null;
  try {
    const { usage = 0, quota = 0 } = await nav.storage.estimate();
    return { usage, quota, ratio: quota > 0 ? usage / quota : 0 };
  } catch {
    return null;
  }
}

/**
 * Decisão explícita (spec 003 LG-022, 2026-09-14): "TV antiga" para fins de
 * corte de cache = motor sem `navigator.storage.estimate` — o mesmo sinal já
 * usado acima para desligar a poda por pressão de quota. Achado real (TV LG
 * física webOS ~4.5 e o Emulator oficial webOS TV 4.0, Chrome 53): sem essa
 * API, não dá para saber a cota disponível ANTES de sincronizar, então
 * `CatalogSync` usa isto para gravar um recorte do catálogo por categoria em
 * vez do catálogo inteiro (ver `CacheConfig.sync.maxItemsPerCategoryLowStorage`)
 * — só nesses aparelhos; motores modernos (Android, webOS 6+, Tizen novo)
 * seguem sincronizando o catálogo completo como sempre.
 *
 * Investigado (2026-09-17, spec 003 LG-RF-22) substituir este sinal por uma
 * leitura nativa via LS2 (`com.webos.service.pdm`/`storageaccess`) e descartado:
 * são APIs de disco de dispositivos USB/PDM (ou exclusivas do webOS OSE), não
 * expõem a cota do motor web sandboxed e exigem ACG que apps de terceiros não
 * recebem. Não há alternativa nativa confiável para webOS 4.0.
 */
export async function isLowStorageDevice(): Promise<boolean> {
  return (await storageEstimate()) === null;
}

/** Teto de saltos na cadeia `cause` — encerra em erro circular sem travar (LS-045A). */
const PROFUNDIDADE_MAXIMA_CAUSE = 8;

/**
 * `QuotaExceededError` pode chegar de formas diferentes dependendo do motor/
 * camada que aborta a transação (achado real: Dexie, numa TV LG física,
 * entregou um erro com `name: "AbortError"` e a causa real só no `message`,
 * em vez do `DOMException` padrão com `name: "QuotaExceededError"") —
 * checar as duas em vez de confiar só em `err.name`.
 *
 * LS-045A (spec 005): também segue a cadeia `cause` (`new Error('x', { cause:
 * quotaErrorOriginal })`) — um wrapper genérico (ex.: `HttpClient`/qualquer
 * `catch`+`throw new Error(...)` no caminho do recovery) some com o
 * `DOMException`/formato Dexie original se só o topo da cadeia for checado.
 * Teto de profundidade evita loop em cadeia circular ou anormalmente longa.
 */
export function isQuotaExceededError(err: unknown): boolean {
  let atual = err;
  for (let i = 0; i < PROFUNDIDADE_MAXIMA_CAUSE && atual != null; i++) {
    const e = atual as { name?: string; message?: string; cause?: unknown };
    const texto = `${e.name ?? ''} ${e.message ?? ''}`;
    if (/quotaexceedederror/i.test(texto)) return true;
    if (atual === e.cause) break; // cadeia circular — não gira para sempre
    atual = e.cause;
  }
  return false;
}

/**
 * Mantém no máximo `maxRows` linhas em `movieInfo` + `seriesInfo` (as mais recentes por
 * `cachedAt`), apagando as mais antigas. `get_vod_info`/`get_series_info` são caros de
 * buscar mas baratos de re-buscar sob demanda.
 */
export async function evictInfoLru(db: AuraDb, maxRows: number): Promise<number> {
  let removed = 0;
  for (const table of [db.movieInfo, db.seriesInfo]) {
    const total = await table.count();
    if (total <= maxRows) continue;
    const excess = total - maxRows;
    const oldest = await table.orderBy('cachedAt').limit(excess).primaryKeys();
    if (oldest.length) {
      await table.bulkDelete(oldest as never[]);
      removed += oldest.length;
    }
  }
  return removed;
}

/** Poda de programas de EPG vencidos (usada pelo sync de EPG — M8). */
export async function pruneOldProgrammes(
  db: AuraDb,
  listId: string,
  olderThan: number,
): Promise<number> {
  const stale = await db.epgProgrammes
    .where('[listId+stop]')
    .between([listId, 0], [listId, olderThan], true, false)
    .primaryKeys();
  if (stale.length) await db.epgProgrammes.bulkDelete(stale as never[]);
  return stale.length;
}

/**
 * Poda a geração anterior de EPG (PERF-02/03 / spec 002) — o `wipe()` prévio
 * ao `EpgSync` foi trocado por gravar a geração nova durante o parse e podar a
 * antiga só no fim, quando a nova terminou de escrever. Mesmo padrão de
 * `CatalogRepo.pruneSection`: `[listId+gen]` no lugar de `[listId+syncGen]`.
 */
export async function pruneOldEpgGeneration(
  db: AuraDb,
  listId: string,
  keepGen: number,
): Promise<number> {
  const stale = await db.epgProgrammes
    .where('[listId+gen]')
    .between([listId, 0], [listId, keepGen], true, false)
    .primaryKeys();
  if (stale.length) await db.epgProgrammes.bulkDelete(stale as never[]);
  return stale.length;
}
