/**
 * Normalização de texto para busca e casamento de EPG: sem acento, minúsculo,
 * espaços colapsados. Usada tanto para construir o índice de busca (RF-42) quanto
 * para casar `epg_channel_id` com o XMLTV (RF-15).
 */
export function normalizeText(s: string): string {
  return s
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // marcas de acento combinantes
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ') // pontuação vira espaço
    .replace(/\s+/g, ' ')
    .trim();
}

/** Divide um texto normalizado em tokens úteis (≥ 2 caracteres). */
export function tokenize(s: string): string[] {
  return normalizeText(s)
    .split(' ')
    .filter((t) => t.length >= 2);
}
