import { HttpClient, NotJsonError } from '../../http/HttpClient.js';
import type {
  Account,
  Category,
  Channel,
  EpgEntry,
  Movie,
  MovieDetail,
  Series,
  SeriesDetail,
  StreamKind,
} from '../../models/index.js';
import { bool, epochSecsToMs, firstStr, num, str } from '../../util/coerce.js';
import type { IptvProvider, RequestContext } from '../IptvProvider.js';

export type XtreamAuthReason = 'not_xtream' | 'bad_credentials' | 'banned' | 'expired';

export class XtreamAuthError extends Error {
  constructor(
    readonly reason: XtreamAuthReason,
    message: string,
  ) {
    super(message);
    this.name = 'XtreamAuthError';
  }
}

export interface XtreamCredentials {
  serverUrl: string; // http://host:porta (sem barra final)
  username: string;
  password: string;
  userAgent?: string;
  /**
   * Segmento do path de canal ao vivo: `live` na maioria dos painéis, `''` em
   * alguns (`/{user}/{pass}/{id}`). Não há campo no `server_info` que diga qual
   * é — medido no painel de teste, os dois funcionavam. Quem descobre é o
   * player, ao levar 404 no primeiro caminho, e grava o que funcionou na lista.
   */
  livePathSegment?: string;
  /**
   * Base HTTPS já validada numa autenticação anterior desta lista (persistida
   * como `StoredList.preferredHttpsBase`) — pula o probe de rede no boot
   * quando já sabemos a resposta.
   */
  knownHttpsBase?: string;
}

/** Implementa IptvProvider contra player_api.php de um painel Xtream Codes. */
export class XtreamProvider implements IptvProvider {
  private readonly base: string;
  private readonly livePathSegment: string;
  private httpsBase: string | null = null; // Cache de URL HTTPS validada
  /** `true` só quando ESTE boot fez o probe de verdade (não veio de cache). */
  private httpsBaseRecemAprendido = false;

  constructor(
    private readonly creds: XtreamCredentials,
    private readonly http: HttpClient = new HttpClient({ userAgent: creds.userAgent }),
  ) {
    this.base = creds.serverUrl.replace(/\/+$/, '');
    this.livePathSegment = creds.livePathSegment ?? 'live';
    // Já sabemos a resposta de um boot anterior (StoredList.preferredHttpsBase)
    // — pula o probe de rede, que só custa tempo sem aprender nada de novo.
    if (creds.knownHttpsBase) this.httpsBase = creds.knownHttpsBase;
  }

  /** Probe HTTPS: se passar, persiste como preferência (GTV-033/034). */
  private async preferHttpsUrl(): Promise<string> {
    // Já validou HTTPS nesta sessão (ou já sabíamos de um boot anterior)
    if (this.httpsBase) return this.httpsBase;

    // URL já é HTTPS
    if (this.base.startsWith('https')) {
      this.httpsBase = this.base;
      return this.httpsBase;
    }

    // Tenta HTTPS, com um teto BEM menor que o das chamadas de dados de
    // verdade: é só uma otimização oportunista, não pode competir com o
    // login em prioridade — uma conexão travada (comum logo após o rádio
    // Wi-Fi "acordar" de volta) não pode custar os 15s × 3 tentativas
    // padrão do HttpClient (~45s) só para essa checagem opcional.
    try {
      const httpsUrl = this.base.replace(/^http:/, 'https:');
      const testUrl =
        httpsUrl +
        '/player_api.php?action=get_live_categories&username=test&password=test';
      await this.http.resolveFinalUrl(testUrl, { timeoutMs: 4_000, retries: 0 });
      this.httpsBase = httpsUrl;
      this.httpsBaseRecemAprendido = true;
      return httpsUrl;
    } catch {
      // HTTPS não respondeu, fallback para HTTP — tenta de novo no próximo boot
      return this.base;
    }
  }

  /** Só preenchido em `Account` quando o probe rodou e aprendeu algo NOVO. */
  private httpsBaseParaPersistir(): string | undefined {
    return this.httpsBaseRecemAprendido && this.httpsBase ? this.httpsBase : undefined;
  }

  private api(params: Record<string, string>, baseOverride?: string): string {
    const base = baseOverride ?? this.base;
    const q = new URLSearchParams({
      username: this.creds.username,
      password: this.creds.password,
      ...params,
    });
    return `${base}/player_api.php?${q.toString()}`;
  }

  async authenticate(): Promise<Account> {
    // GTV-033: Prefere HTTPS quando disponível (probe silent)
    const baseUrl = await this.preferHttpsUrl();

    let data: any;
    try {
      data = await this.http.json<any>(this.api({}, baseUrl));
    } catch (err) {
      // Respondeu em HTML (erro do nginx com 200, portal cativo) ou com corpo
      // vazio: é servidor, mas não é painel Xtream. Rede e status ruim seguem
      // subindo como estão — quem decide autoconfiguração precisa distinguir
      // "não é painel" de "não respondeu" (D-16).
      if (err instanceof NotJsonError) {
        throw new XtreamAuthError(
          'not_xtream',
          'Servidor não respondeu como um painel Xtream',
        );
      }
      throw err;
    }
    const info = data?.user_info;
    const server = data?.server_info ?? {};

    // sem user_info não é um painel Xtream (ou é uma página de erro do servidor)
    if (!info || typeof info !== 'object') {
      throw new XtreamAuthError(
        'not_xtream',
        'Servidor não respondeu como um painel Xtream',
      );
    }
    // auth: 0 / "0" / false = credencial recusada
    if (info.auth !== undefined && !bool(info.auth)) {
      throw new XtreamAuthError('bad_credentials', 'Usuário ou senha inválidos');
    }
    if (str(info.status)?.toLowerCase() === 'banned') {
      throw new XtreamAuthError('banned', 'Esta conta está bloqueada pelo provedor');
    }

    return {
      serverUrl: this.base,
      username: str(info.username) ?? this.creds.username,
      status: str(info.status) ?? 'Unknown',
      expiresAt: epochSecsToMs(info.exp_date),
      maxConnections: num(info.max_connections) ?? 1,
      isTrial: bool(info.is_trial),
      serverTimezone: str(server.timezone),
      livePathSegment: this.livePathSegment,
      preferredHttpsBase: this.httpsBaseParaPersistir(),
    };
  }

  async getLiveCategories(): Promise<Category[]> {
    return this.categories('get_live_categories');
  }

  async getLiveChannels(categoryId?: string): Promise<Channel[]> {
    const rows = await this.http.json<any[]>(
      this.api({
        action: 'get_live_streams',
        ...(categoryId ? { category_id: categoryId } : {}),
      }),
    );
    return mapCatalogRows(rows, (r) => ({
      id: String(r.stream_id),
      name: str(r.name) ?? '',
      num: num(r.num),
      logo: str(r.stream_icon),
      categoryId: str(r.category_id),
      epgChannelId: str(r.epg_channel_id),
      containerExt: str(r.container_extension) ?? 'm3u8',
    }));
  }

  async getVodCategories(): Promise<Category[]> {
    return this.categories('get_vod_categories');
  }

  async getVodItems(categoryId?: string): Promise<Movie[]> {
    const rows = await this.http.json<any[]>(
      this.api({
        action: 'get_vod_streams',
        ...(categoryId ? { category_id: categoryId } : {}),
      }),
    );
    return mapCatalogRows(rows, (r) => ({
      id: String(r.stream_id),
      name: str(r.name) ?? '',
      poster: str(r.stream_icon) ?? str(r.cover),
      categoryId: str(r.category_id),
      categoryIds: categorias(r.category_id, r.category_ids),
      rating: num(r.rating),
      addedAt: epochSecsToMs(r.added) ?? undefined,
      containerExt: str(r.container_extension) ?? 'mp4',
    }));
  }

  async getVodInfo(id: string, ctx?: RequestContext): Promise<MovieDetail> {
    const data = await this.http.json<any>(
      this.api({ action: 'get_vod_info', vod_id: id }),
      ctx,
    );
    const i = data?.info ?? {};
    const m = data?.movie_data ?? {};
    return {
      id,
      name: str(m.name) ?? str(i.name) ?? '',
      poster: str(i.movie_image) ?? str(i.cover_big),
      backdrop: firstStr(i.backdrop_path),
      containerExt: str(m.container_extension) ?? 'mp4',
      plot: str(i.plot) ?? str(i.description),
      cast: str(i.cast),
      director: str(i.director),
      genre: str(i.genre),
      releaseDate: str(i.releasedate),
      durationSecs: num(i.duration_secs),
      tmdbId: str(i.tmdb_id),
      rating: num(i.rating),
    };
  }

  async getSeriesCategories(): Promise<Category[]> {
    return this.categories('get_series_categories');
  }

  async getSeriesList(categoryId?: string): Promise<Series[]> {
    const rows = await this.http.json<any[]>(
      this.api({
        action: 'get_series',
        ...(categoryId ? { category_id: categoryId } : {}),
      }),
    );
    return mapCatalogRows(rows, (r) => ({
      id: String(r.series_id),
      name: str(r.name) ?? '',
      poster: str(r.cover),
      categoryId: str(r.category_id),
      categoryIds: categorias(r.category_id, r.category_ids),
      rating: num(r.rating),
      lastModified: epochSecsToMs(r.last_modified) ?? undefined,
    }));
  }

  async getSeriesInfo(id: string, ctx?: RequestContext): Promise<SeriesDetail> {
    const data = await this.http.json<any>(
      this.api({ action: 'get_series_info', series_id: id }),
      ctx,
    );
    const i = data?.info ?? {};
    // `episodes` costuma ser um objeto { "1": [...], "2": [...] }, mas alguns painéis
    // devolvem um array. `seasons` (array separado) traz nome/capa/ordem das
    // temporadas — inclusive de temporadas sem episódios listados (validado contra
    // painel real: "Especiais"/season 0 aparece só ali).
    const rawEpisodes = data?.episodes ?? {};
    const episodesBySeason: Record<string, any[]> = Array.isArray(rawEpisodes)
      ? Object.fromEntries(
          rawEpisodes.map((list: any[]) => [
            String(list?.[0]?.season ?? list?.[0]?.season_num ?? 1),
            list ?? [],
          ]),
        )
      : rawEpisodes;

    const seasonMeta = new Map<number, { name?: string; poster?: string }>();
    for (const s of (data?.seasons ?? []) as any[]) {
      const n = num(s.season_number ?? s.season);
      if (n == null) continue;
      seasonMeta.set(n, { name: str(s.name), poster: str(s.cover_big ?? s.cover) });
    }

    const seasonNums = new Set<number>([
      ...Object.keys(episodesBySeason).map(Number),
      ...seasonMeta.keys(),
    ]);
    const seasons = [...seasonNums]
      .filter((n) => Number.isFinite(n))
      .sort((a, b) => a - b)
      .map((season) => {
        const meta = seasonMeta.get(season);
        return {
          season,
          ...(meta?.name ? { name: meta.name } : {}),
          ...(meta?.poster ? { poster: meta.poster } : {}),
          episodes: (episodesBySeason[String(season)] ?? []).map((e) => ({
            id: String(e.id),
            seriesId: id,
            season,
            episode: num(e.episode_num) ?? 0,
            title: str(e.title) ?? `Episódio ${num(e.episode_num) ?? '?'}`,
            plot: str(e.info?.plot),
            durationSecs: num(e.info?.duration_secs),
            containerExt: str(e.container_extension) ?? 'mp4',
          })),
        };
      })
      // só temporadas com episódios reproduzíveis (o painel às vezes lista
      // temporadas "fantasma" no array `seasons` sem nenhum episódio)
      .filter((s) => s.episodes.length > 0);
    return {
      id,
      name: str(i.name) ?? '',
      poster: str(i.cover),
      backdrop: firstStr(i.backdrop_path),
      plot: str(i.plot),
      cast: str(i.cast),
      genre: str(i.genre),
      rating: num(i.rating),
      seasons,
    };
  }

  async getShortEpg(channelId: string, limit = 8): Promise<EpgEntry[]> {
    const data = await this.http.json<any>(
      this.api({ action: 'get_short_epg', stream_id: channelId, limit: String(limit) }),
    );
    return ((data?.epg_listings ?? []) as any[]).map((e) => ({
      channelId,
      start: (num(e.start_timestamp) ?? 0) * 1000,
      stop: (num(e.stop_timestamp) ?? 0) * 1000,
      title: decodeBase64(str(e.title)) ?? '',
      description: decodeBase64(str(e.description)),
    }));
  }

  getFullEpgStream(): Promise<ReadableStream<Uint8Array>> {
    const q = new URLSearchParams({
      username: this.creds.username,
      password: this.creds.password,
    });
    return this.http.stream(`${this.base}/xmltv.php?${q.toString()}`, {
      timeoutMs: 60_000,
      userAgent: this.creds.userAgent,
    });
  }

  buildStreamUrl(kind: StreamKind, id: string, ext?: string): string {
    const { username: u, password: p } = this.creds;
    const seg =
      kind === 'live' ? this.livePathSegment : kind === 'movie' ? 'movie' : 'series';
    const container = ext ?? (kind === 'live' ? 'm3u8' : 'mp4');
    const path = seg ? `${seg}/` : '';
    return `${this.base}/${path}${encodeURIComponent(u)}/${encodeURIComponent(p)}/${id}.${container}`;
  }

  private async categories(action: string): Promise<Category[]> {
    const rows = await this.http.json<any[]>(this.api({ action }));
    return lista(rows).map((r) => ({
      id: String(r.category_id),
      name: str(r.category_name) ?? '',
      parentId: str(r.parent_id),
    }));
  }
}

/**
 * Painel Xtream manda `false` no lugar de lista vazia — e, em alguns, um objeto
 * de erro no lugar do array. Medido: sem esta guarda, `getLiveChannels()`
 * estourava `(rows ?? []).map is not a function` e a tela ficava em branco.
 */
function lista(x: unknown): any[] {
  return Array.isArray(x) ? x : [];
}

/** Dá tempo ao controle remoto/renderização entre lotes de categorias grandes. */
async function mapCatalogRows<T>(raw: unknown, map: (row: any) => T): Promise<T[]> {
  const rows = lista(raw);
  const result = new Array<T>(rows.length);
  const batchSize = 500;
  for (let start = 0; start < rows.length; start += batchSize) {
    if (start > 0) await new Promise<void>((resolve) => setTimeout(resolve, 0));
    const end = Math.min(start + batchSize, rows.length);
    for (let i = start; i < end; i++) result[i] = map(rows[i]);
  }
  return result;
}

/**
 * `category_ids` do painel — números ou strings, e às vezes ausente. Sempre
 * inclui a `category_id` "principal", que é a única que existia antes.
 */
function categorias(principal: unknown, todas: unknown): string[] {
  const ids = lista(todas).map(String);
  const p = principal === undefined || principal === null ? null : String(principal);
  if (p && !ids.includes(p)) ids.unshift(p);
  return ids;
}

const BASE64 = /^[A-Za-z0-9+/]+={0,2}$/;
// bytes de controle (exceto \t \n \r) indicam que o "base64" era texto puro
// eslint-disable-next-line no-control-regex
const CONTROL_CHARS = /[\x00-\x08\x0B\x0C\x0E-\x1F]/;

/**
 * `get_short_epg` devolve título/descrição em base64 na maioria dos painéis — mas não
 * em todos. Decodificar cego corrompe texto puro em silêncio ("Cine" é base64 válido),
 * então só aceitamos o resultado se ele for UTF-8 plausível.
 */
function decodeBase64(v: string | undefined): string | undefined {
  if (v === undefined) return undefined;
  const compact = v.replace(/\s/g, '');
  if (compact.length < 4 || compact.length % 4 !== 0 || !BASE64.test(v)) return v;
  try {
    const bin =
      typeof atob === 'function'
        ? atob(compact)
        : Buffer.from(compact, 'base64').toString('binary');
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    const out = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
    // rejeita se sobrou byte de controle — sinal de que era texto puro, não base64
    return CONTROL_CHARS.test(out) ? v : out;
  } catch {
    return v;
  }
}
