import {
  memo,
  type ReactNode,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import {
  FocusContext,
  setFocus,
  useFocusable,
} from '@noriginmedia/norigin-spatial-navigation';
import { useDragScroll } from './useDragScroll.js';
import { lembrarPosicao, posicaoLembrada } from '../nav/listMemory.js';

export interface VirtualRowProps<T> {
  items: T[];
  /** Identidade do conteúdo da trilha — ver `VirtualGrid`. */
  restoreKey?: string;
  /** Quantos cartões cabem na largura visível — tamanho vem do viewport medido. */
  visibleCount?: number;
  /**
   * Largura mínima de cada cartão. Quando dada, manda no lugar de
   * `visibleCount`: quantos couberem. Usada onde a trilha divide a tela com
   * outra coluna e a largura disponível varia muito.
   */
  minItemWidth?: number;
  /** Proporção altura/largura do cartão (default 3/2 = pôster). */
  aspectRatio?: number;
  /** Fixos (fallback quando `visibleCount` não é dado). */
  itemWidth?: number;
  itemHeight?: number;
  gap?: number;
  /** Fração da largura visível onde o item focado é ancorado (0..1). */
  anchor?: number;
  /** Itens extra renderizados antes/depois da janela visível. */
  overscan?: number;
  focusKey: string;
  renderItem: (item: T, index: number, focused: boolean) => ReactNode;
  onItemPress?: (item: T, index: number) => void;
  onItemFocus?: (item: T, index: number) => void;
}

/**
 * Trilha horizontal virtualizada com foco preservado (plan.md §Listas virtualizadas):
 * renderiza só a janela visível + overscan, move por `translate3d` (sem scroll suave,
 * constitution §8) e mantém o item focado numa âncora fixa. Cartões dimensionados
 * a partir do viewport medido (design-inventory §Responsividade).
 *
 * PERF-09/PERF-10 (spec 002): células memoizadas (`RowCell`) com handlers
 * estáveis; o arrasto escreve o `transform` direto no nó, sem passar pelo React
 * a cada quadro — ver o mesmo desenho em `VirtualGrid`.
 */
export function VirtualRow<T>({
  items,
  restoreKey,
  visibleCount,
  minItemWidth,
  aspectRatio = 1.5,
  itemWidth: fixedW,
  itemHeight: fixedH,
  gap = 16,
  anchor = 1 / 3,
  overscan = 4,
  focusKey,
  renderItem,
  onItemPress,
  onItemFocus,
}: VirtualRowProps<T>) {
  const [focusedIndex, setFocusedIndex] = useState(
    () => posicaoLembrada(restoreKey) ?? 0,
  );
  const [viewportWidth, setViewportWidth] = useState(1200);

  // conteúdo novo começa na posição dele — ver `VirtualGrid`
  const [chaveAnterior, setChaveAnterior] = useState(restoreKey);
  if (chaveAnterior !== restoreKey) {
    setChaveAnterior(restoreKey);
    setFocusedIndex(posicaoLembrada(restoreKey) ?? 0);
  }

  const { ref, focusKey: fk } = useFocusable({
    focusKey,
    trackChildren: true,
    saveLastFocusedChild: true,
  });

  useEffect(() => {
    const node = ref.current as HTMLDivElement | null;
    if (!node) return;
    const measure = () => setViewportWidth(node.clientWidth || 1200);
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(measure);
    ro.observe(node);
    return () => ro.disconnect();
  }, [ref]);

  const cabem = minItemWidth
    ? Math.max(2, Math.floor((viewportWidth + gap) / (minItemWidth + gap)))
    : (visibleCount ?? 6);
  const itemWidth = fixedW ?? Math.floor((viewportWidth - gap * (cabem - 1)) / cabem);
  const itemHeight = fixedH ?? Math.round(itemWidth * aspectRatio);
  const stride = itemWidth + gap;

  const maxOffset = Math.max(0, items.length * stride - viewportWidth);
  const offsetDoFoco = Math.max(
    0,
    Math.min(focusedIndex * stride - anchor * viewportWidth, maxOffset),
  );

  const offsetExibido = useRef(offsetDoFoco);
  const conteudoRef = useRef<HTMLDivElement>(null);

  const calcularJanela = useCallback(
    (off: number) => ({
      start: Math.max(0, Math.floor(off / stride) - overscan),
      end: Math.min(items.length, Math.ceil((off + viewportWidth) / stride) + overscan),
    }),
    [stride, overscan, items.length, viewportWidth],
  );
  // Janela do foco: pura, sem `useState` — ver o mesmo desenho em `VirtualGrid`.
  const janelaFoco = calcularJanela(offsetDoFoco);
  // Janela do arrasto: só o próprio arrasto escreve nela, nunca um efeito.
  const [janelaArrasto, setJanelaArrasto] = useState(janelaFoco);

  const aplicarOffsetDoArrasto = useCallback(
    (off: number) => {
      offsetExibido.current = off;
      const node = conteudoRef.current;
      if (node) node.style.transform = `translate3d(${-off}px, 0, 0)`;
      setJanelaArrasto((atual) => {
        const nova = calcularJanela(off);
        return nova.start === atual.start && nova.end === atual.end ? atual : nova;
      });
    },
    [calcularJanela],
  );

  const adotarPosicaoRef = useRef<(fim: number) => void>(() => {});
  // arrasto horizontal do dedo; fora dele a janela segue o item focado — a
  // adoção de posição e o motivo do `setFocusedIndex` direto seguem a mesma
  // lógica do `VirtualGrid`
  const arrasto = useDragScroll(
    ref as { current: HTMLElement | null },
    'x',
    maxOffset,
    () => offsetExibido.current,
    (fim) => adotarPosicaoRef.current(fim),
  );

  useEffect(() => {
    adotarPosicaoRef.current = (fim: number) => {
      const bruto = Math.round((fim + anchor * viewportWidth) / stride);
      const idx = Math.max(0, Math.min(bruto, items.length - 1));
      setFocusedIndex(idx);
      void setFocus(`${focusKey}-${idx}`);
    };
  });

  // Escreve o transform fora do `style` declarativo — ver `VirtualGrid`. Só
  // toca o DOM (sem `setState`), então não é um setState síncrono em efeito.
  useLayoutEffect(() => {
    if (arrasto.ativo()) return;
    offsetExibido.current = offsetDoFoco;
    const node = conteudoRef.current;
    if (node) node.style.transform = `translate3d(${-offsetDoFoco}px, 0, 0)`;
  });

  useLayoutEffect(
    () =>
      arrasto.assinar((off) => (off !== null ? aplicarOffsetDoArrasto(off) : undefined)),
    [arrasto, aplicarOffsetDoArrasto],
  );

  const janela = arrasto.ativo() ? janelaArrasto : janelaFoco;

  const handleFocus = useCallback(
    (index: number) => {
      if (!arrasto.ativo()) arrasto.soltar(); // ver `VirtualGrid`
      setFocusedIndex(index);
      if (restoreKey) lembrarPosicao(restoreKey, index);
      const item = items[index];
      if (item !== undefined) onItemFocus?.(item, index);
    },
    [items, onItemFocus, arrasto, restoreKey],
  );

  const handlePress = useCallback(
    (index: number) => {
      if (arrasto.arrastou()) return; // clique sintético do fim do arrasto
      // o toque também leva o foco para o item, senão o anel fica para trás
      setFocus(`${focusKey}-${index}`);
      const item = items[index];
      if (item !== undefined) onItemPress?.(item, index);
    },
    [arrasto, focusKey, items, onItemPress],
  );

  const visible = useMemo(() => {
    const out: { item: T; index: number }[] = [];
    for (let i = janela.start; i < janela.end; i++) {
      const item = items[i];
      if (item !== undefined) out.push({ item, index: i });
    }
    return out;
  }, [items, janela]);

  return (
    <FocusContext.Provider value={fk}>
      <div
        ref={ref}
        style={{
          overflow: 'hidden',
          width: '100%',
          height: itemHeight,
          // só o eixo horizontal é nosso: o gesto vertical continua rolando a página
          touchAction: 'pan-y',
        }}
      >
        <div
          ref={conteudoRef}
          // `transform` fora deste objeto de propósito — ver `VirtualGrid`.
          // Salto direto, sem `transition`: a constitution §8 veta animação
          // custosa no hardware mínimo (webOS 4 / Tizen 4 / Android TV 8) — animar
          // o transform de uma camada de ~146.000px a cada tecla é esse custo.
          style={{
            position: 'relative',
            height: '100%',
            width: items.length * stride,
          }}
        >
          {visible.map(({ item, index }) => (
            <RowCell
              key={`${focusKey}-${index}`}
              focusKeyPrefix={focusKey}
              index={index}
              item={item}
              renderItem={renderItem}
              onFocusIndex={handleFocus}
              onPressIndex={handlePress}
              left={index * stride}
              width={itemWidth}
              height={itemHeight}
            />
          ))}
        </div>
      </div>
    </FocusContext.Provider>
  );
}

interface RowCellProps<T> {
  focusKeyPrefix: string;
  index: number;
  item: T;
  renderItem: (item: T, index: number, focused: boolean) => ReactNode;
  onFocusIndex: (index: number) => void;
  onPressIndex: (index: number) => void;
  left: number;
  width: number;
  height: number;
}

/** Célula memoizada (PERF-09) — ver `GridCell` em `VirtualGrid.tsx`. */
function RowCellInner<T>({
  focusKeyPrefix,
  index,
  item,
  renderItem,
  onFocusIndex,
  onPressIndex,
  left,
  width,
  height,
}: RowCellProps<T>) {
  const focusKey = `${focusKeyPrefix}-${index}`;
  const onFocus = useCallback(() => onFocusIndex(index), [onFocusIndex, index]);
  const onEnterPress = useCallback(() => onPressIndex(index), [onPressIndex, index]);
  const { ref, focused } = useFocusable({ focusKey, onFocus, onEnterPress });
  return (
    <div
      ref={ref}
      onClick={onEnterPress}
      style={{
        position: 'absolute',
        left,
        top: 0,
        width,
        height,
        cursor: 'pointer',
      }}
    >
      {renderItem(item, index, focused)}
    </div>
  );
}
const RowCell = memo(RowCellInner) as typeof RowCellInner;
