import { useEffect, useRef } from 'react';
import type { StoredList } from '@mfp/core';
import { LoadingState } from '../components/states.js';
import { SyncProgress } from '../components/SyncProgress.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useLists } from '../state/lists.js';
import { useSession } from '../state/session.js';
import { useSync } from '../state/sync.js';
import { useEpg } from '../state/epg.js';
import { t } from '../i18n/index.js';

/**
 * Splash de boot (RF-55): autentica a lista ativa, dispara o sync inicial e mostra
 * o progresso. Chama `onReady` quando o app pode abrir a Home; `onExpired` se a
 * conta venceu (RF-54).
 */
export function Boot({
  list,
  onReady,
  onExpired,
  onCredencialNecessaria,
  onServidorInacessivel,
}: {
  list: StoredList;
  onReady: () => void;
  onExpired: () => void;
  /**
   * O secure storage não tem a senha desta lista — sem relação com a conta
   * ter vencido (spec 003 LG-RF-24/LG-050). Acontece de verdade em plataforma
   * sem armazenamento protegido aprovado (webOS 4–23: senha só em memória,
   * some a cada encerramento real do app), e mais raramente se o keystore for
   * limpo por fora do app. Antes disto caía em `onExpired`, o que mandava o
   * usuário "trocar de lista" quando na verdade só precisava redigitar a
   * mesma senha — ver `CredentialRequired.tsx`.
   */
  onCredencialNecessaria: () => void;
  /**
   * O servidor não respondeu — caso em que um espelho pode resolver (D-16).
   * Só dispara em falha de rede/servidor: senha errada, conta banida ou vencida
   * não melhoram trocando de endereço, e tentar dezenas de espelhos exporia a
   * credencial à toa.
   */
  onServidorInacessivel: () => void;
}) {
  const rt = useRuntime();
  const getPassword = useLists((s) => s.getPassword);
  const authenticate = useSession((s) => s.authenticate);
  const runSync = useSync((s) => s.run);
  // Seletores estreitos (PERF-11): o store inteiro (`useSync()`) muda a cada
  // seção baixada no sync inicial (D-24), centenas de vezes — só pegar os três
  // campos usados aqui evita recriar `sync` (o objeto todo) como dependência
  // implícita a cada leitura, embora `sections` em si já mude com a frequência
  // real do progresso (isso não tem como evitar: é trabalho de verdade).
  const phase = useSync((s) => s.phase);
  const sections = useSync((s) => s.sections);
  const firstRun = useSync((s) => s.firstRun);
  const started = useRef(false);

  useEffect(() => {
    if (started.current) return;
    started.current = true;

    void (async () => {
      useSession.getState().reset();
      const password = await getPassword(rt, list.id);
      if (!password) {
        onCredencialNecessaria();
        return;
      }
      await authenticate(rt, list, password);
      const status = useSession.getState().status;
      if (status === 'expired') {
        onExpired();
        return;
      }
      if (status === 'error') {
        const codigo = useSession.getState().error?.code ?? '';
        // NET-* (rede), SRV-* (servidor fora ou não é painel Xtream) → espelho
        // pode resolver. AUTH-* não: é a conta, não o endereço.
        if (codigo.startsWith('NET-') || codigo.startsWith('SRV-')) {
          onServidorInacessivel();
          return;
        }
        // demais falhas: abre mesmo assim, a Home serve o cache
        onReady();
        return;
      }
      const provider = rt.makeProvider(list, password);
      const dispararEpg = () => {
        // EPG entra em segundo plano — o boot não espera por 9 MB de XMLTV (D-22)
        const tz = useSession.getState().account?.serverTimezone;
        void useEpg.getState().run(rt, list.id, provider, tz);
      };

      // Já existe catálogo em cache: abre a Home na hora com o que tem e
      // atualiza em segundo plano. Sem isso, um cache vencido pelo TTL (RF-65:
      // live 6h, vod/série 24h) travava o boot inteiro numa lista grande
      // esperando o resync completo — mesmo já tendo dado pra abrir com o
      // conteúdo salvo. Só sem cache nenhum (1º uso) é que faz sentido esperar.
      const temCacheExistente = !(await rt.makeSync(list.id, provider).isEmpty());
      if (temCacheExistente) {
        onReady();
        void runSync(rt, list.id, provider).then(dispararEpg);
        return;
      }

      // LS-032A: sem cache nenhum, o sync completo abaixo pode nunca chegar a
      // `series` (por vir por último em `ALL_SECTIONS`) se `vod` estourar a
      // cota no meio — gap real em dispositivos de baixo storage (spec 005).
      // Aquece no máximo 1 categoria de vod + 1 de série ANTES, com
      // instância própria (evita competir por `syncGen`/gravação com o
      // `runSync` de baixo) — é rápido (no máximo duas categorias pequenas) e
      // não atrasa a Home além do que o primeiro boot já esperava (a linha
      // logo abaixo já bloqueia em cima do sync completo).
      await rt.makeSync(list.id, provider).warmPriorityCategories();
      await runSync(rt, list.id, provider);
      dispararEpg();
      onReady();
    })();
  }, [
    rt,
    list,
    getPassword,
    authenticate,
    runSync,
    onReady,
    onExpired,
    onCredencialNecessaria,
    onServidorInacessivel,
  ]);

  // Durante o sync: uma barra por seção (D-24). Antes/depois: só o balanço.
  if (phase === 'running') {
    return <SyncProgress sections={sections} firstRun={firstRun} />;
  }

  return <LoadingState label={t('boot.starting')} />;
}
