// Impl de VideoPlayer para o navegador (apps/dev APENAS — constitution §4).
// hls.js para .m3u8, mpegts.js para .ts, <video> nativo para progressivo/HLS Safari.
// Recuperação barata in-place do engine ANTES do PlaybackController reiniciar a
// sessão (playback-design.md §0.1): recoverMediaError / startLoad.

import Hls from 'hls.js';
import mpegts from 'mpegts.js';
import type {
  LoadOptions,
  PlayerError,
  Track,
  VideoFit,
  VideoPlayer,
} from '@mfp/core';

type Listeners = {
  ready: Set<() => void>;
  playing: Set<() => void>;
  paused: Set<() => void>;
  buffering: Set<() => void>;
  ended: Set<() => void>;
  error: Set<(e: PlayerError) => void>;
  positionchanged: Set<(secs: number) => void>;
};

export function createWebVideoPlayer(mount: HTMLElement): VideoPlayer {
  const video = document.createElement('video');
  video.style.width = '100%';
  video.style.height = '100%';
  video.style.background = '#000'; // backdrop das barras de letterbox (só no dev)
  video.playsInline = true;
  video.controls = false;
  mount.appendChild(video);

  const L: Listeners = {
    ready: new Set(),
    playing: new Set(),
    paused: new Set(),
    buffering: new Set(),
    ended: new Set(),
    error: new Set(),
    positionchanged: new Set(),
  };
  const fire = <K extends keyof Listeners>(k: K, ...a: unknown[]) =>
    L[k].forEach((cb) => (cb as (...x: unknown[]) => void)(...a));

  let hls: Hls | null = null;
  let ts: mpegts.Player | null = null;
  let kind: 'live' | 'vod' = 'live';
  let fit: VideoFit = 'original';
  let posTimer: number | null = null;

  // Formato de exibição (D-21). No dev é só CSS: `object-fit` para
  // original/preencher, e dimensionar o elemento para a caixa nas razões fixas.
  const applyFit = () => {
    const box = mount.getBoundingClientRect();
    video.style.position = 'absolute';
    if (fit === 'original' || fit === 'fill') {
      video.style.inset = '0';
      video.style.width = '100%';
      video.style.height = '100%';
      video.style.objectFit = fit === 'fill' ? 'cover' : 'contain';
      return;
    }
    const a = fit === '16:9' ? 16 / 9 : 4 / 3;
    let w: number;
    let h: number;
    if (box.width / box.height > a) {
      h = box.height;
      w = h * a;
    } else {
      w = box.width;
      h = w / a;
    }
    video.style.inset = 'auto';
    video.style.width = `${w}px`;
    video.style.height = `${h}px`;
    video.style.left = `${(box.width - w) / 2}px`;
    video.style.top = `${(box.height - h) / 2}px`;
    video.style.objectFit = 'cover';
  };
  let mediaErrorRecoveries = 0;

  const emitErr = (code: PlayerError['code'], httpStatus?: number, detail?: string) =>
    fire('error', { code, httpStatus, detail } as PlayerError);

  const teardownEngines = () => {
    if (hls) {
      hls.destroy();
      hls = null;
    }
    if (ts) {
      ts.destroy();
      ts = null;
    }
    mediaErrorRecoveries = 0;
  };

  video.addEventListener('playing', () => fire('playing'));
  video.addEventListener('pause', () => fire('paused'));
  video.addEventListener('ended', () => fire('ended'));
  video.addEventListener('waiting', () => fire('buffering'));
  video.addEventListener('canplay', () => fire('ready'));
  video.addEventListener('error', () =>
    emitErr('DECODE', undefined, 'video element error'),
  );

  const httpCode = (status?: number): PlayerError['code'] => {
    if (status === 401) return 'HTTP_401';
    if (status === 403) return 'HTTP_403';
    if (status === 404) return 'HTTP_404';
    if (status && status >= 500) return 'HTTP_5XX';
    return 'NET_DROPPED';
  };

  return {
    async load(url: string, opts: LoadOptions): Promise<void> {
      this.stop();
      kind = opts.kind;
      const isHls = /\.m3u8(\?|$)/i.test(url) || url.includes('m3u8');
      const isTs = /\.ts(\?|$)/i.test(url);

      if (isHls && Hls.isSupported()) {
        hls = new Hls({
          lowLatencyMode: false,
          backBufferLength: opts.buffer.backBufferSecs,
          maxBufferLength: opts.buffer.targetSecs,
          maxMaxBufferLength: opts.buffer.targetSecs * 1.5,
          liveSyncDurationCount: opts.buffer.liveEdgeSegments ?? 3,
          xhrSetup: (xhr) => {
            // UA de request é read-only no browser; no nativo (ExoPlayer/AVPlay) o
            // override real acontece na camada da TV.
            void xhr;
          },
        });
        // PERF-26 (spec 002): teto de resolução — no dev, cap pelo nível de HLS
        // após o manifesto. No nativo é `trackSelectionParameters` do ExoPlayer.
        const maxH = opts.buffer.maxVideoHeight ?? 0;
        if (maxH > 0) {
          hls.on(Hls.Events.MANIFEST_PARSED, (_e, data) => {
            let cap = -1;
            let melhorH = 0;
            data.levels.forEach((lvl, i) => {
              const h = lvl.height ?? 0;
              if (h > 0 && h <= maxH && h > melhorH) {
                melhorH = h;
                cap = i;
              }
            });
            if (cap >= 0 && hls) hls.autoLevelCapping = cap;
          });
        }
        hls.on(Hls.Events.ERROR, (_e, data) => {
          if (!data.fatal) return;
          if (data.type === Hls.ErrorTypes.MEDIA_ERROR && mediaErrorRecoveries < 2) {
            mediaErrorRecoveries++;
            hls?.recoverMediaError();
            return;
          }
          if (data.type === Hls.ErrorTypes.NETWORK_ERROR) {
            const status = data.response?.code;
            if (status && [401, 403, 404].includes(status)) {
              emitErr(httpCode(status), status);
              return;
            }
            // tenta retomar o load in-place uma vez
            hls?.startLoad();
            emitErr(httpCode(status), status ?? undefined);
            return;
          }
          emitErr('SRC_PARSE', undefined, data.details);
        });
        hls.loadSource(url);
        hls.attachMedia(video);
      } else if (isTs && mpegts.isSupported()) {
        ts = mpegts.createPlayer(
          { type: 'mpegts', isLive: opts.kind === 'live', url },
          {
            liveBufferLatencyChasing: opts.kind === 'live',
            stashInitialSize: 384 * 1024,
          },
        );
        ts.on(mpegts.Events.ERROR, (type: string, detail: string) => {
          emitErr(
            type === mpegts.ErrorTypes.NETWORK_ERROR ? 'NET_DROPPED' : 'SRC_PARSE',
            undefined,
            detail,
          );
        });
        ts.attachMediaElement(video);
        ts.load();
      } else {
        // HLS nativo (Safari) ou progressivo
        video.src = url;
      }

      if (opts.startAtSecs && opts.kind === 'vod') {
        video.currentTime = opts.startAtSecs;
      }

      applyFit();

      if (posTimer) window.clearInterval(posTimer);
      posTimer = window.setInterval(
        () => fire('positionchanged', video.currentTime),
        1000,
      );
    },

    play() {
      void video.play().catch(() => {
        /* autoplay pode ser bloqueado no dev; a UI mostra "toque para tocar" */
      });
    },
    pause() {
      video.pause();
    },
    stop() {
      video.pause();
      teardownEngines();
      video.removeAttribute('src');
      video.load();
      if (posTimer) {
        window.clearInterval(posTimer);
        posTimer = null;
      }
    },
    seek(seconds: number) {
      if (kind === 'live' && hls) {
        // "borda ao vivo": seconds normalmente vem como duration (Infinity/0) → vai pro fim
        video.currentTime = video.seekable.length
          ? video.seekable.end(video.seekable.length - 1)
          : seconds;
      } else {
        video.currentTime = seconds;
      }
    },
    getPositionSecs: () => video.currentTime || 0,
    getDurationSecs: () =>
      kind === 'live' || !isFinite(video.duration) ? 0 : video.duration,
    isBuffering: () => video.readyState < 3,

    getAudioTracks(): Track[] {
      if (hls) {
        return hls.audioTracks.map((t, i) => ({
          id: String(t.id ?? i),
          label: t.name || t.lang || `Faixa ${i + 1}`,
          language: t.lang,
        }));
      }
      return [];
    },
    setAudioTrack(id: string) {
      if (hls) hls.audioTrack = Number(id);
    },
    getTextTracks(): Track[] {
      if (hls) {
        return hls.subtitleTracks.map((t, i) => ({
          id: String(t.id ?? i),
          label: t.name || t.lang || `Legenda ${i + 1}`,
          language: t.lang,
        }));
      }
      return [];
    },
    setTextTrack(id: string | null) {
      if (hls) hls.subtitleTrack = id == null ? -1 : Number(id);
    },
    setVideoFit(mode: VideoFit) {
      fit = mode;
      applyFit();
    },

    on(event: string, cb: (arg: never) => void): () => void {
      const set = L[event as keyof Listeners] as Set<unknown>;
      set.add(cb);
      return () => set.delete(cb);
    },

    destroy() {
      this.stop();
      video.remove();
      (Object.keys(L) as (keyof Listeners)[]).forEach((k) => L[k].clear());
    },
  } as VideoPlayer;
}
