import { create } from 'zustand';
import type { Account, StoredList } from '@mfp/core';
import { ACTIVE_LIST_KEY, passwordKey, type Runtime } from '../runtime/runtime.js';

// Múltiplas listas Xtream + troca (RF-53, constitution §9). Metadados (sem senha)
// no Dexie `lists`; a senha só no secure storage da plataforma.

export interface AddListInput {
  name?: string;
  serverUrl: string;
  username: string;
  password: string;
  userAgent?: string;
}

interface ListsState {
  lists: StoredList[];
  activeListId: string | null;
  loaded: boolean;
  load: (rt: Runtime) => Promise<void>;
  /** Autentica antes de persistir; devolve a Account em caso de sucesso. */
  addList: (rt: Runtime, input: AddListInput) => Promise<Account>;
  /**
   * Troca servidor/usuário/senha de uma lista já cadastrada (RF-49). Autentica
   * com os dados novos **antes** de gravar; a senha vai só para o secure
   * storage. O cache do catálogo é apagado — outra conta/servidor pode ter
   * outro acervo — e o próximo boot refaz o sync.
   */
  editList: (rt: Runtime, listId: string, input: AddListInput) => Promise<Account>;
  setActive: (rt: Runtime, listId: string) => Promise<void>;
  /**
   * Grava o segmento de path que de fato funcionou para canal ao vivo nesta
   * lista (`live` ou vazio). Descoberto pelo player ao levar 404 no primeiro
   * caminho — não há campo no `server_info` que informe isso.
   */
  definirSegmentoLive: (rt: Runtime, listId: string, segmento: string) => Promise<void>;
  /**
   * Grava a base HTTPS validada para esta lista (GTV-033/034), aprendida no
   * probe do boot — evita refazer essa checagem de rede em todo boot futuro.
   */
  definirHttpsBase: (rt: Runtime, listId: string, base: string) => Promise<void>;
  removeList: (rt: Runtime, listId: string) => Promise<void>;
  /**
   * Troca só o endereço do servidor, mantendo usuário, senha e todo o cache.
   * Usado pela autoconfiguração quando um espelho assume o lugar do domínio que
   * caiu (decisions D-16) — é a mesma conta no mesmo provedor.
   */
  trocarServidor: (rt: Runtime, listId: string, serverUrl: string) => Promise<void>;
  getPassword: (rt: Runtime, listId: string) => Promise<string | null>;
  /**
   * "Credencial necessária" (spec 003 LG-RF-24/LG-050): o secure storage não
   * tem a senha desta lista — não porque a conta expirou, mas porque a
   * plataforma não a persiste (webOS 4–23 sem Keymanager3: senha só em
   * memória, apagada a cada relaunch de verdade) ou porque o keystore foi
   * limpo por fora do app. Autentica com a senha redigitada e, se bater,
   * grava de volta no secure storage — mesmo contrato em toda plataforma, sem
   * `if (webos)` na UI.
   */
  reentrarComSenha: (rt: Runtime, listId: string, senha: string) => Promise<Account>;
}

export const useLists = create<ListsState>((set, get) => ({
  lists: [],
  activeListId: null,
  loaded: false,

  load: async (rt) => {
    const lists = await rt.db.lists.orderBy('addedAt').toArray();
    const active = await rt.adapter.secureStorage.get(ACTIVE_LIST_KEY);
    const activeListId =
      active && lists.some((l) => l.id === active) ? active : (lists[0]?.id ?? null);
    set({ lists, activeListId, loaded: true });
  },

  addList: async (rt, input) => {
    const id = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
    const serverUrl = input.serverUrl.replace(/\/+$/, '');

    // valida credenciais antes de gravar qualquer coisa
    const provider = rt.makeProvider(
      { serverUrl, username: input.username, userAgent: input.userAgent },
      input.password,
    );
    const account = await provider.authenticate();

    const list: StoredList = {
      id,
      name: input.name?.trim() || hostOf(serverUrl),
      serverUrl,
      username: input.username,
      userAgent: input.userAgent,
      livePathSegment: account.livePathSegment,
      preferredHttpsBase: account.preferredHttpsBase,
      addedAt: Date.now(),
    };

    await rt.adapter.secureStorage.set(passwordKey(id), input.password);
    await rt.db.lists.put(list);
    await rt.adapter.secureStorage.set(ACTIVE_LIST_KEY, id);

    set((s) => ({ lists: [...s.lists, list], activeListId: id }));
    return account;
  },

  editList: async (rt, listId, input) => {
    const anterior = get().lists.find((l) => l.id === listId);
    if (!anterior) throw new Error('lista não encontrada');
    const serverUrl = input.serverUrl.replace(/\/+$/, '');

    // valida antes de tocar em qualquer coisa — se falhar, nada muda
    const provider = rt.makeProvider(
      { serverUrl, username: input.username, userAgent: input.userAgent },
      input.password,
    );
    const account = await provider.authenticate();

    const atualizada: StoredList = {
      ...anterior,
      name: input.name?.trim() || hostOf(serverUrl),
      serverUrl,
      username: input.username,
      userAgent: input.userAgent,
      livePathSegment: account.livePathSegment,
      // só reaproveita a base HTTPS antiga se o servidor não mudou — outro
      // endereço invalida qualquer coisa aprendida sobre o anterior.
      preferredHttpsBase:
        account.preferredHttpsBase ??
        (serverUrl === anterior.serverUrl ? anterior.preferredHttpsBase : undefined),
    };

    // Só apaga o cache se servidor OU usuário mudou — aí o acervo pode ser
    // outro. Corrigir só a senha (o caso mais comum) mantém o catálogo: é a
    // mesma conta no mesmo servidor. A chave do `ActiveList` no `App` também
    // inclui servidor+usuário, então uma mudança nesses dois remonta e
    // ressincroniza; senão, nada além da senha muda.
    const acervoMudou =
      serverUrl !== anterior.serverUrl || input.username !== anterior.username;
    if (acervoMudou) {
      await rt.db.wipeList(listId);
      rt.invalidateCatalog(listId);
    }
    await rt.adapter.secureStorage.set(passwordKey(listId), input.password);
    await rt.db.lists.put(atualizada);

    set((s) => ({
      lists: s.lists.map((l) => (l.id === listId ? atualizada : l)),
    }));
    return account;
  },

  trocarServidor: async (rt, listId, serverUrl) => {
    const limpa = serverUrl.replace(/\/+$/, '');
    // outro endereço invalida a base HTTPS aprendida para o anterior.
    await rt.db.lists.update(listId, { serverUrl: limpa, preferredHttpsBase: undefined });
    set({
      lists: get().lists.map((l) =>
        l.id === listId ? { ...l, serverUrl: limpa, preferredHttpsBase: undefined } : l,
      ),
    });
  },

  definirSegmentoLive: async (rt, listId, segmento) => {
    await rt.db.lists.update(listId, { livePathSegment: segmento });
    set({
      lists: get().lists.map((l) =>
        l.id === listId ? { ...l, livePathSegment: segmento } : l,
      ),
    });
  },

  definirHttpsBase: async (rt, listId, base) => {
    await rt.db.lists.update(listId, { preferredHttpsBase: base });
    set({
      lists: get().lists.map((l) =>
        l.id === listId ? { ...l, preferredHttpsBase: base } : l,
      ),
    });
  },

  setActive: async (rt, listId) => {
    await rt.adapter.secureStorage.set(ACTIVE_LIST_KEY, listId);
    set({ activeListId: listId });
  },

  removeList: async (rt, listId) => {
    await rt.db.wipeList(listId);
    rt.invalidateCatalog(listId);
    await rt.db.lists.delete(listId);
    await rt.adapter.secureStorage.delete(passwordKey(listId));
    const remaining = get().lists.filter((l) => l.id !== listId);
    const nextActive =
      get().activeListId === listId ? (remaining[0]?.id ?? null) : get().activeListId;
    if (nextActive) await rt.adapter.secureStorage.set(ACTIVE_LIST_KEY, nextActive);
    else await rt.adapter.secureStorage.delete(ACTIVE_LIST_KEY);
    set({ lists: remaining, activeListId: nextActive });
  },

  getPassword: (rt, listId) => rt.adapter.secureStorage.get(passwordKey(listId)),

  reentrarComSenha: async (rt, listId, senha) => {
    const lista = get().lists.find((l) => l.id === listId);
    if (!lista) throw new Error('lista não encontrada');

    // autentica ANTES de gravar — senha errada não pode substituir a
    // ausente no secure storage (mesma cautela de addList/editList).
    const provider = rt.makeProvider(lista, senha);
    const account = await provider.authenticate();

    await rt.adapter.secureStorage.set(passwordKey(listId), senha);

    // mesma lógica de session.ts: só persiste se aprendeu algo NOVO agora.
    if (
      account.preferredHttpsBase &&
      account.preferredHttpsBase !== lista.preferredHttpsBase
    ) {
      await get().definirHttpsBase(rt, listId, account.preferredHttpsBase);
    }

    return account;
  },
}));

function hostOf(url: string): string {
  const m = /^https?:\/\/([^/:]+)/i.exec(url);
  return m?.[1] ?? url;
}
