import type { Channel, Movie, Series } from '../models/index.js';
import { isAdultCategoryName } from '../util/adultContent.js';
import { normalizeText } from '../util/normalize.js';
import type { CatalogPolicy } from './catalogRepo.js';
import type { AuraDb, CatalogSection, SearchRow } from './db.js';
import { MetaRepo } from './metaRepo.js';

export interface SearchHit {
  kind: CatalogSection;
  id: string;
  name: string;
  poster?: string;
  categoryId?: string;
}

export interface SearchItem {
  id: string;
  name: string;
  poster?: string;
  categoryId?: string;
}

/** Nenhuma categoria bloqueada. */
const SEM_BLOQUEIO: ReadonlySet<string> = new Set<string>();

/** Chave em `meta` que marca o índice de palavras como completo, por lista. */
const CHAVE_PALAVRAS = 'search.wordsGen';
/** Suba isto se a forma das palavras mudar — força o preenchimento de novo. */
const GERACAO_PALAVRAS = 1;
/** Teto de linhas trazidas pelo índice de palavras antes de ranquear. */
const TETO_POR_PALAVRA = 300;

/**
 * Palavras indexáveis de um título já normalizado.
 *
 * Sem repetição (uma palavra repetida no nome traria a mesma linha duas vezes) e
 * sem as de uma letra, que a consulta nunca procura — `query` exige 2 caracteres.
 */
export function palavrasDoTitulo(norm: string): string[] {
  return [...new Set(norm.split(' ').filter((p) => p.length > 1))];
}

/** Devolve a thread ao navegador entre blocos do preenchimento. */
const cederAThread = () => new Promise<void>((r) => setTimeout(r, 0));

export interface SearchOptions {
  kind?: CatalogSection;
  limit?: number;
}

/**
 * Índice de busca persistido no Dexie (RF-42): uma linha por item com o título
 * normalizado. Preenchido durante o sync — não reconstruído em memória a cada boot.
 * Consulta = prefixo pelo índice `[listId+norm]` + varredura de substring limitada
 * como reforço (varrer ~30k strings fica abaixo de ~20ms e só roda na busca).
 */
export class SearchRepo {
  /** ids de categoria escondidos, por seção — resolvidos sob demanda. */
  private bloqueadas: Partial<Record<CatalogSection, Promise<ReadonlySet<string>>>> = {};

  constructor(
    private readonly db: AuraDb,
    private readonly listId: string,
    private readonly policy: CatalogPolicy = {},
  ) {}

  private idsBloqueados(section: CatalogSection): Promise<ReadonlySet<string>> {
    if (!this.policy.hideAdult) return Promise.resolve(SEM_BLOQUEIO);
    this.bloqueadas[section] ??= this.db.categories
      .where('[listId+kind]')
      .equals([this.listId, section])
      .toArray()
      .then(
        (rows) =>
          new Set(
            rows.filter((r) => isAdultCategoryName(r.name)).map((r) => String(r.id)),
          ),
      );
    return this.bloqueadas[section]!;
  }

  /** Acrescenta/atualiza linhas de busca em lote (durante o sync, por categoria). */
  async upsert(
    kind: CatalogSection,
    items: SearchItem[],
    syncGen: number,
  ): Promise<void> {
    if (!items.length) return;
    await this.db.search.bulkPut(items.map((it) => this.toRow(kind, it, syncGen)));
  }

  /** Apaga linhas de gerações antigas — itens que sumiram do painel. */
  /**
   * Remove as linhas de uma seção que ficaram para trás da geração atual.
   *
   * O escopo por `kind` é essencial: `syncGen` é gerado **por seção**
   * (`catalogSync`), então uma limpeza global apagaria o índice das outras.
   * Era o que acontecia — como as seções sincronizam em sequência, sobrava só a
   * última (séries) e a busca nunca achava filme nem canal.
   */
  /**
   * PERF-04 (spec 002, esquema v4): antes varria `.where('listId').filter(...)`
   * — ~55 mil linhas em JS, 3× por sync (uma por seção). Pelo índice composto
   * `[listId+kind+syncGen]`, o `between` já chega só nas linhas da seção com
   * geração anterior à atual, sem materializar o resto da tabela pra descartar
   * depois. Mesmo resultado da varredura: qualquer linha desta lista+seção com
   * `syncGen` menor que o atual é órfã (sumiu do painel) — a diferença é só o
   * caminho até achá-las.
   */
  async pruneStale(kind: CatalogSection, syncGen: number): Promise<number> {
    const stale = await this.db.search
      .where('[listId+kind+syncGen]')
      .between([this.listId, kind, 0], [this.listId, kind, syncGen], true, false)
      .primaryKeys();
    if (stale.length) await this.db.search.bulkDelete(stale as never[]);
    return stale.length;
  }

  async query(term: string, opts: SearchOptions = {}): Promise<SearchHit[]> {
    const norm = normalizeText(term);
    if (norm.length < 2) return [];
    const limit = opts.limit ?? 40;
    if (limit <= 0) return [];
    const tokens = norm.split(' ').filter(Boolean);
    const porSecao = new Map<CatalogSection, ReadonlySet<string>>();
    if (this.policy.hideAdult) {
      await Promise.all(
        (['live', 'vod', 'series'] as const).map(async (section) => {
          porSecao.set(section, await this.idsBloqueados(section));
        }),
      );
    }
    const accept = (row: SearchRow) =>
      row.listId === this.listId &&
      (!opts.kind || row.kind === opts.kind) &&
      !porSecao.get(row.kind)?.has(String(row.categoryId));
    const candidates = Math.max(limit, TETO_POR_PALAVRA);

    const prefix = opts.kind
      ? this.db.search
          .where('[listId+kind+norm]')
          .between([this.listId, opts.kind, norm], [this.listId, opts.kind, norm + '￿'])
      : this.db.search
          .where('[listId+norm]')
          .between([this.listId, norm], [this.listId, norm + '￿']);
    const byPrefix = await prefix.filter(accept).limit(candidates).toArray();

    let hits: SearchRow[] = byPrefix;

    if (hits.length < limit) {
      const seen = new Set(hits.map((h) => `${h.kind}:${h.id}`));
      const resto = (await this.indiceDePalavrasPronto())
        ? await this.porPalavra(tokens, accept, candidates)
        : await this.varrendoTudo(tokens, accept, candidates);
      hits = hits.concat(resto.filter((r) => !seen.has(`${r.kind}:${r.id}`)));
    }

    hits.sort(
      (a, b) =>
        rank(a.norm, norm, tokens) - rank(b.norm, norm, tokens) ||
        a.name.localeCompare(b.name),
    );
    return hits.slice(0, limit).map((h) => this.toHit(h));
  }

  async clear(): Promise<void> {
    await this.db.search.where('listId').equals(this.listId).delete();
  }

  /**
   * Linhas cuja *palavra* começa pelo token mais longo do termo — é isto que
   * acha "vingado" dentro de "Os Vingadores". Os demais tokens são conferidos
   * em memória, sobre as poucas linhas que voltaram.
   *
   * `distinct()`: uma linha com duas palavras casando o prefixo aparece duas
   * vezes no índice multiEntry.
   */
  private async porPalavra(
    tokens: string[],
    accept: (row: SearchRow) => boolean,
    limit: number,
  ): Promise<SearchRow[]> {
    const alvo = tokens.reduce((a, b) => (b.length > a.length ? b : a), '');
    if (!alvo) return [];
    const linhas = await this.db.search
      .where('words')
      .between(alvo, alvo + '￿', true, true)
      .distinct()
      .filter((r) => accept(r) && tokens.every((t) => r.norm.includes(t)))
      .limit(limit)
      .toArray();
    return linhas;
  }

  /**
   * Caminho anterior ao índice de palavras: varre a lista inteira. Fica só como
   * rede de segurança enquanto o preenchimento não termina — medido no aparelho
   * de teste, são 5.473ms para 54.535 linhas.
   */
  private varrendoTudo(
    tokens: string[],
    accept: (row: SearchRow) => boolean,
    limit: number,
  ): Promise<SearchRow[]> {
    return this.db.search
      .where('listId')
      .equals(this.listId)
      .filter((r) => accept(r) && tokens.every((t) => r.norm.includes(t)))
      .limit(limit)
      .toArray();
  }

  private get meta(): MetaRepo {
    return new MetaRepo(this.db, this.listId);
  }

  /** Todas as linhas desta lista já têm `words`? */
  async indiceDePalavrasPronto(): Promise<boolean> {
    return (await this.meta.get<number>(CHAVE_PALAVRAS)) === GERACAO_PALAVRAS;
  }

  /**
   * Declara o índice pronto. O sync chama isto ao terminar um ciclo completo:
   * ali toda linha foi reescrita por `upsert`, que já grava `words`.
   */
  async marcarIndiceDePalavras(): Promise<void> {
    await this.meta.set(CHAVE_PALAVRAS, GERACAO_PALAVRAS);
  }

  /**
   * Preenche `words` nas linhas gravadas antes da v2 e marca o índice pronto.
   *
   * Roda em segundo plano, em blocos, cedendo a thread entre eles: numa
   * transação só, as 54.535 linhas do aparelho de teste seriam ~19s de tela
   * congelada. Fatiado, leva ~2min20 no total e a tela segue usável — o bloco de
   * 800 foi escolhido medindo o quadro mais longo (160ms, contra 265ms com
   * blocos de 2.000, sem diferença no tempo total). Enquanto não termina, a
   * busca continua caindo em `varrendoTudo`, então nada regride.
   *
   * @returns quantas linhas foram preenchidas.
   */
  async garantirIndiceDePalavras(tamanhoDoBloco = 800): Promise<number> {
    if (await this.indiceDePalavrasPronto()) return 0;

    let preenchidas = 0;
    let inicio: [string, string, string] = [this.listId, '', ''];
    let incluiInicio = true;
    for (;;) {
      const bloco = await this.db.search
        .where('[listId+kind+id]')
        .between(inicio, [this.listId, '￿', '￿'], incluiInicio, true)
        .limit(tamanhoDoBloco)
        .toArray();
      if (!bloco.length) break;

      const semPalavras = bloco.filter((r) => r.words === undefined);
      if (semPalavras.length) {
        await this.db.search.bulkPut(
          semPalavras.map((r) => ({ ...r, words: palavrasDoTitulo(r.norm) })),
        );
        preenchidas += semPalavras.length;
      }

      const ultima = bloco[bloco.length - 1]!;
      inicio = [ultima.listId, ultima.kind, ultima.id];
      incluiInicio = false;
      if (bloco.length < tamanhoDoBloco) break;
      await cederAThread();
    }

    await this.marcarIndiceDePalavras();
    return preenchidas;
  }

  private toRow(kind: CatalogSection, it: SearchItem, syncGen: number): SearchRow {
    const norm = normalizeText(it.name);
    return {
      listId: this.listId,
      kind,
      id: it.id,
      name: it.name,
      norm,
      words: palavrasDoTitulo(norm),
      syncGen,
      ...(it.poster !== undefined ? { poster: it.poster } : {}),
      ...(it.categoryId !== undefined ? { categoryId: it.categoryId } : {}),
    };
  }

  private toHit(h: SearchRow): SearchHit {
    return {
      kind: h.kind,
      id: h.id,
      name: h.name,
      ...(h.poster !== undefined ? { poster: h.poster } : {}),
      ...(h.categoryId !== undefined ? { categoryId: h.categoryId } : {}),
    };
  }
}

/** Menor = melhor: começa com o termo < contém o termo < só casa tokens soltos. */
function rank(norm: string, term: string, tokens: string[]): number {
  if (norm.startsWith(term)) return 0;
  if (norm.includes(term)) return 1;
  if (tokens.every((t) => norm.includes(t))) return 2;
  return 3;
}

export function toSearchItem(m: Channel | Movie | Series): SearchItem {
  const src = m as { poster?: string; logo?: string };
  const poster = src.poster ?? src.logo;
  return {
    id: m.id,
    name: m.name,
    ...(poster !== undefined ? { poster } : {}),
    ...(m.categoryId !== undefined ? { categoryId: m.categoryId } : {}),
  };
}
