import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  DEFAULT_DETAIL_CACHE_POLICY,
  resolveDetailState,
  shouldFetchDetail,
  type Episode,
  type SeriesDetail as SeriesDetailModel,
} from '@mfp/core';
import { FocusButton } from '../components/FocusButton.js';
import { ProgressBar, RatingStars } from '../components/badges.js';
import { LoadingState, ErrorScreen } from '../components/states.js';
import { BalanceLoader } from '../components/BalanceLoader.js';
import { SortDropdown } from '../components/SortDropdown.js';
import { DetailBackdrop } from '../components/DetailBackdrop.js';
import { DetailContainer } from './MovieDetail.js';
import { VirtualGrid } from '../components/VirtualGrid.js';
import { useRemPx } from '../theme/useRemPx.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';
import { cssLen } from '../theme/cssMath.js';
import { focusRing } from '../nav/focusRing.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useProvider } from '../runtime/useProvider.js';
import { useNavigation } from '../nav/navigationStack.js';
import { useNowPlaying } from '../state/nowPlaying.js';
import { useFavorites } from '../state/favorites.js';
import { DEFAULT_PROFILE } from '../state/catalog.js';
import { resumePoint } from '../util/resume.js';
import { classifyError, type AppError } from '../errors.js';
import { t } from '../i18n/index.js';

type ProgressMap = Record<
  string,
  { positionSecs: number; durationSecs: number; completed: boolean }
>;

/** Ponto de retomada de um episódio, ou `undefined` para começar do início. */
function retomadaDe(p: ProgressMap[string] | undefined): number | undefined {
  if (!p) return undefined;
  const secs = resumePoint(p.positionSecs, p.durationSecs, p.completed);
  return secs > 0 ? secs : undefined;
}

let nextGeneration = 0;
function newGeneration(): number {
  return ++nextGeneration;
}

export function SeriesDetail({ id, listId }: { id: string; listId: string }) {
  const rt = useRuntime();
  const getProvider = useProvider();
  const push = useNavigation((s) => s.push);
  const setQueue = useNowPlaying((s) => s.setQueue);
  const isFav = useFavorites((s) => s.isFav);
  const toggle = useFavorites((s) => s.toggle);
  const loadFavs = useFavorites((s) => s.load);
  const _favKeys = useFavorites((s) => s.keys);
  const [detail, setDetail] = useState<SeriesDetailModel | null>(null);
  const [error, setError] = useState<AppError | null>(null);
  const [season, setSeason] = useState(1);
  const [progress, setProgress] = useState<ProgressMap>({});
  // Indicador de enriquecimento (só aparece com o shell já visível — GTV-RF-23):
  // some assim que cache OU rede completarem as temporadas. Uma revalidação de
  // cache stale (SWR) não liga isto de novo (GTV-RF-25).
  const [enriching, setEnriching] = useState(true);
  const ctrlRef = useRef<AbortController | null>(null);
  const genRef = useRef(newGeneration());

  useEffect(() => {
    const ctrl = new AbortController();
    const gen = newGeneration();
    ctrlRef.current = ctrl;
    genRef.current = gen;

    let isActive = true;
    setEnriching(true);

    rt.perf.marcar('detail:open', { tipo: 'series' });
    void loadFavs(rt, listId);
    void (async () => {
      try {
        // Shell imediato (GTV-RF-23): nome/poster/rating do catálogo já
        // sincronizado, sem esperar `get_series_info` nem o cache — tira a
        // tela de "Carregando…" na primeira visita a uma série. `seasons: []`
        // até o cache/rede chegarem — a lista de episódios aparece vazia até lá.
        const seed = await rt.catalog(listId).seriesById(id);
        if (!isActive || genRef.current !== gen) return;
        if (seed) {
          setDetail((d) => d ?? ({ ...seed, seasons: [] } as SeriesDetailModel));
          rt.perf.marcar('detail:usable', { origem: 'seed' });
        }

        const cached = await rt.db.seriesInfo.get([listId, id]);
        if (!isActive || genRef.current !== gen) return;
        if (cached) {
          setDetail(cached);
          setSeason(cached.seasons[0]?.season ?? 1);
          setEnriching(false);
          rt.perf.marcar('detail:cacheDone', { origem: 'cache' });
        }

        // TTL (GTV-RF-24): cache válido não dispara `get_series_info` de novo.
        const policy = DEFAULT_DETAIL_CACHE_POLICY;
        const state = resolveDetailState(
          null,
          cached ? { data: cached, cachedAt: cached.cachedAt } : null,
          policy,
        );
        const { fetch: deveBuscar } = shouldFetchDetail(state, policy);
        if (cached && !deveBuscar) {
          // segue para a leitura de progresso abaixo, sem bater rede
        } else {
          const { provider } = await getProvider();
          const fresh = await provider.getSeriesInfo(id, { signal: ctrl.signal });
          if (!isActive || genRef.current !== gen) return;
          setDetail(fresh);
          setSeason((s) =>
            fresh.seasons.some((x) => x.season === s) ? s : (fresh.seasons[0]?.season ?? 1),
          );
          setEnriching(false);
          rt.perf.marcar('detail:apiDone', { origem: 'network' });
          await rt.db.seriesInfo.put({ ...fresh, listId, cachedAt: Date.now() });
        }
      } catch (err) {
        if (!isActive || genRef.current !== gen) return;
        setEnriching(false);
        setError((e) => e ?? classifyError(err));
      }

      if (!isActive || genRef.current !== gen) return;
      const rows = await rt.db.progress
        .where('[profileId+listId]')
        .equals([DEFAULT_PROFILE, listId])
        .toArray();
      const map: ProgressMap = {};
      for (const r of rows) {
        map[r.id] = {
          positionSecs: r.positionSecs,
          durationSecs: r.durationSecs,
          completed: r.completed,
        };
      }
      setProgress(map);
    })();

    return () => {
      isActive = false;
      ctrl.abort();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, listId]);

  const flatEpisodes = useMemo(
    () => (detail?.seasons ?? []).flatMap((s) => s.episodes),
    [detail],
  );

  // próximo a assistir: 1º não concluído com algum progresso, senão o 1º
  const nextEp = useMemo(() => {
    const inProgress = flatEpisodes.find(
      (e) =>
        progress[e.id] &&
        !progress[e.id]?.completed &&
        (progress[e.id]?.positionSecs ?? 0) > 15,
    );
    if (inProgress) return inProgress;
    return flatEpisodes.find((e) => !progress[e.id]?.completed) ?? flatEpisodes[0];
  }, [flatEpisodes, progress]);

  if (error && !detail) {
    return <ErrorScreen title={error.title} body={error.body} code={error.code} />;
  }
  if (!detail) return <LoadingState />;

  const fav = isFav('series', id);
  const currentSeason =
    detail.seasons.find((s) => s.season === season) ?? detail.seasons[0];

  const playFrom = (ep: Episode) => {
    const list = flatEpisodes.map((e) => ({
      id: e.id,
      title: `${detail.name} — T${e.season}:E${e.episode}`,
      subtitle: e.title,
      ext: e.containerExt,
      // mesma regra do filme (`resumePoint`): abaixo de 15s recomeça, acima de
      // 95% conta como assistido. Sem ela, sair aos 3s do episódio fazia a
      // retomada "continuar" 3 segundos depois do início.
      startAtSecs: retomadaDe(progress[e.id]),
    }));
    const index = flatEpisodes.findIndex((e) => e.id === ep.id);
    setQueue('vod', list, Math.max(0, index));
    push({
      name: 'player',
      params: {
        kind: 'vod',
        streamId: ep.id,
        ext: ep.containerExt ?? 'mp4',
        title: `${detail.name} — T${ep.season}:E${ep.episode}`,
        subtitle: ep.title,
        seriesId: detail.id,
        ...(detail.poster ? { poster: detail.poster } : {}),
        ...(list[index]?.startAtSecs
          ? { startAtSecs: String(Math.floor(list[index]!.startAtSecs!)) }
          : {}),
      },
    });
  };

  return (
    <DetailContainer>
      <DetailBackdrop backdrop={detail.backdrop} poster={detail.poster} />
      {enriching && (
        <div
          role="status"
          className={gapRowClass}
          style={{
            position: 'absolute',
            top: '1.5rem',
            right: '1.5rem',
            zIndex: 1,
            padding: '0.5rem 1rem',
            borderRadius: 'var(--radius-sm)',
            background: 'var(--bg-scrim)',
            color: 'var(--text-primary)',
            display: 'flex',
            alignItems: 'center',
            ...gapVar('0.7rem'),
          }}
        >
          {/* mesmo indicador do player durante abertura/buffering */}
          <BalanceLoader size="1.1em" />
          {t('detail.enriching')}
        </div>
      )}
      <div
        className={gapColClass}
        style={{
          position: 'relative', // acima da arte de fundo
          // deixa a faixa da direita para a arte de fundo (DetailBackdrop)
          maxWidth: cssLen('min(60rem, 62%)'),
          display: 'flex',
          flexDirection: 'column',
          ...gapVar('1rem'),
        }}
      >
        <h1>{detail.name}</h1>
        <div
          className={gapRowClass}
          style={{ display: 'flex', alignItems: 'center', ...gapVar('0.6rem') }}
        >
          <span style={{ color: 'var(--text-secondary)' }}>
            {detail.seasons.length}{' '}
            {detail.seasons.length === 1 ? 'temporada' : 'temporadas'}
          </span>
          {detail.rating != null && detail.rating > 0 && (
            <RatingStars value={detail.rating} />
          )}
        </div>
        {detail.genre && <p style={{ color: 'var(--text-secondary)' }}>{detail.genre}</p>}
        {detail.plot && <p>{detail.plot}</p>}

        <div className={gapRowClass} style={{ display: 'flex', ...gapVar('1rem') }}>
          {nextEp && (
            <FocusButton
              primary
              autoFocus
              focusKey="series-play"
              onPress={() => playFrom(nextEp)}
            >
              {t('detail.resume', { label: `T${nextEp.season}:E${nextEp.episode}` })}
            </FocusButton>
          )}
          <FocusButton
            focusKey="series-fav"
            onPress={() => void toggle(rt, listId, 'series', id)}
          >
            {fav ? t('detail.inMyList') : t('detail.myList')}
          </FocusButton>
        </div>

        <h3>{t('detail.episodes')}</h3>
        <SortDropdown
          focusKey="series-season"
          selectedId={String(season)}
          options={detail.seasons.map((s) => ({
            id: String(s.season),
            label: s.name ?? t('detail.season', { n: s.season }),
          }))}
          onChange={(sid) => setSeason(Number(sid))}
        />

        <EpisodeGrid
          episodes={currentSeason?.episodes ?? []}
          progress={progress}
          nextEpId={nextEp?.id}
          onPlayEpisode={playFrom}
        />
      </div>
    </DetailContainer>
  );
}

/**
 * Grade virtualizada de episódios (GTV-RF-27 / M7). Renderiza apenas os
 * visíveis na tela, evitando a materialização de ~500 episódios. A consulta
 * de progresso é feita uma vez no `SeriesDetail` (linha 86) para toda a série.
 */
function EpisodeGrid({
  episodes,
  progress,
  nextEpId,
  onPlayEpisode,
}: {
  episodes: Episode[];
  progress: ProgressMap;
  nextEpId?: string;
  onPlayEpisode: (ep: Episode) => void;
}) {
  const rem = useRemPx();
  const renderItem = useCallback(
    (ep: Episode, _i: number, focused: boolean) => (
      <EpisodeRow
        ep={ep}
        focused={focused}
        progress={progress[ep.id]}
        isNext={ep.id === nextEpId}
        onPress={() => onPlayEpisode(ep)}
      />
    ),
    [progress, nextEpId, onPlayEpisode],
  );

  return (
    <VirtualGrid<Episode>
      focusKey="series-episodes"
      restoreKey="series-episodes"
      items={episodes}
      columns={1}
      itemHeight={Math.round(rem * 5.2)} // ~2 linhas (título + plot ou progresso)
      rowGap={Math.round(rem * 0.45)}
      colGap={0}
      onItemPress={onPlayEpisode}
      renderItem={renderItem}
    />
  );
}

function EpisodeRow({
  ep,
  focused,
  progress,
  isNext,
  onPress,
}: {
  ep: Episode;
  focused: boolean;
  progress?: { positionSecs: number; durationSecs: number; completed: boolean };
  isNext: boolean;
  onPress: () => void;
}) {
  // Sem `useFocusable` aqui: o `VirtualGrid` já registra a célula (índice) como
  // o nó focável real e passa `focused` como prop — igual ao `ChannelRow` em
  // LiveChannels. Registrar OUTRO `useFocusable` aninhado dentro da mesma
  // célula criava um segundo nó focável, do mesmo tamanho e por cima do
  // primeiro; o norigin passava a focar o nó interno (`series-ep-<id>`), então
  // o `focused` desta célula nunca virava `true` e o anel de foco não aparecia.
  const mins = ep.durationSecs ? Math.round(ep.durationSecs / 60) : null;
  const done = progress?.durationSecs ? Math.round(progress.positionSecs / 60) : null;
  return (
    <div
      className={gapColClass}
      style={{
        height: '100%',
        padding: '0.8rem 1rem',
        borderRadius: 'var(--radius-sm)',
        background: focused ? 'var(--bg-raised)' : 'var(--bg-panel)',
        cursor: 'pointer',
        display: 'flex',
        flexDirection: 'column',
        ...gapVar('0.3rem'),
        ...focusRing(focused),
      }}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between' }}>
        <strong>
          {ep.episode}. {ep.title}
          {isNext && (
            <span
              style={{ color: 'var(--accent)', marginLeft: '0.5rem', fontSize: '0.8em' }}
            >
              {t('detail.nextEpisode')}
            </span>
          )}
        </strong>
        {mins != null && (
          <span style={{ color: 'var(--text-secondary)', flexShrink: 0 }}>
            {mins} min
          </span>
        )}
      </div>
      {ep.plot && (
        <p
          style={{
            color: 'var(--text-secondary)',
            fontSize: 'var(--fs-meta)',
            margin: 0,
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            display: '-webkit-box',
            WebkitLineClamp: 1,
            WebkitBoxOrient: 'vertical',
          }}
        >
          {ep.plot}
        </p>
      )}
      {progress && progress.durationSecs > 0 && (
        <div style={{ marginTop: '0.2rem' }}>
          <ProgressBar value={progress.positionSecs / progress.durationSecs} />
          {done != null && mins != null && (
            <span style={{ color: 'var(--text-disabled)', fontSize: '0.75em' }}>
              {t('detail.episodeProgress', { done, total: mins })}
            </span>
          )}
        </div>
      )}
    </div>
  );
}
