import { create } from 'zustand';
import { MetaRepo, type Category, type Channel } from '@mfp/core';
import type { Runtime } from '../runtime/runtime.js';

const LAST_CHANNEL_KEY = 'ui.lastChannel';

/**
 * Debounce de categoria (GTV-RF-30 / M6). Aqui o alvo é a lista principal, não
 * um enfeite — mais curta que o `useNowNext` (450ms). Medido em G08: 100 ms é o
 * intervalo sugerido para evitar leituras concorrentes sem sacrificar UX.
 */
const ESPERA_CATEGORIA_MS = 100;
const esperar = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

interface LiveState {
  categories: Category[];
  categoryId: string | null;
  channels: Channel[];
  /**
   * A troca de categoria ainda está no debounce/leitura — `channels` continua
   * mostrando a categoria anterior até a nova responder, então usar
   * `channels.length === 0` sozinho para decidir "vazio" mostraria a lista
   * antiga como se já fosse a nova. Consumida pela tela para não afirmar
   * "sem canais" enquanto isto for `true`.
   */
  carregandoCanais: boolean;
  loadCategories: (rt: Runtime, listId: string) => Promise<void>;
  selectCategory: (
    rt: Runtime,
    listId: string,
    categoryId: string | null,
    beforePublish?: (channels: Channel[]) => void,
  ) => Promise<void>;
  rememberChannel: (rt: Runtime, listId: string, channelId: string) => Promise<void>;
  getLastChannel: (rt: Runtime, listId: string) => Promise<string | null>;
}

/**
 * Token da seleção em curso (GTV-RF-28 / M6). Percorrer a coluna de categorias
 * no D-pad disparava uma leitura completa por tecla, sem cancelamento: descer 10
 * categorias enfileirava 10 leituras concorrentes. Também previne result fora
 * de ordem — a última a **responder** já não necessariamente ganha.
 */
let selecaoAtual = 0;

/**
 * Cache de canais em sessão (GTV-RF-29 / M6). Navegar rapidamente por
 * categorias não dispara consultas remotas concorrentes. O cache é uma chave de
 * lookup apenas — o resultado real é aplicado via set({channels}) após o
 * debounce.
 */
const cacheCanais = new WeakMap<
  Runtime,
  {
    repo: ReturnType<Runtime['catalog']>;
    hideAdult: boolean;
    categories: Map<string | null, Channel[]>;
  }
>();
const MAX_CACHED_CHANNELS = 5000;
const MAX_CACHED_CATEGORIES = 3;

export const useLive = create<LiveState>((set) => ({
  categories: [],
  categoryId: null,
  channels: [],
  // Começa `true`: a tela monta e só chama `selectCategory` depois de decidir
  // qual categoria abrir (RF-34, ver `LiveChannels`) — sem isto o primeiro
  // render, antes desse efeito rodar, já mostrava "nada por aqui" com
  // `channels` ainda vazio de propósito (não vazio de fato).
  carregandoCanais: true,

  loadCategories: async (rt, listId) => {
    const repo = rt.catalog(listId);
    const categories = await repo.categories('live');
    set({ categories });
  },

  selectCategory: async (rt, listId, categoryId, beforePublish) => {
    const minha = ++selecaoAtual;
    // o realce da categoria acompanha o foco na hora; só a leitura dos canais
    // espera — é ela que é cara (GTV-RF-29)
    set({ categoryId, carregandoCanais: true });

    const repo = rt.catalog(listId);
    const hideAdult = !!rt.contentPolicy?.hideAdult;
    let cache = cacheCanais.get(rt);
    if (!cache || cache.repo !== repo || cache.hideAdult !== hideAdult) {
      cache = { repo, hideAdult, categories: new Map() };
      cacheCanais.set(rt, cache);
    }
    const emCache = cache.categories.get(categoryId);
    if (emCache) {
      cache.categories.delete(categoryId);
      cache.categories.set(categoryId, emCache);
      // Restaurar o último canal não lê a mesma categoria duas vezes (GTV-RF-28)
      if (minha === selecaoAtual) {
        beforePublish?.(emCache);
        set({ channels: emCache, carregandoCanais: false });
      }
      return;
    }

    await esperar(ESPERA_CATEGORIA_MS);
    if (minha !== selecaoAtual) return; // outra seleção já passou na frente

    const channels = await repo.channels(categoryId ?? undefined);
    if (minha !== selecaoAtual) return; // esta resposta chegou tarde demais

    if (channels.length <= MAX_CACHED_CHANNELS) {
      cache.categories.set(categoryId, channels);
      let size = [...cache.categories.values()].reduce((n, rows) => n + rows.length, 0);
      while (
        cache.categories.size > MAX_CACHED_CATEGORIES ||
        size > MAX_CACHED_CHANNELS
      ) {
        const oldest = cache.categories.keys().next().value!;
        size -= cache.categories.get(oldest)!.length;
        cache.categories.delete(oldest);
      }
    }
    beforePublish?.(channels);
    set({ channels, carregandoCanais: false });
  },

  rememberChannel: async (rt, listId, channelId) => {
    await new MetaRepo(rt.db, listId).set(LAST_CHANNEL_KEY, channelId);
  },

  getLastChannel: (rt, listId) =>
    new MetaRepo(rt.db, listId).get<string>(LAST_CHANNEL_KEY).then((v) => v ?? null),
}));
