import { useEffect, useState } from 'react';
import { gapRowClass, gapVar } from '../theme/gap.js';

/**
 * Relógio no canto do cabeçalho (padrão dos players de TV — XCIPTV, SS IPTV).
 * Útil sobretudo na TV ao vivo: ver a hora sem pegar o celular, saber quanto
 * falta pro programa. Fora do player e do boot — só onde o cabeçalho aparece.
 *
 * Atualiza no virar do minuto, não num intervalo fixo, para o `14:32` trocar
 * junto com a hora do aparelho e não gastar um tick por segundo.
 */
export function HeaderClock() {
  const [agora, setAgora] = useState(() => new Date());

  useEffect(() => {
    let timer: number;
    const agendar = () => {
      const d = new Date();
      setAgora(d);
      // ms até o próximo minuto cheio
      const restante = 60_000 - (d.getSeconds() * 1000 + d.getMilliseconds());
      timer = window.setTimeout(agendar, restante + 50);
    };
    agendar();
    return () => window.clearTimeout(timer);
  }, []);

  const hora = agora.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  // "qui., 10/09" → "qui 10/09" (sem o ponto do dia da semana abreviado)
  const data = agora
    .toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' })
    .replace('.', '');

  return (
    <div
      className={gapRowClass}
      style={{
        flexShrink: 0,
        display: 'flex',
        alignItems: 'baseline',
        fontFamily: 'var(--font-display)',
        whiteSpace: 'nowrap',
        letterSpacing: '0.02em',
        ...gapVar('0.5rem'),
      }}
    >
      <span style={{ fontSize: 'var(--fs-body)', fontWeight: 600 }}>{hora}</span>
      {/* a data some em viewport estreito (base.css) para não brigar com o menu */}
      <span className="header-date" style={{ color: 'var(--text-secondary)' }}>
        {data}
      </span>
    </div>
  );
}
