import { useEffect, useRef } from 'react';
import type { LogicalKey, PlatformAdapter } from '@mfp/platform';

export type { LogicalKey };

/**
 * Um handler pode devolver `true` para **consumir** a tecla: além de
 * `preventDefault`, o evento não chega ao norigin (nem a outros handlers), o que
 * permite, por exemplo, a seekbar usar ←/→ para scrub sem que o foco escape
 * para o botão vizinho.
 */
export type LogicalKeyHandlers = Partial<
  Record<LogicalKey, (key: LogicalKey) => void | boolean>
>;

/**
 * Nomes padrão de `KeyboardEvent.key` (W3C UI Events + extensão de TV).
 *
 * Achado medindo no device (Android TV / WebView do Capacitor): o WebView NÃO
 * entrega os keycodes nativos do Android — o Chromium já os traduz para os
 * códigos web (DPAD_UP 19 → 38, DPAD_CENTER 23 → 13, CHANNEL_UP 166 → 33…).
 * Pior: as teclas coloridas chegam com `keyCode: 0` e só podem ser identificadas
 * por `event.key` (`ColorF0Red` etc). Por isso resolvemos primeiro pelo `key`
 * padrão e só depois caímos no `keyMap` numérico do adapter.
 */
const KEY_BY_NAME: Readonly<Record<string, LogicalKey>> = {
  ArrowUp: 'Up',
  ArrowDown: 'Down',
  ArrowLeft: 'Left',
  ArrowRight: 'Right',
  Enter: 'Enter',
  Backspace: 'Back',
  Escape: 'Back',
  BrowserBack: 'Back',
  GoBack: 'Back',
  MediaPlay: 'Play',
  MediaPause: 'Pause',
  MediaPlayPause: 'PlayPause',
  MediaStop: 'Stop',
  MediaTrackNext: 'FastForward',
  MediaTrackPrevious: 'Rewind',
  MediaFastForward: 'FastForward',
  MediaRewind: 'Rewind',
  ChannelUp: 'ChannelUp',
  ChannelDown: 'ChannelDown',
  ColorF0Red: 'Red',
  ColorF1Green: 'Green',
  ColorF2Yellow: 'Yellow',
  ColorF3Blue: 'Blue',
};

/** Teclas que o norigin também precisa ver para mover o foco. */
const NAVIGATION_KEYS: ReadonlySet<LogicalKey> = new Set<LogicalKey>([
  'Up',
  'Down',
  'Left',
  'Right',
  'Enter',
]);

/**
 * Ouve `keydown` global (na fase de **captura**, antes do norigin), traduz para
 * tecla lógica e chama o handler da tela ativa.
 *
 * Por padrão setas e OK seguem para o norigin — uma tela pode observar `Up` ou
 * `Enter` sem quebrar a navegação espacial. Se o handler devolver `true`, a
 * tecla é consumida ali e não chega ao norigin.
 *
 * `handlers` pode mudar a cada render sem re-registrar o listener.
 */
export function useLogicalKeys(adapter: PlatformAdapter, handlers: LogicalKeyHandlers) {
  const ref = useRef(handlers);
  useEffect(() => {
    ref.current = handlers;
  }, [handlers]);

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      const logical =
        KEY_BY_NAME[e.key] ?? adapter.keyMap[e.keyCode || e.which] ?? undefined;
      if (!logical) return;
      const handler = ref.current[logical];
      if (!handler) return;

      const consumed = handler(logical) === true;
      if (consumed || !NAVIGATION_KEYS.has(logical)) e.preventDefault();
      if (consumed) e.stopImmediatePropagation();
    };
    // captura: roda antes do listener do norigin (registrado em bubble no
    // bootstrap), então dá para consumir a tecla quando preciso
    window.addEventListener('keydown', onKeyDown, true);
    return () => window.removeEventListener('keydown', onKeyDown, true);
  }, [adapter]);
}
