import type { EpgEntry } from '../models/index.js';
import type { AuraDb, StoredProgramme } from './db.js';

export interface NowNext {
  now?: EpgEntry;
  next?: EpgEntry;
}

const H = 3_600_000;

/**
 * Leitura do EPG local (`epgProgrammes`, alimentado pelo `EpgSync` — D-22).
 * Só o cache: nada de rede. `channelId` é o **nosso** id de canal, não o
 * `epg_channel_id` — o `EpgSync` já fez o casamento na hora de gravar.
 */
export class EpgRepo {
  constructor(
    private readonly db: AuraDb,
    private readonly listId: string,
  ) {}

  private toEntry(p: StoredProgramme): EpgEntry {
    return {
      channelId: p.channelId,
      start: p.start,
      stop: p.stop,
      title: p.title,
      ...(p.description ? { description: p.description } : {}),
    };
  }

  /** Programa no ar e o próximo, para um canal. */
  async nowNext(channelId: string, at = Date.now()): Promise<NowNext> {
    // um programa em curso começou antes de `at` — recua a janela para pegá-lo
    const rows = await this.db.epgProgrammes
      .where('[listId+channelId+start]')
      .between([this.listId, channelId, at - 12 * H], [this.listId, channelId, at + 24 * H])
      .toArray();
    rows.sort((a, b) => a.start - b.start);
    const now = rows.find((p) => p.start <= at && p.stop > at);
    const next = rows.find((p) => p.start > at);
    return {
      ...(now ? { now: this.toEntry(now) } : {}),
      ...(next ? { next: this.toEntry(next) } : {}),
    };
  }

  /** Programas que tocam a janela `[from, to)`, em ordem de início (para o guia). */
  async window(channelId: string, from: number, to: number): Promise<EpgEntry[]> {
    const rows = await this.db.epgProgrammes
      .where('[listId+channelId+start]')
      .between([this.listId, channelId, from - 12 * H], [this.listId, channelId, to])
      .toArray();
    return rows
      .filter((p) => p.stop > from && p.start < to)
      .sort((a, b) => a.start - b.start)
      .map((p) => this.toEntry(p));
  }

  /**
   * Programa no ar de cada canal da lista que tem guia, numa passada só — para
   * a lista de canais e o overlay do player, sem uma consulta por linha.
   */
  async nowForList(at = Date.now()): Promise<Map<string, EpgEntry>> {
    // um programa no ar tem `stop` em (at, at + duração]; cortar em +6h evita
    // varrer daqui até o fim dos dados (~55 mil linhas → alguns milhares). Um
    // programa de 6h+ no ar fica sem linha — raríssimo, aceitável.
    const rows = await this.db.epgProgrammes
      .where('[listId+stop]')
      .between([this.listId, at], [this.listId, at + 6 * H])
      .toArray();
    const mapa = new Map<string, EpgEntry>();
    for (const p of rows) {
      if (p.start <= at && p.stop > at && !mapa.has(p.channelId)) {
        mapa.set(p.channelId, this.toEntry(p));
      }
    }
    return mapa;
  }

  /** `true` se há algum programa desta lista que ainda não acabou. */
  async temGuia(): Promise<boolean> {
    const um = await this.db.epgProgrammes
      .where('[listId+stop]')
      .between([this.listId, Date.now()], [this.listId, Infinity])
      .first();
    return !!um;
  }
}
