import type { CSSProperties } from 'react';

/**
 * Regras de foco 10-foot (design-inventory §Foco): anel branco + leve escala;
 * item primário/armado troca por anel da cor de destaque + glow.
 * Fonte única para todos os componentes focáveis não usarem valores soltos.
 */
export function focusRing(focused: boolean, primary = false): CSSProperties {
  const ring = primary ? 'var(--focus-ring-armed)' : 'var(--focus-ring)';
  return {
    outline: focused
      ? `var(--focus-ring-width) solid ${ring}`
      : 'var(--focus-ring-width) solid transparent',
    outlineOffset: '2px',
    transform: focused ? 'scale(var(--focus-scale))' : 'scale(1)',
    boxShadow: focused && primary ? 'var(--focus-glow)' : 'none',
    transition: 'transform var(--dur-fast) var(--ease), outline-color var(--dur-fast)',
  };
}
