import { DEFAULT_CACHE_CONFIG, type CacheConfig } from '../cache/config.js';
import type { AuraDb, StoredProgramme } from '../cache/db.js';
import { MetaRepo } from '../cache/metaRepo.js';
import {
  isQuotaExceededError,
  pruneOldEpgGeneration,
  pruneOldProgrammes,
} from '../cache/quota.js';
import { nullLogger, type Logger } from '../log/logger.js';
import type { IptvProvider } from '../providers/IptvProvider.js';
import { Emitter } from '../util/emitter.js';
import { parseXmltvTimestamp } from '../util/epgTime.js';
import { normalizeText } from '../util/normalize.js';
import { parseXmltvStream } from './xmltvParser.js';

/** `meta` key: `{ lastSyncAt, programmeCount }`. */
const CHAVE_SYNC = 'epg:sync';
/** Programa que já acabou há mais de 1h não serve para nada. */
const JANELA_PODA_MS = 60 * 60_000;
/**
 * Cada programa vira uma linha por canal que compartilha o `epg_channel_id`
 * (SD/HD/FHD/H265/4K…), então são ~170 mil linhas neste painel. Lotes grandes e
 * ceder a thread a cada poucos lotes: no aparelho, lote de 500 cedendo sempre
 * levava mais de um minuto só para gravar.
 */
const LOTE = 2000;
const CEDE_A_CADA = 4;

const cederAThread = () => new Promise<void>((r) => setTimeout(r, 0));

export interface EpgSyncEvents {
  'epg:start': { channelsWithEpg: number };
  'epg:progress': { programmes: number };
  'epg:done': { programmeCount: number; matchedChannels: number };
  'epg:skip': { reason: 'fresh' | 'noChannels' };
  'epg:error': { error: unknown };
}

export interface EpgSyncResult {
  ran: boolean;
  programmeCount: number;
  cancelled: boolean;
}

export interface EpgSyncDeps {
  db: AuraDb;
  provider: IptvProvider;
  listId: string;
  config?: CacheConfig;
  logger?: Logger;
  /**
   * Offset do fuso do painel em minutos (`server_info.timezone`). Só entra em
   * jogo se o XMLTV mandar horário sem offset e sem `start_timestamp` — raro,
   * mas o RF-67 exige não deslocar o guia.
   */
  fallbackOffsetMinutes?: number;
}

/**
 * Ingestão do EPG completo via `xmltv.php` (decisions D-22).
 *
 * `replace-all` por lista: o XMLTV é um retrato completo, sem lógica de
 * merge/dedup — mas desde o PERF-02/03 (spec 002) o "replace" não é mais um
 * `wipe()` antes de gravar. As linhas casadas viram um LOTE por vez, gravado
 * **durante** o parse com a geração desta rodada (`gen: Date.now()`) — o
 * array `rows` chegava a acumular as ~170 mil linhas do arquivo inteiro antes
 * de tocar o banco, o pico de heap que o RP-9 mede. A geração ANTERIOR fica
 * inteira e consultável (as leituras do `EpgRepo` não filtram por `gen`, só
 * por `[listId+channelId+start]`/`[listId+stop]`) até a nova terminar de
 * escrever por completo — só então a antiga é podada. Um programa que
 * continua igual entre duas rodadas (mesmo `channelId`+`start`) é
 * sobrescrito em paz, pela própria chave primária composta; só o que SUMIU
 * do guia novo (`gen` antigo, sem par na geração atual) é removido no fim.
 * Casa `<programme channel>` com o `epg_channel_id` do canal; programa de
 * canal fora da lista é descartado (é a maior parte do arquivo).
 *
 * Rede de segurança: um parse que termina sem erro mas não casa NENHUM
 * programa nunca poda a geração anterior — só substitui o guia quando há
 * dado de verdade para substituir por.
 */
export class EpgSync {
  readonly events = new Emitter<EpgSyncEvents>();

  private readonly config: CacheConfig;
  private readonly log: Logger;
  private readonly meta: MetaRepo;
  private stopped = false;

  constructor(private readonly deps: EpgSyncDeps) {
    this.config = deps.config ?? DEFAULT_CACHE_CONFIG;
    this.log = (deps.logger ?? nullLogger).child({ mod: 'epg', listId: deps.listId });
    this.meta = new MetaRepo(deps.db, deps.listId);
  }

  cancel(): void {
    this.stopped = true;
  }

  /** `true` se um `run()` sem `force` de fato baixaria o XMLTV agora (TTL). */
  async plannedRefresh(now = Date.now()): Promise<boolean> {
    const m = await this.meta.get<{ lastSyncAt: number }>(CHAVE_SYNC);
    if (!m?.lastSyncAt) return true;
    return now - m.lastSyncAt >= this.config.ttlMs.epg;
  }

  async run(opts: { force?: boolean } = {}): Promise<EpgSyncResult> {
    this.stopped = false;
    const { db, listId } = this.deps;

    if (!opts.force && !(await this.plannedRefresh())) {
      this.events.emit('epg:skip', { reason: 'fresh' });
      return { ran: false, programmeCount: 0, cancelled: false };
    }

    const alvo = await this.mapaDeCanais();
    this.events.emit('epg:start', { channelsWithEpg: alvo.size });

    if (alvo.size === 0) {
      // nenhum canal tem `epg_channel_id` — não vale baixar 9 MB
      await this.marcar(0);
      this.events.emit('epg:skip', { reason: 'noChannels' });
      return { ran: true, programmeCount: 0, cancelled: false };
    }

    let stream: ReadableStream<Uint8Array>;
    try {
      stream = await this.deps.provider.getFullEpgStream();
    } catch (error) {
      this.log.warn('xmltv indisponível', { err: String(error) });
      this.events.emit('epg:error', { error });
      return { ran: false, programmeCount: 0, cancelled: false };
    }

    // Geração desta rodada (mesmo padrão do `syncGen` do catálogo). A antiga
    // só é podada no fim, com esta já gravada por inteiro — nunca há um
    // instante em que o guia fica vazio.
    const gen = Date.now();
    const matched = new Set<string>();
    const { fallbackOffsetMinutes } = this.deps;
    let lote: StoredProgramme[] = [];
    let total = 0;
    let lotesGravados = 0;
    const oldestStop = Date.now() - JANELA_PODA_MS;

    const despejar = async (): Promise<void> => {
      if (!lote.length) return;
      try {
        await db.epgProgrammes.bulkPut(lote as never[]);
      } catch (error) {
        if (!isQuotaExceededError(error)) throw error;
        // Mesma defesa do CatalogSync (LG-022): para de forma limpa em vez de
        // deixar o erro subir. A geração anterior (inteira, íntegra) nunca é
        // podada porque `this.stopped` faz o `run()` sair antes do prune.
        this.log.warn('epg: cota de armazenamento estourada — parando o sync', {
          programmesGravados: total,
        });
        this.events.emit('epg:error', { error });
        this.stopped = true;
        return;
      }
      total += lote.length;
      this.events.emit('epg:progress', { programmes: total });
      lote = [];
      lotesGravados++;
      if (lotesGravados % CEDE_A_CADA === 0) await cederAThread();
    };

    try {
      await parseXmltvStream(
        stream,
        (raw) => {
          const ids = alvo.get(normalizeText(raw.channel));
          if (!ids) return;
          const start = raw.startTimestamp
            ? Number(raw.startTimestamp) * 1000
            : (parseXmltvTimestamp(raw.start, { fallbackOffsetMinutes }) ?? Number.NaN);
          const stop = raw.stopTimestamp
            ? Number(raw.stopTimestamp) * 1000
            : (parseXmltvTimestamp(raw.stop, { fallbackOffsetMinutes }) ?? Number.NaN);
          if (!Number.isFinite(start) || !Number.isFinite(stop) || stop <= start) return;
          // O feed pode conter dias de histórico: não expandir/gravar o que a
          // poda removeria logo depois (uma linha por variante SD/HD/FHD...).
          if (stop < oldestStop) return;
          for (const channelId of ids) {
            matched.add(channelId);
            // PERF-02: `description` fora da ingestão em massa — é a maior
            // fatia dos bytes do XMLTV, e hoje nenhuma tela lê
            // `EpgEntry.description` (a busca/lista mostram só `title`). Se um
            // dia existir uma tela de detalhe de programa, ela busca sob
            // demanda — não vale reter a descrição de ~170 mil linhas pra um
            // consumidor que ainda não existe.
            lote.push({ listId, channelId, start, stop, title: raw.title, gen });
          }
          if (lote.length >= LOTE) return despejar();
        },
        {
          aborted: () => this.stopped,
          acceptChannel: (channel) => alvo.has(normalizeText(channel)),
          includeDescription: false,
        },
      );
    } catch (error) {
      this.log.warn('falha ao parsear xmltv', { err: String(error) });
      this.events.emit('epg:error', { error });
      // a geração anterior está inteira no banco — não podamos nada
      return { ran: false, programmeCount: total, cancelled: false };
    }

    if (this.stopped) {
      // idem: a geração anterior fica intacta, só não podamos a antiga
      return { ran: false, programmeCount: total, cancelled: true };
    }

    try {
      await despejar(); // resto do último lote, menor que `LOTE`
    } catch (error) {
      this.log.warn('falha ao gravar o último lote do xmltv', { err: String(error) });
      this.events.emit('epg:error', { error });
      return { ran: false, programmeCount: total, cancelled: false };
    }

    if (this.stopped) {
      // a cota pode estourar só neste flush final (arquivo pequeno, nunca
      // atinge `LOTE` no meio do parse) — mesma garantia do check acima.
      return { ran: false, programmeCount: total, cancelled: true };
    }

    // Achado real (bug pré-existente, não introduzido aqui, mas no mesmo
    // trecho): um parse que termina SEM ERRO mas não casa NENHUM programa
    // (feed vazio/truncado por um hiccup de rede que ainda assim fecha limpo,
    // por exemplo) não pode podar a geração anterior — geração nova vazia +
    // poda incondicional = guia inteiro apagado sem nada para substituir. Um
    // guia desatualizado é sempre melhor que nenhum guia.
    if (matched.size === 0) {
      this.log.warn(
        'epg: parse terminou sem casar nenhum programa — geração anterior mantida',
      );
      this.events.emit('epg:error', { error: new Error('xmltv sem programas casados') });
      return { ran: false, programmeCount: 0, cancelled: false };
    }

    // só agora, com a geração nova gravada por inteiro e com dado de verdade,
    // a antiga é podada — e, dentro da atual, o que já expirou há mais de 1h
    await pruneOldEpgGeneration(db, listId, gen);
    await pruneOldProgrammes(db, listId, Date.now() - JANELA_PODA_MS);
    await this.marcar(total);
    this.events.emit('epg:done', {
      programmeCount: total,
      matchedChannels: matched.size,
    });
    this.log.info('epg sincronizado', { programmes: total, canais: matched.size });
    return { ran: true, programmeCount: total, cancelled: false };
  }

  /** epg_channel_id normalizado → nossos channelId(s) (vários canais podem compartilhar). */
  private async mapaDeCanais(): Promise<Map<string, string[]>> {
    const { db, listId } = this.deps;
    const canais = await db.channels
      .where('[listId+id]')
      .between([listId, ''], [listId, '￿'])
      .toArray();
    const mapa = new Map<string, string[]>();
    for (const c of canais) {
      if (!c.epgChannelId) continue;
      const key = normalizeText(c.epgChannelId);
      if (!key) continue;
      const arr = mapa.get(key);
      if (arr) arr.push(c.id);
      else mapa.set(key, [c.id]);
    }
    return mapa;
  }

  private marcar(programmeCount: number): Promise<void> {
    return this.meta.set(CHAVE_SYNC, { lastSyncAt: Date.now(), programmeCount });
  }
}
