import { HttpError, NetworkError, XtreamAuthError } from '@mfp/core';
import { t, type TextKey } from './i18n/index.js';

// Taxonomia de códigos de erro (design-inventory tela 15). O código curto vai para
// a tela de diagnóstico e o "reportar problema"; a mensagem é sempre pt-BR.

export interface AppError {
  code: string;
  title: string;
  body: string;
  /** Falha de rede/servidor → oferecer "Tentar novamente". */
  retriable: boolean;
}

export function classifyError(err: unknown): AppError {
  if (err instanceof XtreamAuthError) {
    const map: Record<string, { code: string; key: TextKey }> = {
      not_xtream: { code: 'SRV-001', key: 'errors.notXtream' },
      bad_credentials: { code: 'AUTH-001', key: 'errors.badCredentials' },
      banned: { code: 'AUTH-002', key: 'errors.banned' },
      expired: { code: 'AUTH-003', key: 'errors.expired' },
    };
    const hit = map[err.reason] ?? map['not_xtream']!;
    return {
      code: hit.code,
      title: t('errors.authTitle'),
      body: t(hit.key),
      retriable: err.reason === 'not_xtream',
    };
  }

  if (err instanceof NetworkError) {
    // Certificado inválido/expirado é falha de rede para o `fetch`, mas o
    // usuário não tem como resolver "verifique a conexão da TV": o problema é o
    // servidor da lista, e muitas TVs antigas têm a raiz vencida (RF-71). A
    // mensagem precisa dizer isso — a causa vem do motor, em inglês, e cada
    // plataforma escreve de um jeito.
    if (ehCertificado(err.cause)) {
      return {
        code: 'NET-TLS',
        title: t('states.errorTitle'),
        body: t('errors.certificate'),
        retriable: true,
      };
    }
    return {
      code: 'NET-001',
      title: t('states.errorTitle'),
      body: t('errors.network'),
      retriable: true,
    };
  }

  if (err instanceof HttpError) {
    const code = err.status >= 500 ? `SRV-${err.status}` : `SRV-${err.status}`;
    return {
      code,
      title: t('states.errorTitle'),
      body: err.status >= 500 ? t('errors.server5xx') : t('errors.server4xx'),
      retriable: err.status >= 500 || err.status === 429,
    };
  }

  return {
    code: 'ERR-000',
    title: t('states.errorTitle'),
    body: t('errors.unknown'),
    retriable: true,
  };
}

/**
 * Falha de TLS disfarçada de falha de rede.
 *
 * Nenhuma plataforma expõe isso como tipo: o Chromium fala em
 * `ERR_CERT_*`/`SSL`, o WebView do Android em `CertPathValidatorException`, o
 * webOS/Tizen em `certificate`. Casar por texto é feio, mas é o que existe — e
 * o custo de errar é só mostrar a mensagem genérica de rede.
 */
function ehCertificado(cause: unknown): boolean {
  const texto = String(
    (cause as { message?: string } | undefined)?.message ?? cause ?? '',
  ).toLowerCase();
  return texto.includes('cert') || texto.includes('ssl') || texto.includes('handshake');
}
