import { useCallback, useEffect } from 'react';
import type { ContinueItem } from '../state/catalog.js';
import type { Movie, Series } from '@mfp/core';
import { HeroCarousel, type HeroItem } from '../components/HeroCarousel.js';
import { VirtualRow } from '../components/VirtualRow.js';
import { PosterCard } from '../components/PosterCard.js';
import { EmptyState, LoadingState } from '../components/states.js';
import { FocusButton } from '../components/FocusButton.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useProvider } from '../runtime/useProvider.js';
import { useCatalog } from '../state/catalog.js';
import { useSync } from '../state/sync.js';
import { useNavigation } from '../nav/navigationStack.js';
import { useFocusGuard } from '../nav/focusGuard.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapVar } from '../theme/gap.js';

// Sem closure — estáveis para sempre (PERF-09 / spec 002): a folha (`renderItem`)
// não precisa saber de nada além do próprio item.
const renderMovie = (m: Movie, i: number, focused: boolean) => (
  <PosterCard
    focused={focused}
    prioridade={i}
    data={{ title: m.name, poster: m.poster }}
  />
);
const renderSeries = (s: Series, i: number, focused: boolean) => (
  <PosterCard
    focused={focused}
    prioridade={i}
    data={{ title: s.name, poster: s.poster }}
  />
);
const renderContinue = (p: ContinueItem, i: number, focused: boolean) => (
  <PosterCard
    focused={focused}
    prioridade={i}
    data={{
      title: p.title,
      ...(p.poster ? { poster: p.poster } : {}),
      progress: p.durationSecs ? p.positionSecs / p.durationSecs : 0,
    }}
  />
);

export function Home({ listId }: { listId: string }) {
  const rt = useRuntime();
  const { recentMovies, recentSeries, continueWatching, counts, loaded, loadHome } =
    useCatalog();
  const runSync = useSync((s) => s.run);
  const stalled = useSync(
    (s) =>
      s.sections.live.status === 'stalled' ||
      s.sections.vod.status === 'stalled' ||
      s.sections.series.status === 'stalled',
  );
  const getProvider = useProvider();
  const push = useNavigation((s) => s.push);
  // LG-022: sync parou por cota antes de terminar — tenta de novo em vez de
  // deixar o usuário preso no spinner eterno de `boot.firstSync`. `stalled` só
  // fica `true` por estouro de cota (`CatalogSync` só marca `cancelled` nesse
  // caso), então repetir sem antes liberar espaço bateria na mesma parede na
  // hora — a limpeza reconstruível (LS-RF-15) roda primeiro, preservando
  // favoritos/progresso.
  const onRetrySync = useCallback(() => {
    void (async () => {
      const { provider } = await getProvider();
      await rt.db.wipeReconstructibleCache(listId);
      await runSync(rt, listId, provider);
      await loadHome(rt, listId);
    })();
  }, [getProvider, runSync, loadHome, rt, listId]);

  const openMovie = useCallback(
    (m: Movie) => push({ name: 'movieDetail', params: { id: m.id } }),
    [push],
  );
  const openSeries = useCallback(
    (sr: Series) => push({ name: 'seriesDetail', params: { id: sr.id } }),
    [push],
  );
  const openContinue = useCallback(
    (p: ContinueItem) =>
      // episódio abre a série a que pertence, não a tela de filme
      p.seriesId
        ? push({ name: 'seriesDetail', params: { id: p.seriesId } })
        : push({
            name: p.kind === 'series' ? 'seriesDetail' : 'movieDetail',
            params: { id: p.id },
          }),
    [push],
  );

  useEffect(() => {
    void loadHome(rt, listId);
  }, [rt, listId, loadHome]);

  const total = counts.vod + counts.series + counts.live;

  // RP-1 (spec 002): a marca `boot:homeInteractive` mora em `ActiveList`
  // (App.tsx), não aqui — o RF-56 (boot → última seção) costuma tirar o
  // usuário da Home antes de `loadHome` terminar, e um efeito só reage
  // enquanto o componente que o declara está montado.

  // A Início é a tela para onde o app sempre volta (BACK do player, do catálogo…)
  // e é montada com os dados ainda carregando, então não tem um "foco inicial"
  // próprio: o guarda assume assim que houver algo focável.
  useFocusGuard(['home-hero', 'home-continue', 'header-home'], [total]);
  if (total === 0) {
    // Distingue "ainda lendo o cache" (comum: acontece a cada reabertura do
    // app, a store zera com o processo) de "catálogo mesmo vazio" — só o
    // segundo caso justifica o aviso de primeira sincronização.
    if (!loaded) return <LoadingState label={t('nav.home')} />;
    if (stalled) {
      return (
        <EmptyState
          title={t('nav.home')}
          body={t('boot.syncStalled')}
          action={
            <FocusButton
              primary
              autoFocus
              focusKey="home-retry-sync"
              onPress={onRetrySync}
            >
              {t('common.retry')}
            </FocusButton>
          }
        />
      );
    }
    return <EmptyState loading title={t('nav.home')} body={t('boot.firstSync')} />;
  }

  const heroItems: HeroItem[] = recentMovies.slice(0, 6).map((m) => ({
    id: m.id,
    title: m.name,
    poster: m.poster,
    meta: m.rating ? `★ ${m.rating.toFixed(1)}` : undefined,
  }));

  return (
    <div
      className={gapColClass}
      style={{ display: 'flex', flexDirection: 'column', ...gapVar('var(--row-gap)') }}
    >
      {heroItems.length > 0 && (
        <HeroCarousel
          focusKey="home-hero"
          items={heroItems}
          onWatch={(it) => {
            const m = recentMovies.find((x) => x.id === it.id);
            if (m) openMovie(m);
          }}
          onInfo={(it) => {
            const m = recentMovies.find((x) => x.id === it.id);
            if (m) openMovie(m);
          }}
        />
      )}

      {continueWatching.length > 0 && (
        <Track title={t('home.continueWatching')}>
          <VirtualRow<ContinueItem>
            focusKey="home-continue"
            restoreKey="home-continue"
            items={continueWatching}
            visibleCount={4}
            aspectRatio={0.58}
            renderItem={renderContinue}
            onItemPress={openContinue}
          />
        </Track>
      )}

      <Track title={t('home.recentMovies')}>
        <VirtualRow<Movie>
          focusKey="home-movies"
          restoreKey="home-movies"
          items={recentMovies}
          visibleCount={6}
          renderItem={renderMovie}
          onItemPress={openMovie}
        />
      </Track>

      <Track title={t('home.recentSeries')}>
        <VirtualRow<Series>
          focusKey="home-series"
          restoreKey="home-series"
          items={recentSeries}
          visibleCount={6}
          renderItem={renderSeries}
          onItemPress={openSeries}
        />
      </Track>
    </div>
  );
}

function Track({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section>
      <h3 style={{ fontSize: 'var(--fs-section)' }}>{title}</h3>
      {children}
    </section>
  );
}
