import {
  AuraDb,
  CatalogGateway,
  EpgRepo,
  EpgSync,
  HttpClient,
  CatalogSync,
  SearchRepo,
  XtreamProvider,
  createLogger,
  consoleSink,
  criarPerf,
  offsetOf,
  type CatalogPolicy,
  type IptvProvider,
  type Logger,
  type Perf,
} from '@mfp/core';
import type { PlatformAdapter } from '@mfp/platform';
import type { StoredList } from '@mfp/core';

/**
 * Raiz de composição (plan.md §Layout): instancia os serviços do `core` e injeta o
 * `PlatformAdapter`. `core`/`ui` nunca importam uma impl de plataforma — ela chega
 * aqui, montada pelo `apps/<plataforma>`.
 */
export interface Runtime {
  db: AuraDb;
  adapter: PlatformAdapter;
  logger: Logger;
  /**
   * Marcas de performance para o orçamento do RF-68 (spec 002). A casca publica
   * `globalThis.__auraPerf` para o roteiro de medição ler — nunca em release.
   */
  perf: Perf;
  /** Cliente HTTP compartilhado — usado fora dos providers (ex.: autoconfiguração). */
  http: HttpClient;
  /**
   * Política de conteúdo em vigor, aplicada a toda leitura de catálogo e busca.
   * É mutável de propósito: o controle parental altera `hideAdult` em tempo de
   * execução e as fábricas abaixo leem o valor **na hora da chamada**.
   */
  contentPolicy: CatalogPolicy;
  /** Repositório de catálogo já com a política aplicada — use sempre este. */
  catalog(listId: string): CatalogGateway;
  /** Índice de busca já com a política aplicada — use sempre este. */
  search(listId: string): SearchRepo;
  /** Descarta memoizações de leitura após atualizar/remover o catálogo. */
  invalidateCatalog(listId: string): void;
  /** Leitura do EPG local (XMLTV — D-22). */
  epg(listId: string): EpgRepo;
  makeProvider(
    list: Pick<
      StoredList,
      'serverUrl' | 'username' | 'userAgent' | 'livePathSegment' | 'preferredHttpsBase'
    >,
    password: string,
  ): XtreamProvider;
  makeSync(listId: string, provider: IptvProvider): CatalogSync;
  makeEpgSync(listId: string, provider: IptvProvider, serverTimezone?: string): EpgSync;
}

export function createRuntime(adapter: PlatformAdapter): Runtime {
  const logger = createLogger({
    level: 'info',
    sinks: [consoleSink],
    base: { platform: adapter.name },
  });
  const db = new AuraDb();
  const contentPolicy: CatalogPolicy = {};
  const http = new HttpClient();

  // relógio de alta resolução do navegador/WebView — o core não o acessa direto
  // (constitution §2), a composição injeta
  const perf = criarPerf(() =>
    typeof performance !== 'undefined' ? performance.now() : Date.now(),
  );
  // a casca captura `performance.now()` antes do React existir e o deixa aqui;
  // sem isso o `boot:start` nasceria já dentro do 1º render
  const bootT0 = (globalThis as { __auraBootT0?: number }).__auraBootT0;
  if (typeof bootT0 === 'number') perf.marcarUnica('boot:start', undefined, bootT0);

  // PERF-07 (spec 002): antes, cada `rt.catalog(listId)` criava uma instância
  // nova — o `indiceCompletoCache`/`bloqueadas` do `CatalogRepo` (PERF-01a)
  // são memoizados NA INSTÂNCIA, então recriá-la a cada chamada jogava fora
  // esse cache. Foi como o bug real do PERF-01a apareceu (`home:load` de
  // 2032ms→3917ms antes de eu perceber): o custo de recontar `indiceCompleto`
  // ficava mascarado num teste que sempre usava a MESMA instância, e só
  // apareceu medindo no aparelho contra o runtime de verdade.
  //
  // Sem invalidação por `contentPolicy.hideAdult` (diferente do desenho
  // original): `policy` é a MESMA referência de objeto sempre — o repo lê
  // `this.policy.hideAdult` na hora de cada chamada, nunca guarda o valor no
  // construtor. O cache interno que sobra (`bloqueadas`, os ids de categoria
  // adulta) não depende do VALOR do toggle, só de quais categorias SÃO
  // adultas — um fato do conteúdo, não da política — então reusar a
  // instância através de um toggle de `hideAdult` é seguro sem invalidar nada.
  const catalogRepos = new Map<string, CatalogGateway>();
  const searchRepos = new Map<string, SearchRepo>();
  const epgRepos = new Map<string, EpgRepo>();

  return {
    db,
    adapter,
    http,
    perf,
    contentPolicy,
    invalidateCatalog(listId) {
      catalogRepos.delete(listId);
      searchRepos.delete(listId);
    },
    catalog: (listId) => {
      let repo = catalogRepos.get(listId);
      if (!repo) {
        repo = new CatalogGateway(db, listId, contentPolicy);
        catalogRepos.set(listId, repo);
      }
      return repo;
    },
    search: (listId) => {
      let repo = searchRepos.get(listId);
      if (!repo) {
        repo = new SearchRepo(db, listId, contentPolicy);
        searchRepos.set(listId, repo);
      }
      return repo;
    },
    epg: (listId) => {
      let repo = epgRepos.get(listId);
      if (!repo) {
        repo = new EpgRepo(db, listId);
        epgRepos.set(listId, repo);
      }
      return repo;
    },
    logger,
    makeProvider(list, password) {
      return new XtreamProvider({
        serverUrl: list.serverUrl,
        username: list.username,
        password,
        userAgent: list.userAgent,
        // o segmento aprendido para esta lista; sem isto, o valor era gravado
        // em `lists` e ignorado na hora de montar a URL do stream
        livePathSegment: list.livePathSegment,
        knownHttpsBase: list.preferredHttpsBase,
      });
    },
    makeSync(listId, provider) {
      return new CatalogSync({ db, provider, listId, logger });
    },
    makeEpgSync(listId, provider, serverTimezone) {
      return new EpgSync({
        db,
        provider,
        listId,
        logger,
        // fuso do painel → minutos, só para XMLTV sem offset e sem timestamp
        ...(serverTimezone
          ? { fallbackOffsetMinutes: offsetOf(serverTimezone, Date.now()) }
          : {}),
      });
    },
  };
}

/** Chave da senha da lista no secure storage da plataforma (constitution §9). */
export const passwordKey = (listId: string) => `list.pw.${listId}`;
export const ACTIVE_LIST_KEY = 'list.active';
