import { create } from 'zustand';
import type { StreamKindPB } from '@mfp/core';

// Fila de reprodução para zapping (D-pad ChannelUp/Down no player) e "próximo
// episódio". Setada antes de navegar para a tela do player.

export interface QueueItem {
  id: string;
  title: string;
  subtitle?: string;
  ext?: string;
  startAtSecs?: number;
  /** Número do canal — barra de info e salto por número no player (só live). */
  num?: number;
  logo?: string;
}

interface NowPlayingState {
  kind: StreamKindPB | null;
  items: QueueItem[];
  index: number;
  setQueue: (kind: StreamKindPB, items: QueueItem[], index: number) => void;
  clear: () => void;
  /** move o índice; retorna o item novo ou null se fora dos limites. */
  step: (delta: number) => QueueItem | null;
  goto: (index: number) => QueueItem | null;
}

export const useNowPlaying = create<NowPlayingState>((set, get) => ({
  kind: null,
  items: [],
  index: 0,
  setQueue: (kind, items, index) => set({ kind, items, index }),
  clear: () => set({ kind: null, items: [], index: 0 }),
  step: (delta) => {
    const { items, index } = get();
    const next = index + delta;
    if (next < 0 || next >= items.length) return null;
    set({ index: next });
    return items[next] ?? null;
  },
  goto: (index) => {
    const { items } = get();
    if (index < 0 || index >= items.length) return null;
    set({ index });
    return items[index] ?? null;
  },
}));
