/**
 * `min()`/`max()`/`clamp()` (CSS Values 4) só chegaram no Chrome 79 — TV LG
 * real roda Chrome 53 (achado em campo, 2026-09-13: toda a escala do app,
 * baseada nisso, ficava travada no tamanho padrão do navegador). Diferente de
 * sintaxe de linguagem, Web APIs/funções CSS não são cobertas pelo Babel/
 * core-js do build legacy — ou o motor entende, ou a declaração inteira é
 * descartada, sem erro.
 *
 * `cssLen()` resolve essas funções em JS usando `window.innerWidth/Height`
 * (fixos numa TV — sem media query dinâmica necessária) e o font-size raiz
 * corrente para `rem`/`em`, só quando o motor não suporta nativamente
 * (feature-detect uma vez, cacheado). Em qualquer motor moderno é passthrough
 * puro — zero custo, zero mudança de comportamento.
 *
 * Cobre exatamente os padrões usados no app: `min(a, b)`, `max(a, b)`,
 * `clamp(min, pref, max)`, `calc(a ± b)`, `var(--x)`/`var(--x, fallback)`,
 * aninhados, e listas separadas por espaço (ex. padding `"min(a,b) min(c,d)"`).
 * `%` é resolvido contra a largura da janela — aproximação correta para os
 * usos atuais (containers full-bleed ou próximos disso); não serve para um
 * `%` aninhado num container estreito arbitrário.
 */

let suportaNativo: boolean | null = null;

function suportaMinMaxClamp(): boolean {
  if (suportaNativo === null) {
    suportaNativo =
      typeof CSS !== 'undefined' &&
      typeof CSS.supports === 'function' &&
      CSS.supports('width', 'min(1px, 2px)');
  }
  return suportaNativo;
}

function rootFontSizePx(): number {
  if (typeof document === 'undefined') return 16;
  const fs = window.getComputedStyle(document.documentElement).fontSize;
  const n = parseFloat(fs);
  return Number.isFinite(n) && n > 0 ? n : 16;
}

const NUM_UNIT = /^(-?\d*\.?\d+)(px|rem|em|vw|vh|%)?$/;

function unidadeParaPx(valor: number, unidade: string): number {
  switch (unidade) {
    case 'rem':
    case 'em':
      return valor * rootFontSizePx();
    case 'vw':
      return (valor / 100) * window.innerWidth;
    case 'vh':
      return (valor / 100) * window.innerHeight;
    case '%':
      // aproximação: sem o container real, assume contexto full-bleed
      return (valor / 100) * window.innerWidth;
    default:
      return valor;
  }
}

/** Separa por vírgulas/espaços de nível zero (fora de parênteses aninhados). */
function separarNivelZero(s: string, sep: ',' | ' '): string[] {
  const partes: string[] = [];
  let atual = '';
  let profundidade = 0;
  for (const ch of s) {
    if (ch === '(') profundidade++;
    if (ch === ')') profundidade--;
    if (profundidade === 0 && ch === sep && atual.trim()) {
      partes.push(atual.trim());
      atual = '';
      continue;
    }
    if (profundidade === 0 && ch === sep && !atual.trim()) continue;
    atual += ch;
  }
  if (atual.trim()) partes.push(atual.trim());
  return partes;
}

function resolverVar(termo: string): string {
  // var(--x) ou var(--x, fallback)
  const dentro = termo.slice(4, -1); // remove "var(" e ")"
  const partes = separarNivelZero(dentro, ',');
  const nome = partes[0]!.trim();
  const valor = document.documentElement.style.getPropertyValue(nome).trim() ||
    window.getComputedStyle(document.documentElement).getPropertyValue(nome).trim();
  if (valor) return valor;
  return partes[1] ?? '0px';
}

function resolverTermo(termoBruto: string): number {
  const termo = termoBruto.trim();
  if (termo.startsWith('calc(')) return resolverExpressao(termo.slice(5, -1));
  if (termo.startsWith('min(')) {
    const args = separarNivelZero(termo.slice(4, -1), ',').map(resolverTermo);
    return Math.min(...args);
  }
  if (termo.startsWith('max(')) {
    const args = separarNivelZero(termo.slice(4, -1), ',').map(resolverTermo);
    return Math.max(...args);
  }
  if (termo.startsWith('clamp(')) {
    const [minV, prefV, maxV] = separarNivelZero(termo.slice(6, -1), ',').map(resolverTermo);
    return Math.min(maxV!, Math.max(minV!, prefV!));
  }
  if (termo.startsWith('var(')) return resolverTermo(resolverVar(termo));
  const m = NUM_UNIT.exec(termo);
  if (m) return unidadeParaPx(parseFloat(m[1]!), m[2] ?? 'px');
  return 0;
}

/** `calc(a + b - c)` — só +/- de nível zero, suficiente para os usos daqui. */
function resolverExpressao(expr: string): number {
  let total = 0;
  let sinal = 1;
  let atual = '';
  let profundidade = 0;
  const fechar = () => {
    if (atual.trim()) total += sinal * resolverTermo(atual);
    atual = '';
  };
  for (const ch of expr) {
    if (ch === '(') profundidade++;
    if (ch === ')') profundidade--;
    if (profundidade === 0 && (ch === '+' || ch === '-') && atual.trim()) {
      fechar();
      sinal = ch === '+' ? 1 : -1;
      continue;
    }
    atual += ch;
  }
  fechar();
  return total;
}

/**
 * Resolve uma expressão CSS (possivelmente com vários termos separados por
 * espaço, ex. shorthand de `padding`) para pixels fixos, só quando o motor
 * não suporta `min`/`max`/`clamp` nativamente. Em motor moderno devolve a
 * string original sem tocar nela.
 */
export function cssLen(expr: string): string {
  if (!expr || suportaMinMaxClamp()) return expr;
  if (!/\b(min|max|clamp)\(/.test(expr)) return expr;
  try {
    return separarNivelZero(expr, ' ')
      .map((termo) => `${Math.round(resolverTermo(termo) * 100) / 100}px`)
      .join(' ');
  } catch {
    return expr;
  }
}

/** Só para teste: força o resultado do feature-detect na próxima chamada. */
export function _resetCacheParaTeste(valor: boolean | null = null): void {
  suportaNativo = valor;
}

/**
 * `html { font-size: clamp(...) }` e `--header-h` (tokens.css) vivem em CSS
 * estático — não dá pra interceptar isso com `cssLen()` (só serve pra style
 * inline). Chamar uma vez no boot da casca (antes do primeiro render) escreve
 * o valor calculado como propriedade inline na raiz, que tem prioridade sobre
 * a declaração da folha de estilo — só roda de verdade quando o motor não
 * suporta `min/max/clamp` nativamente.
 */
export function aplicarFallbackCssRaiz(): void {
  if (suportaMinMaxClamp()) return;
  const raiz = document.documentElement;
  raiz.style.fontSize = cssLen('clamp(13px, min(1.3vw, 2.35vh), 42px)');
  raiz.style.setProperty('--header-h', cssLen('clamp(3rem, 8vh, 4.4rem)'));
}
