/** Compartilha uma operação em andamento sem reter seu resultado após terminar. */
export function createSingleFlight<T>() {
  const pending = new WeakMap<object, Map<string, Promise<T>>>();

  return (scope: object, key: string, work: () => Promise<T>): Promise<T> => {
    let operations = pending.get(scope);
    if (!operations) {
      operations = new Map();
      pending.set(scope, operations);
    }
    const existing = operations.get(key);
    if (existing) return existing;

    // Registra antes de iniciar: chamadas concorrentes no mesmo tick também aderem.
    const result = Promise.resolve()
      .then(work)
      .finally(() => {
        operations.delete(key);
      });
    operations.set(key, result);
    return result;
  };
}
