import { create } from 'zustand';
import { type CatalogSort, type Category } from '@mfp/core';
import type { Runtime } from '../runtime/runtime.js';
import { useToast } from '../components/Toast.js';
import { t } from '../i18n/index.js';

// Navegação de catálogo VOD/Séries (telas 04/06): categorias como "gêneros",
// ordenação client-side (nome/nota) ou por índice (recente — PERF-01a), busca
// pelo índice local (constitution §6).

export type BrowseSection = 'vod' | 'series';

export interface BrowseItem {
  id: string;
  name: string;
  poster?: string;
  categoryId?: string;
  rating?: number;
}

interface BrowseState {
  listId: string | null;
  section: BrowseSection;
  categories: Category[];
  categoryId: string | null;
  sort: CatalogSort;
  query: string;
  items: BrowseItem[];
  total: number;
  /** Presente = há mais itens; `carregarMais` busca a próxima leva. `undefined`
   *  também quando a lista é filtrada por categoria (aí já vem inteira). */
  cursor?: string;
  /** Evita disparar duas buscas da próxima página ao mesmo tempo (rolagem rápida). */
  carregandoMais: boolean;
  /**
   * Leva ainda a caminho (`load`/`setCategory`/`setSort`/`setQuery`) — enquanto
   * `true`, `items.length === 0` não significa "vazio de fato", só que a busca
   * nova ainda não respondeu. Sem isto a tela mostrava "NADA POR AQUI" a cada
   * troca de categoria, antes de confirmar que realmente não há resultado.
   */
  carregando: boolean;
  /**
   * Mensagem da última falha ao buscar (LS-030, spec 005 M3) — `null` enquanto
   * tudo vai bem. `buscarPrimeiraLeva` pode rejeitar (painel fora do ar, quota
   * estourada) e antes disso a rejeição não tinha NENHUM observador: a tela
   * ficava presa em `carregando: true` para sempre (o "spinner travado" de
   * `research.md` §8, aqui na troca de gênero/ordenação/busca, não só no boot).
   * Quando `items` já tem conteúdo de antes, o erro não apaga a grade — só
   * dispara um toast (ver `Catalog.tsx`); sem itens, a tela mostra `ErrorScreen`
   * com retry.
   */
  erro: string | null;
  /**
   * Incrementado a cada `load`/`setCategory`/`setSort`/`setQuery` — usado só
   * para descartar um `total` que chegue depois de o usuário já ter mudado de
   * categoria/ordenação/busca de novo (a contagem agora resolve em paralelo,
   * sem bloquear a pintura da página).
   */
  geracaoBusca: number;
  /**
   * @param manter não recarrega se esta mesma lista/seção já estiver carregada —
   * usado ao **voltar** para o catálogo, para não apagar gênero, ordenação e
   * busca (e, com eles, a posição em que a grade estava).
   */
  load: (
    rt: Runtime,
    listId: string,
    section: BrowseSection,
    manter?: boolean,
  ) => Promise<void>;
  setCategory: (rt: Runtime, listId: string, categoryId: string | null) => Promise<void>;
  setSort: (rt: Runtime, listId: string, sort: CatalogSort) => Promise<void>;
  setQuery: (rt: Runtime, listId: string, query: string) => Promise<void>;
  /** Busca a próxima leva e anexa a `items` — chamado quando a grade se aproxima do fim. */
  carregarMais: (rt: Runtime, listId: string) => Promise<void>;
  /**
   * Refaz a busca atual depois de `erro` (LS-030) — não é `setCategory`/
   * `setSort`/`setQuery` de novo: aquelas saem cedo quando o valor não mudou
   * (`categoryId === categoryId`), o que faria o botão de retry não fazer nada
   * quando a falha aconteceu sem trocar nenhum filtro. Também recarrega
   * `categories` quando ela está vazia — cobre a falha em `load()`, que busca
   * categorias e itens juntos.
   */
  retry: (rt: Runtime, listId: string) => Promise<void>;
}

/**
 * Tamanho de cada leva na visão "todas as categorias" (PERF-01a / spec 002).
 *
 * Antes disto era um TETO fixo de 3.000 — cortado depois de materializar e
 * ordenar o acervo inteiro (42.640 filmes medidos, ~1,5s de leitura + ~0,5s de
 * ordenação), então não economizava nada. Agora é o tamanho de página de uma
 * rolagem infinita: a primeira leva sai do índice em milissegundos, e a grade
 * pede mais conforme o usuário rola (`onChegouPertoDoFim` do `VirtualGrid`).
 * Uma categoria específica continua vindo inteira de uma vez — é barata (a
 * maior tem ~11 mil itens, ~120ms) e não paginamos por categoria (plan §2.6).
 */
const TAMANHO_DA_LEVA = 200;

interface Busca {
  items: BrowseItem[];
  total: number;
  cursor?: string;
  /**
   * Resolve com a contagem exata — separado de propósito (achado medindo no
   * tablet: `contar()` levava até 510ms em `series`, e travava a pintura da
   * grade esperando os dois em `Promise.all`, mesmo a página em si já estando
   * pronta). O total exibido ("200 de X títulos") pode chegar alguns
   * milissegundos depois dos itens, sem bloquear a primeira pintura.
   */
  totalPromise?: Promise<number>;
}

async function buscarPrimeiraLeva(
  rt: Runtime,
  listId: string,
  s: Pick<BrowseState, 'section' | 'query' | 'categoryId' | 'sort'>,
): Promise<Busca> {
  if (s.query.trim().length >= 2) {
    const hits = await rt.search(listId).query(s.query, { kind: s.section, limit: 300 });
    const items = hits.map(paraBrowseItem);
    return { items, total: items.length }; // busca não pagina — teto de 300 já existia
  }

  const repo = rt.catalog(listId);
  const contar = () =>
    s.section === 'vod'
      ? repo.countMovies({ categoryId: s.categoryId ?? undefined })
      : repo.countSeries({ categoryId: s.categoryId ?? undefined });
  const buscarPagina = () => {
    // Achado real (2026-09-15): "categoria inteira é barata" não se sustentou —
    // uma categoria de 11.019 itens levava ~950ms pelo caminho antigo
    // (materializa + ordena tudo em JS). `CatalogRepo` pagina categoria pelo
    // índice de `categoryMembers` quando ele existe (`paginaCategoriaIndexada`),
    // então pedir `limit` aqui também é seguro e sempre foi o certo a fazer.
    const opts = {
      categoryId: s.categoryId ?? undefined,
      sort: s.sort,
      limit: TAMANHO_DA_LEVA,
    };
    return s.section === 'vod' ? repo.moviesPage(opts) : repo.seriesPage(opts);
  };
  // `contar()` roda em paralelo, mas NÃO é esperado aqui — só a página.
  // Achado real (2026-09-15, medido num tablet): a contagem de `series`
  // chegou a levar ~510ms, e travava a pintura da grade mesmo com a página já
  // pronta bem antes, porque as duas eram esperadas juntas num `Promise.all`.
  // O total exibido ("200 de X títulos") chega depois, assíncrono, via
  // `totalPromise`, sem bloquear a primeira pintura.
  // A contagem não bloqueia a página nem deixa uma rejeição sem observador
  // enquanto a leitura dos itens ainda está em andamento.
  const totalPromise = contar().catch((err: unknown) => {
    rt.logger.warn('falha ao contar catálogo', { err: String(err) });
    return 0;
  });
  const pagina = await buscarPagina();
  return {
    items: pagina.items.map(paraBrowseItem),
    total: pagina.items.length, // placeholder até `totalPromise` resolver
    totalPromise,
    ...(pagina.cursor ? { cursor: pagina.cursor } : {}),
  };
}

function paraBrowseItem(r: {
  id: string;
  name: string;
  poster?: string;
  categoryId?: string;
  rating?: number;
}): BrowseItem {
  return {
    id: r.id,
    name: r.name,
    ...(r.poster !== undefined ? { poster: r.poster } : {}),
    ...(r.categoryId !== undefined ? { categoryId: r.categoryId } : {}),
    ...(r.rating !== undefined ? { rating: r.rating } : {}),
  };
}

export const useBrowse = create<BrowseState>((set, get) => {
  /**
   * Aplica items/cursor assim que a página chega (sem esperar a contagem) e
   * atualiza `total` depois, só se o usuário não tiver disparado outra busca
   * enquanto isso (`geracaoBusca` mudou).
   */
  const aplicarBusca = (token: number, busca: Busca) => {
    if (get().geracaoBusca !== token) return;
    const { totalPromise, ...resto } = busca;
    set({ ...resto, cursor: busca.cursor, carregando: false });
    totalPromise?.then((total) => {
      if (get().geracaoBusca === token)
        set({ total: Math.max(total, get().items.length) });
    });
  };

  return {
    listId: null,
    section: 'vod',
    categories: [],
    categoryId: null,
    sort: 'recent',
    query: '',
    items: [],
    total: 0,
    cursor: undefined,
    carregandoMais: false,
    carregando: false,
    erro: null,
    geracaoBusca: 0,

    load: async (rt, listId, section, manter = false) => {
      const s = get();
      if (manter && s.listId === listId && s.section === section && s.items.length > 0) {
        return;
      }
      const token = s.geracaoBusca + 1;
      set({
        listId,
        section,
        categories: [],
        items: [],
        total: 0,
        categoryId: null,
        query: '',
        sort: 'recent',
        cursor: undefined,
        carregandoMais: false,
        carregando: true,
        erro: null,
        geracaoBusca: token,
      });
      try {
        // Sem chip "Todos" (removido — o filtro geral já cobre esse caso), a
        // categoria ativa ao abrir é a primeira real da lista, como no Live —
        // senão a grade abre sem filtro e sem nenhum chip destacado, dando a
        // impressão de que "Todos" ainda está selecionado por baixo dos panos.
        const categories = await rt.catalog(listId).categories(section);
        if (
          get().listId !== listId ||
          get().section !== section ||
          get().geracaoBusca !== token
        )
          return;
        const categoryId = categories[0]?.id ?? null;
        set({ categories, categoryId });
        aplicarBusca(token, await buscarPrimeiraLeva(rt, listId, get()));
      } catch (err) {
        falhouBusca(rt, get, set, token, listId, section, err);
      }
    },

    setCategory: async (rt, listId, categoryId) => {
      if (get().categoryId === categoryId && !get().query) return;
      rt.perf.marcar('browse:change', { tipo: 'categoria' }); // RP-6 (spec 002)
      const token = get().geracaoBusca + 1;
      const section = get().section;
      set({
        categoryId,
        query: '',
        cursor: undefined,
        carregandoMais: false,
        carregando: true,
        erro: null,
        geracaoBusca: token,
      });
      try {
        aplicarBusca(token, await buscarPrimeiraLeva(rt, listId, get()));
      } catch (err) {
        falhouBusca(rt, get, set, token, listId, section, err);
      }
    },

    setSort: async (rt, listId, sort) => {
      if (get().sort === sort) return;
      rt.perf.marcar('browse:change', { tipo: 'ordenacao' });
      const token = get().geracaoBusca + 1;
      const section = get().section;
      set({
        sort,
        cursor: undefined,
        carregandoMais: false,
        carregando: true,
        erro: null,
        geracaoBusca: token,
      });
      try {
        aplicarBusca(token, await buscarPrimeiraLeva(rt, listId, get()));
      } catch (err) {
        falhouBusca(rt, get, set, token, listId, section, err);
      }
    },

    setQuery: async (rt, listId, query) => {
      if (get().query === query) return;
      rt.perf.marcar('browse:change', { tipo: 'busca' });
      const token = get().geracaoBusca + 1;
      const section = get().section;
      set({
        query,
        cursor: undefined,
        carregandoMais: false,
        carregando: true,
        erro: null,
        geracaoBusca: token,
      });
      try {
        aplicarBusca(token, await buscarPrimeiraLeva(rt, listId, get()));
      } catch (err) {
        falhouBusca(rt, get, set, token, listId, section, err);
      }
    },

    carregarMais: async (rt, listId) => {
      const s = get();
      if (s.carregandoMais || !s.cursor || s.listId !== listId) return;
      set({ carregandoMais: true });
      try {
        const repo = rt.catalog(listId);
        const opts = {
          categoryId: s.categoryId ?? undefined,
          sort: s.sort,
          limit: TAMANHO_DA_LEVA,
          cursor: s.cursor,
        };
        const pagina =
          s.section === 'vod' ? await repo.moviesPage(opts) : await repo.seriesPage(opts);
        // a leva pode ter chegado depois de o usuário trocar de gênero/busca —
        // não anexa numa lista que não é mais esta
        if (
          get().listId !== listId ||
          get().geracaoBusca !== s.geracaoBusca ||
          get().cursor !== s.cursor
        )
          return;
        set({
          items: [...s.items, ...pagina.items.map(paraBrowseItem)],
          cursor: pagina.cursor,
        });
      } catch (err) {
        // A grade já tem itens (é uma continuação) — nunca troca por tela de
        // erro, só avisa e deixa o cursor como estava para uma nova tentativa
        // ao rolar de novo.
        rt.logger.warn('carregarMais falhou', { listId, err: String(err) });
        useToast.getState().show(t('catalog.updateFailedToast'), 'error');
      } finally {
        if (get().geracaoBusca === s.geracaoBusca) set({ carregandoMais: false });
      }
    },

    retry: async (rt, listId) => {
      const s = get();
      if (s.listId !== listId || !s.erro) return;
      const { section } = s;
      const token = s.geracaoBusca + 1;
      set({ carregando: true, erro: null, geracaoBusca: token });
      try {
        let categories = s.categories;
        let categoryId = s.categoryId;
        if (categories.length === 0) {
          // a falha original foi em `load()`, antes de categorias existirem
          categories = await rt.catalog(listId).categories(section);
          if (get().listId !== listId || get().geracaoBusca !== token) return;
          categoryId = categories[0]?.id ?? null;
          set({ categories, categoryId });
        }
        aplicarBusca(token, await buscarPrimeiraLeva(rt, listId, get()));
      } catch (err) {
        falhouBusca(rt, get, set, token, listId, section, err);
      }
    },
  };
});

/**
 * Compartilhado pelas 4 ações que buscam catálogo (LS-030): descarta a falha
 * se uma busca mais nova já começou, preserva `items` existentes (nunca troca
 * por tela vazia por causa de uma falha de atualização) e só toca o estado
 * `erro` — que `Catalog.tsx` decide como mostrar (tela cheia sem itens, toast
 * com itens).
 */
function falhouBusca(
  rt: Runtime,
  get: () => BrowseState,
  set: (partial: Partial<BrowseState>) => void,
  token: number,
  listId: string,
  section: BrowseSection,
  err: unknown,
): void {
  if (get().geracaoBusca !== token) return; // usuário já trocou de novo — descarta
  rt.logger.error('busca de catálogo falhou', { listId, section, err: String(err) });
  set({ carregando: false, erro: String(err) });
  if (get().items.length > 0) {
    useToast.getState().show(t('catalog.updateFailedToast'), 'error');
  }
}
