import {
  CatalogRepo,
  CHAVE_CATEGORIAS_MULTIPLAS,
  GERACAO_CATEGORIAS_MULTIPLAS,
  invalidarIndiceCompleto,
} from '../cache/catalogRepo.js';
import { DEFAULT_CACHE_CONFIG, type CacheConfig } from '../cache/config.js';
import type { AuraDb, CatalogSection } from '../cache/db.js';
import { MetaRepo } from '../cache/metaRepo.js';
import {
  evictInfoLru,
  isLowStorageDevice,
  isQuotaExceededError,
  storageEstimate,
} from '../cache/quota.js';
import { SearchRepo, toSearchItem } from '../cache/searchRepo.js';
import { isStale } from '../cache/ttl.js';
import { nullLogger, type Logger } from '../log/logger.js';
import type { Category, Channel, Movie, Series } from '../models/index.js';
import type { IptvProvider } from '../providers/IptvProvider.js';
import { Emitter } from '../util/emitter.js';
import { normalizeText } from '../util/normalize.js';
import { mapPool } from '../util/pool.js';

type Item = Channel | Movie | Series;

export interface SyncEvents {
  'section:start': { section: CatalogSection; totalCategories: number; resumed: boolean };
  'section:progress': {
    section: CatalogSection;
    done: number;
    total: number;
    categoryName: string;
    items: number;
  };
  'section:done': { section: CatalogSection; itemCount: number; pruned: number };
  'section:skip': { section: CatalogSection; reason: 'fresh' };
  'section:error': { section: CatalogSection; error: unknown };
  'sync:done': { ran: CatalogSection[] };
}

export interface SyncResult {
  ran: CatalogSection[];
  skipped: CatalogSection[];
  failed: CatalogSection[];
  cancelled: boolean;
}

export interface CatalogSyncDeps {
  db: AuraDb;
  provider: IptvProvider;
  listId: string;
  config?: CacheConfig;
  logger?: Logger;
}

export interface RunOptions {
  sections?: CatalogSection[];
  /** Ignora TTL e estado de retomada — sync completo do zero. */
  force?: boolean;
  /**
   * `max_connections` da conta (PERF-20 / spec 002, precedente D-14): teto
   * duro pra concorrência de categorias — nunca abrir mais conexões
   * simultâneas ao painel do que a conta permite, senão o próprio provedor
   * derruba a mais nova (ou todas). `undefined`/`0` = sem teto adicional além
   * do já configurado.
   */
  maxConnections?: number;
  /**
   * Sobrescreve `CacheConfig.sync.maxItemsPerCategoryLowStorage` (LG-022) só
   * nesta rodada. Exposto na tela de Configurações (spec 003, decisão de
   * 2026-09-14): o valor por categoria é um chute pragmático sem cota oficial
   * pra mirar, então dá pra ajustar em campo sem depender de um novo build a
   * cada tentativa. Só tem efeito quando `isLowStorageDevice()` é `true`.
   */
  maxItemsPerCategoryLowStorage?: number;
}

const ALL_SECTIONS: CatalogSection[] = ['live', 'vod', 'series'];
const PERSIST_BATCH_SIZE = 250;

/**
 * Estado de uma seção já inicializada (categorias + retomada), mutável durante
 * o pool intercalado de `runInterleaved` (LS-033) — separado de `syncSection`
 * pra permitir mais de uma seção em voo ao mesmo tempo, cada uma com seu
 * próprio progresso.
 */
interface SectionInit {
  section: CatalogSection;
  categories: Category[];
  done: Set<string>;
  syncGen: number;
  startedAt: number;
  filterIgnored: boolean;
  itemCount: number;
  doneCount: number;
}

/**
 * Sincroniza o catálogo Xtream **por categoria** (D-14 / RF-63): nunca baixa tudo num
 * JSON só. Retomável via `meta` (RF-64), concorrência limitada, poda de itens sumidos,
 * e detecção de painel que ignora `category_id`.
 */
export class CatalogSync {
  readonly events = new Emitter<SyncEvents>();

  private readonly config: CacheConfig;
  private readonly log: Logger;
  private readonly catalog: CatalogRepo;
  private readonly search: SearchRepo;
  private readonly meta: MetaRepo;
  private stopped = false;
  /**
   * Concorrência efetiva desta rodada (PERF-20): começa no teto configurado
   * (respeitando `max_connections` da conta) e se ajusta entre seções pela
   * latência medida — sem reescrever `mapPool` pra mexer no meio de uma
   * seção, o que arriscaria a lógica já testada de retomada/detecção de
   * filtro ignorado (D-14). Uma seção lenta reduz a concorrência da PRÓXIMA;
   * uma rápida permite voltar ao teto.
   */
  private concorrenciaAtual = 1;
  /**
   * Decidido uma vez por `run()` (LG-022, 2026-09-14): motor sem
   * `navigator.storage.estimate` (TVs antigas de verdade — ver `cache/quota.ts`)
   * grava só um recorte por categoria em vez do catálogo inteiro, e para de
   * vez ao primeiro `QuotaExceededError` em vez de insistir seção a seção.
   */
  private lowStorage = false;
  /** Resolvido a cada `run()`: `opts.maxItemsPerCategoryLowStorage` ou o padrão do config. */
  private capItensPorCategoria = 0;
  /** `true` quando um `persistComLimite` estourou a cota nesta rodada — ver ali. */
  private quotaEstourada = false;

  constructor(private readonly deps: CatalogSyncDeps) {
    this.config = deps.config ?? DEFAULT_CACHE_CONFIG;
    this.log = (deps.logger ?? nullLogger).child({ mod: 'sync', listId: deps.listId });
    this.catalog = new CatalogRepo(deps.db, deps.listId);
    this.search = new SearchRepo(deps.db, deps.listId);
    this.meta = new MetaRepo(deps.db, deps.listId);
  }

  /** Interrompe o sync em andamento; o estado de retomada fica persistido. */
  cancel(): void {
    this.stopped = true;
  }

  /** Só para teste (PERF-20): concorrência que a PRÓXIMA seção vai usar. */
  _concorrenciaAtual(): number {
    return this.concorrenciaAtual;
  }

  /**
   * Seções que um `run()` sem `force` de fato sincronizaria agora — cache vencido pelo
   * TTL ou sync anterior incompleto. Usado pelo scheduler de auto-refresh (RF-65) e
   * pela tela de boot para decidir se mostra "sincronizando".
   */
  async plannedSections(now = Date.now()): Promise<CatalogSection[]> {
    const all = await this.meta.allSectionSync();
    return ALL_SECTIONS.filter((s) => {
      const m = all[s];
      if (m?.resume) return true;
      return isStale(m?.lastSyncAt, this.config.ttlMs[s], now);
    });
  }

  /** `true` se nunca houve um sync completo de nenhuma seção (primeiro uso). */
  async isEmpty(): Promise<boolean> {
    const all = await this.meta.allSectionSync();
    return !ALL_SECTIONS.some((s) => all[s]?.lastSyncAt !== undefined);
  }

  async run(opts: RunOptions = {}): Promise<SyncResult> {
    this.stopped = false;
    this.quotaEstourada = false;
    this.lowStorage = await isLowStorageDevice();
    this.capItensPorCategoria =
      opts.maxItemsPerCategoryLowStorage ??
      this.config.sync.maxItemsPerCategoryLowStorage;
    const sections = opts.sections ?? ALL_SECTIONS;
    const result: SyncResult = { ran: [], skipped: [], failed: [], cancelled: false };
    // PERF-20: teto = o menor entre o configurado e o da conta (0/ausente =
    // sem limite extra da conta). Começa no teto — a primeira leva mede a
    // latência real; se vier alta, o restante desta MESMA rodada já reduz,
    // em vez de esperar a próxima rodada de sync inteira.
    const tetoConcorrencia = Math.max(
      1,
      Math.min(this.config.sync.concurrency, opts.maxConnections || Infinity),
    );
    this.concorrenciaAtual = tetoConcorrencia;

    // LS-033 (2026-09-18): inicializa cada seção sequencialmente — igual a
    // antes, isso preserva a garantia de que uma cota já estourada nas
    // escritas pequenas de início de seção (`putCategories`/`patchSectionSync`,
    // fora de `persistComLimite`) impede qualquer seção SEGUINTE de sequer
    // começar a inicializar (achado 2026-09-17). A mudança real vem depois: as
    // categorias das seções que conseguiram inicializar não baixam mais uma
    // seção inteira de cada vez — entram intercaladas (round-robin) num único
    // pool com teto de concorrência GLOBAL. Antes, `ALL_SECTIONS = ['live',
    // 'vod', 'series']` rodava 100% de 'live', depois 100% de 'vod'; se 'vod'
    // estourasse a cota no meio, 'series' — por vir por último — nunca
    // chegava a baixar sequer uma categoria (gap real, spec 005). Preferi
    // round-robin simples a um agendador "justo" por peso: mais fácil de
    // raciocinar e testar, e já resolve o problema de verdade — ver
    // tasks.md LS-033. Limitação aceita: se uma seção falha ao
    // INICIALIZAR (putCategories) depois de outra já ter inicializado com
    // sucesso, a seção já inicializada também fica sem processar categoria
    // nenhuma nesta rodada (o pool sequer começa) — cenário raro (cota
    // estourando bem no início, antes de qualquer item baixado) e sem
    // regressão real: essa seção retoma normalmente na próxima rodada.
    const inits: SectionInit[] = [];
    for (const section of sections) {
      if (this.stopped) {
        result.cancelled = true;
        break;
      }
      try {
        const init = await this.initSection(section, opts.force ?? false);
        if (init) inits.push(init);
        else result.skipped.push(section);
      } catch (err) {
        this.log.error('falha ao sincronizar seção', { section, err: String(err) });
        this.events.emit('section:error', { section, error: err });
        result.failed.push(section);
        // LG-022 (achado 2026-09-17): `persistComLimite` só protege a escrita EM
        // LOTE de itens — `putCategories`/`patchSectionSync`, chamados no início de
        // CADA seção, ainda são escritas diretas no IndexedDB, sem essa proteção.
        // Com a cota já estourada por uma seção anterior, essas escritas pequenas
        // também lançam `QuotaExceededError`, mas caíam aqui (catch genérico) sem
        // marcar `this.stopped` — a seção seguinte tentava de novo, repetia o
        // mesmo erro, e nenhuma virava `cancelled`. Sem `cancelled`, a UI nunca
        // trocava o spinner de "baixando catálogo" pelo estado de erro com
        // "tentar novamente" (RF-`boot.syncStalled`) — o usuário ficava preso
        // pra sempre, mesmo a seção tendo de fato falhado por cota.
        if (isQuotaExceededError(err)) {
          this.stopped = true;
          this.quotaEstourada = true;
        }
      }
    }

    if (inits.length > 0) {
      await this.runInterleaved(inits, tetoConcorrencia);
      for (const init of inits) {
        if (await this.finalizeSection(init)) result.ran.push(init.section);
      }
    }

    // Um ciclo completo reescreveu todas as linhas de busca (o `upsert` já grava
    // as palavras do título), então o índice está pronto sem precisar do
    // preenchimento em blocos. Só vale com as três seções: uma pulada por TTL
    // pode ter linhas gravadas por uma versão anterior do app.
    if (
      !this.stopped &&
      ALL_SECTIONS.every((s) => result.ran.includes(s)) &&
      result.failed.length === 0
    ) {
      await this.search.marcarIndiceDePalavras();
      // Idem para `categoryIds`: só um ciclo completo garante que toda linha do
      // catálogo tem a lista de categorias do painel. Antes disso a consulta por
      // gênero segue pelo índice antigo (ver `CatalogRepo.daCategoria`).
      await this.meta.set(CHAVE_CATEGORIAS_MULTIPLAS, GERACAO_CATEGORIAS_MULTIPLAS);
    }

    await this.maybeEvict();
    if (!this.stopped) this.events.emit('sync:done', { ran: result.ran });
    else result.cancelled = true;
    return result;
  }

  /**
   * Prepara uma seção pra sincronizar (categorias + estado de retomada) sem
   * baixar nenhum item ainda — LS-033 separou isso da parte de categoria-a-
   * categoria pra poder intercalar várias seções no mesmo pool. `undefined` =
   * seção pulada (cache ainda fresco pelo TTL).
   */
  private async initSection(
    section: CatalogSection,
    force: boolean,
  ): Promise<SectionInit | undefined> {
    const prev = await this.meta.getSectionSync(section);
    const resuming = !force && !!prev?.resume;

    if (!force && !resuming && !isStale(prev?.lastSyncAt, this.config.ttlMs[section])) {
      this.events.emit('section:skip', { section, reason: 'fresh' });
      return undefined;
    }

    const categories = await this.fetchCategories(section);
    await this.catalog.putCategories(section, categories);

    const resume = resuming ? prev!.resume! : undefined;
    const syncGen = resume?.syncGen ?? Date.now();
    const done = new Set(resume?.doneCategoryIds ?? []);
    const filterIgnored = resume?.filterIgnored ?? false;
    const startedAt = resume?.startedAt ?? Date.now();

    await this.meta.patchSectionSync(section, {
      resume: {
        syncGen,
        doneCategoryIds: [...done],
        totalCategories: categories.length,
        startedAt,
        ...(filterIgnored ? { filterIgnored: true } : {}),
      },
    });

    this.events.emit('section:start', {
      section,
      totalCategories: categories.length,
      resumed: resuming,
    });

    const init: SectionInit = {
      section,
      categories,
      done,
      syncGen,
      startedAt,
      filterIgnored,
      itemCount: 0,
      doneCount: done.size,
    };

    if (filterIgnored) {
      // Retomada de uma rodada anterior que já tinha detectado o painel
      // ignorando `category_id` — sem categoria pendente pra intercalar, busca
      // tudo de uma vez, igual sempre foi (LS-033 só muda o caminho
      // categoria-a-categoria).
      const all = await this.fetchItems(section, undefined);
      const ok = await this.persistComLimite(section, all, syncGen);
      if (ok) {
        init.itemCount = all.length;
        init.doneCount = categories.length;
      }
    }

    return init;
  }

  /**
   * Baixa as categorias pendentes de TODAS as seções inicializadas num único
   * pool, intercalando round-robin (1 categoria de cada seção por vez) — o
   * teto de concorrência é global, não por seção (LS-033). Cada `SectionInit`
   * guarda seu próprio progresso/estado de "painel ignora category_id", já
   * que agora várias seções correm ao mesmo tempo.
   */
  private async runInterleaved(
    inits: SectionInit[],
    tetoConcorrencia: number,
  ): Promise<void> {
    const filas = new Map(
      inits.map((init) => [
        init.section,
        init.filterIgnored ? [] : init.categories.filter((c) => !init.done.has(c.id)),
      ]),
    );
    const porSecao = new Map(inits.map((init) => [init.section, init]));

    const combinado: { section: CatalogSection; cat: Category }[] = [];
    let sobrou = true;
    while (sobrou) {
      sobrou = false;
      for (const init of inits) {
        const fila = filas.get(init.section)!;
        const cat = fila.shift();
        if (cat) {
          combinado.push({ section: init.section, cat });
          sobrou = true;
        }
      }
    }

    // PERF-20: com várias seções correndo juntas, a latência deixa de ser "por
    // seção" — usa a mediana combinada desta rodada inteira pra ajustar a
    // concorrência (simplificação assumida de LS-033; com uma seção só, o
    // efeito é idêntico ao de antes).
    const latenciasMs: number[] = [];

    await mapPool(
      combinado,
      this.concorrenciaAtual,
      async ({ section, cat }) => {
        const init = porSecao.get(section)!;
        if (this.stopped || init.filterIgnored) return;
        const t0 = Date.now();
        const items = await this.fetchItems(section, cat.id);
        latenciasMs.push(Date.now() - t0);
        // Outra requisição em voo pode ter detectado o catálogo inteiro.
        // Não grave/indexe a mesma resposta gigante uma vez por worker.
        if (this.stopped || init.filterIgnored) return;

        // painel ignora o filtro quando a resposta é grande E a maioria dos itens
        // pertence a outras categorias. "Pertence" olha `categoryIds` quando
        // existe: um item pode estar em várias categorias e trazer outra como
        // principal, e contá-lo como estrangeiro faria a detecção disparar
        // numa categoria legítima (foi o caso de "Lançamentos").
        let foreign = 0;
        if (items.length > this.config.sync.ignoredFilterItemThreshold) {
          for (const it of items) {
            const todas = (it as { categoryIds?: string[] }).categoryIds;
            const belongs = todas?.length
              ? todas.includes(cat.id)
              : !it.categoryId || it.categoryId === cat.id;
            if (!belongs && ++foreign > items.length / 2) break;
          }
        }
        if (
          items.length > this.config.sync.ignoredFilterItemThreshold &&
          foreign > items.length / 2
        ) {
          init.filterIgnored = true;
          this.log.warn('painel ignora category_id — sync em tacada única', {
            section,
          });
          const ok = await this.persistComLimite(section, items, init.syncGen);
          if (!ok) return; // cota estourada — this.stopped já foi setado
          init.itemCount = items.length;
          init.doneCount = init.categories.length;
          await this.meta.patchSectionSync(section, {
            resume: {
              syncGen: init.syncGen,
              doneCategoryIds: init.categories.map((c) => c.id),
              totalCategories: init.categories.length,
              startedAt: init.startedAt,
              filterIgnored: true,
            },
          });
          return;
        }

        const ok = await this.persistComLimite(section, items, init.syncGen, cat.id);
        if (!ok) return; // cota estourada — this.stopped já foi setado
        init.itemCount += items.length;
        init.done.add(cat.id);
        const at = ++init.doneCount;
        await this.meta.markCategoryDone(section, cat.id);
        this.events.emit('section:progress', {
          section,
          done: at,
          total: init.categories.length,
          categoryName: cat.name,
          items: items.length,
        });
      },
      { shouldStop: () => this.stopped },
    );

    if (latenciasMs.length > 0) {
      const ordenadas = [...latenciasMs].sort((a, b) => a - b);
      const mediana = ordenadas[Math.floor(ordenadas.length / 2)]!;
      if (mediana > 3_000)
        this.concorrenciaAtual = Math.max(1, this.concorrenciaAtual - 1);
      else if (mediana < 800)
        this.concorrenciaAtual = Math.min(tetoConcorrencia, this.concorrenciaAtual + 1);
    }
  }

  /**
   * Fecha uma seção que terminou TODAS as suas categorias (poda + `lastSyncAt`)
   * — devolve `false` sem fechar quando ficou parcial (cota/cancelamento):
   * o estado de retomada já foi persistido categoria a categoria, então a
   * seção conta como "rodou" mesmo incompleta (LS-033 preserva essa semântica,
   * agora possível para mais de uma seção na mesma rodada).
   */
  private async finalizeSection(init: SectionInit): Promise<boolean> {
    const { section } = init;
    const completo = init.doneCount >= init.categories.length;
    if (!completo) return init.doneCount > 0 || init.itemCount > 0;

    const pruned = await this.catalog.pruneSection(section, init.syncGen);
    await this.catalog.pruneCategoryMembers(section, init.syncGen);
    await this.search.pruneStale(section, init.syncGen);
    await this.meta.patchSectionSync(section, {
      lastSyncAt: Date.now(),
      itemCount: init.itemCount,
      resume: undefined,
    });
    // PERF-01a: um sync completo pode ter trazido item sem `addedAt`/
    // `lastModified` que não existia antes (ou o contrário) — invalida a marca
    // de "índice completo" para o próximo acesso recalcular, em vez de confiar
    // numa resposta que pode ter ficado desatualizada.
    if (section === 'vod' || section === 'series') {
      await invalidarIndiceCompleto(this.deps.db, this.deps.listId, section);
    }
    this.events.emit('section:done', { section, itemCount: init.itemCount, pruned });
    return true;
  }

  /**
   * LS-032A: aquece no máximo 1 categoria de VOD e 1 de série antes/sem
   * depender do sync completo — o gap real (spec 005) é que `series` vem por
   * último em `ALL_SECTIONS` e nunca chega a baixar nada se `vod` estourar a
   * cota no meio. Só age em seções que nunca tiveram um sync completo nem
   * estão com um sync em andamento (não compete por `syncGen`/gravação com
   * `run()`) — best-effort, erros de uma seção não impedem a outra. Não
   * bloqueia quem chamou: o método inteiro processa no máximo duas categorias
   * pequenas, e o chamador (boot) decide se aguarda ou dispara e segue.
   */
  async warmPriorityCategories(): Promise<void> {
    for (const section of ['vod', 'series'] as const) {
      try {
        await this.warmOneCategory(section);
      } catch (err) {
        this.log.warn('aquecimento de categoria prioritária falhou', {
          section,
          err: String(err),
        });
      }
    }
  }

  private async warmOneCategory(section: 'vod' | 'series'): Promise<void> {
    if (this.stopped) return;
    const sectionMeta = await this.meta.getSectionSync(section);
    // sync completo já rodou, ou um está em andamento agora — aquecimento é só
    // pra cobrir o buraco de "nunca rodou nem uma vez"; não compete com o
    // `run()` de verdade nem re-baixa o que já está lá.
    if (sectionMeta?.lastSyncAt !== undefined || sectionMeta?.resume) return;

    let categories = await this.catalog.categories(section);
    if (categories.length === 0) {
      // só metadado (nome/id da categoria) — nunca um item, por isso não conta
      // como "baixar uma categoria só pra descobrir seu tamanho".
      categories = await this.fetchCategories(section);
      if (categories.length === 0) return;
      await this.catalog.putCategories(section, categories);
    }

    const candidata = await this.escolherCategoriaPrioritaria(section, categories);
    if (!candidata) return;

    const jaTemItens =
      section === 'vod'
        ? await this.catalog.countMovies({ categoryId: candidata.id })
        : await this.catalog.countSeries({ categoryId: candidata.id });
    if (jaTemItens > 0) return; // já aquecida numa rodada anterior

    const syncGen = Date.now();
    const items = await this.fetchItems(section, candidata.id);
    const ok = await this.persistComLimite(section, items, syncGen, candidata.id);
    if (!ok) return; // cota estourada — nem o aquecimento cabe, desiste sem marcar nada

    // Registra como um sync PARCIAL da seção (mesmo formato de `resume` que um
    // `run()` cancelado no meio deixaria) — assim, quando o sync completo de
    // verdade rodar depois, ele RETOMA a partir daqui (`doneCategoryIds` já
    // inclui esta categoria) em vez de baixá-la de novo.
    await this.meta.patchSectionSync(section, {
      resume: {
        syncGen,
        doneCategoryIds: [candidata.id],
        totalCategories: categories.length,
        startedAt: Date.now(),
      },
    });
  }

  /**
   * Ordem de prioridade do LS-032A: (1) última categoria usada pelo usuário —
   * NÃO existe hoje nenhum estado persistido de "última categoria vista"
   * (`browse.ts` guarda isso só em memória, no Zustand store) — tratado como
   * indisponível em vez de inventar um sistema de tracking novo fora do
   * escopo desta tarefa; (2) categoria "recente/lançamentos" pelo nome; (3)
   * categoria pequena já aprendida de um sync anterior (conta via
   * `categoryMembers`, sem baixar nada só pra medir); (4) primeira da lista.
   */
  private async escolherCategoriaPrioritaria(
    section: 'vod' | 'series',
    categories: Category[],
  ): Promise<Category | undefined> {
    if (categories.length === 0) return undefined;

    const recente = categories.find((c) =>
      /\b(lancamento|lancamentos|recente|recentes)\b/.test(normalizeText(c.name)),
    );
    if (recente) return recente;

    let menor: { cat: Category; count: number } | undefined;
    for (const c of categories) {
      const count =
        section === 'vod'
          ? await this.catalog.countMovies({ categoryId: c.id })
          : await this.catalog.countSeries({ categoryId: c.id });
      if (count > 0 && (!menor || count < menor.count)) menor = { cat: c, count };
    }
    if (menor) return menor.cat;

    return categories[0];
  }

  /**
   * Envolve `persist()` com o corte de itens (LG-022, TVs sem
   * `navigator.storage.estimate`) e a parada limpa em `QuotaExceededError` —
   * usado nos três lugares que gravam itens de categoria, pra não duplicar
   * essa lógica. Devolve `false` quando a cota estourou (chamador deve parar
   * sem marcar a seção/categoria como concluída); relança qualquer outro erro.
   */
  private async persistComLimite(
    section: CatalogSection,
    items: Item[],
    syncGen: number,
    requestedCategoryId?: string,
  ): Promise<boolean> {
    // `capItensPorCategoria <= 0` = "sem limite" (opção "Sem limite" na tela
    // de Configurações) — não é o mesmo que `items.slice(0, 0)`, que zeraria.
    const gravar =
      this.lowStorage && this.capItensPorCategoria > 0
        ? items.slice(0, this.capItensPorCategoria)
        : items;
    try {
      return await this.persist(section, gravar, syncGen, requestedCategoryId);
    } catch (err) {
      if (!isQuotaExceededError(err)) throw err;
      this.log.warn('cota de armazenamento estourada — parando a sincronização', {
        section,
        categoryId: requestedCategoryId,
      });
      this.stopped = true;
      this.quotaEstourada = true;
      return false;
    }
  }

  /**
   * Catálogo, memberships e busca continuam atômicos por lote (PERF-21).
   * Limitar o lote evita milhares de pedidos IndexedDB e cópias temporárias
   * simultâneas. A categoria só é marcada como concluída após todos os lotes;
   * uma interrupção retoma a categoria com a mesma geração, sem podar dados.
   */
  private async persist(
    section: CatalogSection,
    items: Item[],
    syncGen: number,
    requestedCategoryId?: string,
  ): Promise<boolean> {
    for (let offset = 0; offset < items.length; offset += PERSIST_BATCH_SIZE) {
      if (offset > 0) await new Promise<void>((resolve) => setTimeout(resolve, 0));
      if (this.stopped) return false;
      await this.persistBatch(
        section,
        items.slice(offset, offset + PERSIST_BATCH_SIZE),
        syncGen,
        requestedCategoryId,
      );
    }
    return !this.stopped;
  }

  private async persistBatch(
    section: CatalogSection,
    items: Item[],
    syncGen: number,
    requestedCategoryId?: string,
  ): Promise<void> {
    const { db } = this.deps;
    if (section === 'live') {
      const channels = items as Channel[];
      const rows = requestedCategoryId
        ? channels.map((c) => ({ ...c, categoryId: c.categoryId ?? requestedCategoryId }))
        : channels;
      await db.transaction('rw', [db.channels, db.search], async () => {
        await this.catalog.putChannels(rows, syncGen);
        await this.search.upsert('live', rows.map(toSearchItem), syncGen);
      });
    } else if (section === 'vod') {
      const movies = items as Movie[];
      await db.transaction('rw', [db.movies, db.search, db.categoryMembers], async () => {
        await this.catalog.putMovies(movies, syncGen);
        await this.search.upsert('vod', movies.map(toSearchItem), syncGen);
      });
    } else {
      const series = items as Series[];
      await db.transaction('rw', [db.series, db.search, db.categoryMembers], async () => {
        await this.catalog.putSeries(series, syncGen);
        await this.search.upsert('series', series.map(toSearchItem), syncGen);
      });
    }
  }

  private fetchCategories(section: CatalogSection): Promise<Category[]> {
    const p = this.deps.provider;
    if (section === 'live') return p.getLiveCategories();
    if (section === 'vod') return p.getVodCategories();
    return p.getSeriesCategories();
  }

  private fetchItems(
    section: CatalogSection,
    categoryId: string | undefined,
  ): Promise<Item[]> {
    const p = this.deps.provider;
    if (section === 'live') return p.getLiveChannels(categoryId);
    if (section === 'vod') return p.getVodItems(categoryId);
    return p.getSeriesList(categoryId);
  }

  private async maybeEvict(): Promise<void> {
    const est = await storageEstimate();
    const pressure = !!est && est.ratio >= this.config.lru.quotaPressure;
    const cap = pressure
      ? Math.floor(this.config.lru.infoMaxRows / 2)
      : this.config.lru.infoMaxRows;
    const removed = await evictInfoLru(this.deps.db, cap);
    if (removed) this.log.info('LRU: linhas de info removidas', { removed, pressure });
  }
}
