import type { ReactNode } from 'react';
import { t } from '../i18n/index.js';
import { FocusButton } from './FocusButton.js';
import { BalanceLoader } from './BalanceLoader.js';

// PERF-12 (spec 002): estilo estático → `.centered` em `theme/base.css`.

export function LoadingState({ label }: { label?: string }) {
  return (
    <div className="centered" role="status" aria-live="polite">
      <div>
        <div style={{ marginBottom: '1em' }}>
          <BalanceLoader />
        </div>
        <p style={{ color: 'var(--text-secondary)' }}>{label ?? t('common.loading')}</p>
      </div>
    </div>
  );
}

export function EmptyState({
  title = t('states.emptyTitle'),
  body = t('states.emptyBody'),
  action,
  loading = false,
}: {
  title?: string;
  body?: string;
  action?: ReactNode;
  /**
   * A tela está vazia porque o conteúdo ainda vem chegando (primeira
   * sincronização), não porque não existe nada. Só aí faz sentido animar — numa
   * busca sem resultado ou nos favoritos vazios, um indicador de carregamento
   * prometeria algo que nunca vai chegar.
   */
  loading?: boolean;
}) {
  return (
    <div className="centered">
      <div>
        {loading && (
          <div style={{ marginBottom: '1.2em' }}>
            <BalanceLoader />
          </div>
        )}
        <h2>{title}</h2>
        <p style={{ color: 'var(--text-secondary)' }}>{body}</p>
        {action}
      </div>
    </div>
  );
}

export interface DiagnosticRow {
  label: string;
  value: string;
  ok: boolean;
}

export function DiagnosticTable({ rows }: { rows: DiagnosticRow[] }) {
  return (
    <table style={{ margin: '1.5em auto', borderCollapse: 'collapse', minWidth: 320 }}>
      <tbody>
        {rows.map((r) => (
          <tr key={r.label}>
            <td style={{ padding: '0.4em 1em', color: 'var(--text-secondary)' }}>
              {r.label}
            </td>
            <td
              style={{
                padding: '0.4em 1em',
                textAlign: 'right',
                color: r.ok ? 'var(--success)' : 'var(--danger)',
                fontWeight: 600,
              }}
            >
              {r.value}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export function ErrorScreen({
  title = t('states.errorTitle'),
  body = t('states.errorBody'),
  code,
  diagnostics,
  onRetry,
  retryLabel,
  autoFocusRetry = false,
}: {
  title?: string;
  body?: string;
  /** Código próprio: NET-001, SRV-xxx, AUTH-xxx… (design-inventory tela 15). */
  code?: string;
  diagnostics?: DiagnosticRow[];
  onRetry?: () => void;
  /** Rótulo do botão — quando o "erro" é uma recusa antecipada (ver Player.tsx,
   *  bloqueio de decodificação), "Tentar novamente" não descreve a ação. */
  retryLabel?: string;
  /**
   * Pede foco no botão de retry assim que ele existe (LS-030, spec 005 M3) —
   * necessário quando `ErrorScreen` SUBSTITUI uma tela que já tinha foco (ex.:
   * a grade do catálogo): o `useFocusGuard` da rota não reage sozinho aqui
   * porque seu efeito não está nas dependências deste estado de erro, só na
   * rota/fase — sem isto o D-pad fica sem alvo até o polling de última
   * instância (até 3s) resolver. Outros usos (detalhe/player) mantêm `false`,
   * comportamento inalterado.
   */
  autoFocusRetry?: boolean;
}) {
  return (
    <div className="centered">
      <div>
        <h2 style={{ color: 'var(--danger)' }}>{title}</h2>
        <p style={{ color: 'var(--text-secondary)' }}>{body}</p>
        {diagnostics && <DiagnosticTable rows={diagnostics} />}
        {code && <p style={{ color: 'var(--text-disabled)', fontSize: 12 }}>{code}</p>}
        {onRetry && (
          <FocusButton
            primary
            autoFocus={autoFocusRetry}
            focusKey="error-retry"
            onPress={onRetry}
          >
            {retryLabel ?? t('common.retry')}
          </FocusButton>
        )}
      </div>
    </div>
  );
}
