import { useEffect, useState } from 'react';

/**
 * Valor atual de 1rem em pixels.
 *
 * A raiz usa `font-size: clamp(...)` em unidades de viewport (base.css), então a
 * escala inteira acompanha a tela: 13px num telefone, ~25px numa TV 1080p. Quem
 * precisa de medida em px — as listas virtualizadas recebem altura de linha
 * numérica — tem de derivar daqui, senão a linha fica minúscula na TV.
 */
export function useRemPx(): number {
  const [rem, setRem] = useState(16);

  useEffect(() => {
    const medir = () => {
      const v = parseFloat(getComputedStyle(document.documentElement).fontSize);
      if (Number.isFinite(v) && v > 0) setRem(v);
    };
    medir();
    window.addEventListener('resize', medir);
    return () => window.removeEventListener('resize', medir);
  }, []);

  return rem;
}
