import type { AuraDb, CatalogSection } from './db.js';

/** Estado de sync de uma seção — `resume` só existe enquanto um sync está incompleto. */
export interface SectionSyncMeta {
  lastSyncAt?: number;
  itemCount?: number;
  resume?: {
    syncGen: number;
    doneCategoryIds: string[];
    totalCategories: number;
    startedAt: number;
    /** painel ignora `category_id` — o sync já pegou tudo numa tacada. */
    filterIgnored?: boolean;
  };
}

export class MetaRepo {
  constructor(
    private readonly db: AuraDb,
    private readonly listId: string,
  ) {}

  async get<T>(key: string): Promise<T | undefined> {
    const row = await this.db.meta.get([this.listId, key]);
    return row?.value as T | undefined;
  }

  async set(key: string, value: unknown): Promise<void> {
    await this.db.meta.put({ listId: this.listId, key, value, updatedAt: Date.now() });
  }

  private syncKey(section: CatalogSection): string {
    return `sync:${section}`;
  }

  getSectionSync(section: CatalogSection): Promise<SectionSyncMeta | undefined> {
    return this.get<SectionSyncMeta>(this.syncKey(section));
  }

  async patchSectionSync(
    section: CatalogSection,
    patch: Partial<SectionSyncMeta>,
  ): Promise<void> {
    const current = (await this.getSectionSync(section)) ?? {};
    await this.set(this.syncKey(section), { ...current, ...patch });
  }

  /** Marca uma categoria como concluída no estado de retomada (RF-64). */
  async markCategoryDone(section: CatalogSection, categoryId: string): Promise<void> {
    const current = (await this.getSectionSync(section)) ?? {};
    const resume = current.resume;
    if (!resume) return;
    if (!resume.doneCategoryIds.includes(categoryId)) {
      resume.doneCategoryIds.push(categoryId);
      await this.set(this.syncKey(section), current);
    }
  }

  async allSectionSync(): Promise<Partial<Record<CatalogSection, SectionSyncMeta>>> {
    const sections: CatalogSection[] = ['live', 'vod', 'series'];
    const out: Partial<Record<CatalogSection, SectionSyncMeta>> = {};
    for (const s of sections) {
      const meta = await this.getSectionSync(s);
      if (meta) out[s] = meta;
    }
    return out;
  }
}
