// Componentes de metadado recorrentes nos cartões (design-inventory §Componentes).

export function AgeBadge({ rating }: { rating: string }) {
  return (
    <span
      style={{
        border: '1px solid var(--rating)',
        color: 'var(--rating)',
        borderRadius: 4,
        padding: '0 0.35em',
        fontSize: '0.8em',
        fontWeight: 700,
      }}
    >
      {rating}
    </span>
  );
}

export function QualityBadge({ label }: { label: '4K' | 'HDR' | 'DUAL' | 'LEG' }) {
  return (
    <span
      style={{
        background: 'var(--bg-raised)',
        color: 'var(--text-secondary)',
        borderRadius: 4,
        padding: '0 0.35em',
        fontSize: '0.8em',
        fontWeight: 700,
      }}
    >
      {label}
    </span>
  );
}

export function RatingStars({ value }: { value: number }) {
  // value 0..10 → nota com uma casa, no padrão dos mockups ("8,7").
  const formatted = value.toFixed(1).replace('.', ',');
  return <span style={{ color: 'var(--rating)', fontWeight: 700 }}>★ {formatted}</span>;
}

export function ProgressBar({ value }: { value: number }) {
  const pct = Math.max(0, Math.min(1, value)) * 100;
  return (
    <div
      style={{
        height: 4,
        borderRadius: 2,
        background: 'var(--bg-raised)',
        overflow: 'hidden',
      }}
    >
      <div style={{ width: `${pct}%`, height: '100%', background: 'var(--accent)' }} />
    </div>
  );
}
