import { useCallback, useEffect, useRef } from 'react';

/** Distância antes de virar arrasto — abaixo disso o gesto ainda é um toque. */
const LIMIAR_PX = 8;
/** Abaixo disso o impulso não vale a pena. */
const VELOCIDADE_MINIMA = 0.05; // px/ms
/**
 * Atrito por quadro (~60fps). Com o teto de velocidade abaixo, um lance rápido
 * percorre ~`VELOCIDADE_MAXIMA * 16 / (1 - ATRITO)` px. Em 0,92 e 2,5 px/ms cada
 * gesto andava só ~500px, o que numa lista de 2357 canais (≈146.000px) torna
 * qualquer travessia inviável.
 */
const ATRITO = 0.95;
/**
 * Teto da velocidade (px/ms). Dois `touchmove` muito próximos dão `dt` perto de
 * zero e a divisão explode — um arrasto de 300px chegou a virar 11.500px de
 * impulso na medição. Também protege de relógios com pouca resolução.
 */
const VELOCIDADE_MAXIMA = 6;
/** `dt` mínimo considerado, pelo mesmo motivo. */
const DT_MINIMO_MS = 4;

export interface DragScroll {
  /**
   * Assina os quadros do gesto — chamado a cada `touchmove`/passo do impulso
   * com o deslocamento imposto pelo dedo, e uma vez com `null` quando o gesto
   * termina (a lista volta a seguir o foco). Devolve o cancelador.
   *
   * Por que assinatura, e não estado do React (PERF-10 / spec 002): um arrasto
   * numa lista de milhares de itens chamava `setState` a cada quadro (~60/s),
   * re-renderizando a janela inteira de células a cada um. O consumidor agora
   * escreve o `transform` direto no nó e só re-renderiza quando a **janela de
   * linhas** muda — bem mais raro que a cada pixel.
   */
  assinar(fn: (offset: number | null) => void): () => void;
  /** Houve arrasto de verdade — o clique que vem em seguida deve ser ignorado. */
  arrastou: () => boolean;
  /** Volta a seguir o foco (chamar quando o D-pad move o foco). */
  soltar: () => void;
  /** Dedo na tela ou impulso rodando — o foco não deve reancorar a lista agora. */
  ativo: () => boolean;
}

/**
 * Rolagem por arrasto para as listas virtualizadas.
 *
 * As listas posicionam o conteúdo por `translate3d` a partir do item focado
 * (D-pad), então o container é `overflow: hidden` e o gesto de rolar do sistema
 * não tem o que mover. Este hook notifica um deslocamento próprio enquanto o
 * dedo manda, e um `null` assim que o foco volta a comandar.
 *
 * Toque é **adicional**: a constitution §7 exige que nada dependa dele, e nada
 * depende — o D-pad continua sendo o caminho completo.
 *
 * Usa **Touch Events**, não Pointer Events, por dois motivos medidos:
 * 1. o alvo mínimo (webOS 4 / Tizen 4, Chromium 53-56 — constitution §8) não tem
 *    Pointer Events, e a versão com eles ficaria morta ali;
 * 2. mesmo no WebView do Android, o Chromium cancela o fluxo de ponteiro assim
 *    que decide que o gesto é uma rolagem (`pointercancel` +
 *    `lostpointercapture` logo após o primeiro `pointermove`), enquanto os
 *    `touchmove` continuam chegando.
 *
 * Os listeners são nativos e **não passivos**: o React registra `onTouchMove`
 * como passivo no root desde a v17, e ali `preventDefault()` não teria efeito —
 * sem ele o navegador rola a página junto.
 */
export function useDragScroll(
  alvo: { current: HTMLElement | null },
  eixo: 'x' | 'y',
  max: number,
  atual: () => number,
  /** Chamado quando o gesto termina de fato, com o deslocamento final. */
  aoParar?: (offset: number) => void,
): DragScroll {
  const arrastouRef = useRef(false);
  const impulso = useRef(0);
  const dedoNaTela = useRef(false);
  const aoPararRef = useRef(aoParar);
  // lidos dentro dos listeners nativos, que são registrados uma vez só
  const maxRef = useRef(max);
  const atualRef = useRef(atual);
  const assinantesRef = useRef(new Set<(o: number | null) => void>());
  useEffect(() => {
    maxRef.current = max;
    atualRef.current = atual;
    aoPararRef.current = aoParar;
  });

  const notificar = useCallback((o: number | null) => {
    for (const fn of assinantesRef.current) fn(o);
  }, []);

  const pararImpulso = useCallback(() => {
    if (impulso.current) cancelAnimationFrame(impulso.current);
    impulso.current = 0;
  }, []);

  useEffect(() => {
    const node = alvo.current;
    if (!node) return;

    const limitar = (v: number) => Math.max(0, Math.min(v, maxRef.current));
    const pos = (t: Touch) => (eixo === 'y' ? t.clientY : t.clientX);
    let g: {
      inicio: number;
      base: number;
      moveu: boolean;
      ultimaPos: number;
      ultimoMs: number;
      velocidade: number;
    } | null = null;

    const onStart = (e: TouchEvent) => {
      const t = e.touches[0];
      if (!t || e.touches.length > 1) return;
      if (impulso.current) cancelAnimationFrame(impulso.current);
      impulso.current = 0;
      arrastouRef.current = false;
      dedoNaTela.current = true;
      g = {
        inicio: pos(t),
        base: atualRef.current(),
        moveu: false,
        ultimaPos: pos(t),
        ultimoMs: e.timeStamp,
        velocidade: 0,
      };
    };

    const onMove = (e: TouchEvent) => {
      const t = e.touches[0];
      if (!g || !t) return;
      const p = pos(t);
      const delta = g.inicio - p;
      if (!g.moveu) {
        if (Math.abs(delta) < LIMIAR_PX) return;
        g.moveu = true;
        arrastouRef.current = true;
      }
      // o gesto é nosso: sem isto o navegador rola a página por baixo
      e.preventDefault();
      const dt = Math.max(DT_MINIMO_MS, e.timeStamp - g.ultimoMs);
      const v = (g.ultimaPos - p) / dt;
      g.velocidade = Math.max(-VELOCIDADE_MAXIMA, Math.min(VELOCIDADE_MAXIMA, v));
      g.ultimaPos = p;
      g.ultimoMs = e.timeStamp;
      notificar(limitar(g.base + delta));
    };

    const parou = () => {
      impulso.current = 0;
      dedoNaTela.current = false;
      // Primeiro o consumidor adota a posição (move a âncora do foco para onde o
      // dedo parou), só então soltamos — nessa ordem o deslocamento calculado
      // pelo foco já bate com o do gesto e a lista não salta.
      aoPararRef.current?.(atualRef.current());
      notificar(null);
    };

    const onEnd = () => {
      const fim = g;
      g = null;
      if (!fim?.moveu) {
        dedoNaTela.current = false;
        return;
      }
      let v = fim.velocidade;
      if (Math.abs(v) < VELOCIDADE_MINIMA) {
        parou();
        return;
      }
      let off = limitar(atualRef.current());
      const passo = () => {
        v *= ATRITO;
        if (Math.abs(v) < VELOCIDADE_MINIMA) {
          parou();
          return;
        }
        off = limitar(off + v * 16);
        notificar(off);
        impulso.current = requestAnimationFrame(passo);
      };
      impulso.current = requestAnimationFrame(passo);
    };

    node.addEventListener('touchstart', onStart, { passive: true });
    node.addEventListener('touchmove', onMove, { passive: false });
    node.addEventListener('touchend', onEnd, { passive: true });
    node.addEventListener('touchcancel', onEnd, { passive: true });
    return () => {
      node.removeEventListener('touchstart', onStart);
      node.removeEventListener('touchmove', onMove);
      node.removeEventListener('touchend', onEnd);
      node.removeEventListener('touchcancel', onEnd);
    };
  }, [alvo, eixo, notificar]);

  useEffect(() => pararImpulso, [pararImpulso]);

  return {
    assinar: useCallback((fn) => {
      assinantesRef.current.add(fn);
      return () => assinantesRef.current.delete(fn);
    }, []),
    arrastou: useCallback(() => arrastouRef.current, []),
    ativo: useCallback(() => dedoNaTela.current || impulso.current !== 0, []),
    soltar: useCallback(() => {
      pararImpulso();
      notificar(null);
    }, [pararImpulso, notificar]),
  };
}
