import { create } from 'zustand';
import type { StreamKind } from '@mfp/core';
import type { Runtime } from '../runtime/runtime.js';
import { DEFAULT_PROFILE } from './catalog.js';

// Favoritos por perfil (tela 09). Lista única no Dexie `favorites`; a UI separa
// por aba (canais / filmes / séries).

interface FavoritesState {
  keys: Set<string>; // `${kind}:${id}` do perfil/lista atual
  load: (rt: Runtime, listId: string) => Promise<void>;
  isFav: (kind: StreamKind, id: string) => boolean;
  toggle: (rt: Runtime, listId: string, kind: StreamKind, id: string) => Promise<void>;
}

const k = (kind: StreamKind, id: string) => `${kind}:${id}`;

export const useFavorites = create<FavoritesState>((set, get) => ({
  keys: new Set(),

  load: async (rt, listId) => {
    const rows = await rt.db.favorites
      .where('[profileId+listId]')
      .equals([DEFAULT_PROFILE, listId])
      .toArray();
    set({ keys: new Set(rows.map((r) => k(r.kind, r.id))) });
  },

  isFav: (kind, id) => get().keys.has(k(kind, id)),

  toggle: async (rt, listId, kind, id) => {
    const key = k(kind, id);
    const has = get().keys.has(key);
    if (has) {
      await rt.db.favorites.delete([DEFAULT_PROFILE, listId, kind, id]);
    } else {
      await rt.db.favorites.put({
        profileId: DEFAULT_PROFILE,
        listId,
        kind,
        id,
        addedAt: Date.now(),
      });
    }
    const next = new Set(get().keys);
    if (has) next.delete(key);
    else next.add(key);
    set({ keys: next });
  },
}));
