import { setFocus } from '@noriginmedia/norigin-spatial-navigation';

/**
 * Handler de clique/toque que **move o foco para o item tocado** antes de agir.
 *
 * O foco espacial do D-pad e o dedo são dois ponteiros independentes: tocar num
 * item dispara a ação, mas o norigin continua com o foco onde estava. Sem isto,
 * o destaque fica preso — no teclado do PIN, digitar 5, 8 e 2 registrava os três
 * dígitos com o vermelho parado no "1", que é onde o foco tinha nascido.
 *
 * Também deixa o D-pad continuar de onde o dedo parou, em vez de saltar de volta.
 */
export function pressWithFocus(focusKey: string, onPress?: () => void) {
  return () => {
    void setFocus(focusKey);
    onPress?.();
  };
}
